prompt --application/shared_components/logic/application_processes/css_imresion
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(544092685305191994)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CSS_IMRESION'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    DECLARE',
'          l_id          REPORTES_PDF.id%TYPE := :P138_ID_REPORTE;',
'          l_nombres     VARCHAR2(4000);',
'          l_colores     VARCHAR2(4000);',
'          l_estilo      CLOB;',
'          TYPE t_arr IS TABLE OF VARCHAR2(500) INDEX BY PLS_INTEGER;',
'          l_arr_nombres t_arr;',
'          l_arr_colores t_arr;',
'          PROCEDURE split_csv(p_str IN VARCHAR2, p_arr OUT t_arr) IS',
'            v_str VARCHAR2(4000) := p_str || '','';',
'            v_ini NUMBER := 1;',
'            v_fin NUMBER;',
'            v_i   NUMBER := 1;',
'          BEGIN',
'            LOOP',
'              v_fin := INSTR(v_str, '','', v_ini);',
'              EXIT WHEN v_fin = 0;',
'              p_arr(v_i) := TRIM(SUBSTR(v_str, v_ini, v_fin - v_ini));',
'              v_ini := v_fin + 1;',
'              v_i   := v_i + 1;',
'            END LOOP;',
'          END;',
'        BEGIN',
'          SELECT nombre_archivo, color',
'          INTO   l_nombres, l_colores',
'          FROM  REPORTES_PDF',
'          WHERE  id = l_id;',
'          split_csv(l_nombres, l_arr_nombres);',
'          split_csv(l_colores, l_arr_colores);',
'          l_estilo := '':root {'' || CHR(10);',
'          FOR i IN 1 .. l_arr_nombres.COUNT LOOP',
'            l_estilo := l_estilo ||',
'              ''  --'' || l_arr_nombres(i) || '': '' || l_arr_colores(i) || '';'' || CHR(10);',
'          END LOOP;',
'          l_estilo := l_estilo || ''}'' || CHR(10) || CHR(10);',
'          FOR i IN 1 .. l_arr_nombres.COUNT LOOP',
'            l_estilo := l_estilo ||',
'              ''#'' || l_arr_nombres(i) || '' {'' || CHR(10) ||',
'              ''  background-color: var(--'' || l_arr_nombres(i) || '', '' || l_arr_colores(i) || '');'' || CHR(10) ||',
'              ''  border: 1px solid var(--'' || l_arr_nombres(i) || '', '' || l_arr_colores(i) || '') !important;'' || CHR(10) ||',
'              ''  border-radius: 5px;'' || CHR(10) ||',
'              ''  color: white;'' || CHR(10) ||',
'              ''}'' || CHR(10) || CHR(10);',
'          END LOOP;',
'          sys.HTP.init;',
'          sys.OWA_UTIL.mime_header(''text/css'', FALSE);',
'          sys.OWA_UTIL.http_header_close;',
'          htp.p(l_estilo);',
'        EXCEPTION',
'          WHEN NO_DATA_FOUND THEN',
unistr('            htp.p(''/* Error: no se encontr\00F3 el registro id: '' || l_id || '' */'');'),
'          WHEN OTHERS THEN',
'            htp.p(''/* Error: '' || SQLERRM || '' */'');',
'        END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>408722155
);
end;
/
