'        ,CC.DESCCOBERT DESCRIPCION',
'        -- ,C.SUMAASEGURADA',
'        -- ,C.PRIMA_COBERT',
'    FROM COBERTURAS_DE_SEGUROS CC',
'    WHERE CC.CODCIA     = 1',
'    AND CC.CODEMPRESA = 1',
'    AND CC.IDTIPOSEG  = NVL(:P1753_IDTIPOSEG,:P1704_TIPOSEG)',
'    AND CC.PLANCOB    = NVL(:P1753_PLANCOB,:P1704_PLANCOB)',
'    -- AND NOT EXISTS (SELECT ''S'' ',
'    --                 FROM SOLICITUD_COBERTURAS SC',
'    --                 WHERE SC.CODCIA      = 1',
'    --                 AND SC.CODEMPRESA  = 1',
'    --                 AND IDSOLICITUD = NVL(:P1753_IDSOLICITUD,:P1704_IDSOLICITUD)',
'    --                 AND IDETSOL     = NVL(:P1753_IDETSOL,:P1704_IDETSOL)',
'    --                 -- AND SC.IDSOLICITUD = :P1704_IDSOLICITUD',
'    --                 -- AND SC.IDETSOL     = :P1704_IDETSOL',
'    --                 AND SC.CODCOBERT   = CC.CODCOBERT',
'    --                 AND SC.CODCOBERT NOT IN :P1704_CODCOBERT)                '))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'CODCOBERT'
,p_display_column_name=>'DESCCOBERT'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
