,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_existe NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'      INTO v_existe',
'      FROM DETALLE_POLIZA',
'     WHERE CODCIA   = :P4_CODCIA',
'       AND IDPOLIZA = :P4_IDPOLIZA',
'       AND IDETPOL  = :P4_DET_INI;',
'',
'    IF v_existe = 0 THEN',
'        RETURN FALSE;',
'    ELSE',
'        RETURN TRUE;',
'    END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
