'var idReporte = apex.item(''P4_ID_REPORTE'').getValue();',
'',
'if (!idReporte) return;',
'',
'apex.server.process(',
'  ''GET_REPORT_COLORS'',',
'  { pageItems: ''#P4_ID_REPORTE'' },',
'  {',
'    dataType: ''json'',',
'    success: function(resp) {',
'      if (resp.status !== ''ok'') {',
'        console.error(''GET_REPORT_COLORS:'', resp.msg);',
'        return;',
'      }',
'',
'      var items = JSON.parse(resp.data);',
'',
'      $(''#dynamic-report-style'').remove();',
'',
'      var css = '''';',
'      items.forEach(function(item) {',
'        css +=',
'          ''#'' + item.id + '' {'' +',
'            ''background-color: '' + item.color + '' !important;'' +',
'            ''border: 1px solid '' + item.color + '' !important;'' +',
'            ''border-radius: 5px;'' +',
'            ''color: white !important;'' +',
'          ''}'';',
'      });',
'',
'      $(''<style id="dynamic-report-style">'').text(css).appendTo(''head'');',
'    }',
'  }',
');',
''))
);
