wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(560229037019408266)
,p_event_id=>wwv_flow_imp.id(560228580396408266)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'PR_Impresio/Color'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_nombres VARCHAR2(4000);',
'  l_colores VARCHAR2(4000);',
'  l_estilo  CLOB;',
'',
'  TYPE t_arr IS TABLE OF VARCHAR2(500) INDEX BY PLS_INTEGER;',
'  l_arr_nombres t_arr;',
'  l_arr_colores t_arr;',
'',
'  PROCEDURE split_csv(p_str IN VARCHAR2, p_arr OUT t_arr) IS',
'    v_str VARCHAR2(4000) := NVL(p_str, '''') || '','';',
'    v_ini NUMBER := 1;',
'    v_fin NUMBER;',
'    v_i   NUMBER := 1;',
'  BEGIN',
'    LOOP',
'      v_fin := INSTR(v_str, '','', v_ini);',
'      EXIT WHEN v_fin = 0;',
'      p_arr(v_i) := TRIM(SUBSTR(v_str, v_ini, v_fin - v_ini));',
'      v_ini := v_fin + 1;',
'      v_i   := v_i + 1;',
'    END LOOP;',
'  END;',
'BEGIN',
'  OC_IMPRESION_PAPELERIA3.GENERA_REPORTE(',
'      vPoliza                 => :P4_IDPOLIZA,',
'      vFecha_Ini              => :P4_FEC_DESDE,',
'      vFecha_Fin              => :P4_FEC_HASTA,',
'      vDet_Ini                => :P4_DET_INI,',
'      vDet_Fin                => :P4_DET_FIN,',
'      vAseg_Ini               => :P4_ASEG_INI,',
'      vAseg_Fin               => :P4_ASEG_FIN,',
'      vEndoso_Ini             => :P4_ENDOSO_INI,',
'      vEndoso_Fin             => :P4_ENDOSO_FIN,',
'      vCH_Asegurado           => :P4_ASEGURADO,',
'      vCH_Regla               => :P4_REGLA,',
'      vCH_Nutra               => :P4_NUTRA,',
'      vCH_Suma                => :P4_SUMA_ASEG,',
'      vUsuario                => :APP_USER,',
'      vRep_Pol_Vida_Grupo     => :P4_REP_POL_VIDA_GRUPO,',
'      vRep_Acci_Colectivo     => :P4_REP_ACCI_COLECTIVO,',
'      vRep_Acci_Col_Sub       => :P4_REP_ACCI_COL_SUB,',
'      vRep_Pol_Ind            => :P4_REP_POL_IND,',
'      vRep_Vida_Flex          => :P4_REP_VIDA_FLEX,',
'      vRep_Cer_Ind_Bloque     => :P4_REP_CER_IND_BLOQUE,',
'      vRep_Cons_Ind_Pol       => :P4_REP_CONS_IND_POL,',
'      vRep_Cons_Ind_ASE       => :P4_REP_CONS_IND_ASEG,  ',
'      vRep_Aseg_Prima         => :P4_REP_ASEG_PRIMA,',
'      vRep_Aseg_Sin_Prima     => :P4_REP_ASEG_SIN_PRIMA,',
'      vRep_Bienvenida         => :P4_REP_BIENVENIDA,',
'      vRep_Sini_Vida          => :P4_REP_SINI_VIDA,',
'      vRep_Sini_AP            => :P4_REP_SINI_AP,',
'      vRep_Endoso_Asis        => :P4_REP_ENDOSO_ASIS,',
'      vRep_Auto_Admin         => :P4_REP_AUTO_ADMIN,',
'      vRep_Cond_Especiales    => :P4_REP_COND_ESPECIALES,',
'      vRep_Endoso_Gral        => :P4_REP_ENDOSO_GRAL,',
'      vRep_Rec_Fact_Elec      => :P4_REP_REC_FACT_ELEC,',
'      vRep_Condiciones_Gral   => :P4_REP_CONDICIONES_GRAL,',
'      vRep_Aviso_Cobro        => :P4_REP_AVISO_COBRO,',
'      vRep_Aporte_Reg         => :P4_REP_APORTE_REG,',
'      vRep_Aviso_Dev          => :P4_REP_AVISO_DEV,',
'      vRep_Aporte_Extra       => :P4_REP_APORTE_EXTRA,',
'      vRep_Fondo_Colec        => :P4_REP_FONDO_COLEC,',
'      vRep_Cer_Ind_aseg      => :P4_REP_CER_IND_ASEG, ',
'     VNombre_Archivo         => :P4_CONDICIONES_GEN, ',
'     vRep_ARCHIVO_Condiciones_Gral=> :P4_CONDICIONES_GEN',
'  );',
'',
'  SELECT MAX(id)',
'    INTO :P4_ID_REPORTE',
'    FROM REPORTES_PDF',
'   WHERE CODUSUARIO = :APP_USER;',
'',
'  SELECT nombre_archivo, color',
'    INTO l_nombres, l_colores',
'    FROM REPORTES_PDF',
'   WHERE id = :P4_ID_REPORTE;',
'',
'  split_csv(l_nombres, l_arr_nombres);',
'  split_csv(l_colores, l_arr_colores);',
'',
'  l_estilo := '''';',
'',
'  FOR i IN 1 .. LEAST(l_arr_nombres.COUNT, l_arr_colores.COUNT) LOOP',
'    l_estilo := l_estilo ||',
'      ''label[for="'' || l_arr_nombres(i) || ''"]{'' ||',
'      ''background-color:'' || l_arr_colores(i) || '' !important;'' ||',
'      ''border:1px solid ''  || l_arr_colores(i) || '' !important;'' ||',
'      ''border-radius:5px !important;'' ||',
'      ''color:white !important;'' ||',
'      ''padding:2px 6px;'' ||',
'      ''}'';',
'  END LOOP;',
'',
'  :P4_ESTILOS_CS := l_estilo;',
':P4_URL_DESCARGA := APEX_PAGE.GET_URL(',
'    p_page      => 1390,',
'    p_items     => ''P1390_ID_REPORTE'',',
'    p_values    => :P4_ID_REPORTE,',
'    p_plain_url => TRUE',
');',
'END;'))
,p_attribute_02=>'P4_IDPOLIZA,P4_FEC_DESDE,P4_FEC_HASTA,P4_DET_INI,P4_DET_FIN,P4_ASEG_INI,P4_ASEG_FIN,P4_ENDOSO_INI,P4_ENDOSO_FIN,P4_ASEGURADO,P4_REGLA,P4_NUTRA,P4_SUMA_ASEG,P4_REP_POL_VIDA_GRUPO,P4_REP_ACCI_COLECTIVO,P4_REP_ACCI_COL_SUB,P4_REP_POL_IND,P4_REP_VIDA_FLE'
||'X,P4_REP_CER_IND_BLOQUE,P4_REP_CONS_IND_POL,P4_REP_ASEG_PRIMA,P4_REP_ASEG_SIN_PRIMA,P4_REP_BIENVENIDA,P4_REP_SINI_VIDA,P4_REP_SINI_AP,P4_REP_ENDOSO_ASIS,P4_REP_AUTO_ADMIN,P4_REP_COND_ESPECIALES,P4_REP_ENDOSO_GRAL,P4_REP_REC_FACT_ELEC,P4_REP_CONDICION'
||'ES_GRAL,P4_REP_AVISO_COBRO,P4_REP_APORTE_REG,P4_REP_AVISO_DEV,P4_REP_APORTE_EXTRA,P4_REP_FONDO_COLEC,P4_REP_CONS_IND_ASEG,P4_REP_CER_IND_ASEG,P4_CONDICIONES_GEN'
,p_attribute_03=>'P4_ID_REPORTE,P4_ESTILOS_CS,P4_URL_DESCARGA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
