,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- Lanzamos el trabajo en segundo plano',
'    DBMS_SCHEDULER.CREATE_JOB (',
'        job_name        => ''JOB_ZIP_'' || :APP_USER || ''_'' || TO_CHAR(SYSDATE,''HH24MISS''),',
'        job_type        => ''PLSQL_BLOCK'',',
'        job_action      => ''BEGIN PRC_GENERA_ZIP_CONSENTIMIENTOS(''''''||:P4_IDPOLIZA||'''''',''''''||:P4_DET_INI||'''''',''''''||:P4_DET_FIN||'''''',''''''||:P4_ENDOSO_INI||'''''',''''''||:P4_ENDOSO_FIN||'''''',''''''||:APP_USER||''''''); END;'',',
'        enabled         => TRUE,',
'        auto_drop       => TRUE',
'    );',
'',
'/*',
'apex_error.add_error (',
unistr('    p_error_code       => ''El proceso de generaci\00F3n ha iniciado en segundo plano. Podr\00E1s descargar el ZIP en unos minutos.'','),
'    p0                 => 1,',
'    p_display_location => apex_error.c_inline_with_field_and_notif,',
'    p_page_item_name   => ''P4_IDPOLIZA'' );*/',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(560160318056408148)
,p_internal_uid=>121092415181336720
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(560184551535408243)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GenerCertificados_1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_zip_blob        BLOB;',
'    l_idx             NUMBER := 0;',
'    l_reportes        APEX_APPLICATION_GLOBAL.VC_ARR2;',
'    l_sizes           APEX_APPLICATION_GLOBAL.VC_ARR2;',
'    nCount            NUMBER := 1;',
'    curl              VARCHAR2(4000);',
'    nUrl              NUMBER(2) := 0;',
'    vErrorMsj         VARCHAR2(4000);',
'    vErrorNum         NUMBER;',
'    vCntrol           VARCHAR2(4000);',
'    nnum              NUMBER;',
'    cArchivoFinal     VARCHAR2(1000);',
'    vPoliza           VARCHAR2(100) := :P4_IDPOLIZA;',
'        l_zip_file BLOB;',
'    BEGIN',
'        ',
'        DBMS_LOB.createtemporary(l_zip_file, FALSE);',
'        FOR l_file IN (',
'            SELECT NOMBRE file_name, ARCHIVO file_content',
'            FROM REPORTES_PDF',
'            WHERE CODUSUARIO = :APP_USER',
'              AND NOMBRE     != ''Consentimientos_''||vPoliza||''.zip''',
'        ) LOOP',
'            APEX_ZIP.ADD_FILE(',
'                p_zipped_blob => l_zip_file,',
'                p_file_name   => l_file.file_name,',
'                p_content     => l_file.file_content',
'            );',
'        END LOOP;',
'        ',
'        INSERT INTO REPORTES_PDF (ID, NOMBRE, ARCHIVO, CODUSUARIO, FECHA)',
'        VALUES (9999, ''Consentimientos_''||vPoliza||''.zip'', l_zip_file, :APP_USER, SYSDATE);',
'        COMMIT;',
'        ',
'        APEX_ZIP.FINISH(p_zipped_blob => l_zip_file);',
'        DBMS_LOB.freetemporary(l_zip_file);',
'        ',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            RAISE;',
'    END GENERA_ZIP;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Descargando ZIP'
,p_internal_uid=>121092854704336720
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(560184955612408243)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GenerCertificados_1_1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_filename  VARCHAR2(255);',
'    l_mime      VARCHAR2(50) := ''application/zip'';',
'BEGIN',
'    -- 1. Obtener el archivo de la tabla',
'    SELECT ARCHIVO, NOMBRE',
'      INTO l_blob, l_filename',
'      FROM REPORTES_PDF',
'     WHERE CODUSUARIO = :APP_USER',
'       AND NOMBRE LIKE ''%Consentimientos_Poliza_%''',
unistr('       AND ROWNUM = 1; -- Traer el m\00E1s reciente'),
'',
'    -- 2. Configurar las cabeceras HTTP para la descarga',
'    HTP.init;',
'    OWA_UTIL.mime_header(l_mime, FALSE);',
'    HTP.p(''Content-Length: '' || DBMS_LOB.getlength(l_blob));',
'    HTP.p(''Content-Disposition: attachment; filename="'' || l_filename || ''"'');',
'    OWA_UTIL.http_header_close;',
'',
'    -- 3. Descargar el archivo',
'    WPG_DOCLOAD.download_file(l_blob);',
'',
unistr('    -- 4. Detener el motor de APEX para que no pinte nada m\00E1s'),
'    APEX_APPLICATION.stop_apex_engine;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        -- Si no hay archivo, puedes mostrar un mensaje o dejar que APEX maneje el error',
'        NULL;',
'    WHEN APEX_APPLICATION.E_STOP_APEX_ENGINE THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Descargando ZIP'
,p_internal_uid=>121093258781336720
);
