,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_json.open_array;',
'',
'FOR r IN (',
'    SELECT COD_ASEGURADO',
'      FROM ASEGURADO_CERTIFICADO',
'     WHERE CODCIA   = :P4_CODCIA',
'       AND IDPOLIZA = :P4_IDPOLIZA',
'       AND ESTADO IN (''SOL'', ''EMI'', ''XRE'')',
'       AND IDETPOL BETWEEN :P4_DET_INI AND :P4_DET_FIN',
'       AND IDENDOSO BETWEEN :P4_ENDOSO_INI AND :P4_ENDOSO_FIN',
'       AND COD_ASEGURADO BETWEEN :P4_ASEG_INI AND :P4_ASEG_FIN',
'     ORDER BY IDETPOL, COD_ASEGURADO',
') LOOP',
'    apex_json.write(r.COD_ASEGURADO); ',
'END LOOP;',
'',
'apex_json.close_array;',
''))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(690440983571095281)
,p_internal_uid=>121097281009336723
