,p_process_name=>'GENERA_CONSENTIMIENTOS_'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_filename  VARCHAR2(255);',
'    l_mime      VARCHAR2(50) := ''application/zip'';',
'BEGIN',
'    -- 1. Obtener el archivo de la tabla',
'    SELECT ARCHIVO, NOMBRE',
'      INTO l_blob, l_filename',
'      FROM REPORTES_PDF',
'     WHERE CODUSUARIO = :APP_USER',
'       AND NOMBRE LIKE ''%Consentimientos_Poliza_%''',
unistr('       AND ROWNUM = 1; -- Traer el m\00E1s reciente'),
'',
'    -- 2. Configurar las cabeceras HTTP para la descarga',
'    HTP.init;',
'    OWA_UTIL.mime_header(l_mime, FALSE);',
'    HTP.p(''Content-Length: '' || DBMS_LOB.getlength(l_blob));',
'    HTP.p(''Content-Disposition: attachment; filename="'' || l_filename || ''"'');',
'    OWA_UTIL.http_header_close;',
'',
'    -- 3. Descargar el archivo',
'    WPG_DOCLOAD.download_file(l_blob);',
'',
unistr('    -- 4. Detener el motor de APEX para que no pinte nada m\00E1s'),
'    APEX_APPLICATION.stop_apex_engine;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        -- Si no hay archivo, puedes mostrar un mensaje o dejar que APEX maneje el error',
'        NULL;',
'    WHEN APEX_APPLICATION.E_STOP_APEX_ENGINE THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(560160318056408148)
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Descargando ZIP',
''))
,p_internal_uid=>121094425777336721
);
