'  P_USUARIO VARCHAR2(200);',
'BEGIN',
'',
'  P_POLIZA := :P4_IDPOLIZA;',
'  P_DET_INI := :P4_DET_INI;',
'  P_DET_FIN := :P4_DET_FIN;',
'  P_ENDOSO_INI := :P4_ENDOSO_INI;',
'  P_ENDOSO_FIN := :P4_ENDOSO_FIN;',
'  P_USUARIO := :APP_USER;',
'',
'  PRC_GENERA_ZIP_CONSENTIMIENTOS(',
'    P_POLIZA => P_POLIZA,',
'    P_DET_INI => P_DET_INI,',
'    P_DET_FIN => P_DET_FIN,',
'    P_ENDOSO_INI => P_ENDOSO_INI,',
'    P_ENDOSO_FIN => P_ENDOSO_FIN,',
'    P_USUARIO => P_USUARIO',
'  );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
