wwv_flow_imp_page.create_page(
 p_id=>100
,p_name=>'Seguros y Fianzas'
,p_alias=>'SEGUROS-Y-FIANZAS'
,p_step_title=>'Seguros y Fianzas'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(554442154264684290)
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--Valida todos los botones que se encuentran en la pagina 100 ',
'--validacionEndoso',
'--validacionpoliza',
'--validacion_certificado',
'--validacion_recibo_prima',
'--validacion_recibo_obligaciones',
'#APP_FILES#Validacion_botones#MIN#.js',
'---pload_page carga todo el js al principio de la pagina ',
'#APP_FILES#Pload_page#MIN#.js',
'#APP_FILES#app_utils#MIN#.js',
'',
'--Archivo de funcionalidades.',
'#APP_FILES#appToolkit#MIN#.js',
'',
'--Achivo de Catalogos.',
'#APP_FILES#AppComponentCatalog#MIN#.js'))
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function controlarBoton(divContenedorId, nombreAtributo, valorAtributo, itemsAPEX) {',
'    var contenedor = document.getElementById(divContenedorId);',
'    if (!contenedor) {',
unistr('        console.warn("No se encontr\00F3 el div contenedor:", divContenedorId);'),
'        return;',
'    }',
'    ',
'    // Selector por atributo (button[nombreAtributo="valor"])',
'    var selector = ''button['' + nombreAtributo + ''="'' + valorAtributo + ''"]'';',
'    var boton = contenedor.querySelector(selector);',
'    ',
'    if (!boton) {',
'        console.warn(',
unistr('            "No se encontr\00F3 el bot\00F3n con",'),
'            nombreAtributo + "=" + valorAtributo',
'        );',
'        return;',
'    }',
'    ',
'    // Establecer fondo amarillo',
'    boton.style.background = "#201747";',
'    boton.style.color="white";',
'    ',
'    // Validar que AL MENOS UN item tenga valor (some = "alguno")',
'    // Si quieres que TODOS tengan valor, cambia ''some'' por ''every''',
'    var habilitar = itemsAPEX.some(function(item) {',
'        var valor = apex.item(item).getValue();',
'        return valor != null && valor != "";',
'    });',
'    ',
'    if (habilitar == ''PAG'') {',
'        boton.disabled = false;',
'        ',
'        // Remover event listeners previos para evitar duplicados',
'        var nuevoBoton = boton.cloneNode(true);',
'        boton.parentNode.replaceChild(nuevoBoton, boton);',
'        boton = nuevoBoton;',
'        ',
'        boton.addEventListener("click", function () {',
'            itemsAPEX.forEach(function(item) {',
'                apex.item(item).setValue(null);',
'            });',
'            apex.region("POLIZAS_IG").refresh();',
'        });',
'    } else {',
'        boton.disabled = true;',
'    }',
'}',
'',
'function cargarDatosDesdeIGPOLIZAS(staticIdIG){',
'',
'    setTimeout(function(){',
'',
'        var region = apex.region(staticIdIG);',
'        if (!region) {',
unistr('            console.warn("No se encontr\00F3 la regi\00F3n:", staticIdIG);'),
'            return;',
'        }',
'',
'        var ig$  = region.widget();',
'        var grid = ig$.interactiveGrid("getViews","grid");',
'        var model = grid.model;',
'',
'        //console.log(grid.view$.grid("getSelectedRecords"));',
'        var selectedRecords = grid.view$.grid("getSelectedRecords");',
'',
'        if (!selectedRecords || selectedRecords.length === 0){',
'            return;',
'        }',
'        ',
'        var record = selectedRecords[0];',
'',
'        ',
'        // apex.message.alert("HOLA: "+staticIdIG)',
'        const fields = {',
'            //POLIZA',
'            P100_PRIMA_MIN_ANUAL: "INDPRIMIN", P100_INI_VIGENCIA: "FECINIVIG", P100_FIN_VIGENCIA: "FECFINVIG", ',
'            P100_FEC_SOLICITUD: "FECSOLICITUD", P100_FEC_EMISION: "FECEMISION", P100_FECHA_RENOVACION: "FECRENOVACION",',
'            P100_FEC_ANULA: "FECANUL", P100_NUM_RENOVACION: "NUMRENOV", P100_NUM_COTIZACION: "NUM_COTIZACION", P100_ESTADO: "STSPOLIZA",',
'            P100_ESTATUS_CTRL: "COD_ESTATUS_POLIZA", P100_NUM_SOLICITUD: "NUMSOLICITUD", P100_DISTRIBPOL: "DISTRIBPOL",',
'            P100_COD_AGENTE: "COD_AGENTE", P100_DESC_COD_AGENTE: "DESC_AGENTE", P100_CTRLCLIENTE: "CODCLIENTECTRL", P100_USO_CFDI_P: "DESC_CODUSOCFDI",',
'            P100_OBJETO_IMP_P: "DESC_CODOBJETOIMP",P100_IDTIPOSEG: "TIPO_SEGURO",',
'            //DATOS_POLIZA  ',
'            P100_CODCIA: "CODCIA", P100_EMPRESA_DP: "CODEMPRESA", P100_IDPOLIZA: "IDPOLIZA", P100_TIPOPOLIZA: "TIPOPOL", P100_POLFONDOS: "INDMANEJAFONDOS",  ',
'            P100_NUMPOLUNICO: "NUMPOLUNICO", P100_FECINIVIG: "FECINIVIG", P100_FECFINVIG: "FECFINVIG", P100_HORAINI: "HORAVIGINI", P100_HORAFIN: "HORAVIGFIN",',
'            P100_MONEDA: "DESC_CODMONEDA", P100_NUMPOLREF: "NUMPOLREF", P100_PRORRATA: "TIPOPRORRATA", P100_PLANPAGO: "DESC_CODPLANPAGO", P100_POLPLD: "PLDSTBLOQUEADA",  ',
'            P100_AUTORIZADA: "PLDSTAPROBADA", P100_AUTORIZOPLD: "PLDUSUARIOAPROB", P100_CLIENTE: "CODCLIENTE", P100_FOLIOPORTAL: "NUMFOLIOPORTAL",',
'            P100_GRUPECO: "CODGRUPOEC", P100_DESC_GRUPOECO: "DESC_GRUPOECO", P100_CANALVENTA: "FORMAVENTA", P100_DESC: "DESCPOLIZA", P100_TIPODIV: "TIPODIVIDENDO",  ',
