'                ,P.PLDSTAPROBADA ',
'                ,P.PLDUSUARIOAPROB ',
'                ,CODCLIENTE || '''' - '''' || SICAS_OC.OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE) AS CODCLIENTE',
'                ,P.NUMFOLIOPORTAL ',
'                ,P.CODGRUPOEC',
'                ,P.CODGRUPOEC || '''' - ''''  || SICAS_OC.OC_GRUPO_ECONOMICO.NOMBRE_GRUPO_ECONOMICO(NVL(1,1), CODGRUPOEC) DESC_GRUPOECO',
'                ,P.FORMAVENTA             ',
'                ,P.DESCPOLIZA',
'                ,P.TIPODIVIDENDO',
'                ,P.IDFORMACOBRO ',
'                ,P.MOTIVANUL, ',
'                    OC_MANTENIMIENTO_BOTONES_POLIZA.DESCRIPCION_ANULACION(P.MOTIVANUL) MOTIVO',
