'                ,P.INDFACTELECTRONICA ',
'                ,P.INDCALCDERECHOEMIS ',
'                ,P.CODPAQCOMERCIAL ',
'                ,P.CODTIPONEGOCIO ',
'                ,P.CODCATEGO || '''' - '''' || GT_CATEGORIAS.CONSULTA_DESCRIP(1,1,P.CODTIPONEGOCIO,P.CODCATEGO) CODCATEGO',
'                ,P.COASEGURO ',
'                ,P.FECSOLICITUD',
'                ,P.FECEMISION',
'                ,P.FECANUL  ',
'                ,P.DEDUCIBLE ',
'                ,P.FECSTS',
'                ,P.FECRENOVACION',
'                ,P.SUMAASEG_MONEDA',
'                ,P.SUMAASEG_LOCAL',
'                ,P.PRIMANETA_MONEDA',
'                ,P.PRIMANETA_LOCAL',
'                ,P.NUM_COTIZACION',
'                ,P.DIACOBROAUTOMATICO',
'                ,P.STSPOLIZA COD_ESTATUS_POLIZA ',
'                ,P.STSPOLIZA || '''' - '''' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''''ESTADOS'''', STSPOLIZA) STSPOLIZA',
'                ,P.INDPRIMIN',
'                ,P.PORCGTOADMIN',
'                ,P.PORCUTILIDAD',
'                ,P.CODRIESGOREA',
'                ,P.PORCDESCUENTO',
'                ,P.PORCGTOADQUI',
'                ,P.INDEXTRAPRIMA ',
'                ,P.INDCONVENCIONES',
'                ,P.CODTIPOBONO',
'                ,P.CODUSOCFDI',
'                ,P.CODUSOCFDI || '''' - '''' || OC_FACT_ELECT_USO_CFDI.DESCRIPCION(P.CODCIA, CODUSOCFDI) DESC_CODUSOCFDI',
'                ,P.CODOBJETOIMP',
'                ,CODOBJETOIMP || '''' - '''' || OC_FACT_ELECT_OBJETO_IMPUESTO.DESCRIPCION(P.CODCIA, P.CODOBJETOIMP) DESC_CODOBJETOIMP',
'                ,P.FACTORAJUSTE',
'                ,P.MONTODEDUCIBLE',
'                ,P.FACTFORMULADEDUC',
'                ,P.DIASVIG',
'                ,P.HORASVIG',
'                ,P.ASEGADHERIDOSPOR',
'                ,P.PORCENCONTRIBUTORIO',
'                ,P.FUENTERECURSOSPRIMA',
'                ,CODOFICINA || '''' - '''' || SICAS_OC.GT_OFICINAS.CONSULTA(CODOFICINA) DESC_OFICINA',
'                ,P.COD_AGENTE',
'                ,COD_AGENTE || '''' - ''''  || SICAS_OC.OC_AGENTES.NOMBRE_AGENTE(1, P.COD_AGENTE) DESC_AGENTE',
'                ,OC_SOLICITUD_EMISION.SOLICITUD_POLIZA(1, 1, P.IDPOLIZA) AS NUMSOLICITUD',
'                ,GT_REA_DISTRIBUCION.EXISTE_DISTRIB_POLIZA(1, P.IDPOLIZA, 0, 0) AS DISTRIBPOL',
'                ,P.CODCLIENTE AS CODCLIENTECTRL',
'                ,CASE WHEN P.STSPOLIZA = ''''ANU'''' THEN',
'                        ''''VA_ANULADO''''',
'                    WHEN OC_FUNCIONALIDADES_MANTENIMIENTO_POLIZA.FUNC_VALIDA_SINIESTRO(1,P.IDPOLIZA) = ''''S'''' THEN',
'                        ''''VA_SINIESTRO''''',
'                    WHEN (P.STSPOLIZA = ''''XRE'''') OR',
'                        ((P.FecRenovacion <= TO_DATE(OC_POLIZAS_COMPLEMENTO.HOY,''''dd/mm/yyyy'''')) AND P.STSPOLIZA = ''''EMI'''') THEN',
'                        ''''VA_PORRENOVAR''''',
'                ELSE',
'                DECODE(',
'                    P.STSPOLIZA,',
'                    ''''SOL'''', ''''VA_SOLICITUD'''',',
'                    ''''EMI'''', ''''VA_EMITIDA'''',',
'                    ''''PRE'''', ''''VA_PREEMITIDA'''',',
'                    ''''REN'''', ''''VA_RENOVADA'''',',
'                    ''''PLD'''', ''''VA_PLD'''',',
'                    -- ''''XRE'''', ''''VA_PORRENOVAR'''',',
'                    NULL',
'                ) END AS COLOR',
'                ,NVL((SELECT IDTIPOSEG FROM DETALLE_POLIZA WHERE IDPOLIZA=P.IDPOLIZA AND ROWNUM=1),''''NO EXISTE CERTIFICADO'''') TIPO_SEGURO',
'            FROM ',
'            POLIZAS P',
'            WHERE 1=1'';',
'',
'    IF :P100_IDPOLIZA_BUSQD IS NOT NULL THEN',
'        s_qly := s_qly|| '' AND IDPOLIZA = :P100_IDPOLIZA_BUSQD'';        -- No. Consecutivo',
'    END IF;',
'',
'    IF :P100_NUMPOLUNICO_BUSQD IS NOT NULL THEN',
unistr('        s_qly := s_qly|| '' AND NUMPOLUNICO = :P100_NUMPOLUNICO_BUSQD'';  -- No. P\00F3liza Unico'),
'    END IF;',
'',
'    IF :P100_IDTIPOSEG_BUSQD IS NOT NULL THEN',
'        s_qly := s_qly|| '' AND IDPOLIZA IN   (SELECT IdPoliza',
'                                            FROM DETALLE_POLIZA',
'                                            WHERE IdTipoSeg =  :P100_IDTIPOSEG_BUSQD)''; -- Producto',
'    END IF;',
'',
'    IF :P100_ESTADO_BUSQD IS NOT NULL THEN',
'        s_qly := s_qly|| '' AND StsPoliza IN (SELECT column_value FROM apex_string.split(:P100_ESTADO_BUSQD, '''':''''))'';   -- Estados',
'    END IF;',
'',
'    IF :P100_CODIGO_AGENTE_BUSQD IS NOT NULL THEN',
'        s_qly := s_qly|| '' AND IDPOLIZA IN   (SELECT IdPoliza',
'                                            FROM AGENTES_DISTRIBUCION_POLIZA',
unistr('                                            WHERE Cod_Agente_Distr =  :P100_CODIGO_AGENTE_BUSQD)'';  -- C\00F3digo Agente'),
'    END IF;',
'',
'    IF :P100_CLIENTE_BUSQD IS NOT NULL THEN',
'        s_qly := s_qly|| '' AND CodCliente = :P100_CLIENTE_BUSQD'';       -- Cliente',
'    END IF;',
'',
'    IF :P100_AGRUPADOR_BUSQD IS NOT NULL THEN',
'        s_qly := s_qly|| '' AND CodAgrupador = :P100_AGRUPADOR_BUSQD'';   -- Agrupador',
'    END IF;',
'',
'    RETURN s_qly;',
'',
'END;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P100_IDPOLIZA_BUSQD,P100_NUMPOLUNICO_BUSQD,P100_IDTIPOSEG_BUSQD,P100_ESTADO_BUSQD,P100_CODIGO_AGENTE_BUSQD,P100_CLIENTE_BUSQD,P100_AGRUPADOR_BUSQD'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
