wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(612046505097331089)
,p_plug_name=>'IG_DETALLE_POLIZA'
,p_region_name=>'ig_detalle_poliza'
,p_parent_plug_id=>wwv_flow_imp.id(606052808227377708)
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690539339353096000)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'ROWID,',
'IDETPOL',
'      ,IDPOLIZA',
'      ,CODCIA',
'      ,NUMDETREF',
'      ,IDTIPOSEG ',
'      ,IDTIPOSEG || '' - '' || OC_TIPOS_DE_SEGUROS.TIPO_DE_SEGURO(1, 1, IDTIPOSEG) TIPO_SEGURO',
'      ,FECINIVIG',
'      ,FECFINVIG ',
'      ,CODFILIAL',
'      ,CODCATEGORIA',
'      ,CODCATEGORIA || '' - '' || OC_FILIALES_CATEGORIAS.DESCRIPCION_CATEGORIA(NVL(1, 1), :P100_GRUPECO, CODFILIAL, CODCATEGORIA) DESC_CODCATEGORIA',
'      ,SUMA_ASEG_MONEDA',
'      ,PRIMA_MONEDA',
'      ,SUMA_ASEG_LOCAL',
'      ,PRIMA_LOCAL',
'      ,MONTOAPORTEFONDO',
'      ,MONTOPRIMACOMPMONEDA',
'      ,STSDETALLE COD_ESTATUS_CERTIFICADO ',
'      ,STSDETALLE || '' - '' ||  OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',STSDETALLE) STSDETALLE',
'      ,COD_ASEGURADO ',
'      ,COD_ASEGURADO || '' - '' || OC_ASEGURADO.NOMBRE_ASEGURADO(1, 1, COD_ASEGURADO) NOMBRE_ASEG',
'      ,INDDECLARA',
'      ,INDSINASEG',
'      ,INDFACTELECTRONICA',
'      ,PORCCOMIS',
'      ,MONTOCOMIS',
'      ,INDASEGMODELO',
'      ,CODPLANPAGO',
'      --,CODPLANPAGO || '' - '' || SICAS_OC.DESC_PLAN_PAGOS(1, 1, CODPLANPAGO) DESC_CODPLANPAGO',
'      ,IDDIRECAVICOB -- || '' - '' || OC_DIRECCIONES_PNJ.DIRECCION_PERSONA(cTipo_Doc_Identificacion, cNum_Doc_Identificacion, IDDIRECAVICOB) IDDIRECAVICOB',
'      ,CANTASEGMODELO',
'      ,CODPROMOTOR ',
'      ,CODPROMOTOR || '' - '' || SICAS_OC.OC_PROMOTORES.NOMBRE_PROMOTOR(1, CODPROMOTOR) DESC_CODPROMOTOR',
'      ,TASA_CAMBIO',
'      ,IDFORMACOBRO',
'      ,PLANCOB',
'      --,PLANCOB || '' - ''|| SICAS_OC.FUNC_NOMBRE_PLAN(PLANCOB, 1, IDTIPOSEG, 1)  DESC_PLANCOB                ',
'      ,FECANUL',
'      ,PORCCOMISH',
'      ,MONTOCOMISH',
'      ,MOTIVANUL',
'      ,CODUSOCFDI',
'      ,CODUSOCFDI || '' - '' || OC_FACT_ELECT_USO_CFDI.DESCRIPCION(1, CODUSOCFDI) DESC_CFDI',
'      ,CODOBJETOIMP',
'      ,CODOBJETOIMP || '' - '' || OC_FACT_ELECT_OBJETO_IMPUESTO.DESCRIPCION(1, CODOBJETOIMP) DESC_CODOBJETOIMP',
'      ,OC_TIPOS_DE_SEGUROS.SEGURO_COLECTIVO(CODCIA,CODEMPRESA,IDTIPOSEG) TIPOSEGCOL',
'      ,case',
'                    WHEN STSDETALLE = ''SOL'' THEN',
'                    ''<i class="fa fa-edit">''',
'                    ELSE NULL ',
'       END AS  ETIQUETAS_DETPOL',
'      ,DECODE(',
'        STSDETALLE,',
'        ''SOL'', ''VA_SOLICITUD'',',
'        ''ANU'', ''VA_ANULADO'',',
'        ''EMI'', ''VA_EMITIDA'',',
'        ''PRE'', ''VA_PREEMITIDA'',',
'        ''REN'', ''VA_RENOVADA'',',
'        ''SUS'', ''VA_SUSPENDIDA'',',
'        ''CEX'', ''VA_EXCLUIDA_COBERTURA'',',
'        ''XRE'', ''VA_PORRENOVAR'',',
'        NULL',
'    ) AS COLOR',
'FROM DETALLE_POLIZA',
'WHERE IDPOLIZA = :P100_IDPOLIZACERT'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P100_IDPOLIZACERT,P100_GRUPECO'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'IG_DETALLE_POLIZA'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
