,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'ROWID,',
'CODEMPRESA,',
'CODCIA,',
'IDPOLIZA,',
'IDETPOL,',
'IDTIPOSEG,',
'TIPOREF,',
'NUMREF,',
'OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(CODCIA, CODEMPRESA, IDTIPOSEG, PLANCOB,CODCOBERT ) DESC_COBERT,',
'CODCOBERT,',
'SUMAASEG_LOCAL,',
'SUMAASEG_MONEDA,',
'TASA,',
'PRIMA_MONEDA,',
'PRIMA_LOCAL,',
'IDENDOSO,',
'STSCOBERTURA,',
'STSCOBERTURA || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSCOBERTURA) DESC_STSCOBERTURA,',
'PLANCOB,',
'COD_MONEDA,',
'DEDUCIBLE_LOCAL,',
'DEDUCIBLE_MONEDA,',
'COD_ASEGURADO,',
'INDCAMBIOSAMI,',
'SUMAASEGORIGEN,',
'SALARIOMENSUAL,',
'VECESSALARIO,',
'SUMAASEGCALCULADA,',
'EDAD_MINIMA,',
'EDAD_MAXIMA,',
'EDAD_EXCLUSION,',
'SUMAASEG_MINIMA,',
'SUMAASEG_MAXIMA,',
'PORCEXTRAPRIMADET,',
'MONTOEXTRAPRIMADET,',
'SUMAINGRESADA,',
'PRIMANIVMONEDA,',
'PRIMANIVLOCAL,',
'IDRAMOREAL,',
'FRANQUICIAINGRESADO,',
'MONTODIARIO,',
'DIAS_CAL, ',
'DECODE(',
'                    STSCOBERTURA,',
'                    ''SOL'', ''VA_SOLICITUD'',',
'                    ''ANU'', ''VA_ANULADO'',',
'                    ''EMI'', ''VA_EMITIDA'',',
'                    ''PRE'', ''VA_PREEMITIDA'',',
'                    ''REN'', ''VA_RENOVADA'',',
'                    ''PLD'', ''VA_PLD'',',
'                    ''XRE'', ''VA_PORRENOVAR'',',
'                    NULL',
'                ) AS COLOR',
'FROM COBERT_ACT',
'WHERE ',
'    IDPOLIZA    = :P100_IDPOLIZA',
'AND IDETPOL     = :P100_IDETPOL',
'AND CODCIA      = :P100_CODCIA',
'AND CODEMPRESA  = :P100_CODEMPRESA',
