wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(605755489479537622)
,p_plug_name=>'IG_FACTURAS'
,p_region_name=>'IG_FACTURAS'
,p_parent_plug_id=>wwv_flow_imp.id(605754687828537614)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>100
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT F.IDFACTURA',
'      ,F.NUMCUOTA',
'      ,F.NUMFACT',
unistr('      ,F.ID_A\00D1O_POLIZA'),
'      ,F.COD_MONEDA',
'      --,F.COD_MONEDA || '' - '' || SICAS_OC.FUNC_DESCRIPCION_MONEDA(F.COD_MONEDA) DESC_MONEDA',
'      ,F.FECVENC',
'      ,F.FECFINVIG',
'      ,F.MONTO_FACT_LOCAL',
'      ,F.MTOCOMISI_LOCAL',
'      ,F.STSFACT',
'      ,F.STSFACT || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSFACT) DESC_STSFACT',
'      ,F.IDETPOL',
'      ,F.IDENDOSO',
'      ,E.NUMENDREF',
'      ,F.TASA_CAMBIO',
'      ,DECODE(',
'        F.STSFACT,      ',
'        ''EMI'', ''VA_EMITIDA'',',
'        ''ANU'', ''VA_ANULADO'',',
'        ''SUS'', ''VA_SUSPENDIDA'',',
'        ''PAG'', ''VA_PAGADO'',',
'        ''PRE'', ''VA_SOLICITUD'',',
'        NULL',
'    ) AS COLOR',
'      ,F.CODCLIENTE || '' - '' || SICAS_OC.OC_CLIENTES.NOMBRE_CLIENTE(CODCLIENTE) AS CODCLIENTE',
'      ,F.MONTOPRIMACOMPMONEDA',
'      ,F.IDTRANSACCION',
'      ,F.CODPLANPAGO',
'      ,F.CODGENERADOR || '' - '' || SICAS_OC.OC_AGENTES.NOMBRE_AGENTE(1,CODGENERADOR) AS CODGENERADOR',
'      ,F.FECPAGO',
'      ,F.FECSTS',
'      ,F.MOTIVANUL',
'      ,F.MOTIVANUL || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''MOTIVANU'', F.MOTIVANUL) AS DESC_MOTIVANUL',
'      ,F.FECANUL',
'      ,F.IDTRANSACCIONANU',
'      ,F.FECCONTABILIZADA',
'      ,F.FECGENAVICOB',
'      ,F.INDCONTABILIZADA',
'      ,F.INDGENAVICOB',
'      ,F.CODUSUARIOENVFACT',
'      ,F.FOLIOFACTELEC',
'      ,F.CODUSUARIOENVFACTANU',
'      ,F.FECENVFACTELEC',
'      ,F.INDFACTELECTRONICA',
'      ,F.FECENVFACTELECANU',
'      ,F.LOGPROCESOFACTELEC',
'      ,F.INDDOMICILIADO',
'      ,F.CODCOBRADOR ',
'      ,F.MONTOPRIMACOMPLOCAL',
'FROM FACTURAS F',
'LEFT JOIN ENDOSOS E ',
'       ON F.IDPOLIZA = E.IDPOLIZA',
'      AND F.IDENDOSO = E.IDENDOSO          ',
'WHERE F.IDPOLIZA = :P100_NUM_POLIZA_RP',
'  AND (',
'        NVL(:P100_FLAG_TAB_CERTIFICADO, ''0'') <> ''1''',
'       OR F.IDETPOL = :P100_IDETPOL',
'     )',
'            ',
'/*',
'WHERE F.IDPOLIZA = :P100_NUM_POLIZA_RP  ',
'  AND ( :P100_IDENDOSO_RP_CTRL IS NULL ',
'        OR F.IDENDOSO = :P100_IDENDOSO_RP_CTRL )',
'*/'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P100_NUM_POLIZA_RP,P100_FLAG_TAB_CERTIFICADO,P100_IDETPOL'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'IG_FACTURAS'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
