wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(607732975274272112)
,p_plug_name=>'IG_NOTAS_DE_CREDITO'
,p_region_name=>'IG_NOTAS_DE_CREDITO'
,p_parent_plug_id=>wwv_flow_imp.id(607731700435272099)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT IDNCR',
'      ,IDPOLIZA',
'      ,IDETPOL',
'      ,IDENDOSO',
'      ,NUMNCR',
'      ,CODCLIENTE',
'      ,CODCLIENTE || '' - '' || SICAS_OC.OC_CLIENTES.NOMBRE_CLIENTE(CODCLIENTE) AS DESC_CLIENTE',
'      ,COD_AGENTE || '' - '' || SICAS_OC.OC_AGENTES.NOMBRE_AGENTE(CODCIA, COD_AGENTE) AS DESC_AGENTE',
'      ,CODPLANPAGO || '' - '' || SICAS_OC.OC_PLAN_DE_PAGOS.DESCRIPCION_PLAN(1, 1, CODPLANPAGO) AS DESC_CODPLANPAGO',
'      ,CODCLIENTE || '' - '' || SICAS_OC.OC_PROVEEDORES.NOMBRE_PROVEEDOR(1, CODCLIENTE) AS PROVEEDOR',
unistr('      ,ID_A\00D1O_POLIZA'),
'      ,CODCIA',
'      ,CODMONEDA',
'      ,FECDEVOL',
'      ,MONTO_NCR_LOCAL',
'      ,MTOCOMISI_LOCAL',
'      ,NUMPRESTAMO ',
'      ,STSNCR',
'      ,FECFINVIG',
'      ,STSNCR || '' - '' ||  OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',STSNCR) STSNCRNC',
'      ,FECSTS',
'      ,MOTIVANUL',
'      ,CTALIQUIDADORA',
'      ,CODUSUARIOENVFACT',
'      ,FOLIOFACTELEC',
'      ,CODUSUARIOENVFACTANU',
'      ,INDFACTELECTRONICA',
'      ,FECENVFACTELEC',
'      ,FECENVFACTELECANU',
'      ,LOGPROCESOFACTELEC, ',
'      IDNCRREHAB, ',
'      IDNOMINA,',
'      --Color de estado',
'    DECODE(',
'        STSNCR,      ',
'        ''EMI'', ''VA_EMITIDA'',',
'        ''ANU'', ''VA_ANULADO'',',
'        ''SUS'', ''VA_SUSPENDIDA'',',
'        ''PAG'', ''VA_PAGADO'',',
'        ''PRE'', ''VA_SOLICITUD'',',
'        ''APL'', ''VA_APLICADA'',',
'        NULL)  AS COLOR',
'FROM NOTAS_DE_CREDITO',
'where idpoliza = :P100_IDPOLIZANC',
'AND ( :P100_IDENDOSO_NC_CTRL IS NULL ',
'      OR IDENDOSO = :P100_IDENDOSO_NC_CTRL )'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P100_IDPOLIZANC,P100_IDENDOSO_NC_CTRL'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'IG_NOTAS_DE_CREDITO'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
