,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT E.IDPOLIZA',
'      ,E.TIPOENDOSO',
'      ,E.TIPOENDOSO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPENDOS'', E.TIPOENDOSO) DESC_TIPOENDOSO',
'      ,E.IDENDOSO',
'      ,E.NUMENDREF',
'      ,E.FECINIVIG',
'      ,E.FECFINVIG',
'      ,E.FECSOLICITUD',
'      ,E.FECEMISION',
'      ,E.SUMA_ASEG_LOCAL',
'      ,E.PRIMA_NETA_LOCAL',
'      ,E.STSENDOSO',
'      ,E.STSENDOSO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', E.STSENDOSO) DESC_STSENDOSO ',
'      ,OC_ENDOSO.TOTAL_ASEGURADOS(E.CODCIA, E.CODEMPRESA, E.IDPOLIZA, E.IDETPOL, E.IDENDOSO) TOTAL_ASEGURADO',
'      ,E.SUMA_ASEG_MONEDA',
'      ,E.PRIMA_NETA_MONEDA',
'      ,E.CVE_MOTIVCANCFACT',
'      ,E.MONTOAPORTEFONDO',
'      ,E.PORCCOMIS',
'      ,E.IDETPOL',
'      ,E.MOTIVO_ENDOSO',
'      ,OC_VALORES_DE_LISTAS.LOV_MOTIVO_ENDOSO(E.TIPOENDOSO, E.MOTIVO_ENDOSO) DESC_MOTIVO_ENDOSO',
'      ,E.CODPLANPAGO ',
'      ,E.MOTIVANUL',
'      ,E.MOTIVANUL || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''MOTANUEN'', E.MOTIVANUL) DESC_MOTIVANUL',
'      ,E.CODUSOCFDI',
'      ,E.CODUSOCFDI || '' - '' || OC_FACT_ELECT_USO_CFDI.DESCRIPCION(1, E.CODUSOCFDI) DESC_CODUSOCFDI',
'      ,E.CODOBJETOIMP',
'      ,E.CODOBJETOIMP || '' - '' || OC_FACT_ELECT_OBJETO_IMPUESTO.DESCRIPCION(1, E.CODOBJETOIMP) DESC_CODOBJETOIMP',
'      ,E.CODOBJETOIMP || '' - '' || OC_FACT_ELECT_OBJETO_IMPUESTO.DESCRIPCION(1, E.CODOBJETOIMP) DESC_CODOBJETOIMP2',
'      ,E.FECANUL',
'      ,E.DESCENDOSO',
'      ,E.FECSTS',
'      ,E.FECEXC',
'      ,E.INDCALCDERECHOEMIS',
'      ,E.PLDSTBLOQUEADA',
'      ,E.PLDSTAPROBADA',
'      ,E.PLDUSUARIOAPROB',
'      ,DECODE(',
'        E.STSENDOSO,',
'        ''SOL'', ''VA_SOLICITUD'',',
'        ''ANU'', ''VA_ANULADO'',',
'        ''EMI'', ''VA_EMITIDA'',',
'        NULL',
'      ) AS COLOR',
'      ,CASE ',
'          WHEN E.STSENDOSO = ''SOL'' THEN ''<i class="fa fa-edit"></i>''',
'          ELSE NULL ',
'       END AS ETIQUETA_EDITAR',
'      ,OC_ENDOSO.TOTAL_ASEGURADOS(1,1,E.IDPOLIZA,E.IDETPOL,E.IDENDOSO) TOTAL_ASEGURADOS',
'      ,OC_ASEGURADO.NOMBRE_ASEGURADO(1, 1, DP.COD_ASEGURADO) NOMBRE_ASEG',
'      ,DP.IDTIPOSEG || '' - '' || OC_TIPOS_DE_SEGUROS.TIPO_DE_SEGURO(1, 1, DP.IDTIPOSEG) TIPO_SEGURO',
'FROM ENDOSOS E',
'INNER JOIN DETALLE_POLIZA DP ON E.IDPOLIZA = DP.IDPOLIZA',
'                             AND (E.IDETPOL = DP.IDETPOL OR E.IDETPOL = 0)',
'WHERE E.IDPOLIZA = :P100_IDPOLIZA;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P100_IDPOLIZA'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
