wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(617658523923476524)
,p_validation_name=>unistr('Validaci\00F3n_BTN_Rehabilitar')
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_sts    polizas.stspoliza%TYPE;',
'    v_motivo polizas.motivanul%TYPE;',
'BEGIN',
'    SELECT a.stspoliza, a.motivanul',
'    INTO   v_sts, v_motivo',
'    FROM   polizas a',
'    WHERE  a.codcia   = :P100_CODCIA',
'    AND    a.idpoliza = :P100_IDPOLIZA;',
'',
unistr('    -- No permitir rehabilitar si est\00E1 anulada por REEXPEDICI\00D3N'),
'    IF v_sts = ''ANU'' AND v_motivo = ''REEX'' THEN',
'        RETURN FALSE;',
'    END IF;',
'',
'    RETURN TRUE;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN FALSE;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('No puede Rehabilitar una poliza Anulada por motivo de Reexpedici\00F3n')
,p_when_button_pressed=>wwv_flow_imp.id(690757846085128297)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
