,p_execute_on_page_init=>'N'
,p_name=>'COUN_validarRegistrosGrid()'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin ',
'/*CUENTA CERTIFICADOS*/',
'    SELECT COUNT (*)',
'    INTO :P100_COUNT_CERTIFICADOS',
'    FROM DETALLE_POLIZA',
'    WHERE IDPOLIZA = :P100_IDPOLIZA;',
'/*CUENTA ENDOSOS*/',
'    SELECT COUNT (*)',
'    INTO :P100_COUNT_ENDOSOS',
'    FROM ENDOSOS',
'    WHERE IDPOLIZA = :P100_IDPOLIZA;',
'/*CUENTA NOTAS */',
'    select  COUNT (d.IDNCR)',
'    INTO :P100_NOTAS_DE_CREDITO',
'    FROM NOTAS_DE_CREDITO n , DETALLE_NOTAS_DE_CREDITO d ',
'    where n.idpoliza = :P100_IDPOLIZA',
'    and d.IDNCR = n.IDNCR;',
'',
'/*CUENTA RECIBOS PRIMA*/',
'    SELECT  COUNT (*)',
'    INTO :P100_COUNT_RECIBOS_PRIMA',
'    FROM FACTURAS ',
'    WHERE IDPOLIZA = :P100_IDPOLIZA;',
'end;'))
,p_attribute_02=>'P100_IDPOLIZA'
,p_attribute_03=>'P100_COUNT_CERTIFICADOS,P100_COUNT_ENDOSOS,P100_NOTAS_DE_CREDITO,P100_COUNT_RECIBOS_PRIMA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
