wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(615227351174271790)
,p_event_id=>wwv_flow_imp.id(612133255384718607)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('    dFecSolicitud   DATE := ''22/06/2026''; -- Fecha a partir de la cual entran en vigor las nuevas reglas de p\00F3lizas colectivas'),
unistr('    cNomGrpEco      VARCHAR2(400); -- Nombre de la filial devuelto por la funci\00F3n.'),
'BEGIN',
'    :P100_VAR_COBERTURAS := NULL;',
'',
'    IF :P100_FEC_SOLICITUD < dFecSolicitud THEN',
'        IF :P100_IDETPOL IS NOT NULL AND :P100_SUBGRUPOCERT IS NOT NULL THEN',
'            cNomGrpEco := OC_FILIALES.NOMBRE_FILIAL(:P100_CODCIA,:P100_GRUPECO,:P100_SUBGRUPOCERT);',
'            ',
'            IF cNomGrpEco = ''NO EXISTE'' THEN',
'                :P100_VAR_COBERTURAS := ''S'';',
'            ELSE',
'                :P100_VAR_COBERTURAS := ''N'';',
'            END IF;',
'        ELSE',
'            :P100_VAR_COBERTURAS := ''S'';',
'        END IF;',
'    ELSE',
'        IF :P100_POLCOL = ''S'' AND :P100_IDETPOL IS NOT NULL AND :P100_TIPOSEGCOL IS NOT NULL THEN',
'            IF :P100_TIPOSEGCOL = ''S'' THEN',
'                :P100_VAR_COBERTURAS := ''N'';',
'            ELSIF :P100_TIPOSEGCOL = ''N'' THEN',
'                :P100_VAR_COBERTURAS := ''S'';',
unistr('                :P100_SHOW_ERROR := ''P\00F3liza con Estatus de P\00F3liza Colectiva, Certificado con Tipo de Seguro Individual. Revisar con Administrador de Sistema'';'),
'            END IF;',
'        END IF;',
'    END IF;',
'END;'))
,p_attribute_02=>'P100_IDETPOL,P100_TIPOSEGCOL,P100_FEC_SOLICITUD,P100_SUBGRUPOCERT,P100_CODCIA,P100_GRUPECO,P100_POLCOL'
,p_attribute_03=>'P100_VAR_COBERTURAS,P100_SHOW_ERROR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
