,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  INDCAMBIOSAMI,SUMAASEGORIGEN,PRIMANIVLOCAL,SUMAASEG_LOCAL,MONTOEXTRAPRIMADET,PORCEXTRAPRIMADET,',
'        DEDUCIBLE_LOCAL,VECESSALARIO,DEDUCIBLE_MONEDA,SALARIOMENSUAL,SUMAASEG_MINIMA,SUMAASEGCALCULADA,',
'        PRIMA_LOCAL,SUMAASEG_MAXIMA,SUMAINGRESADA,EDAD_MINIMA,EDAD_MAXIMA,EDAD_EXCLUSION,',
'        STSCOBERTURA || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSCOBERTURA) DESC_STSCOBERTURA',
'INTO ',
'    :P100_SUMASAMI,:P100_SUMAASEGSAMI,:P100_PRIMACOMP,:P100_SUMAASEGCOB,:P100_EXTPRIMA,:P100_PRIMAEXT,',
'    :P100_DEDUCIBLECOB,:P100_VECSALARIO,:P100_DEDUCIBLE_MDA,:P100_SALMENSUAL,:P100_SUMAASEGMIN,:P100_SUMAASEGCAL,',
'    :P100_PRIMANETA,:P100_SUMAASEGMAX,:P100_SUMAASEGING,:P100_EDADMIN,:P100_EDADMAX,:P100_EDADEXCLU,',
'    :P100_ESTADOCOB',
'FROM COBERT_ACT',
'WHERE IDPOLIZA    = :P100_IDPOLIZA',
'AND IDETPOL     = :P100_IDETPOL',
'-- AND CODCOBERT = :P100_COBERT_CODCOBERT_RID',
'AND ROWID = :P100_COBERT_CODCOBERT_RID;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN;'))
,p_attribute_02=>'P100_IDPOLIZA,P100_IDETPOL,P100_COBERT_CODCOBERT_RID'
,p_attribute_03=>'P100_SUMASAMI,P100_SUMAASEGSAMI,P100_PRIMACOMP,P100_SUMAASEGCOB,P100_EXTPRIMA,P100_PRIMAEXT,P100_DEDUCIBLECOB,P100_VECSALARIO,P100_DEDUCIBLE_MDA,P100_SALMENSUAL,P100_SUMAASEGMIN,P100_SUMAASEGCAL,P100_PRIMANETA,P100_SUMAASEGMAX,P100_SUMAASEGING,P100_E'
||'DADMIN,P100_EDADMAX,P100_EDADEXCLU,P100_ESTADOCOB'
