'  }',
'',
'  $(document).off(''click.openAsegurados'', selector).on(''click.openAsegurados'', selector, function(e){',
'    e.preventDefault();',
'    e.stopImmediatePropagation();',
'',
'    apex.server.process(',
'      ''PREPARE_URL'',',
'      {',
