'        //x03: apex.item(''P100_IDENDOSO'').getValue()',
'      },',
'      {',
'        dataType: ''text'',',
'        success: function(pData){',
'          apex.navigation.dialog(',
'            pData,',
'            { title: ''Asegurados'', modal: true, width: 900, height: 600 }',
'          );',
'        },',
'        error: function(jqXHR, textStatus, errorThrown){',
'          console.error(''PREPARE_URL error:'', textStatus, errorThrown);',
'        }',
'      }',
'    );',
'  });',
'})();'))
,p_build_option_id=>wwv_flow_imp.id(690440983571095281)
);
