,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCount NUMBER;',
'BEGIN',
'    SELECT NVL(COUNT(*),0)',
'    INTO nCount',
'    FROM DETALLE_POLIZA',
'    WHERE IDPOLIZA = :P100_IDPOLIZACERT;',
'',
'    IF nCount > 0 THEN',
'',
'        SELECT IDTIPOSEG',
'        INTO :P100_IDTIPOSEG',
'        FROM DETALLE_POLIZA ',
'        WHERE IDPOLIZA = :P100_IDPOLIZACERT',
'        AND ROWNUM=1;',
'    ELSE',
'        :P100_IDTIPOSEG := ''NO EXISTE CERTIFICADO'';',
'    END IF;',
'    ',
'END;'))
,p_attribute_02=>'P100_IDPOLIZACERT'
