wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(549370898636250856)
,p_event_id=>wwv_flow_imp.id(549370818950250855)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cSTSENDOSO ENDOSOS.STSENDOSO%TYPE;',
'BEGIN',
'',
'    -- SELECT STSENDOSO',
'    -- INTO cSTSENDOSO',
'    -- FROM ENDOSOS',
'    -- WHERE IDPOLIZA = :P100_IDPOLIZA',
'    -- AND IDENDOSO = :P100_IDENDOSO;',
'',
'    -- IF cSTSENDOSO <> ''SOL'' THEN',
'    --     RAISE_APPLICATION_ERROR(-20001,',
unistr('    --     ''Solo se Puede Actualizar el Texto cuando el Endoso est\00E1 en Estarus SOLICITUD.'');'),
'    -- END IF;',
'',
'    IF :P100_ESTADO_EP_VALUE <> ''SOL'' THEN',
'        SELECT TEXTO',
'        INTO :P100_TXT_ENDOSO',
'        FROM ENDOSO_TEXTO',
'        WHERE IDPOLIZA = :P100_IDPOLIZA',
'        AND IDENDOSO = :P100_IDENDOSO;',
'',
'        RAISE_APPLICATION_ERROR(-20001,',
unistr('        ''Solo se Puede Actualizar el Texto cuando el Endoso est\00E1 en Estarus SOLICITUD.'');  '),
'    END IF;',
'',
'    MERGE INTO ENDOSO_TEXTO T USING (',
'        SELECT ',
'            :P100_IDPOLIZA AS IDPOLIZA,',
'            :P100_IDENDOSO AS IDENDOSO,',
'            :P100_TXT_ENDOSO AS TEXTO',
'        FROM dual',
'    ) S',
'    ON (',
'        T.IDPOLIZA = S.IDPOLIZA',
'        AND T.IDENDOSO = S.IDENDOSO',
'    )',
'    WHEN MATCHED THEN',
'        UPDATE SET ',
'            T.TEXTO = S.TEXTO',
'    WHEN NOT MATCHED THEN',
'        INSERT (',
'            IDPOLIZA,',
'            IDENDOSO,',
'            TEXTO',
'        )',
'        VALUES (',
'            S.IDPOLIZA,',
'            S.IDENDOSO,',
'            S.TEXTO',
'        );',
'',
'END;'))
,p_attribute_02=>'P100_IDPOLIZA,P100_IDENDOSO,P100_TXT_ENDOSO,P100_ESTADO_EP_VALUE'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
