 p_id=>wwv_flow_imp.id(550988657492489445)
,p_event_id=>wwv_flow_imp.id(550988578798489444)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCountCobert    NUMBER := NULL;',
'BEGIN',
'    :P100_COBERT_TOTAL_SUMAASEG     := NULL;',
'    :P100_COBERT_TOTAL_PRIMA        := NULL;',
'    :P100_COBERT_TOTAL_PRIMACOMP    := NULL;',
'    ',
'    -- Count Coberturas',
'    SELECT COUNT(*)',
'    INTO nCountCobert',
'    FROM COBERT_ACT',
'    WHERE 1=1',
'    AND IDPOLIZA    = :P100_IDPOLIZA',
'    AND IDETPOL     = :P100_IDETPOL',
'    AND CODCIA      = :P100_CODCIA',
'    AND CODEMPRESA  = :P100_CODEMPRESA',
'    AND IDTIPOSEG   = :P100_IDTIPOSEGCER',
'    ;',
'',
'    IF nCountCobert > 0 THEN',
'        SELECT SUM(SUMAASEG_MONEDA), SUM(PRIMA_MONEDA), SUM(PRIMANIVMONEDA)',
'        INTO :P100_COBERT_TOTAL_SUMAASEG, :P100_COBERT_TOTAL_PRIMA, :P100_COBERT_TOTAL_PRIMACOMP',
'        FROM COBERT_ACT',
'        WHERE 1=1',
'        AND IDPOLIZA    = :P100_IDPOLIZA',
'        AND IDETPOL     = :P100_IDETPOL',
'        AND CODCIA      = :P100_CODCIA',
'        AND CODEMPRESA  = :P100_CODEMPRESA',
'        AND IDTIPOSEG   = :P100_IDTIPOSEGCER;',
'    END IF;',
'',
'    :P100_COUNT_COBERT  := NVL(nCountCobert,0);',
'END;'))
,p_attribute_02=>'P100_IDPOLIZA,P100_IDETPOL,P100_CODCIA,P100_CODEMPRESA,P100_IDTIPOSEGCER'
,p_attribute_03=>'P100_COBERT_TOTAL_SUMAASEG,P100_COBERT_TOTAL_PRIMA,P100_COBERT_TOTAL_PRIMACOMP,P100_COUNT_COBERT'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
