,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT IDENDOSO,SUMA_ASEG_LOCAL,SUMA_ASEG_MONEDA,PRIMA_NETA_LOCAL,PRIMA_NETA_MONEDA,',
'STSENDOSO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSENDOSO) DESC_STSENDOSO,',
'MONTOAPORTEFONDO,PORCCOMIS,CVE_MOTIVCANCFACT,TIPOENDOSO,NUMENDREF,FECINIVIG,FECFINVIG,FECSOLICITUD,FECEMISION,IDETPOL,TIPOENDOSO,STSENDOSO,',
'OC_ENDOSO.TOTAL_ASEGURADOS(CODCIA, CODEMPRESA, IDPOLIZA,IDETPOL, IDENDOSO) TOTAL_ASEGURADO,',
'MOTIVO_ENDOSO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''MTOENDSV'',MOTIVO_ENDOSO) DESC_MOTIVO_ENDOSO,',
'CODPLANPAGO,',
'STSENDOSO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSENDOSO) DESC_STSENDOSO,',
'MOTIVANUL || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''MOTANUEN'',MOTIVANUL) DESC_MOTIVANUL,',
'FECANUL,',
'CODUSOCFDI || '' - '' || OC_FACT_ELECT_USO_CFDI.DESCRIPCION(1, CODUSOCFDI) DESC_CODUSOCFDI,',
'CODOBJETOIMP,DESCENDOSO,FECSTS,PRIMA_NETA_LOCAL,FECEXC,SUMA_ASEG_LOCAL,PRIMA_NETA_MONEDA,INDCALCDERECHOEMIS,SUMA_ASEG_MONEDA,PORCCOMIS,',
'MONTOAPORTEFONDO,PLDSTBLOQUEADA,PLDSTAPROBADA,PLDUSUARIOAPROB,',
