'BEGIN',
'    UPDATE POLIZAS_COMPLEMENTO',
'       SET INDFACTPERSONALIZADA = NVL(:P100_FACTRFCGEN, ''N''),',
'           FORMAIMPRIMENOMBRE   = :P100_IMPNOM',
'     WHERE CODCIA     = NVL(:P100_CODCIA, 1)',
'       AND CODEMPRESA = NVL(:P100_CODEMPRESA, 1)',
'       AND IDPOLIZA   = :P100_IDPOLIZA;',
'',
'    -- Si no existe el registro, se inserta',
'    IF SQL%ROWCOUNT = 0 THEN',
'        INSERT INTO POLIZAS_COMPLEMENTO (',
'            CODCIA,',
'            CODEMPRESA,',
'            IDPOLIZA,',
'            INDFACTPERSONALIZADA,',
'            FORMAIMPRIMENOMBRE',
'        )',
'        VALUES (',
'            NVL(:P100_CODCIA, 1),',
'            NVL(:P100_CODEMPRESA, 1),',
'            :P100_IDPOLIZA,',
'            NVL(:P100_FACTRFCGEN, ''N''),',
'            :P100_IMPNOM',
'        );',
'    END IF;',
'',
'    UPDATE FACTURAS F',
'       SET F.IndFactCteRFCGenerico = NVL(:P100_FACTRFCGEN, ''N'')',
'     WHERE F.CodCia             = NVL(:P100_CODCIA, 1)',
'       AND F.IdPoliza           = :P100_IDPOLIZA;',
'',
'END;'))
,p_attribute_02=>'P100_FACTRFCGEN,P100_IDPOLIZA'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
