wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(617658249090476521)
,p_process_sequence=>110
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Poliza_Reversa_Renovacion'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   dFecHoy   DATE;',
'   nIdPoliza POLIZAS.IdPoliza%TYPE;',
'BEGIN',
'   dFecHoy := SYSDATE;',
'',
'   SELECT IdPoliza',
'     INTO nIdPoliza',
'     FROM POLIZAS',
'    WHERE NumPolRef = :P100_NUMPOLREF',
'      AND NumRenov  = :P100_NUM_RENOVACION - 1;',
'',
'   UPDATE POLIZAS',
'      SET StsPoliza = ''EMI'',',
'          FecSts    = dFecHoy',
'    WHERE IdPoliza  = nIdPoliza;',
'',
'   UPDATE COBERTURAS',
'      SET StsCobertura = ''EMI''',
'    WHERE IdPoliza     = nIdPoliza;',
'',
'   DELETE DATOS_PARTICULARES_VEHICULO',
'    WHERE IdPoliza = :P100_IDPOLIZA;',
'',
'   DELETE DATOS_PARTICULARES_PERSONAS',
'    WHERE IdPoliza = :P100_IDPOLIZA;',
'',
'   DELETE DATOS_PARTICULARES_BIENES',
'    WHERE IdPoliza = :P100_IDPOLIZA;',
'',
'   DELETE COBERTURAS',
'    WHERE IdPoliza = :P100_IDPOLIZA;',
'',
'   DELETE DETALLE_POLIZA',
'    WHERE IdPoliza = :P100_IDPOLIZA;',
'',
'   DELETE POLIZAS',
'    WHERE IdPoliza = :P100_IDPOLIZA;',
'',
'   COMMIT;',
'',
'EXCEPTION',
'   WHEN NO_DATA_FOUND THEN',
'      APEX_ERROR.ADD_ERROR(',
unistr('         p_message => ''No se encontr\00F3 la p\00F3liza anterior para revertir la renovaci\00F3n.'','),
'         p_display_location => apex_error.c_inline_in_notification',
'      );',
'      ROLLBACK;',
'      RAISE;',
'',
'   WHEN OTHERS THEN',
'      APEX_ERROR.ADD_ERROR(',
unistr('         p_message => ''Error al revertir la renovaci\00F3n: '' || SQLERRM,'),
'         p_display_location => apex_error.c_inline_in_notification',
'      );',
'      ROLLBACK;',
'      RAISE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
