wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(549035675404997530)
,p_process_sequence=>208
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_RP_Reversa_Pago'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nIdTransacPagos    TRANSACCION.IdTransaccion%TYPE;',
'    nCodCliente        POLIZAS.CodCliente%TYPE;',
'    cCod_Moneda        POLIZAS.Cod_Moneda%TYPE;',
'    nIdPrimaDeposito   PRIMAS_DEPOSITO.IdPrimaDeposito%TYPE;',
'    nTotPagos          DETALLE_FACTURAS.Saldo_Det_Local%TYPE := 0;',
'    nDirecRegional     DIRECCION_REGIONAL_USR.CodDirecRegional%TYPE;',
'    cProcede           VARCHAR2(1);',
'',
'    CURSOR PAGOS_Q IS',
'       SELECT IdRecibo, NVL(Monto,0) MontoPago',
'         FROM PAGOS',
'        WHERE CodCia        = :P100_CODCIA',
'          AND IdFactura     = :P100_NUM_RECIBO',
'          AND FecAnulacion IS NULL',
'        ORDER BY IdRecibo DESC;',
'',
'BEGIN',
unistr('    -- Validar si el usuario est\00E1 autorizado'),
'    BEGIN',
'        nDirecRegional := OC_DIRECCION_REGIONAL_USR.DIREC_REGIONAL_USUARIO(:P100_CODCIA, :APP_USER);',
'        cProcede := ''N'';',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            cProcede := ''S'';',
'    END;',
'',
'    IF cProcede = ''S'' THEN',
'',
unistr('        -- Crear transacci\00F3n'),
'        IF GT_FAI_CONCENTRADORA_FONDO.ES_FACTURA_DE_FONDOS(',
'                :P100_CODCIA,',
'                :P100_CODEMPRESA,',
'                :P100_NUM_POLIZA_RP,',
'                :P100_CERT_RP,',
'                :P100_NUM_RECIBO',
'           ) = ''S'' THEN',
'',
'            nIdTransacPagos := OC_TRANSACCION.CREA(',
'                                    :P100_CODCIA,',
'                                    :P100_CODEMPRESA,',
'                                    21,',
'                                    ''REVPAG''',
'                               );',
'        ELSE',
'            nIdTransacPagos := OC_TRANSACCION.CREA(',
'                                    :P100_CODCIA,',
'                                    :P100_CODEMPRESA,',
'                                    12,',
'                                    ''REVPAG''',
'                               );',
'        END IF;',
'',
'        -- Recorrer pagos y revertir',
'        FOR W IN PAGOS_Q LOOP',
'            OC_FACTURAS.REVERTIR_PAGO(',
'                :P100_CODCIA,',
'                :P100_CODEMPRESA,',
'                :P100_NUM_RECIBO,',
'                W.IdRecibo,',
'                TRUNC(SYSDATE),',
'                :P100_CODCOBRADOR,',
'                nIdTransacPagos',
'            );',
'',
'            nTotPagos := nTotPagos + W.MontoPago;',
'        END LOOP;',
'',
'        -- Reversar comisiones',
'        OC_COMISIONES.REVERSA_PAGO(',
'            :P100_CODCIA,',
'            :P100_NUM_RECIBO ',
'        );',
'',
'        -- Contabilizar',
'        OC_COMPROBANTES_CONTABLES.CONTABILIZAR(',
'            :P100_CODCIA,',
'            nIdTransacPagos,',
'            ''C''',
'        );',
'',
unistr('        -- Obtener datos de la p\00F3liza'),
'        BEGIN',
'            SELECT CodCliente, Cod_Moneda',
'              INTO nCodCliente, cCod_Moneda',
'              FROM POLIZAS',
'             WHERE IdPoliza = :P100_NUM_POLIZA_RP',
'               AND CodCia   = :P100_CODCIA;',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
unistr('                raise_application_error(-20001, ''La p\00F3liza no existe'');'),
'        END;',
'',
unistr('        -- Insertar prima en dep\00F3sito'),
'        nIdPrimaDeposito := OC_PRIMAS_DEPOSITO.INSERTAR(',
'            nCodCliente,',
'            nTotPagos,',
'            cCod_Moneda,',
unistr('            ''Prima en Dep\00F3sito por reverso de pagos del recibo '' || :P100_NUM_POLIZA_RP ||'),
unistr('            '' de la p\00F3liza '' || :P100_NUM_POLIZA_RP,'),
'            :P100_NUM_POLIZA_RP,',
'            :P100_CERT_RP',
'        );',
'',
'        -- Emitir prima',
'        OC_PRIMAS_DEPOSITO.EMITIR(',
'            :P100_CODCIA,',
'            :P100_CODEMPRESA,',
'            nIdPrimaDeposito,',
'            TRUNC(SYSDATE),',
'            NULL',
'        );',
'',
'        ',
'        APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE :=',
'            ''Se reversaron los pagos del recibo '' || :P100_NUM_RECIBO;',
'',
'    ELSE',
'        raise_application_error(-20002, ''Usuario no autorizado para reversar pagos'');',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        raise_application_error(-20099, SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(605792130122907002)
,p_process_success_message=>'Se reverso correctamente el recibo seleccionado'
,p_internal_uid=>109943978573926007
);
