,p_process_sequence=>410
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_RP_Desmarcar_Recibos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nDirecRegional DIRECCION_REGIONAL_USR.CodDirecRegional%TYPE;',
'    cProcede       VARCHAR2(1);',
'BEGIN',
'',
'    IF OC_PROCESO_AUTORIZA_USUARIO.PROCESO_AUTORIZADO(',
'           :P100_CODCIA,',
'           ''9025'',',
'           :APP_USER,',
'           NULL,',
'           0',
'       ) = ''S'' THEN',
'',
'        BEGIN',
'            nDirecRegional :=',
'                OC_DIRECCION_REGIONAL_USR.DIREC_REGIONAL_USUARIO(',
'                    :P100_CODCIA,',
'                    :APP_USER',
'                );',
'',
'            cProcede := ''S'';',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                cProcede := ''N'';',
'        END;',
'',
'        IF cProcede = ''S'' THEN',
'',
'            UPDATE FACTURAS',
'               SET fecenvfactelec     = NULL,',
'                   codusuarioenvfact  = NULL,',
'                   foliofactelec      = NULL,',
'                   logprocesofactelec = NULL',
'             WHERE idfactura = :P100_NUM_RECIBO;',
'',
'        ELSE',
'            raise_application_error(',
'                -20002,',
'                ''Usuario NO Autorizado para Realizar Desmarcado de Recibos''',
'            );',
'        END IF;',
'',
'    ELSE',
'        raise_application_error(',
'            -20003,',
'            ''Usuario NO Autorizado para el proceso 9025''',
'        );',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        raise_application_error(-20099, SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(605792361210907004)
,p_process_success_message=>'Se desmarco correctamente el recibo seleccionado'
,p_internal_uid=>109944209716926010
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(550104741782461450)
,p_process_sequence=>411
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_RP_Rehabilita'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   nIdTransaccion        TRANSACCION.IdTransaccion%TYPE;',
'   nPrimaNeta_Moneda     POLIZAS.PrimaNeta_Moneda%TYPE;',
'   nDirecRegional        DIRECCION_REGIONAL_USR.CodDirecRegional%TYPE;',
'   cProcede              VARCHAR2(1);',
'',
'   CURSOR FACT_Q IS',
'      SELECT IdFactura',
'        FROM FACTURAS',
'       WHERE IdFactura = :P100_NUM_RECIBO',
'         AND IdPoliza  = :P100_NUM_POLIZA_RP',
'       ORDER BY IdFactura;',
'BEGIN',
'   IF OC_PROCESO_AUTORIZA_USUARIO.PROCESO_AUTORIZADO(:P100_CODCIA, ''9010'', :APP_USER, NULL, 0) = ''S'' THEN',
'      ',
'      BEGIN',
'         nDirecRegional := OC_DIRECCION_REGIONAL_USR.DIREC_REGIONAL_USUARIO(:P100_CODCIA, :APP_USER);',
'         cProcede       := ''N'';',
'      EXCEPTION',
'         WHEN OTHERS THEN',
'            cProcede := ''S'';',
'      END;',
'',
'      IF cProcede = ''S'' THEN',
'',
'         nIdTransaccion := OC_TRANSACCION.CREA(:P100_CODCIA, :P100_CODEMPRESA, 18, ''REHAB'');',
'',
'         OC_DETALLE_TRANSACCION.CREA (',
'            nIdTransaccion,',
'            :P100_CODCIA,',
'            :P100_CODEMPRESA,',
'            18,',
'            ''REHAB'',',
'            ''POLIZAS'',',
'            :P100_NUM_POLIZA_RP,',
'            NULL,',
'            NULL,',
'            NULL,',
'            nPrimaNeta_Moneda',
'         );',
'',
'         FOR W IN FACT_Q LOOP',
'            OC_FACTURAS.REHABILITACION(',
'               :P100_CODCIA,',
'               :P100_CODEMPRESA,',
'               W.IdFactura,',
'               nIdTransaccion',
'            );',
'         END LOOP;',
'',
'         OC_COMPROBANTES_CONTABLES.CONTABILIZAR(',
'            :P100_CODCIA,',
'            nIdTransaccion,',
'            ''100''',
'         );',
'',
'      ELSE',
'         raise_application_error(-20001, ''Usuario NO autorizado para rehabilitar recibos'');',
'      END IF;',
'',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      raise_application_error(-20002, SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(605792418215907005)
,p_process_success_message=>unistr('Se rehabilit\00F3 el recibo correctamente')
,p_internal_uid=>111013044951389927
);
