,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cNaturalidad  VARCHAR2(2);',
'    cValida       VARCHAR2(1);',
'BEGIN',
'    -- Valida si el endoso puede emitirse',
'    cValida := OC_ENDOSO.VALIDA_ENDOSO(:P100_CODCIA,:P100_IDPOLIZA,:P100_IDENDOSO,cNaturalidad);',
'',
'    IF  OC_ENDOSO.VALIDA_ENDOSO(:P100_CODCIA,:P100_IDPOLIZA,:P100_IDENDOSO,cNaturalidad) = ''S'' THEN',
'            OC_ENDOSO.EMITIR_AUMENTO(',
'                :P100_CODCIA,',
'                :P100_CODEMPRESA,',
'                :P100_IDPOLIZA,',
'                :P100_IDETPOL,',
'                :P100_IDENDOSO,',
'                :P100_TIPO_ENDOSO',
'             );',
'        COMMIT;',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        RAISE_APPLICATION_ERROR(-20001, ''Error: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(606773741946423131)
,p_process_success_message=>unistr('Se EMITI\00D3 el Aumento Correctamente')
,p_internal_uid=>53197692696979225
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(593740824292295608)
,p_process_sequence=>603
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Endoso_Reversa'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'dFecHoy       DATE;',
'nRegis        NUMBER(6);',
'nSumaAseg     NUMBER(14,2);',
'cNaturalidad  VARCHAR2(1);',
'nExiste       NUMBER(5);',
'',
'nCodCia     endosos.CodCia%type     := :P100_CODCIA;',
'nIdPoliza   endosos.idpoliza%type   := :P100_IDPOLIZA;',
'nIDetPol    endosos.IDetPol%type    := :P100_DET_POLIZA;',
'nIdEndoso   endosos.IdEndoso%type   := :P100_IDENDOSO;',
'nCodEmpresa endosos.CODEMPRESA%type := :P100_CODEMPRESA;',
'cTipoEndoso endosos.TIPOENDOSO%type := :P100_TIPO_ENDOSO_VALUE;',
'',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO nExiste',
'    FROM ENDOSOS',
'    WHERE IdPoliza  = nIdPoliza',
'    AND IdEndoso  > nIdEndoso',
'    AND StsEndoso = ''EMI'';',
'',
'    IF NVL(nExiste,0) != 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Debe Revertir primero los Endosos Emitidos Posteriormente a este Endoso'');',
'    END IF;',
'',
'    IF CTipoEndoso != ''EAD'' THEN',
'        IF OC_ENDOSO.VALIDA_ENDOSO(nCodCia, nIdPoliza, nIdEndoso, cNaturalidad) = ''S'' THEN',
'         ',
'            BEGIN',
'               OC_ENDOSO.REVERTIR_EMISION(nCodCia, nCodEmpresa, nIdPoliza, nIDetPol, nIdEndoso, CTipoEndoso);',
'',
'            EXCEPTION',
'               WHEN OTHERS THEN',
'                    RAISE_APPLICATION_ERROR(-20002, SQLERRM);',
'            END;',
'            COMMIT;',
'         ',
'        END IF;',
'    ELSE',
unistr('        RAISE_APPLICATION_ERROR(-20003, ''NO Puede Revertir la Emisi\00F3n del Endoso No. '' || RTRIM(LTRIM(TO_CHAR(nIdEndoso))) ||'),
unistr('                                '' Porque es a Declaraci\00F3n.  Debe realizar otro Endoso a Declaraci\00F3n o Cancelarlo.'');'),
'    END IF;',
'',
'DECLARE',
'',
'    set_url VARCHAR2(1000);',
'',
'    BEGIN',
'        set_url := APEX_PAGE.GET_URL(',
'            p_page      => 100,',
'            p_request   => ''BTN_REVERSA_ENDOSO'',',
'            p_items  => ''P100_CONSECUTIVO_EP'',',
'            p_values => :P100_CONSECUTIVO_EP',
'        );',
'        apex_util.redirect_url ( p_url => set_url );',
'',
'    END;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RAISE_APPLICATION_ERROR(-20004,SQLERRM); ',
'END;       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(606773856537423132)
,p_process_success_message=>unistr('Se REVERS\00D3 El Endoso Correctamente')
,p_internal_uid=>55364288822640507
);
