,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_CALCULA_PRIMA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE    ',
'    vl_Existe   NUMBER := 0;',
'BEGIN',
'    SELECT COUNT(1)',
'    INTO vl_Existe',
'    FROM SICAS_OC.VALORES_DE_LISTAS',
'    WHERE CODLISTA =''GMPRCALC'' ',
'        AND CVE_CNSF = ''PRODNEW''',
'        AND CODVALOR = :P100_IDTIPOSEGCER;',
'',
'    IF vl_Existe > 0 THEN ',
'        BEGIN',
'        ',
'            OC_COBERT_ACT_ASEG.PROC_CARGA_MASIVA_COBS(:P100_CODCIA,:P100_CODEMPRESA,:P100_IDTIPOSEGCER,:P100_IDPLANCOB,:P100_IDPOLIZA,:P100_IDETPOL,NVL(:P100_IDENDOSO,0),0,0);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                raise_application_error(-20001,''Error en Carga de Coberturas : '' || :P100_SUBGRUPOCERT||'' - ''||SQLERRM);',
'        END;',
'    ELSE   ',
unistr('        raise_application_error(-20001,''Funci\00F3n valida solo para productos GMPROTECT'');'),
'    END IF;',
'END;',
'       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(349792604135895285)
,p_process_success_message=>'Se cargaron las coberturas Correctamente'
,p_internal_uid=>128405573112371306
);
