wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(544395712216507824)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_TOTAL_SUMA_PRIMA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Datos Poliza',
'    nTotalSumaMoneda    POLIZAS.SUMAASEG_MONEDA%TYPE;',
'    nTotalSumaLocal     POLIZAS.SUMAASEG_LOCAL%TYPE;',
'    nTotalPrimaMoneda   POLIZAS.PRIMANETA_MONEDA%TYPE;',
'    nTotalPrimaocal     POLIZAS.PRIMANETA_LOCAL%TYPE;',
'    -- Certificado y Detalle Certificado',
'    nCertTotalSumaMoneda    DETALLE_POLIZA.SUMA_ASEG_MONEDA%TYPE;',
'    nCertTotalSumaLocal     DETALLE_POLIZA.SUMA_ASEG_LOCAL%TYPE;',
'    nCertTotalPrimaMoneda   DETALLE_POLIZA.PRIMA_MONEDA%TYPE;',
'    nCertTotalPrimaocal     DETALLE_POLIZA.PRIMA_LOCAL%TYPE;',
'BEGIN',
'    ',
'    SELECT SUMAASEG_MONEDA,SUMAASEG_LOCAL,PRIMANETA_MONEDA,PRIMANETA_LOCAL',
'    INTO nTotalSumaMoneda,nTotalSumaLocal,nTotalPrimaMoneda,nTotalPrimaocal',
'    FROM POLIZAS',
'    WHERE IDPOLIZA = :P100_IDPOLIZA;',
'',
'    BEGIN',
'        SELECT SUMA_ASEG_MONEDA,SUMA_ASEG_LOCAL,PRIMA_MONEDA,PRIMA_LOCAL',
'        INTO nCertTotalSumaMoneda,nCertTotalSumaLocal,nCertTotalPrimaMoneda,nCertTotalPrimaocal',
'        FROM DETALLE_POLIZA',
'        WHERE IDPOLIZA = :P100_IDPOLIZA',
'        AND IDETPOL = :P100_IDETPOL;',
'',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                nCertTotalSumaMoneda    := 0;',
'                nCertTotalSumaLocal     := 0;',
'                nCertTotalPrimaMoneda   := 0;',
'                nCertTotalPrimaocal     := 0;',
'    END;',
'',
'    APEX_JSON.open_object;',
'    APEX_JSON.write(''status'', ''ok'');',
'    APEX_JSON.write(''poliza'', :P100_IDPOLIZA);',
'    APEX_JSON.write(''total_sumamoneda'', nTotalSumaMoneda);',
'    APEX_JSON.write(''total_sumalocal'', nTotalSumaLocal);',
'    APEX_JSON.write(''total_primamoneda'', nTotalPrimaMoneda);',
'    APEX_JSON.write(''total_primalocal'', nTotalPrimaocal);',
'    APEX_JSON.write(''total_sumamoneda_cert'', nCertTotalSumaMoneda);',
'    APEX_JSON.write(''total_sumalocal_cert'', nCertTotalSumaLocal);',
'    APEX_JSON.write(''total_primamoneda_cert'', nCertTotalPrimaMoneda);',
'    APEX_JSON.write(''total_primalocal_cert'', nCertTotalPrimaMoneda);',
'    APEX_JSON.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>105304015385436301
);
end;
