'                            p_checksum_type => ''SESSION'');',
'    END IF;',
'',
'    APEX_JSON.OPEN_OBJECT;',
'    IF  nfile_id_1 IS NOT NULL ',
'        OR nfile_id_1 IS NOT NULL ',
'        OR nfile_id_1 IS NOT NULL ',
'    THEN',
'        APEX_JSON.WRITE(''status'',''ok'');',
