 p_id=>wwv_flow_imp.id(608679313165069620)
,p_plug_name=>'PAGO_DETALLE'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT F.CodCia',
'       ,F.IdPoliza',
'       ,DF.CodCpto',
'       ,DF.CodCpto ||'' - '' || OC_CATALOGO_DE_CONCEPTOS.DESCRIPCION_CONCEPTO(1, CodCpto) DESC_CONCEPTO',
'       ,DF.IndCptoPrima',
'       ,SUM(DF.Monto_Det_Local) Monto_Det_Local',
'       ,SUM(DF.Monto_Det_Moneda) Monto_Det_Moneda',
'       ,SUM(DF.Saldo_Det_Local) Saldo_Det_Local',
'       ,SUM(DF.Saldo_Det_Moneda) Saldo_Det_Moneda',
'       ,NVL((SELECT SUM(D.Monto) ',
'FROM PAGO_DETALLE D',
'    ,PAGOS P',
'    ,FACTURAS FA ',
'WHERE FA.CodCia = F.CodCia ',
'AND FA.IdPoliza = :P102_NUM_POLIZA',
'AND P.IdFactura = FA.IdFactura ',
'AND P.IdTransaccionAnu IS NULL ',
'AND D.IdRecibo = P.IdRecibo ',
'AND D.CodCpto = DF.CodCpto),0) Monto_Det_Pagado ',
'FROM DETALLE_FACTURAS DF',
',FACTURAS F ',
'WHERE DF.IdFactura = F.IdFactura ',
'GROUP BY F.CodCia, F.IdPoliza, DF.CodCpto, DF.IndCptoPrima'))
