,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Execute Copiar Polizas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'nNRegPol        NUMBER;',
'vIdPolizaNueva  NUMBER(12);',
'vControl        NUMBER;',
'BEGIN',
'    nNRegPol := :P103_CANTIDAD;',
'    vControl := 0;',
'    IF(NVL(nNRegPol,0) > 0)THEN',
'        vControl := 1;',
'        FOR X IN 1..nNRegPol LOOP',
'            vControl := 1.1;',
'            OC_POLIZAS.COPIAR(:P103_CODCIA_CTRL, :P103_IDPOLIZA_CTRL, vIdPolizaNueva);',
'            vControl := 1.2;',
'            COMMIT;',
'            vControl := 1.3;',
'        END LOOP;',
'    ELSE',
'        vControl := 2;',
'        NULL;',
'    END IF;',
'    vControl := 3;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        raise_application_error(-20001, ''<'' || vControl || ''>ERROR Copiar Polizas:: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(604885259505412431)
,p_process_success_message=>unistr('Se Realiz\00F3 el Copiado Correctamente')
,p_internal_uid=>38905878772666308
);
