,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    t.IDTRANSACCION,',
'    t.CODCIA,',
'    t.CODEMPRESA,',
'    t.IDPROCESO,',
'    pt.IDPROCESO || '' - '' || pt.DESCRIPCION_PROCESO AS DESCIDPROCESO,',
'    t.FECHATRANSACCION,',
'    t.USUARIOGENERO',
'FROM TRANSACCION t',
'LEFT JOIN PROC_TAREA pt',
'    ON pt.IDPROCESO = t.IDPROCESO',
'WHERE (t.IDPROCESO = :P104_IDPROCESO OR :P104_IDPROCESO IS NULL)',
'    AND t.CODCIA = :P104_CODCIA',
'    AND t.CODEMPRESA = :P104_CODEMPRESA',
'    AND EXISTS (',
'        SELECT 1',
'        FROM DETALLE_TRANSACCION d',
'        WHERE d.IDTRANSACCION = t.IDTRANSACCION',
'            AND (:P104_OBJETO IS NULL OR :P104_OBJETO = ''POLIZAS'' OR d.OBJETO = :P104_OBJETO)',
'            AND (:P104_VALOR1 IS NULL OR NVL(d.VALOR1, ''$'') = NVL(:P104_VALOR1, ''$''))',
'            AND (:P104_VALOR2 IS NULL OR ( :P104_OBJETO = ''POLIZAS''',
'                AND NVL(TO_NUMBER(d.VALOR2), 0) BETWEEN NVL(TO_NUMBER(:P104_VALOR2), 99)',
'                    AND NVL((',
'                        SELECT MAX(dp.IDETPOL) FROM DETALLE_POLIZA dp',
'                            WHERE dp.CODCIA   = :P104_CODCIA',
'                                AND dp.IDPOLIZA = TO_NUMBER(:P104_VALOR1)), 99))',
'                OR (:P104_OBJETO <> ''POLIZAS''AND NVL(d.VALOR2, ''$'') = NVL(:P104_VALOR2, ''$'')))',
'            AND (:P104_VALOR3 IS NULL OR NVL(d.VALOR3, ''$'') = NVL(:P104_VALOR3, ''$''))',
'            AND (:P104_VALOR4 IS NULL OR NVL(d.VALOR4, ''$'') = NVL(:P104_VALOR4, ''$''))',
'  )',
'  AND t.IDPROCESO NOT IN (6);'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'RETURN APEX_PAGE.GET_URL(  P_PAGE        => 104,  P_CLEAR_CACHE => ''104'',  P_ITEMS       => ''P104_CODCIA,P104_CODEMPRESA,P104_OBJETO,P104_VALOR1,P104_VALOR2,P104_VALOR3,P104_VALOR4,P104_IDPROCESO'',  P_VALUES      =>         :P325_CODCIA_CMF || '','' ||'
||'        :P325_CODEMPRESA_CMF || '','' ||        ''FAI_CONCENTRADORA_FONDO'' || '','' ||                               :P325_POLIZA_CMF || '','' ||                          :P325_CERTIFICADO_CMF || '','' ||                           :P325_IDFONDO_CMF  || '','' ||'
||'        :P325_CODCPTOMOV || '','' ||        ''21'');'
,p_prn_content_disposition=>'ATTACHMENT'
