wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(544513157045556633)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BTN_Genera_Dist'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   cOrigen VARCHAR2(20);',
'   vExiste VARCHAR2(1);',
'BEGIN',
'',
'   -- ORIGEN',
'   IF :P154_PROCESO IN (7, 18) THEN',
'      cOrigen := ''EMISION'';',
'   ELSIF :P154_PROCESO = 8 THEN',
'      cOrigen := ''ENDOSOS'';',
'   ELSIF :P154_PROCESO = 6 THEN',
'      cOrigen := ''SINIESTRO'';',
'   ELSE',
'      cOrigen := ''ANULAPOL'';',
'   END IF;',
'',
'   -- DISTRIBUCION',
'   IF cOrigen <> ''SINIESTRO'' THEN',
'',
'      GT_REA_DISTRIBUCION.DISTRIBUYE_REASEGURO(',
'       :P104_CODCIA,',
'       :P104_CODEMPRESA,',
'       TO_NUMBER(:P104_IDPOLIZA),',
'       :P104_TRANSACCION,',
'       :P104_FECHA_TRANS,',
'       cOrigen',
'        );',
'',
'      vExiste := GT_REA_DISTRIBUCION.EXISTE_DISTRIB_TRANSACCION(',
'                    :P104_CODCIA,',
'                    TO_NUMBER(:P104_IDPOLIZA),',
'                    :P104_TRANSACCION',
'                 );',
'',
'   ELSE',
'',
'      GT_REA_DISTRIBUCION.DISTRIBUYE_SINIESTROS(',
'         :P104_CODCIA,',
'         :P104_CODEMPRESA,',
'         TO_NUMBER(:P104_IDPOLIZA),',
'         :P104_TRANSACCION,',
'         :P104_FECHA_TRANS',
'      );',
'',
'      vExiste := GT_REA_DISTRIBUCION.EXISTE_DISTRIB_TRANSAC_SINI(',
'                    :P104_CODCIA,',
'                    TO_NUMBER(:P104_IDPOLIZA),',
'                    :P104_TRANSACCION',
'                 );',
'',
'   END IF;',
'',
'   -- VALIDACION RESULTADO',
'   IF vExiste = ''S'' THEN',
'',
'      apex_application.g_print_success_message :=',
unistr('         ''Se gener\00F3 la distribuci\00F3n de reaseguro para la transacci\00F3n '' || :P154_TRANSACCION;'),
'',
'   ELSE',
'',
'      apex_error.add_error(',
unistr('         p_message => ''NO se gener\00F3 la distribuci\00F3n de reaseguro. Solicite soporte a Sistemas.'','),
'         p_display_location => apex_error.c_inline_in_notification',
'      );',
'',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      apex_error.add_error(',
unistr('         p_message => ''Error en distribuci\00F3n de reaseguro: '' || SQLERRM,'),
'         p_display_location => apex_error.c_inline_in_notification',
'      );',
'      RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(610769810880846898)
,p_process_success_message=>unistr('Se gener\00F3 correctamente la distribuci\00F3n de reaseguro')
,p_internal_uid=>105421460214485110
);
end;
