wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(615407707858433992)
,p_event_id=>wwv_flow_imp.id(615407673784433991)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nExiste       NUMBER := 0;',
'    nIdSolicitud  NUMBER;',
'    vMensaje      VARCHAR2(1000);',
'BEGIN',
'    IF :P105_POL_DESTINO IS NULL THEN',
unistr('		RAISE_APPLICATION_ERROR(-20001,''La P\00F3liza Destino es OBLIGATORIA'');'),
'    END IF;',
'',
'    SELECT COUNT(*)',
'    INTO nExiste',
'    FROM POLIZAS',
'    WHERE IDPOLIZA = :P105_POL_DESTINO;',
'',
'    IF nExiste = 0 THEN',
unistr('	    RAISE_APPLICATION_ERROR(-20001,''La P\00F3liza Destino NO EXISTE'');'),
'    END IF;',
'',
'    nIdSolicitud := SICAS_OC.TH_CLAUSULAS.COPIA_CLAUSULAS(',
'                        :P105_NUM_POLIZA,',
'                        :P105_POL_DESTINO,',
'                        vMensaje',
'                        );',
'',
'    IF nIdSolicitud = 0 THEN',
'        ROLLBACK;',
'		RAISE_APPLICATION_ERROR(-20001,''vMensaje'');',
'    ELSE',
'        COMMIT;',
unistr('        apex_application.g_print_success_message := ''Cl\00E1usula COPIADA Correctamente'';'),
'    END IF;',
'END;',
''))
