wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(605413757773749587)
,p_plug_name=>'AGENTE_POLIZA'
,p_region_name=>'agentes_poliza'
,p_parent_plug_id=>wwv_flow_imp.id(605354788069576823)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>110
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  AP.rowid,',
'        AP.IDPOLIZA,',
'        AP.CODCIA,',
'        AP.COD_AGENTE,',
'        AP.COD_AGENTE || '' - '' || SICAS_OC.OC_AGENTES.NOMBRE_AGENTE(CODCIA, COD_AGENTE) AS DESC_AGENTE,',
'        AP.ORIGEN,',
'        AP.ORIGEN || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''IDCONCEP'', ORIGEN) AS DESC_ORIGEN,',
'        AP.PORC_COMISION,',
'        AP.IND_PRINCIPAL,',
'            /*',
'            (SELECT A.CODTIPO',
'            FROM AGENTES A',
'            WHERE A.CODTIPO = A.CODTIPO',
'            AND A.CODCIA = A.CODCIA',
'            AND A.COD_AGENTE = :P110_COD_AGENTE',
'            ) TIPO_AGENTE,',
'            */',
'            (SELECT A.CODTIPO',
'            FROM AGENTES A',
'            WHERE A.COD_AGENTE = AP.COD_AGENTE) TIPO_AGENTE,',
'        CASE',
'            WHEN EXISTS (',
'                SELECT 1',
'                FROM AGENTES_DISTRIBUCION_POLIZA B',
'                WHERE B.CODCIA      = AP.CODCIA',
'                  AND B.IDPOLIZA    = AP.IDPOLIZA',
'                  AND B.COD_AGENTE  = AP.COD_AGENTE',
'            )',
'            THEN ''S''',
'            ELSE ''N''',
'        END AS GENERADO, ',
'        (SELECT ',
'        CASE',
'            WHEN P.STSPOLIZA IN (''XER'', ''SOL'') ',
'                THEN ''<i class="fa fa-edit"></i>''',
'            ELSE NULL ',
'        END',
'    FROM polizas P',
'    WHERE P.IDPOLIZA = AP.IDPOLIZA) AS editar',
'FROM AGENTE_POLIZA AP',
'WHERE IDPOLIZA = :P110_NUM_POLIZA;',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'AGENTE_POLIZA'
