wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(538513857858815029)
,p_plug_name=>'AGENTES_DISTRIBUCION_P'
,p_region_name=>'ig_distribucion'
,p_parent_plug_id=>wwv_flow_imp.id(605354845808576824)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>130
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ADP.CODCIA,',
'       ADP.IDPOLIZA,',
'       ADP.COD_AGENTE,',
'       ADP.CODNIVEL,',
'       ADP.COD_AGENTE_DISTR,',
'       ADP.PORC_COMISION_AGENTE,',
'       ADP.PORC_COM_DISTRIBUIDA,',
'       ADP.PORC_COMISION_PLAN,',
'       ADP.PORC_COM_PROPORCIONAL,',
'       ADP.COD_AGENTE_JEFE,',
'       ADP.PORC_COM_POLIZA,',
'       ADP.ORIGEN, ',
'       (SELECT A.CODTIPO',
'           FROM AGENTES A',
'           WHERE A.COD_AGENTE = ADP.COD_AGENTE_DISTR) TIPO_AGENTE,',
'        ORIGEN || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''IDCONCEP'', ORIGEN) DESC_ORIGEN,',
'       COD_AGENTE_JEFE || '' - '' || OC_AGENTES.NOMBRE_AGENTE(CODCIA, COD_AGENTE_JEFE) DESC_COD_AGENTE_JEFE,',
'      NVL(',
'         (SELECT DECODE(A.INDEXCLUIRHONORARIO,''N'',''S'',''N'')',
'            FROM AGENTES A',
'           WHERE A.COD_AGENTE = ADP.COD_AGENTE_DISTR',
'             AND A.CODTIPO IN (''HONPM'',''HONPF'',''HONORM'',''HONORF'')',
'         ),',
'         ''N'') AS CALC_AUTOM',
'FROM AGENTES_DISTRIBUCION_POLIZA ADP',
'WHERE IDPOLIZA = :P110_NUM_POLIZA ',
'AND COD_AGENTE = :P110_COD_AGENTE',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P110_NUM_POLIZA,P110_FLAG_BTN_MODIFICA,P110_COD_AGENTE'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'AGENTES_DISTRIBUCION_P'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
