,p_validation_name=>'VA_Porcentaje'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'ncounter number :=0;',
'',
'begin',
'    select count(*)',
'    into ncounter',
'    FROM AGENTE_POLIZA AP',
'    WHERE IDPOLIZA = :P110_NUM_POLIZA;',
'',
'    IF ncounter > 0 then',
'        IF OC_FUNCIONALIDADES_MANTENIMIENTO_POLIZA.FUNC_VALIDA_COMISION (:P110_NUM_POLIZA) = ''N'' THEN',
'            RETURN ''La Suma de Comisiones debe ser EXACTAMENTE 100%'';',
'        END IF;',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_item=>wwv_flow_imp.id(611448359508714028)
