wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(538516190073815052)
,p_event_id=>wwv_flow_imp.id(538516004136815051)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	nsuma number;',
'	vdistribuido number;',
'	vproporcional number;',
'	cCodTipoPlan varchar2(100); ',
'	cDescRamo varchar2(100);',
'	vComdistribuida number;',
'	vComproporcional number;',
'	cexcluiragente  AGENTES.INDEXCLUIRHONORARIO%TYPE;',
'	cCodTipoAge varchar2(100);',
'    vIva VARCHAR2(2);',
'BEGIN',
'    OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION(nCodCia    => :P110_CODCIA ',
'															 ,nIdPoliza  => :P110_NUM_POLIZA',
'														     ,nCodAgente => :P110_COD_AGENTE',
'															 );',
'',
'    SELECT SUM(NVL(PORC_COM_DISTRIBUIDA,0))',
'    INTO nsuma',
'    FROM AGENTES_DISTRIBUCION_POLIZA',
'    WHERE IDPOLIZA = :P110_NUM_POLIZA;',
'',
'    UPDATE DETALLE_POLIZA',
'    SET PORCCOMIS = nsuma',
'    WHERE IDPOLIZA = :P110_NUM_POLIZA;',
'',
'    SELECT CODTIPO, INDEXCLUIRHONORARIO',
'    INTO cCodTipoAge, cExcluirAgente',
'    FROM AGENTES',
'    WHERE COD_AGENTE = :P110_COD_AGENTE_DISTR;',
'',
'    IF :P110_TIPO_AGENTE_CTRL IN (''HONPF'',''HONPM'',''UDISPF'',''UDISPM'',''HONORF'',''HONORM'')',
'       AND :P110_CODTIPOPLAN = ''010''',
'       AND cExcluirAgente = ''N''',
'    THEN',
'        SELECT COUNT(*)',
'        INTO vIva',
'        FROM AGENTES_DISTRIBUCION_POLIZA',
'        WHERE IDPOLIZA = :P110_NUM_POLIZA',
'        AND :P110_IVA = ''S'';',
'',
'        IF vIva > 0 THEN',
'            :P110_IVA := ''S'';',
'            /*',
'            UPDATE AGENTES_DISTRIBUCION_POLIZA',
'            SET PORC_COM_DISTRIBUIDA = (PORC_COM_DISTRIBUIDA / 1.16),',
'                PORC_COM_PROPORCIONAL = ROUND(((PORC_COM_DISTRIBUIDA / 1.16) /:P110_PORC_COM_POLIZA)*100,2)',
'            WHERE IDPOLIZA = :P110_NUM_POLIZA',
'            AND :P110_IVA = ''S'';',
'            */',
'',
'    UPDATE AGENTES_DISTRIBUCION_POLIZA ADP',
'    SET PORC_COM_DISTRIBUIDA = PORC_COM_DISTRIBUIDA / 1.16,',
'    PORC_COM_PROPORCIONAL = ROUND(((PORC_COM_DISTRIBUIDA / 1.16) / :P110_PORC_COM_POLIZA) * 100,2)',
'    WHERE IDPOLIZA = :P110_NUM_POLIZA',
'    AND EXISTS (',
'        SELECT 1',
'        FROM AGENTES A',
'        WHERE A.COD_AGENTE = ADP.COD_AGENTE',
'        AND A.CODTIPO IN (''HONPF'',''HONPM'',''UDISPF'',''UDISPM'',''HONORF'',''HONORM'')',
'        AND NVL(A.INDEXCLUIRHONORARIO,''N'') = ''N''',
'        );',
'        ELSE',
'            :P110_IVA := ''N'';',
'        END IF;',
'    ELSE',
'        :P110_IVA := ''N'';',
'    END IF;',
'END;'))
,p_attribute_02=>'P110_CODCIA,P110_NUM_POLIZA, P110_COD_AGENTE,P110_COD_AGENTE_DISTR,P110_TIPO_AGENTE_CTRL,P110_CODTIPOPLAN,P110_PORC_COM_DISTRIBUIDA,P110_IVA'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(690440983571095281)
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(560000460568946431)
,p_event_id=>wwv_flow_imp.id(538516004136815051)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nsuma               NUMBER;',
'	vdistribuido        NUMBER;',
'	vproporcional       NUMBER;',
'	cCodTipoPlan        VARCHAR2(100); ',
'	cDescRamo           VARCHAR2(100);',
'	vComdistribuida     NUMBER;',
'	vComproporcional    NUMBER;',
'	cexcluiragente      AGENTES.INDEXCLUIRHONORARIO%TYPE;',
'	cCodTipoAge         VARCHAR2(100);',
'    vIva                VARCHAR2(2);',
'      ',
'    v_total_regs        NUMBER;',
'    v_regs_en_cero       NUMBER;',
'    v_primer_rowid       ROWID;',
'BEGIN',
'    OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION(nCodCia    => :P110_CODCIA',
'                                                             ,nIdPoliza  => :P110_NUM_POLIZA',
'                                                             ,nCodAgente => :P110_COD_AGENTE);',
'',
'',
'    SELECT COUNT(*),',
'           COUNT(CASE WHEN PORC_COM_DISTRIBUIDA = 0 THEN 1 END)',
'      INTO v_total_regs, v_regs_en_cero',
'      FROM AGENTES_DISTRIBUCION_POLIZA',
'     WHERE IDPOLIZA = :P110_NUM_POLIZA',
'     AND COD_AGENTE =: P110_COD_AGENTE',
'     ;',
'    ',
'    IF v_total_regs = v_regs_en_cero AND v_total_regs > 0 THEN',
'',
'        SELECT ROWID',
'          INTO v_primer_rowid',
'          FROM (',
'                SELECT ROWID',
'                  FROM AGENTES_DISTRIBUCION_POLIZA',
'                 WHERE IDPOLIZA = :P110_NUM_POLIZA',
'                 AND COD_AGENTE =: P110_COD_AGENTE',
'',
'                 ORDER BY CODNIVEL DESC, COD_AGENTE DESC',
'               )',
'         WHERE ROWNUM = 1;',
'',
'        UPDATE AGENTES_DISTRIBUCION_POLIZA',
'           SET PORC_COM_PROPORCIONAL = 100',
'         WHERE ROWID = v_primer_rowid',
'         AND COD_AGENTE =: P110_COD_AGENTE;',
'',
'    END IF;',
'',
'/*',
'    SELECT SUM(NVL(PORC_COM_DISTRIBUIDA,0))',
'    INTO nsuma',
'    FROM AGENTES_DISTRIBUCION_POLIZA',
'    WHERE IDPOLIZA = :P110_NUM_POLIZA;',
'',
'    UPDATE DETALLE_POLIZA',
'    SET PORCCOMIS = nsuma',
'    WHERE IDPOLIZA = :P110_NUM_POLIZA;',
'',
'    SELECT CODTIPO,INDEXCLUIRHONORARIO',
'    INTO cCodTipoAge,cExcluirAgente',
'    FROM AGENTES',
'    WHERE COD_AGENTE = :P110_COD_AGENTE_DISTR;',
'    */',
'end; ',
'    '))
,p_attribute_02=>'P110_CODCIA,P110_NUM_POLIZA, P110_COD_AGENTE,P110_COD_AGENTE_DISTR,P110_TIPO_AGENTE_CTRL,P110_CODTIPOPLAN,P110_PORC_COM_DISTRIBUIDA,P110_IVA'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'VAL_OF_ITEM_IN_COND_NOT_EQ_COND2'
,p_server_condition_expr1=>'P110_IVA'
,p_server_condition_expr2=>'S'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(561831810720380737)
,p_event_id=>wwv_flow_imp.id(538516004136815051)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_tipo              VARCHAR2(200);',
'    nTotalProporcional  NUMBER;',
'    nDiferencia         NUMBER;',
'    nsuma number;',
'    cCodTipoAg varchar2(200);',
'    cCodTipoAge varchar2(200);',
'    cExcluirAgente varchar2(200);',
'      ',
'    v_total_regs        NUMBER;',
'    v_regs_en_cero       NUMBER;',
'    v_primer_rowid       ROWID;',
'',
'BEGIN ',
'    --IF :P110_TIPO_AGENTE_CTRL_ADP IN (''HONPF'', ''HONPM'', ''UDISPF'', ''UDISPM'', ''HONORF'' , ''HONORM'') THEN',
'',
'    SELECT A.CODTIPO',
'    into v_tipo ',
'    FROM AGENTES A',
'    WHERE A.COD_AGENTE = :P110_COD_AGENTE_DISTR;',
'',
'IF v_tipo IN (''HONPF'', ''HONPM'', ''UDISPF'', ''UDISPM'', ''HONORF'' , ''HONORM'') THEN',
'            IF :P110_CODTIPOPLAN = ''010'' THEN ',
'              if :P110_IVA = ''S''          then      ',
'',
'              ',
'                    UPDATE AGENTES_DISTRIBUCION_POLIZA ADP',
'                    SET PORC_COM_DISTRIBUIDA = (PORC_COM_DISTRIBUIDA/ 1.16),',
'                        PORC_COM_PROPORCIONAL = ROUND(((PORC_COM_DISTRIBUIDA ) /:P110_PORC_COM_POLIZA)*100,2)',
'                    WHERE ADP.IDPOLIZA = :P110_NUM_POLIZA',
'                    AND ADP.COD_AGENTE_DISTR= :P110_COD_AGENTE_DISTR;  ',
'',
'                        COMMIT;',
'',
'                      OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION(nCodCia    => :P110_CODCIA',
'                                                             ,nIdPoliza  => :P110_NUM_POLIZA',
'                                                             ,nCodAgente => :P110_COD_AGENTE);',
'',
'                           SELECT COUNT(*),',
'                                   COUNT(CASE WHEN PORC_COM_DISTRIBUIDA = 0 THEN 1 END)',
'                              INTO v_total_regs, v_regs_en_cero',
'                            FROM AGENTES_DISTRIBUCION_POLIZA',
'                            WHERE IDPOLIZA = :P110_NUM_POLIZA',
'                            AND COD_AGENTE =: P110_COD_AGENTE;',
'                            ',
'                            IF v_total_regs = v_regs_en_cero AND v_total_regs > 0 THEN',
'',
'                                SELECT ROWID',
'                                  INTO v_primer_rowid',
'                                  FROM (',
'                                        SELECT ROWID',
'                                          FROM AGENTES_DISTRIBUCION_POLIZA',
'                                         WHERE IDPOLIZA = :P110_NUM_POLIZA',
'                                         AND COD_AGENTE =: P110_COD_AGENTE',
'',
'                                         ORDER BY CODNIVEL DESC, COD_AGENTE DESC',
'                                       )',
'                                 WHERE ROWNUM = 1;',
'',
'                                UPDATE AGENTES_DISTRIBUCION_POLIZA',
'                                   SET PORC_COM_PROPORCIONAL = 100',
'                                 WHERE ROWID = v_primer_rowid',
'                                 AND COD_AGENTE =: P110_COD_AGENTE;',
'',
'                            END IF;',
'',
'                ELSE ',
'                    NULL ; ',
'                END IF; ',
'         ELSE ',
'            NULL ; ',
'            END IF; ',
'     END IF; ',
'END;',
' ',
'',
''))
,p_attribute_02=>'P110_NUM_POLIZA,P110_COD_AGENTE_DISTR,P110_PORC_COM_POLIZA,P110_IVA,P110_CODTIPOPLAN,P110_COD_AGENTE'
,p_attribute_05=>'PLSQL'
