wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(619670683934489922)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Modificacion_Diversas_Polizas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    HayCliente    NUMBER;',
'    HayAsegurado  NUMBER;',
'    cAutorizado   NUMBER;',
'BEGIN',
'    /* =================================================',
'       CAMBIO DE CLIENTE (POLIZA)',
'       ================================================= */',
' ',
'    IF :P113_REQUEST = ''MODIFPOL'' THEN',
'',
'        IF :P113_NUEVO_CLIE IS NULL THEN',
'            APEX_ERROR.ADD_ERROR(',
unistr('                p_message => ''El N\00FAmero de Cliente no puede ser nulo.'','),
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'            RETURN;',
'        END IF;',
'',
'        SELECT COUNT(*)',
'          INTO cAutorizado',
'          FROM PROCESO_AUTORIZA_USUARIO',
'         WHERE CodCia     = NVL(:P113_CODCIA,1)',
'           AND CodProceso = 10017',
'           AND CodUsuario = :P113_USER;',
'',
'        IF cAutorizado = 0 THEN',
'            APEX_ERROR.ADD_ERROR(',
unistr('                p_message => ''Usted no tiene permisos para modificar el cliente de la p\00F3liza.'','),
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'            RETURN;',
'        END IF;',
'',
'        SELECT COUNT(*)',
'          INTO HayCliente',
'          FROM CLIENTES',
'         WHERE CodCliente = :P113_NUEVO_CLIE',
'           AND StsCliente = ''ACT'';',
'',
'        IF HayCliente = 0 THEN',
'            APEX_ERROR.ADD_ERROR(',
unistr('                p_message => ''El cliente no existe o no est\00E1 activo.'','),
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'            RETURN;',
'        END IF;',
'',
'        SICAS_OC.OC_MANTENIMIENTO_BOTONES_POLIZA.CAMBIA_CLIENTE(',
'            nIdPoliza   => :P113_IDPOLIZA,',
'            vCteNuevo   => :P113_NUEVO_CLIE,',
'            vCodCia     => :P113_CODCIA,',
'            vCodEmpresa => :P113_CODEMPRESA,',
'            vIdetPol    => :P113_CERTIFICADO,',
'            vFinVig     => :P113_FINVIG,',
'            vUsuario    => :P113_USER',
'        );',
'',
'        :P113_NUEVO_CLIE   := NULL;',
'        :P113_CAMBIA_CLIE := ''N'';',
'    END IF;',
'',
'',
'    /* =================================================',
'       CAMBIO DE ASEGURADO (CERTIFICADO)',
'       ================================================= */',
'  /*  ',
'    apex_application.g_print_success_message :=',
'    ''<span style="color: red; font-weight: bold;">REQUEST = ''',
'    || NVL(:P113_REQUEST,''NULL'')',
'    || ''</span>'';',
'*/',
'',
'    IF :P113_REQUEST = ''MODIFCERT'' THEN',
'        ',
'        IF :P113_NUEVO_ASEG_ IS NULL THEN',
'            APEX_ERROR.ADD_ERROR(',
unistr('                p_message => ''El C\00F3digo de Asegurado no puede ser nulo.'','),
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'            RETURN;',
'        END IF;',
'        ',
'        SELECT COUNT(*)',
'          INTO cAutorizado',
'          FROM PROCESO_AUTORIZA_USUARIO',
'         WHERE CodCia     = NVL(:P113_CODCIA,1)',
'           AND CodProceso = 9125',
'           AND CodUsuario = :P113_USER;',
'',
'        IF cAutorizado = 0 THEN',
'            APEX_ERROR.ADD_ERROR(',
'                p_message => ''No tiene permisos para modificar el asegurado.'',',
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'            RETURN;',
'        END IF;',
'',
'        SELECT COUNT(*)',
'          INTO HayAsegurado',
'          FROM ASEGURADO',
'         WHERE Cod_Asegurado = :P113_NUEVO_ASEG_;',
'',
'        IF HayAsegurado = 0 THEN',
'            APEX_ERROR.ADD_ERROR(',
'                p_message => ''El asegurado no existe.'',',
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'            RETURN;',
'        END IF;',
'',
'        SICAS_OC.OC_MANTENIMIENTO_BOTONES_POLIZA.CAMBIA_ASEGURADO(',
'            nIdPoliza   => :P113_IDPOLIZA,',
'            nIdetPol    => :P113_CERTIFICADO,',
'            vAseNuevo   => :P113_NUEVO_ASEG_,',
'            vCodCia     => :P113_CODCIA,',
'            vCodEmpresa => :P113_CODEMPRESA,',
'            vUsuario    => :P113_USER',
'        );',
'',
'        :P113_NUEVO_ASEG_ := NULL;',
'        :P113_CAMBIA_ASEG := ''N'';',
'    END IF;',
'    ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(605493056941114186)
,p_process_success_message=>unistr('Se cambi\00F3 el dato correctamente')
,p_internal_uid=>48093477350631237
);
