,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Renovar_Poliza'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nIdPoliza     POLIZAS.IDPOLIZA%TYPE;',
'    nIdCotizacion COTIZACIONES.IdCotizacion%TYPE;',
'BEGIN',
'    nIdCotizacion := :P114_COTIZA_REN;',
'',
'    /*Se agrego proceso de correccion de asistencias ABHC MAY26*/',
'    OC_PROCEDIMIENTOS_MANTENIMIENTO_POLIZA.CORRECION_ASISTENCIAS_ASEGURADO(:P114_CODCIA, 1, :P114_CONSECUTIVO);',
'',
'    nIdPoliza := OC_POLIZAS.RENOVAR(:P114_CODCIA,:P114_CONSECUTIVO,''N'',',
'        :P114_SUBGRUPO,:P114_ASEGURADO,nIdCotizacion);',
'',
'    IF nIdPoliza IS NULL THEN',
unistr('        raise_application_error(-20001,''No se pudo renovar la p\00F3liza'');'),
'    END IF;',
'',
'    :P114_IDPOLIZAREN := nIdPoliza;',
'',
'    COMMIT;',
'END;',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(607090386195578597)
,p_process_success_message=>unistr('Se renov\00F3 correctamente la p\00F3liza')
,p_internal_uid=>44259747322577622
);
