wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(558717545676794562)
,p_validation_name=>'VALIDA_NUMPOLUNICO_EDIT'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nExiste NUMBER;',
'    vNumPolUnico VARCHAR2(30);',
'BEGIN',
unistr('    vNumPolUnico := REGEXP_REPLACE(:P115_NUMPOLUNICO, ''[|~^{}$!\00A1\00BF?,;\005C+#]'', '''');'),
'    vNumPolUnico := REPLACE(REPLACE(REPLACE(vNumPolUnico, CHR(10), ''''), CHR(13), ''''), '' '', '''');',
'',
'    SELECT COUNT(*)',
'    INTO nExiste',
'    FROM POLIZAS',
'    WHERE CodCia      = :P115_CODCIA',
'      AND CodEmpresa  = :P115_CODEMPRESA',
'      AND NumpolUnico = vNumPolUnico',
'      AND StsPoliza   IN (''EMI'',''SOL'')',
'      AND (',
'            :P115_IDPOLIZA IS NULL',
'            OR IdPoliza != :P115_IDPOLIZA',
'          );',
'',
'    RETURN nExiste = 0;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('No. de P\00F3liza Unico YA fue Asignado para otra P\00F3liza que est\00E1 Emitida o en Solicitud.')
,p_always_execute=>'Y'
,p_validation_condition=>'P115_NUMPOLUNICO'
,p_validation_condition_type=>'ITEM_IS_NOT_NULL'
,p_when_button_pressed=>wwv_flow_imp.id(607212668079547231)
,p_associated_item=>wwv_flow_imp.id(607162147137547195)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
