'',
'    IF :P115_INDMANEJAFONDOS = ''S'' THEN',
'        IF NVL(:P115_IDFORMACOBRO, 0) = 0 THEN',
unistr('            RETURN ''Debe Ingresar el Correlativo de Forma de Cobro para P\00F3lizas que Manejan Fondos'';'),
'        ELSE',
