,p_event_id=>wwv_flow_imp.id(598276764732444014)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cTipo_Doc_Identificacion    CLIENTES.Tipo_Doc_Identificacion%TYPE;',
'    cNum_Doc_Identificacion     CLIENTES.Num_Doc_Identificacion%TYPE;',
'    cNomGrupoEcon               VARCHAR2(50);',
'    cNumGrupoEcon               VARCHAR2(50);',
'BEGIN',
'    :P115_SHOW_ERROR := null;',
'    ',
'    IF :P115_INDMANEJAFONDOS = ''S'' THEN',
'        ',
'        BEGIN',
'            SELECT Tipo_Doc_Identificacion, Num_Doc_Identificacion',
'            INTO cTipo_Doc_Identificacion, cNum_Doc_Identificacion',
'            FROM CLIENTES',
'            WHERE CodCliente   = :P115_CODCLIENTE;',
'',
'            IF OC_PERSONA_NATURAL_JURIDICA.EMAIL(cTipo_Doc_Identificacion, cNum_Doc_Identificacion) IS NULL THEN',
unistr('                :P115_SHOW_ERROR := ''Debe Ingresar el Email para el Contratante de la P\00F3liza en Persona Natural Jur\00EDdica'';'),
'            END IF;',
'',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
unistr('                    :P115_SHOW_ERROR := ''C\00F3digo de Cliente - NO EXISTE!!!, No se encontraron coincidencias en Persona Natural Jur\00EDdica'';'),
'',
'                WHEN TOO_MANY_ROWS THEN',
unistr('                    :P115_SHOW_ERROR := ''Existe Varios Registros para el C\00F3digo del Cliente'';'),
'        END;',
'    END IF;',
'END;'))
,p_attribute_02=>'P115_INDMANEJAFONDOS,P115_CODCLIENTE,P115_SHOW_ERROR,P115_CODGRUPOEC,P115_CODCIA'
,p_attribute_03=>'P115_CODGRUPOEC,P115_SHOW_ERROR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
