,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    wcNomGrupoEcon   VARCHAR2(50);',
'BEGIN',
'    IF OC_CLIENTES.EXISTE_CLIENTE(:P115_CODCLIENTE) = ''S'' THEN',
'        :P115_DESC_CODCLIENTE := OC_CLIENTES.NOMBRE_CLIENTE(:P115_CODCLIENTE);',
'',
'        :P115_TIPO_DOC_IDENTIFICACION   := OC_CLIENTES.TIPO_DOC_IDENTIFICACION(:P115_CODCLIENTE);',
'        :P115_NUM_DOC_IDENTIFICACION    := OC_CLIENTES.NUM_DOC_IDENTIFICACION(:P115_CODCLIENTE);',
'        ',
'        IF OC_GRUPO_ECONOMICO.NOMBRE_GRUPO_ECONOMICO(:P115_CODCIA, :P115_CODCLIENTE) = ''NO EXISTE'' THEN',
'            wcNomGrupoEcon := OC_GRUPO_ECONOMICO.ALTA_AUTOMATICA(:P115_CODCLIENTE,:P115_CODCIA);',
'',
'            IF wcNomGrupoEcon = ''0'' THEN',
'                :P115_SHOW_ERROR := ''Error al crear el Grupo Economico de forma automatica'';',
'            ELSE',
'                :P115_CODGRUPOEC := :P115_CODCLIENTE;',
'                :P115_CNOMGRUPOECON := OC_GRUPO_ECONOMICO.NOMBRE_GRUPO_ECONOMICO(:P115_CODCIA, :P115_CODCLIENTE);',
'            END IF;',
'        ELSE',
'            :P115_CODGRUPOEC := :P115_CODCLIENTE;',
'            :P115_CNOMGRUPOECON := OC_GRUPO_ECONOMICO.NOMBRE_GRUPO_ECONOMICO(:P115_CODCIA, :P115_CODCLIENTE);',
'        END IF;        ',
'        ',
'    ELSE',
'        :P115_SHOW_ERROR := ''No. de Cliente ''||:P115_CODCLIENTE||'' no existe.'';',
'        :P115_DESC_CODCLIENTE := ''CLIENTE NO VALIDO'';',
'        :P115_CODGRUPOEC := NULL;',
'        :P115_CNOMGRUPOECON := NULL;',
'    END IF;',
'END;'))
,p_attribute_02=>'P115_CODCIA,P115_CODCLIENTE,P115_SHOW_ERROR,P115_CODGRUPOEC,P115_CNOMGRUPOECON'
,p_attribute_03=>'P115_SHOW_ERROR,P115_CODGRUPOEC,P115_CNOMGRUPOECON,P115_DESC_CODCLIENTE,P115_NUM_DOC_IDENTIFICACION,P115_TIPO_DOC_IDENTIFICACION'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
