,p_name=>'VALIDA_COTIZA_EXISTA'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    :P115_SHOW_ERROR := NULL;',
'',
'    IF GT_COTIZACIONES.EXISTE_COTIZACION_EMITIDA(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION) = ''S'' THEN',
'        IF (GT_COTIZACIONES.INICIO_VIGENCIA(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION) + ',
'        GT_COTIZACIONES.DIAS_RETROACTIVIDAD_EMISION(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION)) < TO_DATE(SUBSTR(:P115_FECINIVIG,1,10)) THEN',
'            :P115_VALIDA_ITEM := ''N'';',
unistr('            :P115_SHOW_ERROR := ''No. de Cotizaci\00F3n Supera los D\00EDas de Retroactividad para su Emisi\00F3n.'';'),
'        ELSE',
'            :P115_VALIDA_ITEM := ''S'';',
'            :P115_FECCOTIZACION := GT_COTIZACIONES.FECHA_COTIZACION(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION);',
'        END IF;',
'    ELSE',
'        :P115_VALIDA_ITEM := ''N'';',
unistr('        :P115_SHOW_ERROR := ''No. de Cotizaci\00F3n no Existe o no Est\00E1 Emitida.'';'),
'    END IF;',
'    ',
'END;'))
,p_attribute_02=>'P115_CODCIA,P115_CODEMPRESA,P115_NUM_COTIZACION,P115_FECINIVIG'
,p_attribute_03=>'P115_SHOW_ERROR,P115_VALIDA_ITEM,P115_FECCOTIZACION'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
