'BEGIN',
'    :P115_SHOW_ERROR := NULL;',
'',
'    IF :P115_NUM_COTIZACION IS NOT NULL AND :P115_NUM_COTIZACION > 0 THEN',
'',
'        IF TO_DATE(SUBSTR(:P115_FECINIVIG,1,10)) NOT BETWEEN GT_COTIZACIONES.INICIO_VIGENCIA(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION) AND (GT_COTIZACIONES.INICIO_VIGENCIA(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION) + ',
'            GT_COTIZACIONES.DIAS_RETROACTIVIDAD_EMISION(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION)) THEN',
'            :P115_VALIDA_ITEM := ''N'';',
unistr('            :P115_SHOW_ERROR := ''La fecha no se Encuentra Dentro de los Dias de Retroactividad Permitidos en la Cotizaci\00F3n'';'),
'        ELSE',
'            :P115_VALIDA_ITEM := NULL;',
'            :P115_SHOW_ERROR := NULL;',
'        END IF;',
'    ELSE',
'        :P115_VALIDA_ITEM := NULL;    ',
'    END IF;',
'END;'))
,p_attribute_02=>'P115_CODCIA,P115_CODEMPRESA,P115_NUM_COTIZACION,P115_FECINIVIG'
,p_attribute_03=>'P115_SHOW_ERROR,P115_VALIDA_ITEM'
