 p_id=>wwv_flow_imp.id(614577996843070987)
,p_event_id=>wwv_flow_imp.id(614577879324070986)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nExistCli   NUMBER := NULL;',
'    cMensaje    VARCHAR(100);',
'BEGIN',
'    BEGIN',
'        SELECT CODCLIENTE',
'        INTO nExistCli',
'        FROM CLIENTES',
'        WHERE 1=1',
'        AND TIPO_DOC_IDENTIFICACION = :P115_CLI_TIPO_DOC_IDENTIFICACION',
'        AND NUM_DOC_IDENTIFICACION  = :P115_CLI_NUM_DOC_IDENTIFICACION;',
'',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                nExistCli := NULL;',
'            WHEN TOO_MANY_ROWS THEN',
'                nExistCli := 99999999;',
'    END;',
'',
'    IF nExistCli IS NOT NULL THEN',
'        IF nExistCli = 99999999 THEN',
'            cMensaje := ''Existen Varios Registros de Clientes con la Identificacion: ''',
'                        ||:P115_CLI_TIPO_DOC_IDENTIFICACION||''-''||:P115_CLI_NUM_DOC_IDENTIFICACION|| '' !Verificar Registros!'';',
'        ELSE',
unistr('            cMensaje := ''Cliente ya Existe con el C\00F3digo No. ''||nExistCli;'),
'        END IF;',
'    ELSE',
'        IF :P115_CLI_NUM_DOC_IDENTIFICACION IS NOT NULL THEN',
'            cMensaje := OC_PERSONA_NATURAL_JURIDICA.NOMBRE_COMPLETO(:P115_CLI_TIPO_DOC_IDENTIFICACION,:P115_CLI_NUM_DOC_IDENTIFICACION);',
'        ELSE',
'            cMensaje := NULL;',
'        END IF;',
'    END IF;       ',
'',
'    :P115_CLI_CNOMCLIENTE := cMensaje;',
'END;'))
,p_attribute_02=>'P115_CLI_NUM_DOC_IDENTIFICACION,P115_CLI_TIPO_DOC_IDENTIFICACION'
,p_attribute_03=>'P115_CLI_CNOMCLIENTE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(690440983571095281)
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(543652526352265748)
,p_event_id=>wwv_flow_imp.id(614577879324070986)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nExistCli   NUMBER := NULL;',
'    cMensaje    VARCHAR(100);',
'BEGIN',
'    :P115_SHOW_ERROR := NULL;',
'    :P115_SELECT_CLIENTE := ''N'';',
'    :P115_MESSAGE_CLIENTE := NULL;',
'    ',
'    IF :P115_CLI_TIPO_DOC_IDENTIFICACION IS NOT NULL THEN',
'        BEGIN',
'            SELECT CODCLIENTE',
'            INTO nExistCli',
'            FROM CLIENTES',
'            WHERE 1=1',
'            AND TIPO_DOC_IDENTIFICACION = :P115_CLI_TIPO_DOC_IDENTIFICACION',
'            AND NUM_DOC_IDENTIFICACION  = :P115_CLI_NUM_DOC_IDENTIFICACION;',
'',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    nExistCli := NULL;',
'                WHEN TOO_MANY_ROWS THEN',
'                    nExistCli := -1;',
'        END;',
'',
'        cMensaje := OC_PERSONA_NATURAL_JURIDICA.NOMBRE_COMPLETO(:P115_CLI_TIPO_DOC_IDENTIFICACION,:P115_CLI_NUM_DOC_IDENTIFICACION);',
'        ',
'        IF nExistCli IS NULL THEN',
'            IF cMensaje IS NULL THEN',
'                cMensaje := ''Persona no Existe en Persona Natural Juridica'';',
'                :P115_SHOW_ERROR := cMensaje;',
'                :P115_SELECT_CLIENTE := ''N'';',
'            ELSE',
'                :P115_SELECT_CLIENTE := ''S'';',
'            END IF;',
'        ELSE',
'            IF nExistCli = -1 THEN',
'                cMensaje := ''Existen Varios Registros de Clientes con Tipo de Documento: ''',
unistr('                            ||:P115_CLI_TIPO_DOC_IDENTIFICACION||'', y No. de Identificaci\00F3n: ''||:P115_CLI_NUM_DOC_IDENTIFICACION||''.'';'),
'                :P115_SHOW_ERROR := cMensaje;',
'            ELSE',
unistr('            --     cMensaje := ''N\00FAmero de Cliente: ''||nExistCli;'),
unistr('                :P115_MESSAGE_CLIENTE := ''Cliente ya Existe con N\00FAmero de Cliente: ''||nExistCli;'),
'            END IF;',
'        END IF;',
'        :P115_CLI_CNOMCLIENTE := cMensaje;',
'    END IF;      ',
'',
'END;'))
,p_attribute_02=>'P115_CLI_NUM_DOC_IDENTIFICACION,P115_CLI_TIPO_DOC_IDENTIFICACION'
,p_attribute_03=>'P115_CLI_CNOMCLIENTE,P115_SHOW_ERROR,P115_SELECT_CLIENTE,P115_MESSAGE_CLIENTE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
