'DECLARE',
'    nExistCli   NUMBER := NULL;',
'    cMensaje    VARCHAR(100) := NULL;',
'BEGIN',
'    :P115_SHOW_ERROR := NULL;',
'',
'    IF :P115_GE_CODGRUPOEC IS NULL THEN',
