'    END IF;',
'',
'    IF :P115_GE_TIPO_DOC_IDENTIFICACION IS NULL THEN',
'        :P115_SHOW_ERROR := :P115_SHOW_ERROR||''Seleccionar "Tipo Doc. Ident.". '';',
'    END IF;',
'',
'    IF :P115_GE_NUM_DOC_IDENTIFICACION IS NULL THEN',
'        :P115_SHOW_ERROR := :P115_SHOW_ERROR||''Ingresar "No. Doc. Ident"'';',
'    END IF;    ',
