'    IF :P115_SHOW_ERROR IS NULL THEN',
'',
'        cMensaje := OC_PERSONA_NATURAL_JURIDICA.EXISTE_PERSONA(:P115_GE_TIPO_DOC_IDENTIFICACION,:P115_GE_NUM_DOC_IDENTIFICACION);',
'',
'        IF cMensaje = ''N'' THEN',
'            :P115_SHOW_ERROR := ''Persona no Existe en Persona Natural Juridica'';',
'        END IF;',
'',
'    END IF;',
'',
'END;'))
