 p_id=>wwv_flow_imp.id(617703572356382908)
,p_event_id=>wwv_flow_imp.id(617703477683382907)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cTipoDocIdentificacion  CLIENTES.Tipo_Doc_Identificacion%TYPE;',
'    cNumDo_Identificacion   CLIENTES.Num_Doc_Identificacion%TYPE; ',
'    cTipoPersona            PERSONA_NATURAL_JURIDICA.Tipo_Persona%TYPE; -- TIPO DE PERSONA PNJ',
'BEGIN',
'    :P115_SHOW_ERROR_2 := NULL;',
'',
'    IF OC_CLIENTES.EXISTE_CLIENTE(:P115_CODCLIENTE) = ''S'' THEN',
'        cTipoDocIdentificacion  := OC_CLIENTES.Tipo_Doc_Identificacion(:P115_CODCLIENTE);',
'        cNumDo_Identificacion   := OC_CLIENTES.Num_Doc_Identificacion(:P115_CODCLIENTE);',
'        ',
'        cTipoPersona := OC_PERSONA_NATURAL_JURIDICA.TIPO_PERSONA(cTipoDocIdentificacion, cNumDo_Identificacion);',
'',
'        IF cTipoPersona IS NULL THEN',
'            :P115_INDFACTURAPOL := ''N'';',
'            :P115_CODUSOCFDI := NULL;',
'            :P115_CODOBJETOIMP := NULL;',
'            :P115_VALIDA_ITEM := ''N'';',
'',
unistr('            :P115_SHOW_ERROR_2 := ''Cliente: ''||:P115_CODCLIENTE||'' no tiene Definido Tipo de Persona en Persona Natural Jur\00EDdica.'),
unistr('                                    No se Habilitan Datos de Facturaci\00F3n'';'),
'        ELSE',
'            :P115_VALIDA_ITEM := ''S'';',
'            ',
'            IF :P115_INDFACTURAPOL = ''S'' THEN',
'                :P115_CODUSOCFDI := ''G03'';',
'                :P115_CODOBJETOIMP := ''02'';',
'            END IF;',
'',
unistr('            -- :P115_SHOW_ERROR_2 := ''Cliente No. ''||:P115_CODCLIENTE; -- Eliminar validaci\00F3n a posteriori'),
'        END IF;',
'',
'    /*ELSE',
unistr('        :P115_SHOW_ERROR_2 := ''NO EXISTE''; -- Eliminar validaci\00F3n a posteriori*/'),
'    END IF;',
'END;'))
,p_attribute_02=>'P115_CODCLIENTE,P115_INDFACTURAPOL'
,p_attribute_03=>'P115_SHOW_ERROR_2,P115_CODUSOCFDI,P115_CODOBJETOIMP,P115_VALIDA_ITEM,P115_INDFACTURAPOL'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
