,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P115_SHOW_ERROR := NULL;',
'',
'IF :P115_FC_CODFORMACOBRO IS NULL THEN',
'    :P115_SHOW_ERROR := ''Seleccionar Forma de Cobro'';',
'ELSIF :P115_FC_CODENTIDADFINAN IS NULL THEN',
'    :P115_SHOW_ERROR := ''Seleccionar Entidad Financiera'';',
'ELSIF :P115_FC_CODFORMACOBRO IN (''TRS'',''DEP'',''DXN'') AND :P115_FC_NUMCUENTABANCARIA IS NULL THEN',
'    :P115_SHOW_ERROR := ''Capturar No. de Cuenta Bancaria'';',
'ELSIF :P115_FC_CODFORMACOBRO IN (''CLAB'') AND :P115_FC_NUMCUENTACLABE IS NULL THEN',
'    :P115_SHOW_ERROR := ''Capturar No. de Cuenta CLABE'';',
'ELSIF :P115_FC_CODFORMACOBRO IN (''CTC'',''LIN'',''TELT'') AND (:P115_FC_NUMTARJETA IS NULL OR :P115_FC_FECHAVENCTARJETA IS NULL) THEN',
'    :P115_SHOW_ERROR := ''Capturar No. de Tarjeta o Fecha Vigencia Tarjeta'';',
'ELSIF :P115_FC_NOMBRETITULAR IS NULL THEN',
'    :P115_SHOW_ERROR := ''Capturar Nombre del Titualar'';',
'END IF;'))
,p_attribute_02=>'P115_FC_CODFORMACOBRO,P115_FC_NUMCUENTABANCARIA,P115_FC_NUMCUENTACLABE,P115_FC_NUMTARJETA,P115_FC_FECHAVENCTARJETA,P115_FC_CODENTIDADFINAN,P115_FC_NOMBRETITULAR'
,p_attribute_03=>'P115_SHOW_ERROR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
