,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cTIPO_DOC_IDENTIFICACION    SICAS_OC.MEDIOS_DE_COBRO.TIPO_DOC_IDENTIFICACION%TYPE;',
'    cNUM_DOC_IDENTIFICACION     SICAS_OC.MEDIOS_DE_COBRO.NUM_DOC_IDENTIFICACION%TYPE;',
'    nIDFORMACOBRO               SICAS_OC.MEDIOS_DE_COBRO.IDFORMACOBRO%TYPE;',
'BEGIN',
'    :P115_SHOW_ERROR := NULL;',
'',
'    IF OC_CLIENTES.EXISTE_CLIENTE(:P115_CODCLIENTE) = ''S'' THEN',
'        cTIPO_DOC_IDENTIFICACION    := OC_CLIENTES.TIPO_DOC_IDENTIFICACION(:P115_CODCLIENTE);',
'        cNUM_DOC_IDENTIFICACION     := OC_CLIENTES.NUM_DOC_IDENTIFICACION(:P115_CODCLIENTE);',
'',
'        SELECT NVL(MAX(IDFORMACOBRO),0) + 1',
'        INTO nIDFORMACOBRO',
'        FROM SICAS_OC.MEDIOS_DE_COBRO',
'        WHERE TIPO_DOC_IDENTIFICACION = cTIPO_DOC_IDENTIFICACION',
'        AND NUM_DOC_IDENTIFICACION = cNUM_DOC_IDENTIFICACION;',
'',
'        INSERT INTO SICAS_OC.MEDIOS_DE_COBRO (TIPO_DOC_IDENTIFICACION, NUM_DOC_IDENTIFICACION, IDFORMACOBRO, INDMEDIOPRINCIPAL,',
'                                            CODFORMACOBRO, CODENTIDADFINAN, NUMCUENTABANCARIA, NUMCUENTACLABE,',
'                                            NUMTARJETA, FECHAVENCTARJETA, NOMBRETITULAR)',
'        VALUES(cTIPO_DOC_IDENTIFICACION,cNUM_DOC_IDENTIFICACION,nIDFORMACOBRO,:P115_FC_INDMEDIOPRINCIPAL,',
'                :P115_FC_CODFORMACOBRO,:P115_FC_CODENTIDADFINAN,:P115_FC_NUMCUENTABANCARIA,:P115_FC_NUMCUENTACLABE,',
'                :P115_FC_NUMTARJETA,SUBSTR(:P115_FC_FECHAVENCTARJETA,1,10),:P115_FC_NOMBRETITULAR);',
'',
'        /*:P115_SHOW_ERROR := ''INSERT INTO SICAS_OC.MEDIOS_DE_COBRO (TIPO_DOC_IDENTIFICACION, NUM_DOC_IDENTIFICACION, IDFORMACOBRO, INDMEDIOPRINCIPAL,',
'                                            CODFORMACOBRO, CODENTIDADFINAN, NUMCUENTABANCARIA, NUMCUENTACLABE,',
'                                            NUMTARJETA, FECHAVENCTARJETA, NOMBRETITULAR)',
'        VALUES(cTIPO_DOC_IDENTIFICACION,cNUM_DOC_IDENTIFICACION,nIDFORMACOBRO,''||:P115_FC_INDMEDIOPRINCIPAL||'',''||',
'                :P115_FC_CODFORMACOBRO||'',''||:P115_FC_CODENTIDADFINAN||'',''||NVL(:P115_FC_NUMCUENTABANCARIA,NULL)||'',''||NVL(:P115_FC_NUMCUENTACLABE,NULL)||'',''||',
'                :P115_FC_NUMTARJETA||'',''||SUBSTR(:P115_FC_FECHAVENCTARJETA,1,10)||'',''||:P115_FC_NOMBRETITULAR||'');'';*/',
'             ',
'    ELSE',
unistr('        :P115_SHOW_ERROR := ''N\00FAmero de Cliente no Existe'';'),
'    END IF;',
'END;'))
,p_attribute_02=>'P115_CODCLIENTE,P115_FC_INDMEDIOPRINCIPAL,P115_FC_CODFORMACOBRO,P115_FC_CODENTIDADFINAN,P115_FC_NUMCUENTABANCARIA,P115_FC_NUMCUENTACLABE,P115_FC_NUMTARJETA,P115_FC_FECHAVENCTARJETA,P115_FC_NOMBRETITULAR'
,p_attribute_03=>'P115_SHOW_ERROR'
