wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(612198352873178595)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_POLIZAS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nIdTarea                    TAREA.IdTarea%TYPE;',
'    dFechaEsperada              TAREA.FechaEsperada%TYPE;',
'    nTiempo                     PROC_TAREA.Tiempo%TYPE;',
'    cParametro_Tiempo           PROC_TAREA.Parametro_Tiempo%TYPE;',
'    p_msg_regreso               VARCHAR2(50);',
'    nIDPoliza                   POLIZAS.IDPOLIZA%TYPE;',
'BEGIN',
'',
'    :P115_STSPOLIZA     := ''SOL'';',
'    nIDPoliza           := OC_POLIZAS.F_GET_NUMPOL(p_msg_regreso);',
'',
'    IF :P115_NUMPOLUNICO IS NULL THEN',
'        :P115_NUMPOLUNICO := nIDPoliza|| ''-'' ||''00'';',
'    END IF;',
'',
'    BEGIN',
'        SELECT Tiempo, Parametro_Tiempo ',
'        INTO nTiempo,cParametro_Tiempo',
'        FROM PROC_TAREA',
'        WHERE PROINI = ''SOL''',
'        AND PROFIN  = ''EMI''',
'        AND IDPROCESO = 7;',
'',
'        IF cParametro_Tiempo = ''M'' THEN',
'            dFechaEsperada := TRUNC (ADD_MONTHS (SYSDATE,nTiempo));',
'        ELSIF cParametro_Tiempo = ''D'' THEN',
'            dFechaEsperada := TRUNC (SYSDATE + nTiempo);',
'        END IF;',
'',
'        SELECT NVL(MAX(IdTarea),0)+1',
'        INTO nIdTarea',
'        FROM TAREA',
'        WHERE CodCia = :P115_CODCIA;',
'',
'        INSERT INTO TAREA (CodCia,IdTarea,CodUsuario,TipoTarea,SubTipoTarea,NombreTarea,IdPoliza,Estado_Inicial,Estado,CodCliente,FechaGraba,FechaEsperada)',
