'            PRIMANETA_LOCAL,INDEXAINSP,STSPOLIZA,INDPRIMIN,CODDIRECREGIONAL,HORAVIGINI,HORAVIGFIN,FECSTS,CARACTERISTICA,',
'            PORCCOMIS,NUMRENOV,FECSOLICITUD,FECEMISION,FECRENOVACION',
'            ) VALUES (',
'            nIDPoliza,:P115_CODCIA,:P115_CODEMPRESA,:P115_TIPOPOL,:P115_TIPOPRORRATA,:P115_COD_MONEDA,:P115_NUMPOLUNICO,:P115_INDMANEJAFONDOS,:P115_CODCLIENTE,',
