'IF :P115_CODCLIENTE IS NOT NULL THEN',
'    :P115_DESC_CODCLIENTE := OC_CLIENTES.NOMBRE_CLIENTE(:P115_CODCLIENTE);',
'    -- :P115_DESC_CODCLIENTE := ''DSADADAS'';',
'END IF;',
'',
'IF :P115_CODGRUPOEC IS NOT NULL THEN',
'    :P115_CNOMGRUPOECON := OC_GRUPO_ECONOMICO.NOMBRE_GRUPO_ECONOMICO(1, :P115_CODCLIENTE);',
'    -- :P115_CNOMGRUPOECON := ''DSADADAS'';',
'END IF;',
'',
'IF :P115_IDPOLIZA IS NULL THEN',
'',
'    SELECT to_char(TRUNC(SYSDATE) + (12/24),''DD/MM/RRRR'') ',
'    INTO :P115_FECINIVIG',
'    FROM DUAL;',
'',
'    SELECT to_char((TRUNC(SYSDATE) + (12/24) )+ INTERVAL ''1'' YEAR,''DD/MM/RRRR'') ',
'    INTO :P115_FECFINVIG',
'    FROM DUAL;',
'',
'    :P115_HORAVIGINI := ''12:00'';',
'    :P115_HORAVIGFIN := ''12:00'';',
'',
'END IF;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>60165770855543317
);
