'BEGIN',
'',
'    IF (GT_COTIZACIONES.INICIO_VIGENCIA(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION) + ',
'        GT_COTIZACIONES.DIAS_RETROACTIVIDAD_EMISION(:P115_CODCIA, :P115_CODEMPRESA, :P115_NUM_COTIZACION)) < :P115_FECINIVIG THEN',
'        HTP.P(''ERROR'');',
'    ELSE        ',
'        HTP.P(''OK'');',
'    END IF;',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            HTP.P(''ERROR'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>38768066677760323
);
