,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
'BEGIN',
'OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION (',
'    nCodCia    => :P117_CODCIA,',
'    nIdPoliza  => :P117_IDPOLIZA,',
'    nCodAgente => :P117_COD_AGENTE',
');',
'END;',
'*/',
'DECLARE',
'nsuma number;',
'begin',
'OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION (',
'    nCodCia    => :P117_CODCIA,',
'    nIdPoliza  => :P117_IDPOLIZA,',
'    nCodAgente => :P117_COD_AGENTE',
');',
'select',
'sum(PORC_COM_DISTRIBUIDA)',
'into nsuma',
'from AGENTES_DISTRIBUCION_POLIZA',
'where IDPOLIZA = :P117_IDPOLIZA',
'and cod_agente = :P117_COD_AGENTE;',
'',
'UPDATE AGENTES_DISTRIBUCION_POLIZA',
'set PORC_COM_POLIZA = nsuma',
'where IDPOLIZA = :P117_IDPOLIZA',
'and cod_agente = :P117_COD_AGENTE;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>48891561030671211
);
