wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(618520377463658920)
,p_plug_name=>'COMPROBANTES_DETALLE'
,p_parent_plug_id=>wwv_flow_imp.id(618516941730658886)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CODCIA,',
'       NUMCOMPROB,',
'       IDDETCUENTA,',
'       FECDETALLE,',
'       NIVELCTA1,',
'       NIVELCTA2,',
'       NIVELCTA3,',
'       NIVELCTA4,',
'       NIVELCTA5,',
'       NIVELCTA6,',
'       NIVELCTA7,',
'       NIVELAUX,',
'       MOVDEBCRED,',
'       DECODE(MOVDEBCRED,''C'',MTOMOVCUENTA,0) MTOCREDITOS,',
'       DECODE(MOVDEBCRED,''D'',MTOMOVCUENTA,0) MTODEBITO,  ',
'       MTOMOVCUENTA,',
'       DESCMOVCUENTA,',
'       CODCENTROCOSTO,',
'       CODCENTROCOSTO || '' - '' || OC_CENTROS_DE_COSTOS.DESCRIPCION(1, 1, CODCENTROCOSTO) DESC_CODCENTROCOSTO,',
'       CODUNIDADNEGOCIO,',
'       CODUNIDADNEGOCIO || '' - '' || OC_UNIDADES_DE_NEGOCIO.DESCRIPCION(1, 1, CODUNIDADNEGOCIO) DESC_CODUNIDADNEGOCIO,',
'       DESCCPTOGENERAL,',
'       MTOMOVCUENTALOCAL,',
'       OC_CATALOGO_CONTABLE.NOMBRE_CUENTA(LPAD(TRIM(TO_CHAR(CODCIA)),14,''0'') ||',
'                     NIVELCTA1 || NIVELCTA2 ||',
'                     NIVELCTA3 || NIVELCTA4 ||',
'                     NIVELCTA5 || NIVELCTA6 ||',
'                     NIVELCTA7 || NIVELAUX) CUENTA_CONTABLE,',
'       DECODE(CODCENTROCOSTO,NULL,NULL,OC_CENTROS_DE_COSTOS.DESCRIPCION(1, 1, CODCENTROCOSTO)) CENTRO_COSTO,',
'       NVL(MTOMOVCUENTALOCAL,1) / NVL(MTOMOVCUENTA,1) TASA_CAMBIO',
'FROM COMPROBANTES_DETALLE',
'WHERE NUMCOMPROB = :P127_NUM_COMPROBANTE',
''))
