'   ELSE',
'      APEX_ERROR.ADD_ERROR(',
'         p_message          => ''Comprobante No. '' || :P127_NUM_COMPROBANTE || '' ya esta cuadrado'',',
'         p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'      );',
'   END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(618519020617658907)
,p_process_success_message=>'Se cuadro correctamente el comprobante'
,p_internal_uid=>100888243711370208
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(539980111186441733)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_CambiaEstado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'   IF :P127_STSCOMPROB = ''DES'' THEN',
'      APEX_ERROR.ADD_ERROR(',
'         p_message => ''No puede cambiar el estatus a comprobantes descuadrados'',',
'         p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'      );',
'',
'   ELSIF :P127_STSCOMPROB = ''CUA'' THEN  ',
'      OC_COMPROBANTES_CONTABLES.ANULA_COMPROBANTE(1,:P127_NUM_COMPROBANTE);',
'',
'   ELSIF :P127_STSCOMPROB = ''ANU'' THEN',
'      OC_COMPROBANTES_CONTABLES.REHABILITA_COMPROBANTE(1,:P127_NUM_COMPROBANTE);',
'   END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(618519109247658908)
,p_process_success_message=>unistr('Se cambi\00F3 el estatus del comprobante correctamente')
,p_internal_uid=>100888414355370210
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(539981188350441743)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_RecontabilizarComprobante'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'   IF :P127_STSCOMPROB  = ''DES'' OR :P127_ENVIO_MIZAR IS NULL THEN',
'',
'      OC_COMPROBANTES_CONTABLES.RECONTABILIZAR(',
'         1,',
'         :P127_TRANSACCION,',
'         ''C'',',
'         :P127_NUM_COMPROBANTE',
'      );',
'',
'      OC_COMPROBANTES_CONTABLES.CUADRA_COMPROBANTE(',
'         1,',
'         :P127_NUM_COMPROBANTE',
'      );',
'',
'      apex_application.g_print_success_message := ',
'         ''Comprobante No. '' || :P127_NUM_COMPROBANTE || '' recontabilizado correctamente'';',
'',
'   ELSE',
'',
'      raise_application_error(',
'         -20001,',
unistr('         ''Comprobante No. '' || :P127_NUM_COMPROBANTE || '' ya est\00E1 cuadrado'''),
'      );',
'',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      raise_application_error(',
'         -20002,',
'         ''Error al recontabilizar comprobante No. '' ||',
'         :P127_NUM_COMPROBANTE || '' - '' || SQLERRM',
'      );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(618519423316658911)
,p_internal_uid=>100889491519370220
);
end;
