,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function asignarValoresIGConFormato(fields, itemsConPeso, data) {',
'',
'  const record = data.selectedRecords[0];',
'  const model  = data.model;',
'',
'  Object.entries(fields).forEach(([pageItem, column]) => {',
'',
'    let value = model.getValue(record, column);',
'',
'    // Formato moneda solo visual',
'    if (itemsConPeso.includes(pageItem) && value !== null && value !== "") {',
'      value = "$ " + Number(value).toLocaleString("es-MX", {',
'        minimumFractionDigits: 2,',
'        maximumFractionDigits: 2',
'      });',
'    }',
'',
'    $s(pageItem, value);',
'  });',
'',
'};',
'',
unistr('// se a\00F1ade funcion para que permita eliminar los asegurados, uno a uno '),
'function borrar(COD_ASEGURADO) {',
unistr('     apex.message.confirm("\00BFDesea Eliminar el Asegurado No. " + COD_ASEGURADO + "?", function(okPressed) {'),
'        if (!okPressed) return;',
'    apex.server.process("deletecod", {',
'        x01: COD_ASEGURADO',
'    }, {',
'        dataType: "text",',
'        success: function(pData) {',
'            console.log("RAW response:", pData);',
'           apex.message.showPageSuccess("Asegurado No. " + COD_ASEGURADO + " Eliminado Correctamente.");',
'',
'            apex.region("IG_ASEGURADOS").refresh();',
'',
'            // IG_ASEGURADOS, funcion carga en el archivo js que forza a cargar el primer registro',
'            apex.region("IG_ASEGURADOS").widget().on("apexafterrefresh", function () {',
'                setTimeout(function () { seleccionarPrimerRegistro("IG_ASEGURADOS", "IG_ASEGURADOS_ig_grid_vc"); }, 300);',
'            });',
'            setTimeout(function () { ',
'                seleccionarPrimerRegistro("IG_ASEGURADOS", "IG_ASEGURADOS_ig_grid_vc"); ',
'                }, ',
'            500);',
'        },',
'        error: function(xhr) {',
'             apex.message.showErrors([{',
'                    type: "error",',
'                    location: "page",',
'                    message: "Error al eliminar el Asegurado No. " + COD_ASEGURADO',
'                }]);',
'            console.error("RAW error:", xhr.responseText);',
'        }',
'        });',
'',
'    });',
'}',
unistr('//Funcion para actualizar pesta\00F1as de coberturas'),
'function actualizarTotalesCoberturas(){',
'',
'    var primamoneda     = apex.item("P132_TOTAL_PRIMA_MONEDA").getValue();',
'    var sumaasegmoneda  = apex.item("P132_TOTAL_SUMAASEG_MONEDA").getValue();',
'    var count_cobert    = Number(apex.item("P132_COUNT_COBERT").getValue());',
'',
'    primamoneda    = formatMonedaTotal(primamoneda);',
'    sumaasegmoneda = formatMonedaTotal(sumaasegmoneda);',
'',
'    if (count_cobert > 0) {',
'        apex.item("BOT_HEREDAR_COBER").enable();',
'    } else {',
'        apex.item("BOT_HEREDAR_COBER").disable();',
'    }',
'',
'    // Mostrar valores',
'    document.getElementById("val_total_prima").textContent = primamoneda;',
'    document.getElementById("val_total_sumaasegurada").textContent = sumaasegmoneda;',
'',
'};',
'',
unistr('//Funcion para actualizar pesta\00F1as de asistencias'),
'function actualizarTotalesAsistencias(){',
'',
'    var asistlocal      = apex.item("P132_TOTAL_MONTOASISTLOCAL").getValue();',
'    var asistmoneda     = apex.item("P132_TOTAL_MONTOASISTMONEDA").getValue();',
'    var count_asist     = Number(apex.item("P132_COUNT_ASISTS").getValue());',
'',
'    asistlocal  = formatMonedaTotal(asistlocal);',
'    asistmoneda = formatMonedaTotal(asistmoneda);',
'',
'    if (count_asist > 0) {',
'        apex.item("BOT_HEREDAR_ASIST").enable();',
'    } else {',
'        apex.item("BOT_HEREDAR_ASIST").disable();',
'    }',
'',
'    // Mostrar valores',
'    document.getElementById("val_total_montolocal").textContent = asistlocal;',
'    document.getElementById("val_total_montomoneda").textContent = asistmoneda;',
'',
'};',
'',
unistr('/*funci\00F3n que borra las coberturas y ademas establece los valores para que cada que se borre una cobertura, '),
'    se establesca de nuevo el valor para  P132_TOTAL_PRIMA_MONEDA y P132_TOTAL_SUMAASEG_MONEDA.',
'    Se llama a la funcion de actulizar para actulizar el html que contiene ese ID*/',
'',
'function borrarcobertura(CODCOBERT) {',
'    var valor  = CODCOBERT;',
'    var valor2 = $v(''P132_COD_ASEGURADO'');',
'    var valor3 = $v(''P132_IDPOLIZA'');',
'    var valor4 = $v(''P132_IDENDOSO'');',
'    var valor5 = $v(''P132_IDETPOL'');',
'',
unistr('    apex.message.confirm("\00BFDesea la Cobertura "+valor +"?", function(okPressed) {'),
'        if (!okPressed) return;',
'    apex.server.process("deletecod_coberturas", {',
'        x01: valor,',
'        x02: valor2,',
'        x03: valor3,',
'        x04: valor4,',
'        x05: valor5',
'    }, {',
'        dataType: "text",',
'        success: function(pData) {',
'            console.log("RAW delete response:", pData);',
'            apex.message.showPageSuccess("El Registro " + valor + " fue Eliminado Correctamente.");',
'            apex.region("IG_COBERTURAS").refresh();',
'',
'            console.log("RAW suma response:", pData);',
'',
'            try {',
'                var result = JSON.parse(pData);',
'',
'                if (result.status === "ok") {',
'                    apex.item("P132_TOTAL_PRIMA_MONEDA").setValue(result.total_prima);',
'                    apex.item("P132_TOTAL_SUMAASEG_MONEDA").setValue(result.total_sumaaseg);',
'',
unistr('                    console.log("Seteado \2014 prima:", result.total_prima, "| suma aseg:", result.total_sumaaseg);'),
'                } else {',
unistr('                    console.warn("Proceso Suma_total respondi\00F3 status:", result.status);'),
'                }',
'            } catch(e) {',
'                console.error("Error parseando respuesta:", e, pData);',
'            }',
'',
'            apex.region("IG_ASEGURADOS").refresh();',
'            apex.region("IG_COBERTURAS").refresh();',
'            actualizarTotalesCoberturas();',
'        },',
'        error: function(xhr) {',
'            console.error("RAW delete error:", xhr.responseText);',
'        }',
'    });  ',
'',
' });',
'}',
'',
'function borrarasistencia(CODASISTENCIA) {',
'    var valor  = CODASISTENCIA;',
'    var valor2 = $v(''P132_COD_ASEGURADO'');',
'    var valor3 = $v(''P132_IDPOLIZA'');',
'    var valor4 = $v(''P132_IDENDOSO'');',
'    var valor5 = $v(''P132_IDETPOL'');',
unistr('    apex.message.confirm("\00BFDesea Eliminar la Asistencia "+valor +"?", function(okPressed) {'),
'        if (!okPressed) return;',
'    apex.server.process("deletecod_asistencias", {',
'        x01: valor,',
'        x02: valor2,',
'        x03: valor3,',
'        x04: valor4,',
'        x05: valor5',
'    }, {',
'        dataType: "text",',
'        success: function(pData) {',
'            console.log("RAW delete response:", pData);',
'            apex.message.showPageSuccess("El Registro " + valor + " fue Eliminado Correctamente.");',
'            apex.region("IG_COBERTURAS").refresh();',
'',
'            console.log("RAW deletecod_asistencias response:", pData);',
'',
'            try {',
'                var result = JSON.parse(pData);',
'',
'                if (result.status === "ok") {',
'                    apex.item("P132_TOTAL_MONTOASISTLOCAL").setValue(result.monto_local);',
'                    apex.item("P132_TOTAL_MONTOASISTMONEDA").setValue(result.monto_moneda);',
'',
unistr('                    //console.log("Seteado \2014 monto_local:", result.monto_local, "| monto_moneda:", result.monto_moneda);'),
'                } else {',
unistr('                    console.warn("Proceso deletecod_asistencias respondi\00F3 status:", result.status);'),
'                }',
'            } catch(e) {',
'                console.error("Error parseando respuesta:", e, pData);',
'            }',
'',
'            apex.region("IG_ASEGURADOS").refresh();',
'            apex.region("IG_ASIST_ASEG").refresh();',
'            actualizarTotalesAsistencias();',
'        },',
'        error: function(xhr) {',
'            console.error("RAW delete error:", xhr.responseText);',
'        }',
'    });  ',
'',
' });',
'}',
'',
unistr('//Funci\00F3n Inhabilita Pesta\00F1as de Coberturas y Asistencias'),
'function tabCoberAsist(){',
'    var tab_coberturas  = document.getElementById("SR_COBERTURAS_ASEGURADO_tab");',
