wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(617705857561382931)
,p_plug_name=>'ASEGURADOS'
,p_region_name=>'IG_ASEGURADOS'
,p_parent_plug_id=>wwv_flow_imp.id(617705690095382929)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>20
,p_plug_grid_column_span=>9
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    s_qly   VARCHAR2(10000);',
'    cTIPOENDOSO ENDOSOS.TIPOENDOSO%TYPE;',
'BEGIN',
'    s_qly   :=  ''SELECT CODCIA,',
'                        IDPOLIZA,',
'                        IDETPOL,',
'                        COD_ASEGURADO,',
'                        OC_ASEGURADO.NOMBRE_ASEGURADO(CODCIA,1,COD_ASEGURADO) CNOM_ASEGURADO,',
'                        ESTADO,',
'                        SUMAASEG,',
'                        PRIMANETA,',
'                        IDENDOSO,',
'                        FECANULEXCLU,',
'                        MOTIVANULEXCLU,',
'                        SUMAASEG_MONEDA,',
'                        PRIMANETA_MONEDA,',
'                        IDENDOSOEXCLU,',
'                        MONTOAPORTEASEG,',
'                        INDAJUSUMAASEGDECL,',
'                        OC_ASEGURADO.EDAD_ASEGURADO(1,1,COD_ASEGURADO,:P132_FECINIVIG_DETPOL) EDAD,',
'                        OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''''ESTADOS'''',ESTADO) CDESCVALOR, ',
'                        null as borrar,',
'                        OC_ASEGURADO.IDENTIFICACION_TRIBUTARIA_ASEG(CODCIA,1,COD_ASEGURADO) NUM_DOC_IDENTIFICACION',
'                FROM ASEGURADO_CERTIFICADO',
'                WHERE 1=1',
'                AND IDPOLIZA = :P132_IDPOLIZA',
'                AND IDETPOL = :P132_IDETPOL'';',
'',
'        IF :P132_IDENDOSO_SUBMIT IS NOT NULL AND :P132_IDENDOSO_SUBMIT <> 0 THEN',
'            /* Querie para obtener el tipo de endoso*/',
'            BEGIN',
'                SELECT TIPOENDOSO',
'                  INTO cTIPOENDOSO',
'                  FROM ENDOSOS',
'                 WHERE IDPOLIZA = :P132_IDPOLIZA',
'                   AND IDENDOSO = :P132_IDENDOSO_SUBMIT;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    cTIPOENDOSO := NULL;',
'            END;',
'',
'            /* Condicionante para endosos y endosos de exclusion*/',
'            IF cTIPOENDOSO <> ''EXA'' THEN',
'                s_qly := s_qly || '' AND IDENDOSO = :P132_IDENDOSO_SUBMIT'';-- # de Endoso',
'            ELSE',
'                s_qly := s_qly || '' AND IDENDOSO = 0 AND IDENDOSOEXCLU =:P132_IDENDOSO_SUBMIT''; -- #numero de endoso en 0 y exclusion diferente a cero',
'            END IF;',
'        END IF;',
'    RETURN s_qly;',
'END;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P132_IDPOLIZA,P132_IDETPOL,P132_FECINIVIG_DETPOL'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
