,p_plug_display_sequence=>30
,p_plug_grid_column_span=>9
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT  -- CODEMPRESA,',
'        -- CODCIA,',
'        IDPOLIZA,',
'        IDETPOL,',
'        IDTIPOSEG,',
'        -- TIPOREF,',
'        -- NUMREF,',
'        CODCOBERT,',
'        COD_ASEGURADO,',
'        SUMAASEG_LOCAL,',
'        SUMAASEG_MONEDA,',
'        TASA,',
'        PRIMA_MONEDA,',
'        PRIMA_LOCAL,',
'        -- IDENDOSO,',
'        -- STSCOBERTURA,',
'        PLANCOB,',
'        COD_MONEDA,',
'        DEDUCIBLE_LOCAL,',
'        DEDUCIBLE_MONEDA,',
'        INDCAMBIOSAMI,',
'        SUMAASEGORIGEN,',
'        SALARIOMENSUAL,',
'        VECESSALARIO,',
'        SUMAASEGCALCULADA,',
'        EDAD_MINIMA,',
'        EDAD_MAXIMA,',
'        EDAD_EXCLUSION,',
'        SUMAASEG_MINIMA,',
'        SUMAASEG_MAXIMA,',
'        PORCEXTRAPRIMADET,',
'        MONTOEXTRAPRIMADET,',
'        SUMAINGRESADA,',
'        PRIMANIVMONEDA,',
'        PRIMANIVLOCAL,',
'        -- IDRAMOREAL,',
'        FRANQUICIAINGRESADO,',
'        -- MONTODIARIO,',
'        -- DIAS_CAL,',
'        OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(CODCIA,CODEMPRESA,IDTIPOSEG,PLANCOB,CODCOBERT) CDESCCOBERT,',
'        OC_TEXTO_COBERTURA.TEXTO_DE_COBERTURA(CODCIA,CODEMPRESA,IDTIPOSEG,PLANCOB,CODCOBERT) CTEXTOCOBERTURA,',
'        OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',StsCobertura) CDESCVALOR,',
'        CASE WHEN STSCOBERTURA = ''SOL'' THEN ''<i class="fa fa-edit"></i>''',
'                    ELSE NULL ',
'        END AS EDIT,',
'        null borrar',
'        ',
'    FROM COBERT_ACT_ASEG',
'    ',
'WHERE 1=1',
'AND IDPOLIZA = :P132_IDPOLIZA',
'AND IDETPOL = :P132_IDETPOL',
'AND IDENDOSO = :P132_IDENDOSO',
'--CASE',
'  -- WHEN  IN (''CLA'',''EXA'') THEN :P132_IDENDOSO --inidicador de TIPO de endoso ',
'  -- ELSE NVL(:P132_IDENDOSO_SUBMIT,0)',
'--END',
'AND COD_ASEGURADO = :P132_COD_ASEGURADO'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P132_IDPOLIZA,P132_IDETPOL,P132_TIPOENDOSO,P132_IDENDOSO,P132_IDENDOSO_SUBMIT,P132_COD_ASEGURADO'
