,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="custom-spinner-thona" ',
'    style="display:none; ',
'    position: fixed; ',
'    top: 0px; ',
'    left: 0px;',
'    width: 100%;',
'    height: 100%;',
'    background-color: rgb(0, 0, 0, 0.4);',
'    flex-direction: column;',
'    justify-content: center;',
'    align-items: center;',
'    z-index: 9999;',
'    opacity: 1;',
'    transition: opacity 0.2s ease;">',
'',
'    <img src="#APP_FILES#logo_thona_load.png" id="spinner-logo" style="width:80px; height:80px;">',
'',
'    <div style="color: white; font-size: 18px; margin-top: 15px; text-align: center;">Procesando, por favor espere...</div>',
'</div>',
'',
'',
'<style>',
'    #spinner-logo {',
'        animation: spin 3s linear infinite;',
'    }',
'',
'    @keyframes spin {',
'        0% { transform: rotate(0deg); }',
'        100% { transform: rotate(360deg); }',
'    }',
'</style>'))
,p_attribute_01=>'N'
,p_attribute_02=>'HTML'
);
