 p_id=>wwv_flow_imp.id(619704119203674628)
,p_event_id=>wwv_flow_imp.id(619080710652910188)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCountCobert    NUMBER := NULL;',
'    nCountAsist     NUMBER := NULL;',
'BEGIN',
'    :P132_TOTAL_SUMAASEG_MONEDA := NULL;',
'    :P132_TOTAL_PRIMA_MONEDA := NULL;',
'    :P132_TOTAL_MONTOASISTLOCAL := NULL;',
'    :P132_TOTAL_MONTOASISTMONEDA := NULL;',
'    ',
'    -- Count Coberturas',
'    SELECT COUNT(*)',
'    INTO nCountCobert',
'    FROM COBERT_ACT_ASEG',
'    WHERE 1=1',
'    AND IDPOLIZA = :P132_IDPOLIZA',
'    AND IDETPOL = :P132_IDETPOL',
'    AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'',
'    -- Count Asistencias',
'    SELECT COUNT(*)',
'    INTO nCountAsist',
'    FROM ASISTENCIAS_ASEGURADO',
'    WHERE 1=1',
'    AND IDPOLIZA = :P132_IDPOLIZA',
'    AND IDETPOL = :P132_IDETPOL',
'    AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'',
'    IF nCountCobert > 0 THEN',
'        SELECT SUM(SUMAASEG_MONEDA), SUM(PRIMA_MONEDA)',
'        INTO :P132_TOTAL_SUMAASEG_MONEDA, :P132_TOTAL_PRIMA_MONEDA',
'        FROM COBERT_ACT_ASEG',
'        WHERE 1=1',
'        AND IDPOLIZA = :P132_IDPOLIZA',
'        AND IDETPOL = :P132_IDETPOL',
'        AND IDENDOSO = NVL(:P132_IDENDOSO_SUBMIT,0)',
'        AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'    END IF;',
'',
'    IF nCountAsist > 0 THEN',
'        SELECT SUM(MONTOASISTLOCAL), SUM(MONTOASISTMONEDA)',
'        INTO :P132_TOTAL_MONTOASISTLOCAL, :P132_TOTAL_MONTOASISTMONEDA',
'        FROM ASISTENCIAS_ASEGURADO',
'        WHERE 1=1',
'        AND IDPOLIZA = :P132_IDPOLIZA',
'        AND IDETPOL = :P132_IDETPOL',
'        AND IDENDOSO = NVL(:P132_IDENDOSO_SUBMIT,0)',
'        AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'    END IF;',
'',
'    :P132_COUNT_COBERT  := NVL(nCountCobert,0);',
'    :P132_COUNT_ASISTS  := NVL(nCountAsist,0);',
'END;'))
,p_attribute_02=>'P132_IDPOLIZA,P132_IDETPOL,P132_COD_ASEGURADO,P132_IDENDOSO_SUBMIT'
,p_attribute_03=>'P132_TOTAL_SUMAASEG_MONEDA,P132_TOTAL_PRIMA_MONEDA,P132_COUNT_COBERT,P132_COUNT_ASISTS,P132_TOTAL_MONTOASISTLOCAL,P132_TOTAL_MONTOASISTMONEDA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
