,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cExistAseg      VARCHAR2(1);',
'    nCodAsegurado   ASEGURADO.Cod_Asegurado%TYPE;',
'BEGIN',
'    cExistAseg := OC_PERSONA_NATURAL_JURIDICA.EXISTE_PERSONA(:P132_ASEG_TIPO_DOC_IDENTIFICACION,:P132_ASEG_NUM_DOC_IDENTIFICACION);',
'',
'    IF cExistAseg = ''N'' THEN',
'        :P132_ASEG_CNOMCLIENTE := ''Persona no Existe en Persona Natural Juridica'';',
'    ELSIF cExistAseg = ''S'' THEN',
'        IF :P132_SHOW_ERROR = 0 THEN',
'',
'            nCodAsegurado := OC_ASEGURADO.CODIGO_ASEGURADO(1,1,:P132_ASEG_TIPO_DOC_IDENTIFICACION,:P132_ASEG_NUM_DOC_IDENTIFICACION);',
'            IF nCodAsegurado = 0 THEN',
'                :P132_ASEG_COD_ASEGURADO := ''Sin # de Asegurado Asignado'';',
'            ELSE',
'                :P132_ASEG_COD_ASEGURADO := nCodAsegurado;',
'            END IF;',
'            ',
'        END IF;',
'        ',
'        :P132_ASEG_CNOMCLIENTE := OC_PERSONA_NATURAL_JURIDICA.NOMBRE_COMPLETO(:P132_ASEG_TIPO_DOC_IDENTIFICACION,:P132_ASEG_NUM_DOC_IDENTIFICACION);',
'    END IF;',
'',
'    :P132_CEXISTASEG := cExistAseg;',
'END;'))
,p_attribute_02=>'P132_ASEG_TIPO_DOC_IDENTIFICACION,P132_ASEG_NUM_DOC_IDENTIFICACION,P132_SHOW_ERROR'
,p_attribute_03=>'P132_ASEG_CNOMCLIENTE,P132_CEXISTASEG,P132_ASEG_COD_ASEGURADO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
