,p_server_condition_expr1=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCount  NUMBER := 0;',
'BEGIN',
'    IF :P132_IDENDOSO_SUBMIT IS NOT NULL THEN',
'        ',
'        SELECT COUNT(*)',
'        INTO nCount',
'        FROM asegurado_certificado',
'        WHERE   IdPoliza    = :P132_IDPOLIZA',
'        AND     IDETPOL     = (SELECT IDETPOL FROM ENDOSOS ED',
'                                WHERE ED.IdPoliza = :P132_IDPOLIZA',
'                                AND ED.IDENDOSO = :P132_IDENDOSO_SUBMIT)',
'        AND     IDENDOSO    = :P132_IDENDOSO_SUBMIT',
'        AND     ESTADO   = ''SOL'';',
'',
'        IF nCount > 0 then',
'            RETURN FALSE;',
'        ELSE',
'            RETURN TRUE;',
'        END IF;',
'',
'    ELSE',
'        ',
'        SELECT COUNT(*)',
'        INTO nCount',
'        FROM asegurado_certificado',
'        WHERE   IdPoliza    = :P132_IDPOLIZA',
'        AND     IDETPOL     = :P132_IDETPOL',
'        AND     ESTADO   = ''SOL'';',
'',
'        IF nCount > 0 then',
'            RETURN FALSE;',
'        ELSE',
'            RETURN TRUE;',
'        END IF;',
'        ',
'    END IF;',
'END;'))
,p_server_condition_expr2=>'PLSQL'
);
