wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(620145315655435104)
,p_event_id=>wwv_flow_imp.id(620143933063435090)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCodAseg    NUMBER;',
'    cExistAseg  VARCHAR2(1);',
'BEGIN',
'    :P132_SHOW_ERROR := NULL;',
'    cExistAseg := OC_PERSONA_NATURAL_JURIDICA.EXISTE_PERSONA(:P132_ASEG_TIPO_DOC_IDENTIFICACION,:P132_ASEG_NUM_DOC_IDENTIFICACION);',
'',
'    IF cExistAseg = ''S'' THEN',
'',
'',
'',
'        IF :P132_ASEG_COD_ASEGURADO IS NOT NULL AND :P132_ASEG_COD_ASEGURADO NOT LIKE ''Sin # de Asegurado Asignado'' THEN',
'            nCodAseg := :P132_ASEG_COD_ASEGURADO;',
'        ELSE',
'            nCodAseg := OC_ASEGURADO.CODIGO_ASEGURADO(1,1,:P132_ASEG_TIPO_DOC_IDENTIFICACION,:P132_ASEG_NUM_DOC_IDENTIFICACION);',
'        END IF;',
'',
'        IF nCodAseg = 0 THEN',
'            nCodAseg := OC_ASEGURADO.INSERTAR_ASEGURADO(1,1,:P132_ASEG_TIPO_DOC_IDENTIFICACION,:P132_ASEG_NUM_DOC_IDENTIFICACION);',
'            OC_ASEGURADO_CERTIFICADO.INSERTA(1,:P132_IDPOLIZA,:P132_IDETPOL,nCodAseg,NVL(:P132_IDENDOSO_SUBMIT,0));',
'            -- :P132_SHOW_ERROR := ''INSERTA ASEGURADO Y ASEGURADO CERTIFICADO'';',
'        ELSE',
'            IF OC_ASEGURADO_CERTIFICADO.EXISTE_ASEGURADO(1,:P132_IDPOLIZA,:P132_IDETPOL,nCodAseg) = ''N'' THEN',
'                OC_ASEGURADO_CERTIFICADO.INSERTA(1,:P132_IDPOLIZA,:P132_IDETPOL,nCodAseg,NVL(:P132_IDENDOSO_SUBMIT,0));',
'                -- :P132_SHOW_ERROR := ''INSERTA ASEGURADO CERTIFICADO'';',
'            ELSE',
unistr('                :P132_SHOW_ERROR := ''Asegurado: ''||nCodAseg||'', ya esta Relacionado a la P\00F3liza ''||:P132_IDPOLIZA||'' y Certificado ''||:P132_IDETPOL;'),
'            END IF;',
'        END IF;',
'    ELSE',
unistr('        :P132_SHOW_ERROR := ''Persona no Existe en Persona Natural Juridica. No se Realizo la Inserci\00F3n de Nuevo Asegurado'';'),
'    END IF;',
'',
'    :P132_ASEG_COD_ASEGURADO := NULL;',
'    :P132_ASEG_TIPO_DOC_IDENTIFICACION := NULL;',
'    :P132_ASEG_NUM_DOC_IDENTIFICACION := NULL;',
'    :P132_ASEG_CNOMCLIENTE := NULL;',
'END;'))
,p_attribute_02=>'P132_ASEG_TIPO_DOC_IDENTIFICACION,P132_ASEG_NUM_DOC_IDENTIFICACION,P132_IDPOLIZA,P132_IDETPOL'
,p_attribute_03=>'P132_SHOW_ERROR,P132_ASEG_COD_ASEGURADO,P132_ASEG_TIPO_DOC_IDENTIFICACION,P132_ASEG_NUM_DOC_IDENTIFICACION,P132_ASEG_CNOMCLIENTE'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
