,p_server_condition_type=>'FUNCTION_BODY'
,p_server_condition_expr1=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCount  NUMBER := 0;',
'BEGIN',
'    IF :P132_IDENDOSO_SUBMIT IS NOT NULL THEN',
'        ',
'        BEGIN',
'            SELECT 1',
'            INTO nCount',
'            FROM ENDOSOS ED, DETALLE_POLIZA DP',
'            WHERE DP.IDPOLIZA  = :P132_IDPOLIZA',
'            AND ED.IDPOLIZA = DP.IDPOLIZA',
'            AND DP.IDETPOL = ED.IDETPOL',
'            AND ED.IDENDOSO    = :P132_IDENDOSO_SUBMIT',
'            AND DP.IdTipoSeg IN (''GMINDI'',''GMINDC'')',
'            AND ED.StsEndoso = ''SOL'';',
'',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    RETURN FALSE;',
'        END;',
'',
'        IF NVL(nCount,0) > 0 then',
'            RETURN TRUE;',
'        ELSE',
'            RETURN FALSE;',
'        END IF;',
'',
'    ELSE',
'        SELECT COUNT(*)',
'        INTO nCount',
'        FROM DETALLE_POLIZA',
'        WHERE IdTipoSeg IN (''GMINDI'',''GMINDC'')',
'        AND IDPOLIZA = :P132_IDPOLIZA',
'        AND IDETPOL = :P132_IDETPOL',
'        AND STSDETALLE = ''SOL'';',
'',
'        IF nCount > 0 then',
'            RETURN TRUE;',
'        ELSE',
'            RETURN FALSE;',
'        END IF;',
'    END IF;',
'END;'))
,p_server_condition_expr2=>'PLSQL'
);
