 p_id=>wwv_flow_imp.id(593391420539208307)
,p_event_id=>wwv_flow_imp.id(593390869679208302)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cNomDoc     VARCHAR2(70);',
'    cFecDoc     VARCHAR2(10);',
'    IdDocument  NUMBER  := NULL;',
'    nIdetpolIni NUMBER  := NULL; ',
'    nIdetpolFin NUMBER  := NULL; ',
'BEGIN',
'    ',
'    :P132_SHOW_ERROR := NULL;',
'    :P132_IDDOCUMENT := NULL;',
'',
'    SELECT MIN(IDetPol), MAX(IDetPol)',
'    INTO nIDetPolIni, nIDetPolFin',
'    FROM DETALLE_POLIZA',
'    WHERE CodCia    = 1',
'    AND CodEmpresa  = 1',
'    AND IdPoliza    = :P132_IDPOLIZA;',
'',
'    IF :P132_NIDETPOLINI < 1 OR :P132_NIDETPOLINI > nIDetPolFin THEN',
unistr('        :P132_SHOW_ERROR := ''N\00FAmero de Certificado Inicial no Valido.'';'),
'    END IF;',
'',
'    IF :P132_NIDETPOLFIN < :P132_NIDETPOLINI THEN',
unistr('        :P132_SHOW_ERROR := :P132_SHOW_ERROR ||'' ''||''N\00FAmero de Certificado Final es Menor al N\00FAmero de Certificado Inicial.'';'),
'    END IF;',
'    ',
'    IF :P132_NIDETPOLFIN > nIDetPolFin THEN',
unistr('        :P132_SHOW_ERROR := :P132_SHOW_ERROR ||'' ''||''N\00FAmero de Certificado Final no Valido.'';'),
'    END IF;',
'',
'    IF :P132_SHOW_ERROR IS NULL THEN',
'        cFecDoc := TO_CHAR(SYSDATE,''DD-MM-YYYY'');',
'        cNomDoc := ''LISTA_ASEGURADOS_''||cFecDoc||''_POLIZA_''||:P132_IDPOLIZA||''_CERTIFICADO_''||:P132_NIDETPOLINI||''_AL_''||:P132_NIDETPOLFIN||''.xls'';',
'',
'        SICAS_OC.GENERAR_LISTADO_ASEGURADOS(cNomDoc,1,1,:P132_IDPOLIZA,:P132_NIDETPOLINI,:P132_NIDETPOLFIN,IdDocument);',
'',
'        IF IdDocument IS NOT NULL THEN',
'            :P132_IDDOCUMENT := APEX_UTIL.PREPARE_URL(',
'                                p_url => ''f?p='' || :APP_ID || '':0:'' || :APP_SESSION || '':APPLICATION_PROCESS=GET_FILE_APEX:::FILE_ID:''||IdDocument,',
'                                p_checksum_type => ''SESSION'');',
'        END IF;',
'    END IF;',
'    ',
'    -- SICAS_OC.GENERAR_LISTADO_ASEGURADOS(''LISTA_ASEGURADOS_PRUEBA_OSCAR.xls'',1,1,68916,1,1,IdDocument);',
'    -- DBMS_OUTPUT.PUT_LINE(''el id devuelto por el proceso es: ''||IdDocument);',
'END;'))
,p_attribute_02=>'CCODCIA,P13_IDPOLIZA,P132_NIDETPOLFIN,P132_NIDETPOLINI'
,p_attribute_03=>'P132_SHOW_ERROR,P132_IDDOCUMENT'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
