'DECLARE',
'    nAsegSini      NUMBER(10);',
'BEGIN',
'    :P132_SHOW_ERROR := NULL;',
'',
'    SELECT COUNT(*)',
'    INTO nAsegSini',
'    FROM ASEGURADO_CERTIFICADO A',
'    WHERE IdPoliza  = :P132_IDPOLIZA',
'    AND CodCia      = 1',
'    AND IdEndoso    = NVL(:P132_IDENDOSO_SUBMIT,0)',
'    AND Estado      IN (''SOL'',''XRE'')',
'    AND EXISTS (SELECT ''S''',
'                FROM SINIESTRO',
'                WHERE CodCia    = A.CodCia',
'                AND IdPoliza    = A.IdPoliza',
'                AND Cod_Asegurado = A.Cod_Asegurado);',
'    ',
'    IF NVL(nAsegSini,0) > 0 THEN',
'        :P132_SHOW_ERROR := ''NO PUEDE ELIMINAR los Asegurados porque ya Tienen Siniestros'';',
'    END IF;',
'               ',
'END;'))
,p_attribute_02=>'P132_IDPOLIZA,P132_IDENDOSO_SUBMIT'
,p_attribute_03=>'P132_SHOW_ERROR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
