wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(538582076607360527)
,p_event_id=>wwv_flow_imp.id(598545603659198451)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCountCobert    NUMBER := NULL;',
'BEGIN',
'    :P132_TOTAL_SUMAASEG_MONEDA := NULL;',
'    :P132_TOTAL_PRIMA_MONEDA := NULL;',
'    ',
'    -- Count Coberturas',
'    SELECT COUNT(*)',
'    INTO nCountCobert',
'    FROM COBERT_ACT_ASEG',
'    WHERE 1=1',
'    AND IDPOLIZA = :P132_IDPOLIZA',
'    AND IDETPOL = :P132_IDETPOL',
'    AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'',
'    IF nCountCobert > 0 THEN',
'        SELECT SUM(SUMAASEG_MONEDA), SUM(PRIMA_MONEDA)',
'        INTO :P132_TOTAL_SUMAASEG_MONEDA, :P132_TOTAL_PRIMA_MONEDA',
'        FROM COBERT_ACT_ASEG',
'        WHERE 1=1',
'        AND IDPOLIZA = :P132_IDPOLIZA',
'        AND IDETPOL = :P132_IDETPOL',
'        AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'    END IF;',
'',
'    :P132_COUNT_COBERT  := NVL(nCountCobert,0);',
'END;'))
,p_attribute_02=>'P132_IDPOLIZA,P132_IDETPOL,P132_COD_ASEGURADO'
,p_attribute_03=>'P132_TOTAL_SUMAASEG_MONEDA,P132_TOTAL_PRIMA_MONEDA,P132_COUNT_COBERT,P132_COUNT_ASISTS'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
