'DECLARE',
'    nCountAsist     NUMBER := NULL;',
'BEGIN',
'    :P132_TOTAL_MONTOASISTLOCAL := NULL;',
'    :P132_TOTAL_MONTOASISTMONEDA := NULL;',
'',
'    -- Count Asistencias',
'    SELECT COUNT(*)',
'    INTO nCountAsist',
'    FROM ASISTENCIAS_ASEGURADO',
'    WHERE 1=1',
'    AND IDPOLIZA = :P132_IDPOLIZA',
'    AND IDETPOL = :P132_IDETPOL',
'    AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'',
'    IF nCountAsist > 0 THEN',
'        SELECT SUM(MONTOASISTLOCAL), SUM(MONTOASISTMONEDA)',
'        INTO :P132_TOTAL_MONTOASISTLOCAL, :P132_TOTAL_MONTOASISTMONEDA',
'        FROM ASISTENCIAS_ASEGURADO',
'        WHERE 1=1',
'        AND IDPOLIZA = :P132_IDPOLIZA',
'        AND IDETPOL = :P132_IDETPOL',
'        AND IDENDOSO = NVL(:P132_IDENDOSO_SUBMIT,0)',
'        AND COD_ASEGURADO = :P132_COD_ASEGURADO;',
'    END IF;',
'',
'    :P132_COUNT_ASISTS  := NVL(nCountAsist,0);',
'END;'))
,p_attribute_02=>'P132_IDPOLIZA,P132_IDETPOL,P132_COD_ASEGURADO'
,p_attribute_03=>'P132_TOTAL_SUMAASEG_MONEDA,P132_TOTAL_PRIMA_MONEDA,P132_COUNT_COBERT,P132_COUNT_ASISTS'
