wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(594903279957335038)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_CODCIA_CODEMPRESAS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nIdetpol    NUMBER;',
'    cEstEndo    VARCHAR2(3) := NULL;',
'BEGIN',
'    :CODCIA := 1;',
'    :COD_EMPRESA := 1;',
'',
'    IF :P132_IDENDOSO_SUBMIT IS NOT NULL AND :P132_IDETPOL IS NULL THEN',
'        SELECT FECINIVIG',
'        INTO :P132_FECINIVIG_DETPOL',
'        FROM POLIZAS',
'        WHERE IDPOLIZA = :P132_IDPOLIZA;',
'',
'        SELECT StsEndoso,IDETPOL',
'        INTO :P132_STS_CERT_ENDO,nIdetpol',
'        FROM ENDOSOS',
'        WHERE IDPOLIZA  = :P132_IDPOLIZA',
'        AND IDENDOSO    = :P132_IDENDOSO_SUBMIT;',
'',
'        SELECT IdTipoSeg, PlanCob',
'        INTO :P132_IDTIPOSEG, :P132_PLANCOB',
'        FROM DETALLE_POLIZA',
'        WHERE 1=1',
'        AND IDPOLIZA    = :P132_IDPOLIZA',
'        AND IDETPOL     = nIdetpol;',
'',
'        :P132_IDETPOL := nIdetpol;',
'',
'    ELSIF :P132_IDENDOSO_SUBMIT IS NULL AND :P132_IDETPOL IS NOT NULL THEN',
'        ',
'        SELECT STSDETALLE,IdTipoSeg, PlanCob',
'        INTO :P132_STS_CERT_ENDO,:P132_IDTIPOSEG, :P132_PLANCOB',
'        FROM DETALLE_POLIZA',
'        WHERE 1=1',
'        AND IDPOLIZA    = :P132_IDPOLIZA',
'        AND IDETPOL     = :P132_IDETPOL;',
'',
'    END IF;',
'    ',
'    IF :P132_IDPROCMASIVO IS NULL THEN',
'        BEGIN',
'        SELECT IDPROCMASIVO, IDBG',
'        INTO :P132_IDPROCMASIVO, :P132_IDBG',
'        FROM PROCESOS_MASIVOS',
'        WHERE 1=1',
'        AND CODUSUARIO = :APP_USER',
'        AND TIPOPROCESO = ''ASEGUR''',
'        AND STSREGPROCESO = ''APPX''',
'        ;',
'',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                :P132_IDPROCMASIVO := NULL;',
'                :P132_IDBG := NULL;',
'        END;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>56526744487679937
);
