wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(542012002269940447)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'deletecod_coberturas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCountCobert NUMBER;',
'    nTotalSumaasegMoneda    COBERT_ACT_ASEG.SUMAASEG_MONEDA%TYPE;',
'    nTotalPrimaMoneda       COBERT_ACT_ASEG.PRIMA_MONEDA%TYPE;',
'BEGIN',
'',
'    DELETE COBERTURA_ASEG',
'    WHERE CODCOBERT     = APEX_APPLICATION.g_x01',
'    AND IdPoliza        = APEX_APPLICATION.g_x03',
'    AND IdetPol         = APEX_APPLICATION.g_x05',
'    AND IdEndoso        = NVL(APEX_APPLICATION.g_x04,0)',
'    AND Cod_Asegurado   = APEX_APPLICATION.g_x02;',
'',
'    DELETE FROM COBERT_ACT_ASEG',
'    WHERE CODCOBERT     = APEX_APPLICATION.g_x01',
'    and COD_ASEGURADO   = APEX_APPLICATION.g_x02',
'    and idpoliza        = APEX_APPLICATION.g_x03',
'    and idendoso        = NVL(APEX_APPLICATION.g_x04,0)',
'    AND IDETPOL         = APEX_APPLICATION.g_x05;',
'    COMMIT;',
'',
'    ',
'    OC_ASEGURADO_CERTIFICADO.ACTUALIZA_VALORES(1,1,APEX_APPLICATION.g_x03,APEX_APPLICATION.g_x05,APEX_APPLICATION.g_x02);',
'    OC_ASEGURADO_CERTIFICADO.ACTUALIZA_ASISTENCIAS(1,1,APEX_APPLICATION.g_x03,APEX_APPLICATION.g_x05,APEX_APPLICATION.g_x02);',
'',
'    IF NVL(APEX_APPLICATION.g_x04,0) = 0 THEN',
'        OC_DETALLE_POLIZA.ACTUALIZA_VALORES(1, APEX_APPLICATION.g_x03, APEX_APPLICATION.g_x05, 0);',
'        OC_POLIZAS.ACTUALIZA_VALORES(1, APEX_APPLICATION.g_x03, 0);',
'    ELSE',
'        OC_ENDOSO.ACTUALIZA_VALORES(1, 1, APEX_APPLICATION.g_x03,',
'                              APEX_APPLICATION.g_x05, NVL(APEX_APPLICATION.g_x04,0));',
'    END IF;',
'',
'    -- Count Coberturas',
'    SELECT COUNT(*)',
'    INTO nCountCobert',
'    FROM COBERT_ACT_ASEG',
'    WHERE 1=1',
'    AND IDPOLIZA = APEX_APPLICATION.g_x03',
'    AND IDETPOL = APEX_APPLICATION.g_x05',
'    AND COD_ASEGURADO = APEX_APPLICATION.g_x02;',
'',
'    IF nCountCobert > 0 THEN',
'        SELECT SUM(SUMAASEG_MONEDA), SUM(PRIMA_MONEDA)',
'        INTO nTotalSumaasegMoneda, nTotalPrimaMoneda',
'        FROM COBERT_ACT_ASEG',
'        WHERE 1=1',
'        AND IDPOLIZA = APEX_APPLICATION.g_x03',
'        AND IDETPOL = APEX_APPLICATION.g_x05',
'        AND COD_ASEGURADO = APEX_APPLICATION.g_x02;',
'    END IF;',
'    ',
'    APEX_JSON.open_object;',
'    APEX_JSON.write(''status'', ''ok'');',
'    APEX_JSON.write(''rows'', SQL%ROWCOUNT);',
'    APEX_JSON.write(''cobertura'', APEX_APPLICATION.g_x01);',
'    APEX_JSON.write(''asegurado'', APEX_APPLICATION.g_x02);',
'    APEX_JSON.write(''poliza'', APEX_APPLICATION.g_x03);',
'    APEX_JSON.write(''total_sumaaseg'', nTotalSumaasegMoneda);',
'    APEX_JSON.write(''total_prima'', nTotalPrimaMoneda);',
'    APEX_JSON.close_object;',
'    ',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            ROLLBACK;',
'            APEX_JSON.open_object;',
'            APEX_JSON.write(''status'', ''error'');',
'            APEX_JSON.write(''message'', SQLERRM);',
'            APEX_JSON.write(''errorcode'', SQLCODE);',
'            APEX_JSON.write(''cobertura_recibido'', APEX_APPLICATION.g_x01);',
'            APEX_JSON.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error'
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Borro al codaseguro',
''))
,p_internal_uid=>102920305438868924
);
