,p_prompt=>'Fecha Desde'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT --DISTINCT ',
'       (SUBSTR(NUMCUOTA,1,5)) || '' - '' || TO_CHAR(FECVENC,''DD/MM/YYYY'') D,',
'       (SUBSTR(NUMCUOTA,1,5)) R',
'  FROM FACTURAS',
' WHERE CODCIA   = :P133_CODCIA_ADPT',
'   AND IDPOLIZA = :P133_NUM_POLIZA',
'   AND (',
'        (:P133_APLICAR_RECIBOS = ''TODOS'' AND STSFACT IN (''EMI'',''PAG''))',
'        OR',
'        (:P133_APLICAR_RECIBOS = ''PEND'' AND STSFACT = ''EMI''));'))
,p_lov_display_null=>'YES'
