wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(619868692277208301)
,p_event_id=>wwv_flow_imp.id(619868579532208300)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'	    :P133_COUNT   := 0;',
'    SELECT COUNT(*)',
'    INTO :P133_COUNT',
'    FROM FACTURAS F',
'    WHERE F.CODCIA   = 1',
'    AND F.IDPOLIZA = :P133_NUM_POLIZA',
'    AND F.STSFACT  IN (''EMI'',''PAG'')',
'    AND F.FECVENC  = :P133_FEC_DESDE;',
'    ',
'        IF :P133_COUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-300,''La fecha DESDE no existe'');',
'        END IF; ',
'        --',
'        IF :P133_FEC_DESDE IS NULL THEN',
'            RAISE_APPLICATION_ERROR(-301,''La fecha DESDE es obligatoria'');',
'        ELSE',
'            BEGIN',
'                OC_FACTURAS.CAMBIO_COMISIONES(1, 1, :P133_NUM_POLIZA, :P133_APLICAR_RECIBOS, :P133_FEC_DESDE);',
'',
'',
'            ---ejecuta el enedoso sin valor ',
'            ',
'            DELETE AGENTE_POLIZA_T',
'            WHERE IdPoliza = :P133_NUM_POLIZA',
'            AND CodCia   = 1;',
'            --',
'            DELETE AGENTES_DISTRIBUCION_POLIZA_T',
'            WHERE IdPoliza = :P133_NUM_POLIZA',
'            AND CodCia   = 1;',
'           ',
'        EXCEPTION',
'   	      WHEN OTHERS THEN',
'   	            RAISE_APPLICATION_ERROR(-302,''Error al Aplicar Ajuste a Comisiones'');',
'   	        END;',
'        END IF;',
'END;',
''))
,p_attribute_02=>'P133_NUM_POLIZA,P133_FEC_DESDE'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
