'DECLARE',
'nsuma number;',
'begin',
'    OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION (',
'        nCodCia    => :P110_CODCIA,',
'        nIdPoliza  => :P110_NUM_POLIZA ,',
'        nCodAgente => :P110_COD_AGENTE',
'    );',
'    ',
'    select',
'    sum(PORC_COM_DISTRIBUIDA)',
'    into nsuma',
'    from AGENTES_DISTRIBUCION_POLIZA',
'    where IDPOLIZA = :P110_NUM_POLIZA ',
'    and cod_agente = :P110_COD_AGENTE;',
'',
'    UPDATE AGENTES_DISTRIBUCION_POLIZA',
'    set PORC_COM_POLIZA = nsuma',
'    where IDPOLIZA = :P110_NUM_POLIZA ',
'    and cod_agente = :P110_COD_AGENTE;',
'',
'END;'))
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
