'apex.server.process(',
'    ''LOAD_ASEGURADOS_APPX'',',
'    {',
'        pageItems: ''#P137_IDPROCMASIVO_PC''',
'    },',
'    {',
'        dataType: "json",',
'        success: function(data) {',
'            // $s("P137_LOAD_ASEGURADOS", data.LoadAsegurados);',
'            // $s("P137_ERRORES", data.Errores);',
'            // $("#custom-spinner-thona").hide();',
'            // document.getElementById("BTN_PROCESAR_1").click();',
'            if (data.status === "hundred") {',
'                if (data.errores === "ERROR"){',
'                    $("#custom-spinner-thona").hide();',
'                }else{',
'                    apex.message.alert("Carga de Asegurados Mayor a 100 registros. Se Pasa a Segundo Plano.",',
'                    function(){',
'                        console.log("Carga de Asegurados Mayor a 100 registros.")',
'                    },{',
'                        title: "Carga Asegurados en Segundo Plano",',
'                        style: "information",',
'                        iconClasses: "fa fa-exclamation-triangle",',
'                        okLabel: "Aceptar"',
'                    });',
'                    $s("P137_LOAD_ASEGURADOS", data.status);',
'                    document.getElementById("BTN_PROCESAR_2").click();',
'                }',
'            } else {',
'                $s("P137_LOAD_ASEGURADOS", data.LoadAsegurados);',
'                $s("P137_ERRORES", data.Errores);',
'                if (data.errores === "ERROR"){',
'                    $("#custom-spinner-thona").hide();',
'                }',
'                document.getElementById("BTN_PROCESAR_1").click();',
'            }',
'        },',
'        error: function(data) {',
'            $s("P137_LOAD_ASEGURADOS", data.LoadAsegurados);',
'            $s("P137_ERRORES", data.Errores);',
'            $("#custom-spinner-thona").hide();',
'            apex.message.alert("Error Cargar Asegurados Certificados.");',
'            document.getElementById("BTN_PROCESAR_1").click();',
'        },',
'        complete: function(data) {',
'            $s("P137_LOAD_ASEGURADOS", data.LoadAsegurados);',
'            $s("P137_ERRORES", data.Errores);',
'            //$("#custom-spinner-thona").hide();',
'            document.getElementById("BTN_PROCESAR_1").click();',
'        }',
'    }',
');'))
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(620910449548273991)
,p_event_id=>wwv_flow_imp.id(620910156894273988)
,p_event_result=>'TRUE'
,p_action_sequence=>50
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vResult VARCHAR2(4000);',
'    nCountProcesLog NUMBER;',
'BEGIN',
'',
'    :P137_ERRORES := '''';',
'',
'    BEGIN',
'        P_LOAD_ASEGURADOS_APPX(:P137_IDPROCMASIVO_PC, vResult);',
'',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                APEX_ERROR.ADD_ERROR(P_MESSAGE => ''ERROR:''  || vResult',
'                                    ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);',
'    END;',
'',
'    /*:P137_LOAD_ASEGURADOS := vResult;',
'    IF(vResult = ''CORRECTO'')THEN',
'        :P137_ERRORES := vResult;',
'        APEX_ERROR.ADD_ERROR(P_MESSAGE => ''CORRECTO ''||vResult',
'                            ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);',
'        APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE:= ''SE PROCESO CORRECTAMENTE LA INFORMACION.'';',
'        -- APEX_ERROR.ADD_ERROR(P_MESSAGE => ''SE PROCESOS CORRECTAMENTE LA INFORMACION.''',
'            --       ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);',
'    ELSE',
'        :P137_ERRORES := vResult;',
'        -- APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE:= ''SE IDENTIFICARON ALGUNOS ERRORES AL PROCESAR LA INFORMACION.'';',
unistr('        APEX_ERROR.ADD_ERROR(P_MESSAGE => ''ERROR AL PROCESAR LA INFORMACI\00D3N: ''||vResult'),
'                            ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);',
'    END IF;*/',
'',
'    BEGIN',
'        SELECT COUNT(*)',
'        INTO nCountProcesLog',
'        FROM PROCESOS_MASIVOS_LOG',
'        WHERE 1 = 1',
'        and IDPROCMASIVO = :P137_IDPROCMASIVO_PC',
'        AND TIPOPROCREG != ''READ_LAYOUT_APPX'';',
'',
'        IF nCountProcesLog > 0 THEN',
'            :P137_LOAD_ASEGURADOS := ''ERROR'';',
'            :P137_ERRORES := ''ERROR'';',
'        ELSIF nCountProcesLog = 0 THEN',
'            :P137_LOAD_ASEGURADOS := ''CORRECTO'';',
'            :P137_ERRORES := ''CORRECTO'';',
'        END IF;',
'    END;    ',
'    ',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            APEX_ERROR.ADD_ERROR(P_MESSAGE => ''ERROR:''  || vResult',
'                                ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);',
'END;'))
,p_attribute_02=>'P137_IDPROCMASIVO_PC'
,p_attribute_03=>'P137_ERRORES,P137_LOAD_ASEGURADOS'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(690440983571095281)
);
