wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(620913579928274022)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_ASEGURADOS_APPX'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vResult         VARCHAR2(4000);',
'    nCountProcesLog NUMBER;',
'    cErrores        VARCHAR2(10);',
'    cLoadAsegurados VARCHAR2(10);',
'    nCountAseg      NUMBER;',
'',
'BEGIN',
'',
'    SELECT NVL(COUNT(*),0)',
'    INTO nCountAseg',
'    FROM SICAS_OC.CARGA_MASIVA_AGENTES',
'    WHERE   USERLOAD   = V(''APP_USER'')',
'    AND     CODCIA     = 1',
'    AND     CODEMPRESA = 1',
'    ORDER BY IDPROCMASIVO, INIDCTRL;',
'',
'    IF nCountAseg < 100 THEN',
'        BEGIN',
'            P_LOAD_ASEGURADOS_APPX(:P137_IDPROCMASIVO_PC, vResult);',
'',
'            /*EXCEPTION',
'                WHEN OTHERS THEN',
'                    APEX_ERROR.ADD_ERROR(P_MESSAGE => ''ERROR:''  || vResult',
'                                        ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);*/',
'        END;',
'    END IF;',
'',
'    BEGIN',
'        SELECT COUNT(*)',
'        INTO nCountProcesLog',
'        FROM PROCESOS_MASIVOS_LOG',
'        WHERE 1 = 1',
'        and IDPROCMASIVO = :P137_IDPROCMASIVO_PC',
'        AND TIPOPROCREG != ''READ_LAYOUT_APPX'';',
'',
'        IF nCountProcesLog > 0 THEN',
'            cLoadAsegurados := ''ERROR'';',
'            cErrores := ''ERROR'';',
'        ELSIF nCountProcesLog = 0 THEN',
'            cLoadAsegurados := ''CORRECTO'';',
'            cErrores := ''CORRECTO'';',
'        END IF;',
'    END;    ',
'    ',
'    /*EXCEPTION',
'        WHEN OTHERS THEN',
'            APEX_ERROR.ADD_ERROR(P_MESSAGE => ''ERROR:''  || vResult',
'                                ,P_DISPLAY_LOCATION => APEX_ERROR.C_INLINE_IN_NOTIFICATION);*/',
'',
'                          ',
'',
'    APEX_JSON.OPEN_OBJECT;',
'    IF nCountAseg < 100 THEN',
'        APEX_JSON.WRITE(''status'',''Termino'');',
'        APEX_JSON.WRITE(''LoadAsegurados'', cLoadAsegurados);',
'        APEX_JSON.WRITE(''errores'', cErrores);',
'    ELSE',
'        APEX_JSON.WRITE(''status'',''hundred'');',
'    END IF;',
'    APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>49336373344415337
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(620499966612923618)
,p_process_sequence=>20
,p_parent_process_id=>wwv_flow_imp.id(620499880537923617)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'1_LOAD_FILE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCodCia      CONSTANT  SICAS_OC.CARGA_MASIVA_AGENTES.CodCia%TYPE     := 1;',
'    nCodEmpresa  CONSTANT  SICAS_OC.CARGA_MASIVA_AGENTES.CodEmpresa%TYPE := 1;',
'    nNumAltas              NUMBER  := 0;',
'    cNutra                 SICAS_OC.CARGA_MASIVA_AGENTES.Nutra%TYPE      := NULL;',
'    dFecha_Mvto            SICAS_OC.CARGA_MASIVA_AGENTES.Fecha_Movto%TYPE := TRUNC(SYSDATE);',
'    cTipo_Identi           SICAS_OC.CARGA_MASIVA_AGENTES.Tipo_Identi%TYPE;',
'    cValor_Identi          SICAS_OC.CARGA_MASIVA_AGENTES.Valor_Identi%TYPE; ',
'    nEdad                  SICAS_OC.CARGA_MASIVA_AGENTES.Edad%TYPE;',
'    nIdEndoso              SICAS_OC.ENDOSOS.IDENDOSO%TYPE := NVL(:P137_IDENDOSO,0);',
'    nIDETPOL               VARCHAR2(10) := :P137_IDETPOL;',
'    --',
'    cErrores    VARCHAR2(4000) := NULL;',
'    set_url     VARCHAR2(1000);',
'    -- ',
'    CURSOR c_files (pFileType VARCHAR2) IS WITH files AS (',
'        SELECT blob_content,',
'        -- CONVERT(blob_content,''WE8ISO8859P1'',''AL32UTF8'') blob_content,',
'        filename',
'        FROM apex_application_temp_files',
'        WHERE 1 = 1',
'        AND UPPER(NAME) = UPPER(:P137_FILE)',
'        ORDER BY created_on DESC',
'        -- FETCH FIRST 1 ROW ONLY',
'        )',
'        SELECT line_number,',
'        CASE WHEN nIdEndoso <> 0  THEN',
'                nIDETPOL',
'            ELSE ',
'                REPLACE(REPLACE(UPPER(col001),CHR(10), ''''),CHR(13), '''')',
'            END col001,',
'        -- REPLACE(REPLACE(UPPER(col001),CHR(10), ''''),CHR(13), '''') col001,',
'        REPLACE(REPLACE(UPPER(col002),CHR(10), ''''),CHR(13), '''') col002,',
'        REPLACE(REPLACE(UPPER(col003),CHR(10), ''''),CHR(13), '''') col003,',
'        REPLACE(REPLACE(UPPER(col004),CHR(10), ''''),CHR(13), '''') col004,',
'        REPLACE(REPLACE(UPPER(col005),CHR(10), ''''),CHR(13), '''') col005,',
'        REPLACE(REPLACE(UPPER(col006),CHR(10), ''''),CHR(13), '''') col006,',
'        REPLACE(REPLACE(UPPER(col007),CHR(10), ''''),CHR(13), '''') col007,',
'        REPLACE(REPLACE(UPPER(col008),CHR(10), ''''),CHR(13), '''') col008,',
'        REPLACE(REPLACE(UPPER(col009),CHR(10), ''''),CHR(13), '''') col009, -- Columna de Suma Asegurada',
'        REPLACE(REPLACE(UPPER(col010),CHR(10), ''''),CHR(13), '''') col010,',
'        REPLACE(REPLACE(UPPER(col011),CHR(10), ''''),CHR(13), '''') col011,',
'        row_info',
'        FROM files f',
'        CROSS JOIN TABLE(apex_data_parser.parse(',
'        p_content => f.blob_content',
'        ,p_file_name => f.filename',
'        --,p_file_charset => ''AL32UTF8''',
'        --,p_file_charset => ''WE8ISO8859P1''',
'        ,p_file_charset => (SELECT DECODE(pFileType,''.CSV'',''WE8ISO8859P1'',''AL32UTF8'') FROM DUAL)',
'        )) excel',
'        WHERE 1 = 1;',
'    --  ',
'    vInfoFile       VARCHAR2(4000);',
'    vFileName       VARCHAR2(100);',
'    vFileType       VARCHAR2(100);       ',
'    vBlobData       BLOB;',
'    --     ',
'    vUsuario        VARCHAR2(4000)  := APEX_CUSTOM_AUTH.GET_USERNAME;',
'    -- APEX_UTIL.GET_USERNAME(APEX_UTIL.GET_CURRENT_USER_ID);',
'    vl_Estatus      VARCHAR2(5) := ''PROCE'';',
'    nIdProcMasivo   NUMBER;',
'    vTipoProceso    VARCHAR2(100)   := ''ASEGAGENT'';',
'    vRegDatosProc   VARCHAR2(4000)  := ''NUEVO PROCESO DE CARGA DE ASEGURADOS DESDE APEX DESDE UN AGENTE, SOLO ES UNA REFERENCIA PARA EL REGISTRO DEL LOG.''; -- SE AGREGA DESDE UN AGENTE PARA IDENTIFICAR EL ORIGEN',
'    -- ',
'    vCodError       NUMBER;',
'    vMsjError       VARCHAR2(4000);',
'    nCountErrores   NUMBER:= 0;',
'    vCadenaInsert   VARCHAR2(4000);',
'    vCadenaValidacion   VARCHAR2(4000) := ''LOS VALORES DE NOMBRE, APELLIDO PATERNO Y FECHA DE NACIMIENTO SON OBLIGATORIOS '' || CHR(13);',
'    vBlobDataC      VARCHAR2(4000);',
'    -- ',
'    vAsegur         VARCHAR2(100) := ''ASEGUR''; ',
'    vEstatsuProceso VARCHAR2(100) := ''APPX'';',
'    vFechaNacim     DATE;',
'    vLanguaje        VARCHAR2(100) := ''MEXICAN SPANISH''; ',
'    vTerritory       VARCHAR2(100) := ''MEXICO''; ',
'    vMsjError2       VARCHAR2(4000);',
'    nNumErrores      NUMBER:= 0;',
'BEGIN',
'    ',
'    DBMS_OUTPUT.ENABLE;    ',
'    APEX_DEBUG.ENABLE(p_level => 4);',
'    --',
'    EXECUTE IMMEDIATE ''BEGIN DELETE FROM SICAS_OC.CARGA_MASIVA_AGENTES WHERE USERLOAD = :vUsr; END; '' USING vUsuario;',
'    EXECUTE IMMEDIATE ''BEGIN DELETE FROM SICAS_OC.UPLOAD_ASEG_APPX WHERE USERLOAD = :vUsr; END; '' USING vUsuario;',
'    EXECUTE IMMEDIATE ''BEGIN DELETE FROM SICAS_OC.PROCESOS_MASIVOS WHERE 1 = 1 AND TIPOPROCESO = :vAsegur AND STSREGPROCESO = :vEstatsuProceso AND CODUSUARIO = :vUsr;  COMMIT; END;'' USING vAsegur, vEstatsuProceso, vUsuario;',
'    -- ',
'    COMMIT;',
'    --     ',
'    APEX_UTIL.set_session_state(p_name => ''P137_FILE_NAME''      , p_value => null);',
'    APEX_UTIL.set_session_state(p_name => ''P137_ERRORES''        , p_value => null);',
'    APEX_UTIL.set_session_state(p_name => ''P137_IDPROCMASIVO''   , p_value => null);',
'    APEX_UTIL.set_session_state(p_name => ''P137_ERRORES''        , p_value => null);',
'    -- ',
'    SELECT NAME, NAME || '' <'' || MIME_TYPE || ''>'', BLOB_CONTENT',
'    INTO   vFileName, vInfoFile, vBlobData',
'    FROM   APEX_APPLICATION_TEMP_FILES',
'    WHERE  1 = 1',
'    AND  UPPER(NAME) = UPPER(:P137_FILE);',
'    -- ',
'    vFileType := SUBSTR(vFileName,INSTR(vFileName,''.''));',
'    vFileName := SUBSTR(vFileName,INSTR(vFileName,''/'')+1);',
'    apex_debug.info(''**## vFileName :: '' || vFileName);',
'    ',
'    FOR rec IN c_files(UPPER(vFileType)) LOOP',
'        IF  rec.col009 IS NULL THEN',
'            apex_debug.info(''**## col009:: '' || rec.col009);',
'            vMsjError2 := ''ERROR LA SUMA ASEGURADA NO DEBE SER NULA O SIN DATO'';',
'            nNumErrores := 1;',
'            Exit;',
'        END IF;',
'',
'        cNutra := rec.col010;',
'',
'        IF NVL(TRIM(rec.col002), ''X'') <> ''X'' AND NVL(TRIM(rec.col003), ''X'') <> ''X'' AND NVL(TRIM(rec.col008), ''X'') <> ''X''  THEN',
'            IF rec.line_number > 1 THEN ',
'                nIdProcMasivo := SICAS_OC.SEQ_CARGAMAS_AGENTE.NEXTVAL;',
'                apex_debug.info(''**## nIdProcMasivo:: '' || nIdProcMasivo);',
'                --       ',
'                BEGIN',
'',
'                    cTipo_Identi := ''RFC'';',
'                    cValor_Identi := NVL(rec.col005,''NO_DATA'');',
'                    -- ',
'                    apex_debug.info(''**## col008:: '' || rec.col008);',
'',
'                    IF (UPPER(vFileType) = ''.CSV'') THEN',
'                        -- NULL;',
'                        vFechaNacim   := TO_DATE(TRIM(rec.col008));',
'                    ELSE',
'                        vFechaNacim   := TO_DATE(TRIM(rec.col008),''YYYY/MM/DD'');',
'                    END IF;',
'',
'                    apex_debug.info(''**## vFechaNacim:: '' || vFechaNacim);',
'',
'                    nEdad         := FLOOR((TRUNC(SYSDATE) - TRUNC(vFechaNacim)) / 365.25);',
'                    apex_debug.info(''**## nEdad:: '' || nEdad);',
'                    -- ',
'                    vCadenaInsert := nIdProcMasivo || '','' || rec.line_number || '','' || vUsuario    || '','' || nCodCia    || '','' || nCodEmpresa || '','' ||',
'                    rec.col001    || '','' || RTRIM(rec.col002 ||'' ''||rec.col003||'' ''||rec.col004)|| '','' || vFechaNacim || '','' || rec.col005 || '','' || rec.col006  || '','' ||',
'                    rec.col007    || '','' || rec.col009 || '','' || rec.col010|| '','' || rec.col011;',
'                    -- ',
'                    IF UPPER(:P137_TIPO_MOVTO) = ''ALTA'' THEN',
'                        -- ',
'                        apex_debug.info(''**## NOMBRE:: '' || rec.col002|| '' '' || rec.col003 || '' '' || rec.col004);',
'                        cErrores := ''''||vCadenaInsert;',
'                        -- vcontrol := 0;',
'                        apex_debug.info(''**## FORMATO:: '' || UPPER(vFileType) || '' **## CADENA:: '' || cErrores);',
'        ',
'                        IF (UPPER(vFileType) = ''.CSV'') THEN',
'                            INSERT INTO SICAS_OC.CARGA_MASIVA_AGENTES',
'                            ( IDPROCMASIVO, INIDCTRL, USERLOAD      , CODCIA      , CODEMPRESA, TIPO_MOVTO , FECHA_MOVTO ,',
'                            SUBGRUPO    , NOMBRE  , APELLIDO_PAT  , APELLIDO_MAT, SEXO      , TIPO_IDENTI, VALOR_IDENTI,',
'                            RFC         , CURP    , FEC_NACIMIENTO, EDAD        , REGLA_SA  , SUMA_ASEG  , VECES_SUELDO,',
'                            NUTRA       , USRINSERT, IDENDOSO, ANTIGUEDAD)',
'                            VALUES ( nIdProcMasivo, rec.line_number-1, vUsuario  , nCodCia, nCodEmpresa      , :P137_TIPO_MOVTO, dFecha_Mvto     ,',
'                            rec.col001, RTRIM(rec.col002), RTRIM(rec.col003), RTRIM(rec.col004), rec.col007       , cTipo_Identi  , cValor_Identi   ,',
'                            rec.col005   , rec.col006       , vFechaNacim, nEdad , :P137_REGLA_SUMASEG, rec.col009    , :P137_VECES_SUELDO,',
'                            cNutra       , APEX_CUSTOM_AUTH.GET_USERNAME,nIdEndoso, TO_DATE(TRIM(rec.col011)));',
'                        ELSE',
'                            INSERT INTO SICAS_OC.CARGA_MASIVA_AGENTES',
'                            ( IDPROCMASIVO, INIDCTRL, USERLOAD      , CODCIA      , CODEMPRESA, TIPO_MOVTO , FECHA_MOVTO ,',
'                            SUBGRUPO    , NOMBRE  , APELLIDO_PAT  , APELLIDO_MAT, SEXO      , TIPO_IDENTI, VALOR_IDENTI,',
'                            RFC         , CURP    , FEC_NACIMIENTO, EDAD        , REGLA_SA  , SUMA_ASEG  , VECES_SUELDO,',
'                            NUTRA       , USRINSERT, IDENDOSO, ANTIGUEDAD )',
'                            VALUES ( nIdProcMasivo, rec.line_number-1, vUsuario   , nCodCia, nCodEmpresa      , :P137_TIPO_MOVTO, dFecha_Mvto     ,',
'                            rec.col001   , RTRIM(rec.col002), RTRIM(rec.col003), RTRIM(rec.col004), rec.col007       , cTipo_Identi  , cValor_Identi   ,',
'                            rec.col005   , rec.col006       , vFechaNacim, nEdad  , :P137_REGLA_SUMASEG, rec.col009    , :P137_VECES_SUELDO,',
'                            cNutra       , APEX_CUSTOM_AUTH.GET_USERNAME,nIdEndoso, TO_DATE(TRIM(rec.col011),''YYYY/MM/DD''));',
'                        END IF;',
'                    ELSE',
'                        nNumAltas := nNumAltas + 1;',
'                    END IF;',
'',
'                    EXCEPTION',
'                        WHEN OTHERS THEN',
'                            nCountErrores := nCountErrores+1;',
'                            vCodError     := SQLCODE;',
'                            vMsjError     := SQLERRM;',
'                    -- ',
'                    OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,''[AGENTES - NumLine:: '' || rec.line_number || '']'' || vMsjError || ''<VALUES('' || vCadenaInsert || '')>'');',
'                END;',
'',
'            END IF;',
'        ELSE',
'            nCountErrores := nCountErrores+1;',
'            IF (UPPER(vFileType) = ''.CSV'') THEN',
'                vCadenaValidacion := vCadenaValidacion || ''REGISTRO EN LINEA '' || rec.line_number ',
'                || '' VALORES:: Nombre '' || NVL(TRIM(rec.col002),''SIN_DATO'') ',
'                || '' ApellidoPaterno '' || NVL(TRIM(rec.col003),''SIN_DATO'') ',
'                || '' FechaNacimiento '' || NVL(rec.col008,''SIN_DATO'')',
'                || '' Suma Asegurada '' || NVL(rec.col009,''SIN_DATO'')',
'                || CHR(13);',
'            ELSE',
'                vCadenaValidacion := vCadenaValidacion || ''REGISTRO EN LINEA '' || rec.line_number ',
'                || '' VALORES:: Nombre '' || NVL(TRIM(rec.col002),''SIN_DATO'') ',
'                || '' ApellidoPaterno '' || NVL(TRIM(rec.col003),''SIN_DATO'') ',
'                || '' FechaNacimiento '' || NVL(TO_CHAR(TO_DATE(rec.col008,''YYYY/MM/DD''),''DD/MM/YYYY''),''SIN_DATO'')',
'                || '' Suma Asegurada ''  || NVL(rec.col009,''SIN_DATO'')',
'                || CHR(13);',
'            END IF;',
'        END IF;   ',
'    END LOOP;',
'    -- ',
'    COMMIT;',
'    --        ',
'    IF (nNumErrores != 0) THEN',
'        apex_debug.info(''Entro a Errores'');',
'        --',
'        :P137_COUNT_ERROR := nNumErrores;',
'        apex_debug.info(''Paso la variable P137_COUNT_ERROR'');',
'        --',
'        cErrores    := ''EL ARCHIVO PROCESADO COMO '' || vFileName ',
'                    || CHR(13) || ''PRESENTO '' || nNumErrores ||'' LINEAS DE ERROR DE PROCESAMIENTO,''',
'                    || CHR(13) || ''ES IMPORTANTE QUE LOS IDENTIFIQUE Y CORRIJA.''',
'                    || CHR(13) || vMsjError2 ',
'                    || CHR(13) || ''SE DETIENE EL PROCESO, Y FAVOR DE VALIDAR EL ARCHIVO DE CARGA.'';',
'        apex_debug.info(''Paso la variable cErrores'');',
'        --',
'        APEX_UTIL.set_session_state(p_name => ''P137_ERRORES''   , p_value => cErrores);',
'        set_url := APEX_PAGE.GET_URL(',
'            p_page      => 137',
'        );',
'        apex_util.redirect_url ( p_url => set_url );                             ',
'        RETURN;',
'    ELSE',
'        IF (nCountErrores != 0) THEN',
'            :P137_COUNT_ERROR := nCountErrores;',
'            cErrores     := ''EL ARCHIVO PROCESADO COMO '' || vFileName || CHR(13) || ''PRESENTO '' || nCountErrores ||',
'            '' LINEAS DE ERROR DE PROCESAMIENTO,'' || CHR(13) || ''SE ENCONTRARON '' || nNumAltas ||',
'            '' REGISTROS QUE NO SON ALTAS DE ASEGURADOS.'' || CHR(13) || ''ES IMPORTANTE QUE LOS IDENTIFIQUE Y CORRIJA.'' ||',
'            CHR(13) || CHR(13) || vCadenaValidacion ||',
'            CHR(13) || CHR(13) || ''SI CONTINUA CON EL PROCESO, ES IMPORTANTE CONSIDERAR LOS REGISTROS QUE NO SE PROCESARAN.''',
'            ;',
'        ELSE',
'            cErrores := ''EL ARCHIVO PROCESADO COMO '' || vFileName || '' NO PRESENTO ERRORES Y SU CARGA FUE COMPLETA.'';',
'            -- apex_pwa.send_push_notification ( p_application_id => 171,',
'            -- p_user_name      => '''',',
'            -- p_title          => ''Proceso finalizado'',',
'            -- p_body           => ''Procesamiento completado correctamente.'' );',
'            -- APEX_UTIL.set_session_state(p_name => ''P137_ERRORES''   , p_value => cErrores);',
'        END IF;',
'',
'        :P137_ERRORES := cErrores;',
'    END IF;',
'    apex_debug.log_dbms_output;',
'    :P137_FILE_NAME := vFileName;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_success_message=>'Archivo Cargado Correctamente. Revisar Observaciones.'
,p_internal_uid=>48922760029064933
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(620500105791923619)
,p_process_sequence=>40
,p_parent_process_id=>wwv_flow_imp.id(620499880537923617)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'2_RELACIONAR'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vl_FecIniVig_P              DATE;',
'    vl_FecFinVig_P              DATE;',
'    vl_FecIniVig_DP             DATE;',
'    vl_FecFinVig_DP             DATE;',
'    vl_Fecha_Movto              DATE;',
'    vl_Fec_Nacimiento           DATE;',
'    vl_FecIngreso               DATE;',
'    vl_FecSts                   DATE;',
'    vl_Emision                  DATE;       ',
'    vl_PorComis                 NUMBER;',
'    vl_IdEndoso                 NUMBER;',
'    nIdProcMasivo               NUMBER;',
'    vl_Codcia                   NUMBER;',
'    vl_Codempresa               NUMBER;',
'    vCodError                   NUMBER;',
'    vl_VecesSueldo              NUMBER;',
'    vl_Subgrupo                 NUMBER;',
'    vl_Edad                     NUMBER;',
'    vl_Regla_Sa                 NUMBER;',
'    vl_Suma_Aseg                NUMBER;',
'    vl_ClienteUnico             NUMBER;',
'    vRegDatosProc               NUMBER;',
'    vl_Uno                      NUMBER;',
'    vl_Dos                      NUMBER;',
'    vl_Tres                     NUMBER;',
'    vl_IdPoliza                 NUMBER;',
'    vl_SALocal                  NUMBER;',
'    vl_SAMoneda                 NUMBER;',
'    vl_PrimaLocal               NUMBER;',
'    vl_PrimaMoneda              NUMBER;',
'    vl_Inidctrl                 NUMBER := 0;',
'    vl_Total                    NUMBER := 0;',
'    nCountErrores               NUMBER := 0;',
'    vl_ExistePNJ                NUMBER := 0;',
'    csg_CodCia      CONSTANT    NUMBER  := 1;',
'    csg_CodEmpresa  CONSTANT    NUMBER  := 1;',
'    vl_StsPoliza                VARCHAR2(5);',
'    vl_IdTipoSeg                VARCHAR2(6);',
'    vl_CodigoZIP                VARCHAR2(5) := NULL;',
'    vl_Tipo_Identi              VARCHAR2(5);',
'    vl_CodPlanPago              VARCHAR2(7);',
'    vl_Tipo_Movto               VARCHAR2(10);',
'    vl_Sexo                     VARCHAR2(15);',
'    vl_Sexo2                    VARCHAR2(15);',
'    vl_PlanCob                  VARCHAR2(15);',
'    vl_Valor_Identi             VARCHAR2(20);',
'    vl_NumPolUnico              VARCHAR2(30);',
'    vl_Nutra                    VARCHAR2(200);',
'    vl_Antiguedad               VARCHAR2(200);',
'    vl_RFC                      VARCHAR2(20);',
'    vl_CURP                     VARCHAR2(20);',
'    vl_Nombre                   VARCHAR2(500);',
'    vl_Apellido_Pat             VARCHAR2(500);',
'    vl_Apellido_Mat             VARCHAR2(500);',
'    vMsjError                   VARCHAR2(4000);',
'    vCadenaInsert               VARCHAR2(4000);',
'    vBlobDataC                  VARCHAR2(4000);',
'    vl_NumTributario            VARCHAR2(15) := NULL;',
'    vl_Userload                 VARCHAR2(20) := NULL;',
'    vl_Estatus                  VARCHAR2(5) := ''PROCE'';',
'    vTipoProceso                VARCHAR2(100) := ''ASEGUR'';',
'    vEstatsuProceso             VARCHAR2(100) := ''APPX'';',
'    vUsuario                    VARCHAR2(4000) := APEX_CUSTOM_AUTH.GET_USERNAME;',
'    vl_DirecRes                 SICAS_OC.PERSONA_NATURAL_JURIDICA.DIRECRES%TYPE := NULL;',
'    vl_CadenaIdenti CONSTANT    VARCHAR2(150) := ''NUEVO PROCESO DE CARGA DE ASEGURADOS DESDE APEX, SOLO ES UNA REFERENCIA PARA EL REGISTRO DEL LOG.'';',
'    vl_CodRamSeg                VARCHAR2(5);',
'    vl_RFC2                     VARCHAR2(20);',
'    set_url     VARCHAR2(1000);',
'    -- ',
'    CURSOR PA_ASEGURADOS IS',
'        SELECT  INIDCTRL, USERLOAD      , CODCIA      , CODEMPRESA, TIPO_MOVTO , FECHA_MOVTO , SUBGRUPO,',
'                NOMBRE  , APELLIDO_PAT  , APELLIDO_MAT, SEXO      , TIPO_IDENTI, VALOR_IDENTI, DECODE(RFC,''NO_DATA'',NULL,RFC) RFC,',
'                CURP    , FEC_NACIMIENTO, EDAD        , REGLA_SA  , SUMA_ASEG  , VECES_SUELDO, NUTRA,IDENDOSO,ANTIGUEDAD',
'        FROM   SICAS_OC.CARGA_MASIVA_AGENTES',
'        WHERE  1 = 1',
'        AND  USERLOAD   = APEX_CUSTOM_AUTH.GET_USERNAME',
'        AND  CODCIA     = csg_CodCia',
'        AND  CODEMPRESA = csg_CodEmpresa',
'        ORDER BY IDPROCMASIVO, INIDCTRL;',
'BEGIN',
'    ',
'    vl_NumPolUnico := (:P137_NUMPOLUNICO_PC);',
'    ',
'    IF vl_NumPolUnico IS NOT NULL THEN',
'',
'        vl_Total := INSTR(vl_NumPolUnico,''-'');',
'',
'        IF vl_Total > 0 THEN',
'            ',
'            SELECT COUNT(1)',
'            INTO   vRegDatosProc',
'            FROM   SICAS_OC.CARGA_MASIVA_AGENTES',
'            WHERE  1 = 1',
'            AND  USERLOAD   = APEX_CUSTOM_AUTH.GET_USERNAME',
'            AND  CODCIA     = csg_CodCia',
'            AND  CODEMPRESA = csg_CodEmpresa;',
'            -- ',
'',
'            IF vRegDatosProc > 0  THEN',
'                OPEN PA_ASEGURADOS;',
'                LOOP',
'                    FETCH PA_ASEGURADOS',
'                    INTO  vl_Inidctrl, vl_Userload      , vl_Codcia      , vl_Codempresa, vl_Tipo_Movto , vl_Fecha_Movto , vl_Subgrupo,',
'                          vl_Nombre  , vl_Apellido_Pat  , vl_Apellido_Mat, vl_Sexo      , vl_Tipo_Identi, vl_Valor_Identi, vl_RFC     ,',
'                          vl_CURP    , vl_Fec_Nacimiento, vl_Edad        , vl_Regla_Sa  , vl_Suma_Aseg  , vl_VecesSueldo , vl_Nutra,vl_IdEndoso,vl_Antiguedad;',
'                    EXIT WHEN PA_ASEGURADOS%NOTFOUND;',
'                    -- ',
'                    ',
'                    IF vl_Inidctrl = 1 THEN',
'                        BEGIN',
'                            SELECT  D.IDTIPOSEG   , D.PLANCOB  , P.FECSTS  , P.CODCLIENTE , P.FECINIVIG      , P.FECFINVIG       , D.FECINIVIG  ,',
'                                    D.FECFINVIG   , P.STSPOLIZA, P.IDPOLIZA, P.CODPLANPAGO, D.SUMA_ASEG_LOCAL, D.SUMA_ASEG_MONEDA, D.PRIMA_LOCAL,',
'                                    D.PRIMA_MONEDA, P.PORCCOMIS, P.FECEMISION, OC_TIPOS_DE_SEGUROS.CODIGO_RAMO(P.CODCIA, P.CODEMPRESA, D.IDTIPOSEG)',
'                            INTO    vl_IdTipoSeg   , vl_PlanCob  , vl_FecSts  , vl_ClienteUnico, vl_FecIniVig_P, vl_FecFinVig_P, vl_FecIniVig_DP,',
'                                    vl_FecFinVig_DP, vl_StsPoliza, vl_IdPoliza, vl_CodPlanPago , vl_SALocal    , vl_SAMoneda   , vl_PrimaLocal  ,',
'                                    vl_PrimaMoneda , vl_PorComis , vl_Emision , vl_CodRamSeg',
'                            FROM   SICAS_OC.POLIZAS P ',
'                            INNER JOIN SICAS_OC.DETALLE_POLIZA D ON P.IDPOLIZA = D.IDPOLIZA',
'                            WHERE  P.IDPOLIZA   >= 1',
'                            AND  P.NUMPOLUNICO = vl_NumPolUnico',
'                            AND  D.IDETPOL     = vl_Subgrupo',
'                            AND  P.STSPOLIZA NOT IN (''ANU'',''REN'');',
'                            -- ',
'                            vl_Total := 1;',
'',
'                            EXCEPTION',
'                                WHEN OTHERS THEN',
'                                    nCountErrores := nCountErrores+1;',
'                                    vCodError := SQLCODE;',
'                                    vMsjError := SQLERRM;',
'                                    vl_Total  := 0;',
'                                    apex_debug.info(''** Ingreso a EXCEPTION  ## nCountErrores :: '' ||nCountErrores||',
'                                                                            '' ## vCodError :: '' || vCodError||',
'                                                                            '' ## vMsjError :: '' || vMsjError||',
'                                                                            '' ## vl_Total  :: '' || vl_Total);',
unistr('                                    -- OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo, ''READ_LAYOUT_APPX'', vCodError, ''No se encontr\00F3 el NUMPOLUNICO'');'),
unistr('                                    APEX_UTIL.set_session_state(p_name => ''P137_ERRORES''   , p_value => ''No se encontr\00F3 el NUMPOLUNICO o SUBGRUPO no existe en P\00F3liza'');'),
'                                    set_url := APEX_PAGE.GET_URL(',
'                                        p_page      => 137',
'                                    );',
'                                    apex_util.redirect_url ( p_url => set_url );  ',
unistr('                        END;        apex_debug.info(''** Sali\00F3 de la EXCEPTION'');'),
'                        -- ',
'                        COMMIT;',
'                        -- ',
'',
'                        IF vl_Total = 1 THEN',
'                            /*VALIDAR SI EL CURSOR TIENE DATOS*/',
'                            EXECUTE IMMEDIATE ''BEGIN DELETE FROM SICAS_OC.UPLOAD_ASEG_APPX WHERE USERLOAD = :vUsr; END; '' USING vUsuario;',
'                            EXECUTE IMMEDIATE ''BEGIN DELETE FROM PROCESOS_MASIVOS WHERE 1 = 1 AND TIPOPROCESO = :vTipoProceso AND STSREGPROCESO = :vEstatsuProceso AND CODUSUARIO = :vUsr;  COMMIT; END;'' USING vTipoProceso, vEstatsuProceso, vUsuario;',
'                            -- ',
'                            nIdProcMasivo := OC_PROCESOS_MASIVOS.CREAR(vl_Codcia,vl_Codempresa);',
'                            -- ',
'                            BEGIN',
'                                INSERT INTO SICAS_OC.PROCESOS_MASIVOS',
'                                ( IdProcMasivo, CodCia      , CodEmpresa , IdTipoSeg  , PlanCob     , TipoProceso , StsRegProceso,',
'                                FecSts      , RegDatosProc, NumPolUnico, NumDetUnico, IndColectiva, IndAsegurado, CodUsuario   , NomArchivoCarga )',
'                                VALUES( nIdProcMasivo , vl_Codcia      , vl_Codempresa , vl_IdTipoSeg, vl_PlanCob, vTipoProceso, ''APPX''  ,',
'                                TRUNC(SYSDATE), vl_CadenaIdenti, vl_NumPolUnico, 1           , ''S''       , ''S''         , vUsuario, NULL );',
'                                -- ',
'                                vl_Total := 1;',
'',
'                                EXCEPTION',
'                                    WHEN OTHERS THEN',
'                                        vl_Total := 0;',
'                            END;',
'                        ELSE',
'                            nCountErrores := nCountErrores+1;',
'                            vCodError     := SQLCODE;',
'                            vMsjError     := SQLERRM;',
'                            vl_Total      := 0;',
'                            -- ',
unistr('                            OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,''No se encontr\00F3 el NUMPOLUNICO'');'),
'                            -- ',
'                            EXIT;        ',
'                        END IF;',
'                    END IF;                         ',
'                    -- ',
'                    IF vl_Total = 1 THEN',
'                        BEGIN   ',
'                            IF vl_Regla_Sa = 1 THEN',
'                                vl_Uno  := vl_Suma_Aseg;',
'                                vl_Dos  := 0;',
'                                vl_Tres := 0;',
'                            ELSIF vl_Regla_Sa = 2 THEN',
'                                vl_Uno  := vl_Suma_Aseg * vl_VecesSueldo;',
'                                vl_Dos  := vl_Suma_Aseg;',
'                                vl_Tres := vl_VecesSueldo;',
'                            ELSE',
'                                vl_Uno  := 0;',
'                                vl_Dos  := 0;',
'                                vl_Tres := 0;',
'                            END IF;',
'                            -- ',
'                            SELECT DECODE(UPPER(vl_Sexo),''HOMBRE'',''M'',''MASCULINO'',''M'',''M'',''M'',''MUJER'',''F'',''FEMENINO'',''F'',''F'',''F'',''N'')',
'                            INTO   vl_Sexo2',
'                            FROM   DUAL;',
'                            -- ',
'                            --  Se ejecuta la funcion para calcular RFC ARH 29092025',
'                            vl_RFC2 := OC_GENERARFC.GENERAPRINCIPAL(',
'                                                                    vl_Nombre,   --  NOMBRE',
'                                                                    vl_Apellido_Pat,   --  APPATERNO',
'                                                                    vl_Apellido_Mat,   --  APMATERNO',
'                                                                    vl_Fec_Nacimiento    --  FECHA',
'                                                                    );',
'                                          ',
'                            IF vl_RFC IS NULL THEN',
'                                vl_RFC:= vl_RFC2;',
'                            END IF;',
'                            -- ',
'                            IF vl_Sexo IS NULL THEN',
'                                nCountErrores := nCountErrores+1;',
'                                vCodError     := SQLCODE;',
'                                vMsjError     := ''El Sexo no puede ser Nulo'';',
'                                OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,''[NumLine:: '' || vl_Inidctrl || '']'' || vMsjError || ''<VALUES('' || vCadenaInsert || '')>'');',
'                            ELSIF vl_Fec_Nacimiento IS NULL THEN',
'                                nCountErrores := nCountErrores+1;',
'                                vCodError     := SQLCODE;',
'                                vMsjError     := ''La Fecha de Nacimiento no puede ser Nula'';',
'                                OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,''[NumLine:: '' || vl_Inidctrl || '']'' || vMsjError || ''<VALUES('' || vCadenaInsert || '')>'');',
'                            ELSIF vl_Suma_Aseg IS NULL THEN',
'                                nCountErrores := nCountErrores+1;',
'                                vCodError     := SQLCODE;',
'                                vMsjError     := ''La Suma Asegurada no puede ser Nula'';',
'                                OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,''[NumLine:: '' || vl_Inidctrl || '']'' || vMsjError || ''<VALUES('' || vCadenaInsert || '')>'');',
'                            ELSE',
'                                INSERT INTO SICAS_OC.UPLOAD_ASEG_APPX',
'                                    ( IDPROCMASIVO      , INIDCTRL               , USERLOAD              , CODCIA  , CODEMPRESA      , IDTIPOSEG       , PLANCOB     , NUMPOLUNICO  ,',
'                                    IDETPOL           , TIPO_DOC_IDENTIFICACION, NUM_DOC_IDENTIFICACION, NOMBRE  , APELLIDO_PATERNO, APELLIDO_MATERNO, SEXO        , FECNACIMIENTO,',
'                                    TIPO_ID_TRIBUTARIA, NUM_TRIBUTARIO         , FECINGRESO            , FECSTS  , DIRECRES        , CODIGOZIP       , CLIENTEUNICO, FECINIVIG_P  ,',
'                                    FECFINVIG_P, FECINIVIG_DP, FECFINVIG_DP, SUMAASEG, SUELDO, VECES_SUELDO, NUTRA, RFC_CAL, RFC, CURP, IDENDOSO, ANTIGUEDAD)',
'                                VALUES ( nIdProcMasivo , vl_Inidctrl     , vl_Userload                , vl_Codcia, vl_Codempresa  , vl_IdTipoSeg   , vl_PlanCob     , vl_NumPolUnico   ,',
'                                    vl_Subgrupo   , vl_Tipo_Identi  , vl_RFC/*vl_Valor_Identi*/            , vl_Nombre, vl_Apellido_Pat, vl_Apellido_Mat, vl_Sexo2       , vl_Fec_Nacimiento,',
'                                    DECODE(NVL(vl_RFC,''NO_DATA''),''NO_DATA'',NULL,''RFC''), vl_RFC, NVL(vl_FecIngreso, SYSDATE), vl_FecSts, vl_DirecRes    , vl_CodigoZIP   , vl_ClienteUnico, vl_FecIniVig_P   ,',
'                                    vl_FecFinVig_P, vl_FecIniVig_DP , vl_FecFinVig_DP, vl_Uno, vl_Dos, vl_Tres, vl_Nutra, vl_RFC2, vl_RFC, vl_CURP, vl_IdEndoso, vl_Antiguedad);',
'                            END IF;',
'                            ',
'                            EXCEPTION',
'                                WHEN OTHERS THEN',
'                                    nCountErrores := nCountErrores+1;',
'                                    vCodError     := SQLCODE;',
'                                    vMsjError     := SQLERRM;',
'                                    OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,''[NumLine:: '' || vl_Inidctrl || '']'' || vMsjError || ''<VALUES('' || vCadenaInsert || '')>'');',
'                        END;',
'                    ELSE',
'                        nCountErrores := nCountErrores+1;',
'                        vCodError     := -1;',
'                        vMsjError     := ''No se logro insertar el registro de procesos masivos inicial.'';',
'                        OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,vMsjError);',
'                    END IF;            ',
'                END LOOP;',
'                CLOSE PA_ASEGURADOS;',
'            ELSE',
'                vCodError := -1;',
'                vMsjError := ''No se encontraron asegurados cargados por este usuario.'';',
'                apex_error.add_error( p_message => ''No se encontraron asegurados cargados por este usuario.''',
'                                         , p_display_location => apex_error.c_inline_in_notification);',
'            END IF;',
'        ELSE',
'            vCodError := -1;',
'            vMsjError := ''No es un NUMPOLUNICO valido.'';',
'            apex_error.add_error( p_message => ''El NUMPOLUNICO ingresado no es valido.'' ',
'                                , p_display_location => apex_error.c_inline_in_notification);',
'        END IF;',
'    ELSE',
'        vCodError := -1;',
'        vMsjError := ''Favor de ingresar un valor en NUMPOLUNICO.'';',
'        OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',vCodError,vMsjError);',
'        apex_error.add_error( p_message => ''Hace falta ingresar un NUMPOLUNICO.'' ',
'                          , p_display_location => apex_error.c_inline_in_notification);',
'    END IF;',
'    -- ',
'    :P137_IDPROCMASIVO := nIdProcMasivo;',
'    :P137_IDPROCMASIVO_PC := nIdProcMasivo;',
'    :P137_ERRORES := :P137_ERRORES||CHR(13)||CHR(13)||''----------------------------------------------------------------------- ''',
unistr('                    ||CHR(13)||''---- RELACI\00D3N CON N\00DAMERO POLIZA UNICO: ''||vl_NumPolUnico||'' ---- '';'),
'',
'    IF (nCountErrores != 0)THEN',
'        :P137_COUNT_ERROR  := nCountErrores;',
'        -- :P137_IDPROCMASIVO := nIdProcMasivo;',
'        -- apex_error.add_error( p_message => ''Durante la carga se generaron '' || nCountErrores || '' lineas de error durante el procesamiento del documento.''',
'        --                     , p_display_location => apex_error.c_inline_in_notification);',
'        -- ',
'        :P137_ERRORES := :P137_ERRORES|| CHR(13) ||''EL PROCESO PRESENTO '' || nCountErrores || '' LINEAS DE ERROR DE PROCESAMIENTO.''',
'                        || CHR(13) || ''ES IMPORTANTE QUE LOS IDENTIFIQUE Y CORRIGA.''',
'                        || CHR(13) || CHR(13) || ''SI CONTINUA CON EL PROCESO, ES IMPORTANTE CONSIDERAR LOS REGISTROS QUE NO SE PRCESARA.'';',
'        ',
'        /*htp.p(''<script>'');',
'        htp.p(''apex.region("GET_ERRORES").refresh();'');',
'        htp.p(''</script>'');*/',
'        ',
'    ELSE',
'        -- :P137_IDPROCMASIVO := nIdProcMasivo;',
'        :P137_ERRORES      := :P137_ERRORES|| CHR(13) ||''SE RELACIONO CORRECTAMENTE LAS INFORMACION A LA POLIZA ['' || :P137_NUMPOLUNICO_PC || '']. PUEDE CONTINUAR CON EL PROCESAMIENTO DE LA CARGA.'';',
'    END IF;',
'   ',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            vCodError := SQLCODE;',
'            vMsjError := SQLERRM;',
'            OC_PROCESOS_MASIVOS_LOG.INSERTA_LOG(nIdProcMasivo,''READ_LAYOUT_APPX'',-1,''[NumLine:: '' || vl_Inidctrl || '']'' || vMsjError || ''<VALUES('' || vCadenaInsert || '')>'');',
'            -- :P137_ERRORES := :P137_ERRORES|| CHR(13) ||''El proceso es: ''||:P137_IDPROCMASIVO; -- Linea de control de errores',
'',
'    :P137_ERRORES := :P137_ERRORES|| CHR(13) ||''EL PROCESO PRESENTO '' || nCountErrores || '' LINEAS DE ERROR DE PROCESAMIENTO.''',
'                || CHR(13) || ''ES IMPORTANTE QUE LOS IDENTIFIQUE Y CORRIGA.''',
'                || CHR(13) || CHR(13) || ''SI CONTINUA CON EL PROCESO, ES IMPORTANTE CONSIDERAR LOS REGISTROS QUE NO SE PRCESARA.'';',
'        ',
'    /*htp.p(''<script>'');',
'    htp.p(''apex.region("GET_ERRORES").refresh();'');',
'    htp.p(''</script>'');*/',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48922899208064934
);
end;
/
prompt --application/pages/page_00138
begin
wwv_flow_imp_page.create_page(
 p_id=>138
,p_name=>unistr('Generaci\00F3n de Papeler\00EDa')
,p_alias=>unistr('GENERACI\00D3N-DE-PAPELER\00CDA')
,p_page_mode=>'MODAL'
,p_step_title=>unistr('Generaci\00F3n de Papeler\00EDa')
,p_reload_on_submit=>'A'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#APP_FILES#JS_EMISION#MIN#.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*cambio de liga dependiendo el ambiente en el que este montada la app */',
'var  url_prod = ''http://sicascloud:8889/reports/rwservlet'';',
'var url_jasper = ''http://sicascloud:8081/jasperserver/rest_v2/reports/''; ',
'var  v_credenciales =''&j_username=jasperadmin&j_password=jasperadmin'';',
'///http://192.168.0.224:8889/reports/rwservlet'';',
'',
'/*cambio de liga dependiendo el ambiente en el que este montada la app */',
'',
'',
'',
'//botones de generar ZIP',
'document.getElementById(''BTN_GENERA'').addEventListener(''click'', function() {',
'    var btn = document.getElementById(''BTN_GENERA'');',
'    if (btn) {',
'        apex.item(''BTN_GENERA'').disable();',
'        btn.classList.add("is-disabled");',
'        btn.innerHTML = ''Generando...'';',
'        console.log("SE BLOQUEO EL BOTON");',
'    }',
'});',
'',
'function desbloquear_boton_genera() {',
'    var btn = document.getElementById("BTN_GENERA");',
'    console.log("SE DESBLOQUEA EL BOTON");',
'    if (btn) {',
unistr('        apex.item(''BTN_GENERA'').enable(); // \00BF Sim\00E9trico al disable() del bloqueo'),
'        btn.disabled = false;',
'        btn.classList.remove("is-disabled");',
'        btn.innerHTML = ''<span class="t-Icon fa fa-print"></span>'';',
'    }',
'}',
'',
'//funcionalidad que bloquea el boton para que no paresca que no esta genernaod las facturas ',
'//y evitar genere erro en el seto del pl/sq',
'function bloquearBoton() {',
'    var btn = document.getElementById("BTN_IMPRIME_GRG"); ',
'    if (btn) {',
'        btn.disabled = true;',
'        btn.classList.add("is-disabled");',
'        btn.innerText = "Generando...";',
'    }',
'}',
'',
'function desbloquearBoton(data) {',
'    var btn = document.getElementById("BTN_IMPRIME_GRG"); ',
'    if (btn) {',
'        btn.disabled = false;',
'        btn.classList.remove("is-disabled");',
'        btn.innerHTML = ''<span class="fa fa-file-pdf-o"></span>'';',
'    }',
'}',
'',
'',
'',
'',
'//en el paquete se genera un txt pero con js no se puede generar, asi que se vuelve a ejecutar varios ',
'//intentos para que se pueda timbrar la P138_REP_REC_FACT_ELEC',
'function ejecutarTimbrado(idPoliza, intentoActual, maxIntentos) {',
'    apex.server.process("Genera_TIMBRE_FACTURA", {',
'        x01: idPoliza',
'    }, {',
'        success: function() {',
'            abrirDocumentosGenerados(idPoliza);',
'        },',
'        error: function(err) {',
'            if (intentoActual < maxIntentos) {',
'                apex.message.showErrors([{',
'                    type: "error",',
'                    message: "Intento " + intentoActual + " fallido. Reintentando... (" +',
'                             (maxIntentos - intentoActual) + " intentos restantes)"',
'                }]);',
'                setTimeout(function() {',
'                    ejecutarTimbrado(idPoliza, intentoActual + 1, maxIntentos);',
'                }, 2000);',
'            } else {',
'                apex.message.showErrors([{',
'                    type: "error",',
unistr('                    message: "Error al Timbrar despu\00E9s de " + maxIntentos +'),
unistr('                             " intentos: " + err + " \2014 Abriendo documentos generados."'),
'                }]);',
'                abrirDocumentosGenerados(idPoliza);',
'            }',
'        }',
'    });',
'}',
'',
'',
'function abrirDocumentosGenerados(idPoliza) {',
'    var promesaPDF = new Promise(function(resolve, reject) {',
'        apex.server.process("GET_FACTURAS_PDF", {',
'            x01: idPoliza',
'        }, {',
'            success: function(pData) {',
'                if (pData.facturas && pData.facturas.length > 0) {',
'                    descargarPDFsDeFacturas(pData.facturas);',
'                }',
'                resolve();',
'            },',
'            error: function(err) {',
'                apex.message.showErrors([{',
'                    type: "error",',
'                    message: "Error al obtener PDFs: " + err',
'                }]);',
'                resolve(); ',
'            }',
'        });',
'    });',
'',
'    var promesaXML = new Promise(function(resolve, reject) {',
'        apex.server.process("GET_FACTURAS_PDF_xlm", {',
'            x01: idPoliza',
'        }, {',
'            success: function(pData) {',
'                pData.facturas.forEach(function(factura) {',
'                    var blob = new Blob([factura.xml], { type: ''application/xml'' });',
'                    var url  = URL.createObjectURL(blob);',
'                    window.open(url, ''_blank'');',
'                });',
'                resolve();',
'            },',
'            error: function(err) {',
'                apex.message.showErrors([{',
'                    type: "error",',
'                    message: "Error XML: " + err',
'                }]);',
'                resolve(); ',
'            }',
'        });',
'    });',
'',
'    Promise.all([promesaPDF, promesaXML]).then(function() {',
'        desbloquearBoton();',
'    });',
'}',
unistr('//permite abrir las pesta\00F1as sin descargar nada'),
'function descargarPDFsDeFacturas(facturas) {',
'    facturas.forEach(function(factura, i) {',
'        var byteChars = atob(factura.pdf);',
'        var byteArray = new Uint8Array(byteChars.length);',
'        for (var j = 0; j < byteChars.length; j++) {',
'            byteArray[j] = byteChars.charCodeAt(j);',
'        }',
'        var blob = new Blob([byteArray], { type: ''application/pdf'' });',
'        var url  = URL.createObjectURL(blob);',
'       window.open(url, ''_blank'');',
'    });',
'}'))
