'BEGIN',
'    SELECT COUNT(*)',
'      INTO v_existe',
'      FROM DETALLE_POLIZA',
'     WHERE CODCIA   = :P138_CODCIA',
'       AND IDPOLIZA = :P138_IDPOLIZA',
'       AND IDETPOL  = :P138_DET_INI;',
'',
'    IF v_existe = 0 THEN',
'        RETURN FALSE;',
'    ELSE',
'        RETURN TRUE;',
'    END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
