,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var nidpol      = $v("P138_IDPOLIZA");',
'var nidetpolini = $v("P138_DET_INI");',
'var nidetpolfin = $v("P138_DET_FIN");',
'var nidendini   = $v("P138_ENDOSO_INI");',
'var nidendfin   = $v("P138_ENDOSO_FIN");',
'var nasegini    = $v("P138_ASEG_INI");',
'var nasegfin    = $v("P138_ASEG_FIN");',
'var nuser       = $v("P138_USER");',
'var nregla      = $v("P138_SUMA_ASEG");',
'var v_credenciales = "&j_username=jasperadmin&j_password=jasperadmin";',
'',
'function abrirReportesPorAsegurado(listaAsegurados) {',
'    if (!listaAsegurados || listaAsegurados.length === 0) {',
'        apex.message.showErrors([{',
'            type: "error",',
'            message: "No se encontraron asegurados en el rango indicado."',
'        }]);',
'        return;',
'    }',
'',
'    listaAsegurados.forEach(function(aseg, i) {',
'        setTimeout(function() {',
'',
'            var codAseg = aseg.cod;  ',
'            if (nregla === ''S'') {',
'                var url = url_jasper +',
'                          ''Cert_Cons_Asegurados/CON_IND_ASE_PO_SUMA.pdf?'' +',
'                          ''IDPOLIZA=''    + nidpol      +',
'                          ''&IDETPOLINI='' + nidetpolini +',
'                          ''&IDETPOLFIN='' + nidetpolfin +',
'                          ''&ENDOSOINI=''  + nidendini   +',
'                          ''&ENDOSOFIN=''  + nidendfin   +',
'                          ''&CODASEGMIN='' + codAseg     +  ',
'                          ''&CODASEGMAX='' + codAseg     + ',
'                          v_credenciales;',
'',
'            } else {',
'                var url = url_jasper +',
'                          ''Cert_Cons_Asegurados/CON_IND_ASE_PO.pdf?'' +',
'                          ''IDPOLIZA=''    + nidpol      +',
'                          ''&IDETPOLINI='' + nidetpolini +',
'                          ''&IDETPOLFIN='' + nidetpolfin +',
'                          ''&ENDOSOINI=''  + nidendini   +',
'                          ''&ENDOSOFIN=''  + nidendfin   +',
'                          ''&CODASEGMIN='' + codAseg     +  ',
'                          ''&CODASEGMAX='' + codAseg     +  ',
'                          v_credenciales;',
'            }',
'',
'            window.open(url, ''_blank'');',
'',
'        }, i * 1500); ',
'    });',
'}',
'',
'if ($v("P138_REP_CONS_IND_ASEG") === ''S'') {',
'',
'    var ini = parseInt(nasegini, 10);',
'    var fin = parseInt(nasegfin, 10);',
'',
'    var esRangoAbierto = (',
'        (nasegini === '''' || nasegini === ''1''           || isNaN(ini)) &&',
'        (nasegfin === '''' || nasegfin === ''9999999999''  || isNaN(fin))',
'    );',
'',
'    if (esRangoAbierto) {',
'        apex.server.process("GET_ASEGURADOS_POLIZA", {',
'            x01: nidpol',
'        }, {',
'            success: function(pData) {',
'                abrirReportesPorAsegurado(pData.asegurados);',
'            },',
'            error: function() {',
'                apex.message.showErrors([{',
'                    type: "error",',
unistr('                    message: "Error al consultar los asegurados de la p\00F3liza."'),
'                }]);',
'            }',
'        });',
'',
'    } else {',
'        apex.server.process("GET_ASEGURADOS_POLIZA", {',
'            x01: nidpol,',
'            x02: nasegini, ',
'            x03: nasegfin',
'        }, {',
'            success: function(pData) {',
'                abrirReportesPorAsegurado(pData.asegurados);',
'            },',
'            error: function() {',
'                apex.message.showErrors([{',
'                    type: "error",',
'                    message: "Error al consultar los asegurados del rango."',
'                }]);',
'            }',
'        });',
'    }',
'}',
''))
);
