,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//Poliza Consecutiva',
'var nidpol = $v("P138_IDPOLIZA");',
'//Usuario',
'var nuser = $v("P138_USER");',
'',
'//Carta de Bienvenida',
'if ($v("P138_REP_BIENVENIDA") === ''S'') {',
