,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'PR_Impresio/Color'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'l_nombres VARCHAR2(4000);',
'l_colores VARCHAR2(4000);',
'l_estilo  CLOB;',
'vControl  NUMBER;',
'TYPE t_arr IS TABLE OF VARCHAR2(500) INDEX BY PLS_INTEGER;',
'l_arr_nombres t_arr;',
'l_arr_colores t_arr;',
'PROCEDURE split_csv(p_str IN VARCHAR2, p_arr OUT t_arr) IS',
'    v_str VARCHAR2(4000) := NVL(p_str, '''') || '','';',
'    v_ini NUMBER := 1;',
'    v_fin NUMBER;',
'    v_i   NUMBER := 1;',
'BEGIN',
'    LOOP',
'    v_fin := INSTR(v_str, '','', v_ini);',
'    EXIT WHEN v_fin = 0;',
'    p_arr(v_i) := TRIM(SUBSTR(v_str, v_ini, v_fin - v_ini));',
'    v_ini := v_fin + 1;',
'    v_i   := v_i + 1;',
'    END LOOP;',
'END;',
'BEGIN',
'',
'  OC_IMPRESION_PAPELERIA.GENERA_REPORTE(vPoliza => :P138_IDPOLIZA,vFecha_Ini => :P138_FEC_DESDE,vFecha_Fin => :P138_FEC_HASTA,vDet_Ini => :P138_DET_INI,vDet_Fin => :P138_DET_FIN,',
'    vAseg_Ini => :P138_ASEG_INI, vAseg_Fin => :P138_ASEG_FIN, vEndoso_Ini => :P138_ENDOSO_INI,vEndoso_Fin => :P138_ENDOSO_FIN,vCH_Asegurado => :P138_ASEGURADO,',
'    vCH_Regla => :P138_REGLA,',
'    vCH_Nutra               => :P138_NUTRA,',
'    vCH_Suma                => :P138_SUMA_ASEG,',
'    vUsuario                => :APP_USER,',
'    vRep_Pol_Vida_Grupo     => :P138_REP_POL_VIDA_GRUPO,',
'    vRep_Acci_Colectivo     => :P138_REP_ACCI_COLECTIVO,',
'    vRep_Acci_Col_Sub       => :P138_REP_ACCI_COL_SUB,',
'    vRep_Pol_Ind            => :P138_REP_POL_IND,',
'    vRep_Vida_Flex          => :P138_REP_VIDA_FLEX,',
'    vRep_Cer_Ind_Bloque     => :P138_REP_CER_IND_BLOQUE,',
'    vRep_Cons_Ind_Pol       => :P138_REP_CONS_IND_POL,',
'    vRep_Cons_Ind_ASE       => :P138_REP_CONS_IND_ASEG,  ',
'    vRep_Aseg_Prima         => :P138_REP_ASEG_PRIMA,',
'    vRep_Aseg_Sin_Prima     => :P138_REP_ASEG_SIN_PRIMA,',
'    vRep_Bienvenida         => :P138_REP_BIENVENIDA,',
'    vRep_Sini_Vida          => :P138_REP_SINI_VIDA,',
'    vRep_Sini_AP            => :P138_REP_SINI_AP,',
'    vRep_Endoso_Asis        => :P138_REP_ENDOSO_ASIS,',
'    vRep_Auto_Admin         => :P138_REP_AUTO_ADMIN,',
'    vRep_Cond_Especiales    => :P138_REP_COND_ESPECIALES,',
'    vRep_Endoso_Gral        => :P138_REP_ENDOSO_GRAL,',
'    vRep_Rec_Fact_Elec      => :P138_REP_REC_FACT_ELEC,',
'    vRep_Condiciones_Gral   => :P138_REP_CONDICIONES_GRAL,',
'    vRep_Aviso_Cobro        => :P138_REP_AVISO_COBRO,',
'    vRep_Aporte_Reg         => :P138_REP_APORTE_REG,',
'    vRep_Aviso_Dev          => :P138_REP_AVISO_DEV,',
'    vRep_Aporte_Extra       => :P138_REP_APORTE_EXTRA,',
'    vRep_Fondo_Colec        => :P138_REP_FONDO_COLEC,',
'    vRep_Cer_Ind_aseg      => :P138_REP_CER_IND_ASEG, ',
'    VNombre_Archivo         => :P138_CONDICIONES_GEN, ',
'    vRep_ARCHIVO_Condiciones_Gral=> :P138_CONDICIONES_GEN,',
'    vCOD_PAQ                => :P138_COD_PAQ,',
'    vRep_Gmm_GMProtect      => :P138_REP_GMM_PROTECT',
'  );',
'',
'  SELECT MAX(id)',
'    INTO :P138_ID_REPORTE',
'    FROM REPORTES_PDF',
'   WHERE CODUSUARIO = :APP_USER',
'   AND REGEXP_SUBSTR(NOMBRE, ''POLIZA_(\d+)'', 1, 1, ''i'', 1) =:P138_IDPOLIZA;',
'',
'  SELECT nombre_archivo, color ',
'  INTO l_nombres, l_colores ',
'  FROM REPORTES_PDF',
'   WHERE id = :P138_ID_REPORTE',
'    AND CODUSUARIO = :APP_USER;',
'    vControl := 4.0; split_csv(l_nombres, l_arr_nombres); vControl := 4.1;  split_csv(l_colores, l_arr_colores); vControl := 5.0;  l_estilo := ''''; vControl := 6.0;',
'  FOR i IN 1 .. LEAST(l_arr_nombres.COUNT, l_arr_colores.COUNT) LOOP',
'',
'    l_estilo := l_estilo ||',
'    ''label[for="'' || l_arr_nombres(i) || ''"]{'' ||',
'    ''background-color:'' || l_arr_colores(i) || '' !important;'' ||',
'    ''border:1px solid ''  || l_arr_colores(i) || '' !important;'' ||',
'    ''border-radius:5px !important;'' ||',
'    ''color:white !important;'' ||',
'    ''padding:2px 6px;'' ||',
'    ''}'';',
'  END LOOP;vControl := 8.0;',
'  :P138_ESTILOS_CS := l_estilo;',
'',
':P138_URL_DESCARGA := APEX_PAGE.GET_URL(p_page      => 1390,p_items     => ''P1390_ID_REPORTE'',p_values    => :P138_ID_REPORTE,p_plain_url => TRUE);',
'',
'EXCEPTION',
'WHEN OTHERS THEN',
'RAISE_APPLICATION_ERROR(-20001,''Error003 ['' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || '']>'' ||  SQLERRM);',
'END;'))
,p_attribute_02=>'P138_IDPOLIZA,P138_FEC_DESDE,P138_FEC_HASTA,P138_DET_INI,P138_DET_FIN,P138_ASEG_INI,P138_ASEG_FIN,P138_ENDOSO_INI,P138_ENDOSO_FIN,P138_ASEGURADO,P138_REGLA,P138_NUTRA,P138_SUMA_ASEG,P138_REP_POL_VIDA_GRUPO,P138_REP_ACCI_COLECTIVO,P138_REP_ACCI_COL_SU'
||'B,P138_REP_POL_IND,P138_REP_VIDA_FLEX,P138_REP_CER_IND_BLOQUE,P138_REP_CONS_IND_POL,P138_REP_ASEG_PRIMA,P138_REP_ASEG_SIN_PRIMA,P138_REP_BIENVENIDA,P138_REP_SINI_VIDA,P138_REP_SINI_AP,P138_REP_ENDOSO_ASIS,P138_REP_AUTO_ADMIN,P138_REP_COND_ESPECIALES,'
||'P138_REP_ENDOSO_GRAL,P138_REP_REC_FACT_ELEC,P138_REP_CONDICIONES_GRAL,P138_REP_AVISO_COBRO,P138_REP_APORTE_REG,P138_REP_AVISO_DEV,P138_REP_APORTE_EXTRA,P138_REP_FONDO_COLEC,P138_REP_CONS_IND_ASEG,P138_REP_CER_IND_ASEG,P138_CONDICIONES_GEN,P138_REP_GM'
||'M_PROTECT'
,p_attribute_03=>'P138_ID_REPORTE,P138_ESTILOS_CS,P138_URL_DESCARGA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
