'TYPE t_arr IS TABLE OF VARCHAR2(500) INDEX BY PLS_INTEGER;',
'l_arr_nombres t_arr;',
'l_arr_colores t_arr;',
'PROCEDURE split_csv(p_str IN VARCHAR2, p_arr OUT t_arr) IS',
'    v_str VARCHAR2(4000) := NVL(p_str, '''') || '','';',
'    v_ini NUMBER := 1;',
'    v_fin NUMBER;',
'    v_i   NUMBER := 1;',
'BEGIN',
'    LOOP',
'    v_fin := INSTR(v_str, '','', v_ini);',
'    EXIT WHEN v_fin = 0;',
'    p_arr(v_i) := TRIM(SUBSTR(v_str, v_ini, v_fin - v_ini));',
'    v_ini := v_fin + 1;',
'    v_i   := v_i + 1;',
'    END LOOP;',
'  END;',
'BEGIN',
'  OC_IMPRESION_PAPELERIA.GENERA_REPORTE(',
'    vPoliza                 => :P138_IDPOLIZA,',
'    vFecha_Ini              => :P138_FEC_DESDE,',
