'if ($v("P138_REP_REC_FACT_ELEC") === ''S'') {',
'',
'    apex.message.confirm(',
unistr('        "\00BFDesea Generar la Factura Electr\00F3nica? ",'),
'        function(primerOk) {',
'            if (primerOk) {',
'',
'                apex.message.confirm(',
'                    "Recuerde Revisar que los Datos para Factura sean Correctos.",',
'                    function(segundoOk) {',
'                        if (segundoOk) {',
'',
'                            apex.server.process("GET_FACTURAS_PDF", {',
'                                x01: $v("P138_IDPOLIZA")',
'                            }, {',
'                                success: function(pData) {',
'                                    pData.facturas.forEach(function(factura, i) {',
'',
'                                        var byteChars = atob(factura.pdf);',
'                                        var byteArray = new Uint8Array(byteChars.length);',
'                                        for (var j = 0; j < byteChars.length; j++) {',
'                                            byteArray[j] = byteChars.charCodeAt(j);',
'                                        }',
'                                        var blob = new Blob([byteArray], { type: ''application/pdf'' });',
'                                        var url  = URL.createObjectURL(blob);',
'',
'                                        var link = document.createElement(''a'');',
'                                        link.href = url;',
'                                        link.target = ''_blank'';',
'                                        link.download = (factura.nombre || ''FACTURA_'' + (i+1)) + ''.pdf'';',
'                                        document.body.appendChild(link);',
'                                        link.click();',
'                                        document.body.removeChild(link);',
'',
'                                    });',
'',
'                                    descargarFacturasPDF($v("P138_IDPOLIZA"));',
'                                },',
'                                error: function(err) {',
'                                    apex.message.showErrors([{ type: "error", message: "Error: " + err }]);',
'                                }',
'                            });',
'',
'                        }',
'                    }',
'                );',
'',
'            }',
'        }',
'    );',
'}'))
