,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P138_COUNT_ASE_ITEM'
,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT COUNT(*)',
'FROM asegurado_certificado ac',
'WHERE ac.IDPOLIZA =:P138_IDPOLIZA',
'AND (',
'      ac.COD_ASEGURADO BETWEEN NVL(:P138_ASEG_INI, ''0'') AND NVL(:P138_ASEG_FIN, ''9999999999'')',
')',
'AND (',
'      (:P138_ENDOSO_INI = 0 AND :P138_ENDOSO_FIN = 0)',
'',
'   OR EXISTS (',
'        SELECT 1',
'        FROM ENDOSOS e',
'        WHERE e.IDPOLIZA = ac.IDPOLIZA',
'          AND e.IDENDOSO = :P138_ENDOSO_INI',
'          AND (',
'                (e.TIPOENDOSO <> ''EXA''',
'                 AND ac.IDENDOSO = :P138_ENDOSO_FIN)',
'             OR (e.TIPOENDOSO = ''EXA''',
'                 AND ac.IDENDOSO = 0',
'                 AND ac.IDENDOSOEXCLU = :P138_ENDOSO_FIN)',
'          )',
'   )',
')',
'AND (',
'      (',
'           :P138_DET_INI = 1',
'       AND :P138_DET_FIN = (',
'            SELECT MAX(ac2.IDETPOL)',
'            FROM ASEGURADO_CERTIFICADO ac2',
'            WHERE ac2.IDPOLIZA = ac.IDPOLIZA',
'       )',
'      )',
'   OR ac.IDETPOL BETWEEN :P138_DET_INI',
'                     AND :P138_DET_FIN',
')',
''))
,p_attribute_07=>'P138_IDPOLIZA,P138_ASEG_INI,P138_ASEG_FIN,P138_ENDOSO_FIN,P138_ENDOSO_INI,P138_DET_INI,P138_DET_FIN'
,p_attribute_08=>'Y'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
