wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(556521845561047058)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_COLECTIVOS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json  CLOB;',
'    l_sep   VARCHAR2(1) := '''';',
'BEGIN',
'    DBMS_LOB.createtemporary(l_json, TRUE);',
'    DBMS_LOB.append(l_json, TO_CLOB(''{"facturas":[''));',
'',
'    FOR r IN (',
'        SELECT DOCTOPDF,',
'               NVL(NOMBARCHZIP, ''FACTURA_'' || IDAGRUPAENV) AS nombre',
'        FROM   FACT_ELECT_DOCTOS_TIMBRE',
'        WHERE  IDFACTURA IN (',
'                   SELECT IDFACTURA',
'                   FROM   FACTURAS',
'                   WHERE  IDPOLIZA = TO_NUMBER(APEX_APPLICATION.G_X01)',
'               )',
'    ) LOOP',
'        DBMS_LOB.append(l_json, TO_CLOB(l_sep || ''{"nombre":"'' || r.nombre || ''","pdf":"''));',
'        DBMS_LOB.append(l_json, r.DOCTOPDF);   ',
'        DBMS_LOB.append(l_json, TO_CLOB(''"}''));',
'        l_sep := '','';',
'    END LOOP;',
'',
'    DBMS_LOB.append(l_json, TO_CLOB('']}''));',
'',
'',
'    DECLARE',
'        l_offset  INTEGER := 1;',
'        l_chunk   VARCHAR2(32767);',
'        l_amount  INTEGER := 32767;',
'    BEGIN',
'        LOOP',
'            BEGIN',
'                DBMS_LOB.read(l_json, l_amount, l_offset, l_chunk);',
'                HTP.prn(l_chunk);',
'                l_offset := l_offset + l_amount;',
'                l_amount := 32767;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN EXIT;',
'            END;',
'        END LOOP;',
'    END;',
'',
'    DBMS_LOB.freetemporary(l_json);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>117430148729975535
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(556519616465047036)
,p_process_sequence=>40
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_ASEGURADOS_POLIZA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json    CLOB;',
'    l_sep     VARCHAR2(1) := '''';',
'    l_aseg_ini NUMBER;',
'    l_aseg_fin NUMBER;',
'BEGIN',
'    l_aseg_ini := CASE ',
'                    WHEN APEX_APPLICATION.G_X02 IS NULL OR APEX_APPLICATION.G_X02 = '''' ',
'                    THEN 1 ',
'                    ELSE TO_NUMBER(APEX_APPLICATION.G_X02) ',
'                  END;',
'',
'    l_aseg_fin := CASE ',
'                    WHEN APEX_APPLICATION.G_X03 IS NULL OR APEX_APPLICATION.G_X03 = '''' ',
'                    THEN 9999999999 ',
'                    ELSE TO_NUMBER(APEX_APPLICATION.G_X03) ',
'                  END;',
'',
'    DBMS_LOB.createtemporary(l_json, TRUE);',
'    DBMS_LOB.append(l_json, TO_CLOB(''{"asegurados":[''));',
'',
'    FOR r IN (',
'        SELECT COD_ASEGURADO',
'          FROM ASEGURADO_CERTIFICADO',
'         WHERE IDPOLIZA      = TO_NUMBER(APEX_APPLICATION.G_X01)  ',
'           AND COD_ASEGURADO BETWEEN l_aseg_ini                    ',
'                                 AND l_aseg_fin                    ',
'         ORDER BY COD_ASEGURADO',
'    ) LOOP',
'        DBMS_LOB.append(l_json,',
'            TO_CLOB(l_sep || ''{"cod":"'' || r.COD_ASEGURADO || ''"}''));',
'        l_sep := '','';',
'    END LOOP;',
'',
'    DBMS_LOB.append(l_json, TO_CLOB('']}''));',
'    HTP.p(l_json);',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.init;',
'        OWA_UTIL.mime_header(''application/json'', TRUE);',
'        HTP.p(''{"error":"'' || SQLERRM || ''"}'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>117427919633975513
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(561833311643380752)
,p_process_sequence=>50
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Genera_TIMBRE_FACTURA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vLeidos       NUMBER;',
'    vIncorrectos  NUMBER;',
'    vCorrectos    NUMBER;',
'    vTextoSalida  VARCHAR2(4000);',
'    vIdAgrupaEnv  NUMBER;',
'    vResultado    VARCHAR2(1);',
'    vFacturasCount  NUMBER := 0;',
'    vFacturasEmi    NUMBER := 0;',
'BEGIN',
'    BEGIN',
'        vResultado := OC_FACT_ELECT_CONF_DOCTO.Genera_Fact_Elect(',
'                            cGenerar      => ''FAC'',',
'                            nCodCia       => 1,',
'                            nCodEmpresa   => 1,',
'                            nIdPoliza     => :P138_IDPOLIZA,',
'                            cIndFactElec  => ''S'',',
'                            nLeidos       => vLeidos,',
'                            nIncorrectos  => vIncorrectos,',
'                            nCorrectos    => vCorrectos,',
'                            cTextoSalida  => vTextoSalida,',
'                            nIdAgrupaEnv  => vIdAgrupaEnv',
'                        );',
'',
'        IF NVL(vResultado, ''N'') <> ''S'' THEN',
'            RAISE_APPLICATION_ERROR(-20004,',
unistr('                ''Error al Generar Facturaci\00F3n Electr\00F3nica: '' || vTextoSalida);'),
'        END IF;',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            IF SQLCODE = -20876 THEN RAISE; END IF;',
'            RAISE_APPLICATION_ERROR(-20003,',
'                ''Error en Timbrado: '' || SQLERRM ||',
'                '' | Backtrace: '' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);',
'    END;',
'',
'  ',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>122741614812309229
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(563725776573831429)
,p_process_sequence=>60
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_FACTURAS_COUNT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    :P138_FACTURAS_COUNT := 0;',
'    :P138_FACTURAS_EMI   := 0;',
'',
'    SELECT COUNT(*)',
'    INTO   :P138_FACTURAS_COUNT',
'    FROM   FACTURAS F',
