,p_process_name=>'GET_FACTURAS_PDF'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json  CLOB;',
'    l_sep   VARCHAR2(1) := '''';',
'BEGIN',
'    DBMS_LOB.createtemporary(l_json, TRUE);',
'    DBMS_LOB.append(l_json, TO_CLOB(''{"facturas":[''));',
'',
'    FOR r IN (',
'        SELECT DOCTOPDF,',
'               NVL(NOMBARCHZIP, ''FACTURA_'' || IDAGRUPAENV) AS nombre',
'        FROM   FACT_ELECT_DOCTOS_TIMBRE',
'        WHERE  IDFACTURA IN (',
'                   SELECT IDFACTURA',
'                   FROM   FACTURAS',
'                   WHERE  IDPOLIZA = TO_NUMBER(APEX_APPLICATION.G_X01)',
'               )',
'    ) LOOP',
'        DBMS_LOB.append(l_json, TO_CLOB(l_sep || ''{"nombre":"'' || r.nombre || ''","pdf":"''));',
'        DBMS_LOB.append(l_json, r.DOCTOPDF);   ',
'        DBMS_LOB.append(l_json, TO_CLOB(''"}''));',
'        l_sep := '','';',
'    END LOOP;',
'',
'    DBMS_LOB.append(l_json, TO_CLOB('']}''));',
'',
'',
'    DECLARE',
'        l_offset  INTEGER := 1;',
'        l_chunk   VARCHAR2(32767);',
'        l_amount  INTEGER := 32767;',
'    BEGIN',
'        LOOP',
'            BEGIN',
'                DBMS_LOB.read(l_json, l_amount, l_offset, l_chunk);',
'                HTP.prn(l_chunk);',
'                l_offset := l_offset + l_amount;',
'                l_amount := 32767;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN EXIT;',
'            END;',
'        END LOOP;',
'    END;',
'',
'    DBMS_LOB.freetemporary(l_json);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>117427794186975511
);
