wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(221406377000735624)
,p_process_sequence=>20
,p_parent_process_id=>wwv_flow_imp.id(559307132366612144)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LISTA_2_PLANO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    l_poliza        NUMBER := :P138_IDPOLIZA;',
'    l_det_ini       NUMBER := :P138_DET_INI;',
'    l_det_fin       NUMBER := :P138_DET_FIN;',
'    l_endoso_ini    NUMBER := :P138_ENDOSO_INI;',
'    l_endoso_fin    NUMBER := :P138_ENDOSO_FIN;',
'    l_codcia        NUMBER := 1;',
'    l_ase_ini       NUMBER := :P138_ASEG_INI;',
'    l_ase_fin       NUMBER := :P138_ASEG_FIN;',
'    l_base_url      VARCHAR2(200) := ''http://sicascloud:8889/reports/rwservlet'';',
'    l_jasper_base   VARCHAR2(200) := '' http://192.168.0.224:8080/jasperserver/rest_v2/reports/'';',
'    l_credenciales  VARCHAR2(200) := ''&''||''j_username=jasperadmin''||''&''||''j_password=jasperadmin'';',
'',
'    TYPE t_reporte IS RECORD (',
'        rep_file  VARCHAR2(50),',
'        url       VARCHAR2(4000),',
'        pdf_name  VARCHAR2(100),',
'        item_name VARCHAR2(60),',
'        tamano    NUMBER',
'    );',
'    TYPE t_reportes IS TABLE OF t_reporte INDEX BY PLS_INTEGER;',
'    l_reportes t_reportes;',
'',
'    l_http_req      UTL_HTTP.req;',
'    l_http_resp     UTL_HTTP.resp;',
'    l_raw_data      RAW(32767);',
'    l_pdf_blob      BLOB;',
'    l_zip_blob      BLOB;',
'    l_url_final     VARCHAR2(32767);',
'    l_total_size    NUMBER;',
'    l_zip_size      NUMBER := 0;',
'    l_id            NUMBER;',
'    l_start_time    NUMBER;',
'    l_end_time      NUMBER;',
'    l_zip_name      VARCHAR2(150);',
'    l_nombres_str   VARCHAR2(500);',
'    l_tamanos_str   VARCHAR2(500);',
'    l_idx           PLS_INTEGER := 0;',
'',
'BEGIN',
'    l_start_time := DBMS_UTILITY.get_time;',
'    UTL_HTTP.set_transfer_timeout(3600);',
'',
'    IF :P138_REP_ASEG_SIN_PRIMA = ''S'' THEN',
'        l_idx := l_idx + 1;',
'        l_reportes(l_idx).rep_file  := ''LSTASESP.rep'';',
'        l_reportes(l_idx).pdf_name  := ''LSTASESP_'' || l_poliza || ''.pdf'';',
'        l_reportes(l_idx).item_name := ''P138_REP_ASEG_SIN_PRIMA'';',
'    END IF;',
'',
'    IF :P138_REP_ASEG_PRIMA = ''S'' THEN',
'        l_idx := l_idx + 1;',
'        l_reportes(l_idx).rep_file  := ''LSTASEG.rep'';',
'        l_reportes(l_idx).pdf_name  := ''LSTASEG_'' || l_poliza || ''.pdf'';',
'        l_reportes(l_idx).item_name := ''P138_REP_ASEG_PRIMA'';',
'    END IF;',
'',
'',
'',
'    IF l_reportes.COUNT = 0 THEN',
unistr('        DBMS_OUTPUT.PUT_LINE(''ERROR: no se seleccion\00F3 ning\00FAn reporte para generar'');'),
'        RETURN;',
'    END IF;',
'',
'    l_zip_name := ''PAPELERIA_POLIZA_'' || l_poliza || ''.zip'';',
'',
'    DBMS_LOB.createtemporary(l_zip_blob, TRUE);',
'',
'    FOR i IN 1 .. l_reportes.COUNT LOOP',
'',
'        l_total_size := 0;',
'',
'        l_url_final := l_base_url',
'                     || ''?keyreportappx''',
'                     || ''&report='' || l_reportes(i).rep_file',
'                     || ''&P_CODCIA='' || l_codcia',
'                     || ''&P_POLIZA='' || l_poliza',
'                     || ''&P_IDETPOLINI='' || l_det_ini',
'                     || ''&P_IDETPOLFIN='' || l_det_fin',
'                     || ''&P_ENDOSOINI='' || l_endoso_ini',
'                     || ''&P_ENDOSOFIN='' || l_endoso_fin',
'                     || ''&desformat=PDF&destype=cache&copies=1'';',
'',
'        l_http_req := UTL_HTTP.begin_request(l_url_final, ''GET'', ''HTTP/1.1'');',
'        UTL_HTTP.set_header(l_http_req, ''User-Agent'', ''Mozilla/5.0'');',
'        UTL_HTTP.set_header(l_http_req, ''Connection'', ''keep-alive'');',
'        l_http_resp := UTL_HTTP.get_response(l_http_req);',
'',
'        IF l_http_resp.status_code != 200 THEN',
'            UTL_HTTP.end_response(l_http_resp);',
'            DBMS_OUTPUT.PUT_LINE(''ERROR: status '' || l_http_resp.status_code ||',
'                '' al descargar '' || l_reportes(i).rep_file);',
'            DBMS_LOB.freetemporary(l_zip_blob);',
'            RETURN;',
'        END IF;',
'',
'        DBMS_LOB.createtemporary(l_pdf_blob, TRUE);',
'        BEGIN',
'            LOOP',
'                UTL_HTTP.read_raw(l_http_resp, l_raw_data, 32767);',
'                DBMS_LOB.writeappend(l_pdf_blob, UTL_RAW.length(l_raw_data), l_raw_data);',
'                l_total_size := l_total_size + UTL_RAW.length(l_raw_data);',
'',
'                IF MOD(l_total_size, 1048576) < 32767 THEN',
'                    DBMS_OUTPUT.PUT_LINE(''Descargado ('' || l_reportes(i).rep_file || ''): '' ||',
'                        ROUND(l_total_size/1048576, 2) || '' MB'');',
'                END IF;',
'            END LOOP;',
'        EXCEPTION',
'            WHEN UTL_HTTP.end_of_body THEN',
'                DBMS_OUTPUT.PUT_LINE(''Descarga completa ('' || l_reportes(i).rep_file || ''): '' ||',
'                    ROUND(l_total_size/1024, 2) || '' KB ('' ||',
'                    ROUND(l_total_size/1048576, 2) || '' MB)'');',
'        END;',
'',
'        UTL_HTTP.end_response(l_http_resp);',
'',
'        IF l_total_size = 0 THEN',
unistr('            DBMS_OUTPUT.PUT_LINE(''ERROR: PDF vac\00EDo ('' || l_reportes(i).rep_file || '')'');'),
'            DBMS_LOB.freetemporary(l_pdf_blob);',
'            DBMS_LOB.freetemporary(l_zip_blob);',
'            RETURN;',
'        END IF;',
'',
'        l_reportes(i).tamano := l_total_size;',
'',
'        APEX_ZIP.ADD_FILE(',
'            p_zipped_blob => l_zip_blob,',
'            p_file_name   => l_reportes(i).pdf_name,',
'            p_content     => l_pdf_blob',
'        );',
'',
'        DBMS_LOB.freetemporary(l_pdf_blob);',
'',
'    END LOOP;',
'',
'    APEX_ZIP.FINISH(l_zip_blob);',
'',
'    l_end_time := DBMS_UTILITY.get_time;',
'    DBMS_OUTPUT.PUT_LINE(''Tiempo total de descarga: '' ||',
'        ROUND((l_end_time - l_start_time)/100, 2) || '' segundos'');',
'',
'    l_zip_size := DBMS_LOB.GETLENGTH(l_zip_blob);',
unistr('    DBMS_OUTPUT.PUT_LINE(''Tama\00F1o ZIP: '' ||'),
'        ROUND(l_zip_size/1024, 2) || '' KB ('' ||',
'        ROUND(l_zip_size/1048576, 2) || '' MB)'');',
'',
'    FOR i IN 1 .. l_reportes.COUNT LOOP',
'        l_nombres_str := l_nombres_str || CASE WHEN i > 1 THEN '','' END || l_reportes(i).item_name;',
'        l_tamanos_str := l_tamanos_str || CASE WHEN i > 1 THEN '','' END || l_reportes(i).tamano;',
'    END LOOP;',
'',
'    DBMS_OUTPUT.PUT_LINE(''Items incluidos: '' || l_nombres_str);',
unistr('    DBMS_OUTPUT.PUT_LINE(''Tama\00F1os (bytes): '' || l_tamanos_str);'),
'',
'    SELECT NVL(MAX(ID), 0) + 1 INTO l_id FROM REPORTES_PDF;',
'',
'    DBMS_OUTPUT.PUT_LINE(''Insertando en tabla REPORTES_PDF con ID: '' || l_id);',
'',
'    INSERT INTO REPORTES_PDF (',
'        ID,',
'        NOMBRE,',
'        ARCHIVO,',
'        CODUSUARIO,',
'        FECHA,',
'        TAMANO_ARCHIVO,',
'        NOMBRE_ARCHIVO,',
'        COLOR,',
'        MIMETYPE',
'    ) VALUES (',
'        l_id,',
'        ''PAPELERIA_POLIZA_'' || l_poliza,',
'        l_zip_blob,',
'        ''&APP_USER.'',',
'        SYSDATE,',
'        l_tamanos_str,',
'        l_nombres_str,',
'        ''#0AC756'',',
'        ''application/x-zip-compressed''',
'       ',
'    );',
'',
'    COMMIT;',
'',
'    DBMS_LOB.freetemporary(l_zip_blob);',
'',
'EXCEPTION',
'    WHEN UTL_HTTP.request_failed THEN',
'        DBMS_OUTPUT.PUT_LINE(''ERROR: No se puede conectar al servidor de reportes'');',
unistr('        DBMS_OUTPUT.PUT_LINE(''Verifique que el servidor est\00E9 disponible'');'),
'        IF DBMS_LOB.ISTEMPORARY(l_pdf_blob) = 1 THEN DBMS_LOB.freetemporary(l_pdf_blob); END IF;',
'        IF DBMS_LOB.ISTEMPORARY(l_zip_blob) = 1 THEN DBMS_LOB.freetemporary(l_zip_blob); END IF;',
'        ROLLBACK;',
'',
'    WHEN UTL_HTTP.transfer_timeout THEN',
unistr('        DBMS_OUTPUT.PUT_LINE(''ERROR: Timeout - La descarga excedi\00F3 el tiempo l\00EDmite'');'),
'        IF DBMS_LOB.ISTEMPORARY(l_pdf_blob) = 1 THEN DBMS_LOB.freetemporary(l_pdf_blob); END IF;',
'        IF DBMS_LOB.ISTEMPORARY(l_zip_blob) = 1 THEN DBMS_LOB.freetemporary(l_zip_blob); END IF;',
'        ROLLBACK;',
'',
'    WHEN OTHERS THEN',
'        DBMS_OUTPUT.PUT_LINE(''ERROR: '' || SQLERRM);',
unistr('        DBMS_OUTPUT.PUT_LINE(''C\00F3digo: '' || SQLCODE);'),
'        IF DBMS_LOB.ISTEMPORARY(l_pdf_blob) = 1 THEN DBMS_LOB.freetemporary(l_pdf_blob); END IF;',
'        IF DBMS_LOB.ISTEMPORARY(l_zip_blob) = 1 THEN DBMS_LOB.freetemporary(l_zip_blob); END IF;',
'        ROLLBACK;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(559307044692612143)
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF (:P138_REP_ASEG_SIN_PRIMA = ''S'' OR :P138_REP_ASEG_PRIMA = ''S'')',
'       AND TO_NUMBER(:P138_ASEGURADOS_COUNT) > 19177 THEN',
'        RETURN TRUE;',
'    ELSE',
'        RETURN FALSE;',
'    END IF;',
'END;'))
,p_process_when_type=>'FUNCTION_BODY'
,p_process_when2=>'PLSQL'
,p_internal_uid=>133596797649567401
);
end;
