,p_is_primary_key=>true
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(595607248811153326)
,p_item_source_plug_id=>wwv_flow_imp.id(595607248811153326)
,p_prompt=>'Asegurado'
,p_source=>'COD_ASEGURADO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    COD_ASEGURADO ||''-''|| OC_ASEGURADO.NOMBRE_ASEGURADO(1,1,a.COD_ASEGURADO) D,',
'    a.COD_ASEGURADO R',
'from asegurado_certificado a',
'where a.idpoliza = :P142_IDPOLIZA',
'  and a.idetpol = (',
'        select e.idetpol',
'        from endosos e',
'        where e.idpoliza = :P142_IDPOLIZA',
'          and e.idendoso = :P142_IDENDOSO',
'  )',
'  and a.estado = ''EMI''',
'  and not exists (',
'        select 1',
'        from stg_endoso_exc_aseg s',
'        where s.idpoliza = :P142_IDPOLIZA',
'          and s.idendoso = :P142_IDENDOSO',
'          and s.cod_asegurado = a.cod_asegurado',
'  );',
''))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P142_IDPOLIZA,P142_IDENDOSO'
