,p_event_id=>wwv_flow_imp.id(542014082478940467)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT MOTIVANULEXCLU',
'      INTO :P142_MOTIVANULEXCLU',
'      FROM stg_default_motivo_exc_endoso',
'     WHERE idpoliza = :P142_IDPOLIZA',
'       AND idendoso = :P142_IDENDOSO;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P142_MOTIVANULEXCLU := NULL;',
'END;'))
,p_attribute_02=>'P142_IDPOLIZA,P142_IDENDOSO'
,p_attribute_03=>'P142_MOTIVANULEXCLU'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(568653183862869530)
,p_name=>'CHANGE_MOTIVANULEXCLU'
,p_event_sequence=>50
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P142_MOTIVANULEXCLU'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(568653225602869531)
,p_event_id=>wwv_flow_imp.id(568653183862869530)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'MERGE INTO stg_default_motivo_exc_endoso t',
'USING (',
'    SELECT',
'        :P142_IDPOLIZA       AS idpoliza,',
'        :P142_IDENDOSO       AS idendoso,',
'        :P142_MOTIVANULEXCLU AS motivanulexclu',
'    FROM dual',
') s',
'ON (',
'    t.idpoliza = s.idpoliza',
'    AND t.idendoso = s.idendoso',
')',
'WHEN MATCHED THEN',
'    UPDATE SET',
'        t.MOTIVANULEXCLU = s.motivanulexclu',
'WHEN NOT MATCHED THEN',
'    INSERT (',
'        IDPOLIZA,',
'        IDENDOSO,',
'        MOTIVANULEXCLU',
'    )',
'    VALUES (',
'        s.idpoliza,',
'        s.idendoso,',
'        s.motivanulexclu',
'    );',
''))
,p_attribute_02=>'P142_MOTIVANULEXCLU,P142_IDPOLIZA,P142_IDENDOSO'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
