begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(595605186810153305)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_CARGA_MASIVA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    nIdPoliza   number := :P142_IDPOLIZA;',
'    nIdEndoso   number := :P142_IDENDOSO;',
'    cUsuario    varchar2(100) := coalesce(v(''APP_USER''), user);',
'',
'    lArchivo    blob;',
'    cNombreFile varchar2(4000);',
'begin',
'    -- Obtener archivo cargado en APEX',
'    select blob_content,',
'           filename',
'      into lArchivo,',
'           cNombreFile',
'      from apex_application_temp_files',
'     where name = :P142_FILE;',
'',
'    -- Llamar a la carga masiva (solo inserta en STG)',
'    OC_MANTENIMIENTO_ENDOSOS_ACCIONES.CARGA_MASIVA_STG_EXCLUSION(',
'        nIdPoliza       => nIdPoliza,',
'        nIdEndoso       => nIdEndoso,',
'        cUsuario        => cUsuario,',
'        lArchivoBinario => lArchivo,',
'        cNombreArchivo  => cNombreFile',
'    );',
'',
'    -- Limpieza del archivo temporal',
'    delete from apex_application_temp_files',
'     where name = :P142_FILE;',
'',
'exception',
'    when no_data_found then',
'        raise_application_error(',
'            -20201,',
unistr('            ''No se encontr\00F3 el archivo cargado.'''),
'        );',
'    when others then',
'        raise;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(595218617550345913)
,p_internal_uid=>57228651340498204
,p_process_comment=>'Proceso para guardar en tabla de listado de asegurados de exclusion de forma masiva'
);
