'    :P142_IDETPOL',
'    from endosos ',
'    where ',
'    idpoliza = :P142_IDPOLIZA AND',
'    idendoso = :P142_IDENDOSO;',
'end if;',
'',
' select  ',
'    trunc(FECINIVIG),trunc(FECFINVIG)',
'    INTO',
'    :P142_FECINIVIG,:P142_FECFINVIG',
'    from endosos ',
'    where ',
'    idpoliza = :P142_IDPOLIZA AND',
