wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(595833444542689806)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'EC_DescargaFormatoMasivo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'BEGIN',
'  -- MIME para TXT',
'  owa_util.mime_header(''text/plain'', FALSE);',
'  htp.p(''Content-Disposition: attachment; filename="CodigoAsegurado.txt"'');',
'  owa_util.http_header_close;',
'',
unistr('  -- Cada COD_ASEGURADO en una l\00EDnea (sin encabezado)'),
'  FOR r IN (',
'    SELECT a.cod_asegurado',
'    FROM asegurado_certificado a',
'    WHERE a.idpoliza = :P142_IDPOLIZA',
'      AND a.idetpol = (',
'            SELECT e.idetpol',
'            FROM endosos e',
'            WHERE e.idpoliza = :P142_IDPOLIZA',
'              AND e.idendoso = :P142_IDENDOSO',
'      )',
'      AND a.estado = ''EMI''',
'      AND NOT EXISTS (',
'            SELECT 1',
'            FROM stg_endoso_exc_aseg s',
'            WHERE s.idpoliza = :P142_IDPOLIZA',
'              AND s.idendoso = :P142_IDENDOSO',
'              AND s.cod_asegurado = a.cod_asegurado',
'      )',
'  ) LOOP',
unistr('    htp.prn(r.cod_asegurado || chr(10)); -- salto de l\00EDnea'),
'  END LOOP;',
'',
'  apex_application.stop_apex_engine;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'DL_TXT'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>57456909073034705
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(542014266617940469)
,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'STATUS_ENDOSOS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'SELECT STSENDOSO',
'INTO',
':P142_STATUS_ENDOSOS',
'FROM',
' ENDOSOS',
'WHERE IDPOLIZA = :P100_IDPOLIZA',
'AND IDENDOSO = :P142_IDENDOSO;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>102922569786868946
);
end;
