 p_id=>wwv_flow_imp.id(596100336244079828)
,p_event_id=>wwv_flow_imp.id(596100312810079827)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nSumaAsegMinima     COBERTURAS_DE_SEGUROS.SumaAsegMinima%TYPE;',
'    nSumaAsegMaxima     COBERTURAS_DE_SEGUROS.SumaAsegMaxima%TYPE;',
'    nSumaAsegMaxIndiv   COBERTURAS_DE_SEGUROS.SumaAsegMaxIndiv%TYPE;',
'    nSamiPoliza         POLIZAS.SamiPoliza%TYPE;',
'    nSUMAASEG_MONEDA    COBERT_ACT_ASEG.SUMAASEG_MONEDA%TYPE;',
'    nTASA               COBERT_ACT_ASEG.TASA%TYPE;',
'    nPRIMA_MONEDA       COBERT_ACT_ASEG.PRIMA_MONEDA%TYPE;',
'BEGIN',
'',
'    nSUMAASEG_MONEDA    := REGEXP_REPLACE(:P144_SUMAASEG_MONEDA, ''[^0-9.]'', '''');',
'    nTASA               := REGEXP_REPLACE(:P144_TASA, ''[^0-9.]'', '''');',
'    nPRIMA_MONEDA       := REGEXP_REPLACE(:P144_PRIMA_MONEDA, ''[^0-9.]'', '''');',
'    ',
'    IF OC_COBERTURAS_DE_SEGUROS.CODIGO_TARIFA(1,1, :P144_IDTIPOSEG,',
'                                            :P144_PLANCOB, :P144_CODCOBERT) IS NOT NULL THEN',
'        ',
'        nTASA  := OC_COBERT_ACT_ASEG.CALCULO_COBERTURA (1,1, :P144_IDTIPOSEG,',
'                                                            :P144_PLANCOB,:P144_IDPOLIZA,:P144_IDETPOL,',
'                                                            :P144_COD_ASEGURADO, :P144_NTASACAMBIO,:P144_CODCOBERT, ''T'');',
'        -- apex_debug.info(''P144_TASA: ''||nTASA);',
'        IF NVL(nTASA,0) = 0 THEN',
'            nPRIMA_MONEDA := ROUND(OC_COBERT_ACT_ASEG.CALCULO_COBERTURA  (1,1, :P144_IDTIPOSEG,',
'                                                                        :P144_PLANCOB, :P144_IDPOLIZA, :P144_IDETPOL,',
'                                                                        :P144_COD_ASEGURADO, :P144_NTASACAMBIO, :P144_CODCOBERT, ''P''),2);',
'            nTASA := nPRIMA_MONEDA / nSUMAASEG_MONEDA;',
'        END IF;',
'',
'        IF NVL(nPRIMA_MONEDA,0) = 0 THEN',
'            nPRIMA_MONEDA := ROUND((NVL(nSUMAASEG_MONEDA,0) * NVL(nTASA,0)) / :P144_NTIPOTASA,2);',
'        END IF;',
'',
'        :P144_PRIMA_LOCAL    := nPRIMA_MONEDA * :P144_NTASACAMBIO;',
' ',
'    END IF;',
'    ',
'    nSumaAsegMinima   := OC_COBERTURAS_DE_SEGUROS.SUMA_ASEGURADA(1, 1, :P144_IDTIPOSEG,',
'                                                                :P144_PLANCOB, :P144_CODCOBERT, ''MIN'');',
'    nSumaAsegMaxima   := OC_COBERTURAS_DE_SEGUROS.SUMA_ASEGURADA(1, 1, :P144_IDTIPOSEG,',
'                                                                :P144_PLANCOB, :P144_CODCOBERT, ''MAX'');',
'    nSumaAsegMaxIndiv := OC_COBERTURAS_DE_SEGUROS.SUMA_ASEGURADA(1, 1, :P144_IDTIPOSEG,',
'                                                                :P144_PLANCOB, :P144_CODCOBERT, ''SAMI'');',
'    nSamiPoliza       := OC_POLIZAS.SAMI_POLIZA(1, 1, :P144_IdPoliza);',
'',
'    IF nSUMAASEG_MONEDA < nSumaAsegMinima AND nSumaAsegMinima > 0 THEN',
unistr('        :P144_SHOW_ERROR := ''Suma Asegurada NO puede ser Menor a la Suma Asegurada M\00EDnima de Cobertura'';'),
'    END IF;',
'',
'    IF nSUMAASEG_MONEDA > nSumaAsegMaxima AND nSumaAsegMaxima > 0 THEN',
unistr('        :P144_SHOW_ERROR := ''Suma Asegurada NO puede ser Mayor a la Suma Asegurada M\00E1xima de Cobertura'';'),
'    END IF;',
'',
'    IF nSUMAASEG_MONEDA > nSumaAsegMaxIndiv AND nSumaAsegMaxIndiv > 0 THEN',
'        :P144_SHOW_ERROR := ''Suma Asegurada Es Mayor al SAMI Configurado para la Cobertura y va a requerir Reaseguro'';',
'    END IF;',
'',
'    IF nSUMAASEG_MONEDA > NVL(nSamiPoliza,0) AND NVL(nSamiPoliza,0) > 0 THEN',
'        :P144_SumaAseg_Local := nSamiPoliza * :P144_nTasaCambio;',
'    END IF;',
'',
'    -- :P144_SUMAASEG_MONEDA   := nSUMAASEG_MONEDA;',
'    :P144_TASA              := nTASA;',
'    :P144_PRIMA_MONEDA      := nPRIMA_MONEDA;',
'END;'))
,p_attribute_02=>'CODCIA,COD_EMPRESA,P144_IDTIPOSEG,P144_PLANCOB,P144_CODCOBERT,P144_IDPOLIZA,P144_IDETPOL,P144_COD_ASEGURADO,P144_NTASACAMBIO,P144_PRIMA_MONEDA,P144_SUMAASEG_MONEDA,P144_TASA,P144_NTIPOTASA'
,p_attribute_03=>'P144_SHOW_ERROR,P144_TASA,P144_PRIMA_MONEDA,P144_PRIMA_LOCAL,P144_SUMAASEG_LOCAL'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
