'DECLARE',
'    nSUMAASEG_MONEDA    COBERT_ACT_ASEG.SUMAASEG_MONEDA%TYPE    := REGEXP_REPLACE(:P144_SUMAASEG_MONEDA, ''[^0-9.]'', '''');',
