'BEGIN',
'    IF OC_ASEGURADO_CERTIFICADO.STATUS_ASEGURADO(:P144_CODCIA,:P144_IDPOLIZA,:P144_IDETPOL,:P144_COD_ASEGURADO) != ''ANU'' THEN',
'        OC_ASEGURADO_CERTIFICADO.ACTUALIZA_VALORES(:P144_CODCIA,:P144_CODEMPRESA,:P144_IDPOLIZA,:P144_IDETPOL,:P144_COD_ASEGURADO);',
'',
'        OC_ASEGURADO_CERTIFICADO.ACTUALIZA_ASISTENCIAS(:P144_CODCIA,:P144_CODEMPRESA,',
'                                                     :P144_IDPOLIZA,:P144_IDETPOL,',
'                                                     :P144_COD_ASEGURADO);',
'',
'        IF NVL(:P144_IDENDOSO,0) = 0 THEN',
'            OC_DETALLE_POLIZA.ACTUALIZA_VALORES(:P144_CODCIA, :P144_IDPOLIZA, :P144_IDETPOL, 0);',
'            OC_POLIZAS.ACTUALIZA_VALORES(:P144_CODCIA, :P144_IDPOLIZA, 0);',
'        ELSE',
'            OC_ENDOSO.ACTUALIZA_VALORES(:P144_CODCIA, :P144_CODEMPRESA, :P144_IDPOLIZA,',
'                                  :P144_IDETPOL, :P144_IDENDOSO);',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>63738269426852702
);
