'    FROM DETALLE_POLIZA',
'    WHERE 1=1',
'    AND IDPOLIZA    = :P144_IDPOLIZA',
'    AND IDETPOL     = :P144_IDETPOL;',
'',
'    IF :P144_COD_ASEGURADO IS NOT NULL THEN ',
'        :P144_CNOM_ASEGURADO := :P144_COD_ASEGURADO||'' - ''||OC_ASEGURADO.NOMBRE_ASEGURADO(1,1,:P144_COD_ASEGURADO);',
'    ELSE',
'        :P144_CNOM_ASEGURADO := ''No se ha Seleccionado Asegurado'';',
'    END IF;',
'',
'    IF :P144_CODCOBERT IS NOT NULL THEN',
'        :P144_CODCOBERT_OLD := :P144_CODCOBERT;',
'    END IF;',
'',
'    IF :P144_COD_MONEDA IS NULL THEN',
'        :P144_COD_MONEDA := ''PS'';',
'    END IF;',
'END;'))
