'DECLARE ',
'    dFecFin DATE;',
'    v_NOCLAUSULA number;',
'BEGIN',
'    IF :P145_TIPO_CLAUSULA IS NOT NULL AND :P145_INICIO_VIGENCIA IS NOT NULL AND :P145_FIN_VIGENCIA IS NOT NULL THEN',
'        :P145_ESTADO := ''SOLICI'';',
'',
'        SELECT NVL(MAX(Cod_Clausula), 0) + 1',
'        INTO :P145_COD_CLAUSULA',
'        FROM CLAUSULAS_COBERT_ACT_ASEG',
'        WHERE CodCia        = 1',
'        AND IdPoliza      = :P145_IDPOLIZA',
'        AND IDetPol       = :P145_IDETPOL',
'        AND Cod_Asegurado = :P145_COD_ASEGURADO',
