 p_id=>wwv_flow_imp.id(597220746383062721)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PR_SetVAlor'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    :P146_NOPOLIZA_CLA := :P146_POLIZA ;',
'    :P146_NODETALLE     := :P146_IDETPOL;',
'    :P146_COD_ASEGURADO_CLA := :P146_ASEGURADO;',
'',
'',
'    -- Cargar datos tipo/plan',
'    IF :P146_POLIZA IS NOT NULL ',
'       AND :P146_IDETPOL IS NOT NULL',
'       AND :P146_TIPOSEGURO IS NULL ',
'       AND :P146_PLAN IS NULL THEN',
'        ',
'        SELECT IdTipoSeg, PlanCob',
'        INTO :P146_TIPOSEGURO, :P146_PLAN  ',
'        FROM DETALLE_POLIZA',
'        WHERE IDPOLIZA = :P146_POLIZA',
'          AND IDETPOL = :P146_IDETPOL;',
'    END IF;',
'',
'',
'',
'    -- nombre del asegurado',
'    :P146_ASEGURADO_NOMBRE := ',
'        CASE ',
'            WHEN :P146_ASEGURADO IS NOT NULL THEN',
'      ',
'                OC_ASEGURADO.NOMBRE_ASEGURADO(1, 1, :P146_ASEGURADO)',
'',
'            ELSE',
'                ''No se ha Seleccionado Asegurado''',
'        END;',
'    :P146_ASEGURADO_CLA := ',
'        CASE ',
'            WHEN :P146_ASEGURADO IS NOT NULL THEN',
'                ',
'                OC_ASEGURADO.NOMBRE_ASEGURADO(1, 1, :P146_ASEGURADO)',
'                ',
'            ELSE',
'                ''No se ha Seleccionado Asegurado''',
'        END;',
'    -- Cargar datos tipo/plan',
'    IF :P146_COBERTURA IS NOT NULL then ',
'        :P146_COBERTURA_DESC :=    OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(1,1,:P146_TIPOSEGURO,:P146_PLAN,:P146_COBERTURA);',
'        :P146_DESCOBERTURAS_CLA  :=    OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(1,1,:P146_TIPOSEGURO,:P146_PLAN,:P146_COBERTURA);',
'        :P146_COBERTURAS_CLA := :P146_COBERTURA;',
'    end if;',
'    ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>58844210913407620
);
end;
