wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(597667776778877322)
,p_plug_name=>'REPORTE'
,p_region_name=>'coberturas'
,p_parent_plug_id=>wwv_flow_imp.id(597667637969877321)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    CS.CodCia, ',
'    CS.CodEmpresa, ',
'    CS.IdTipoSeg, ',
'    CS.PlanCob, ',
'    CS.CodCobert, ',
'    CS.DescCobert, ',
'    CS.Cobertura_Basica,',
'    -- COLUMNAS BASE DE COBERT_ACT_ASEG',
'    NVL(CA.SalarioMensual, 0) AS SalarioMensual,',
'    NVL(CA.VecesSalario, 0) AS VecesSalario,',
'    NVL(CA.SumaIngresada, CA.SumaAseg_Moneda) AS SumaFija,',
'    NVL(CA.SumaAsegCalculada, CA.SumaAseg_Moneda) AS SumaACotizar,',
'    NVL(CA.SumaAseg_Moneda, 0) AS SumaAsegMoneda,',
'    -- Edades',
'    NVL(CA.Edad_Minima, CS.Edad_Minima) AS Edad_Minima,',
'    NVL(CA.Edad_Maxima, CS.Edad_Maxima) AS Edad_Maxima,',
'    NVL(CA.Edad_Exclusion, CS.Edad_Exclusion) AS Edad_Exclusion,',
'    -- Extras y Franquicias',
'    NVL(CA.PorcExtraPrimaDet, 0) AS PorcExtraPrima,',
'    NVL(CA.MontoExtraPrimaDet, 0) AS MontoExtraPrima,',
'    NVL(CA.Franquiciaingresado, 0) AS Franquicia,',
'    NVL(CA.Montodiario, 0) AS MontoDiario,',
'    CA.Dias_cal,',
unistr('    -- DATOS DE COTIZACI\00D3N'),
'    NVL(CM.DeducibleIngresado, 0) AS DeducibleIngresado,',
'    NVL(CM.CuotaPromedio, 0) AS CuotaPromedio,',
'    NVL(CM.PrimaPromedio, 0) AS PrimaPromedio,',
unistr('    -- L\00CDMITES DE SUMA ASEGURADA'),
'   NVL(CA.SUMAASEG_MINIMA, CS.SUMAASEGMINIMA) AS SumaAsegMinima,',
'    NVL(CA.SUMAASEG_MAXIMA, CS.SUMAASEGMAXIMA) AS SumaAsegMaxima,',
'    CS.SumaAsegurada,',
unistr('    -- C\00C1LCULO DE SUMA COTIZACI\00D3N (L\00D3GICA PL/SQL CONVERTIDA)'),
'    CASE ',
'        WHEN NVL(CA.SumaAsegCalculada, 0) != 0 THEN',
'            CA.SumaAsegCalculada',
'        ELSE',
'            ',
'            CASE',
'                WHEN (NVL(CA.SalarioMensual, 0) * NVL(CA.VecesSalario, 0) + ',
'                      CASE ',
'                          WHEN NVL(CA.SumaIngresada, 0) = 0 THEN CS.SumaAsegurada',
'                          ELSE CA.SumaIngresada',
'                      END) < NVL(CA.SumaAseg_Minima, CS.SUMAASEGMINIMA) THEN',
'                    NVL(CA.SumaAseg_Minima, CS.SUMAASEGMINIMA)',
'                    ',
'                WHEN (NVL(CA.SalarioMensual, 0) * NVL(CA.VecesSalario, 0) + ',
'                      CASE ',
'                          WHEN NVL(CA.SumaIngresada, 0) = 0 THEN CS.SumaAsegurada',
'                          ELSE CA.SumaIngresada',
'                      END) > NVL(CA.SumaAseg_Maxima, CS.SUMAASEGMAXIMA) THEN',
'                    NVL(CA.SumaAseg_Maxima, CS.SUMAASEGMAXIMA)',
'                    ',
'                ELSE',
'                    NVL(CA.SalarioMensual, 0) * NVL(CA.VecesSalario, 0) + ',
'                    CASE ',
'                        WHEN NVL(CA.SumaIngresada, 0) = 0 THEN NVL(CS.SumaAsegurada, 0)',
'                        ELSE CA.SumaIngresada',
'                    END',
'            END',
'    END AS SumaCotizacion,',
unistr('    -- VALIDACI\00D3N DE COBERTURAS EXCLUYENTES'),
'    CASE ',
'        WHEN EXISTS (',
'            SELECT 1 ',
'            FROM COBERTURAS_EXCLUYENTES CE',
'            WHERE CE.CodCia = CS.CodCia',
'              AND CE.CodEmpresa = CS.CodEmpresa',
'              AND CE.IdTipoSeg = CS.IdTipoSeg',
'              AND CE.PlanCob = CS.PlanCob',
'              AND CE.CodCobert = CS.CodCobert',
'        ) THEN ''S''',
'        ELSE ''N''',
'    END AS TieneExcluyentes,',
unistr('    -- INDICADOR DE ASIGNACI\00D3N (L\00D3GICA PL/SQL)'),
'    CASE ',
'        WHEN NVL(CS.Cobertura_Basica, ''N'') = ''S'' ',
'         AND NVL(:P147_EXISTEN_COB_MASTER, ''N'') = ''N'' ',
'        THEN ''S''',
'        ELSE ''N''',
'    END AS IndAsignar,',
unistr('    --- CHECKBOX DE SELECCI\00D3N'),
'    ''N'' AS Seleccionado,',
'    -- ROWID PARA OPERACIONES',
'    CA.ROWID AS ROW_ID',
'    ',
'FROM COBERTURAS_DE_SEGUROS CS',
'    -- JOIN CON COBERT_ACT_ASEG',
'    LEFT JOIN COBERT_ACT_ASEG CA ON (',
'        CA.CodCia = :P147_CODCIA',
'        AND CA.CodEmpresa = :P147_CODEMPRESA',
'        AND CA.IdPoliza = :P147_IDPOLIZA',
'        AND CA.IDetPol = :P147_IDETPOL',
'        AND CA.Cod_Asegurado = :P147_COD_ASEG',
'        AND CA.IdTipoSeg = CS.IdTipoSeg',
'        AND CA.PlanCob = CS.PlanCob',
'        AND CA.CodCobert = CS.CodCobert',
'    )',
'    -- JOIN CON COTIZACIONES_COBERT_MASTER',
'    LEFT JOIN COTIZACIONES_COBERT_MASTER CM ON (',
'        CM.CodCobert = CS.CodCobert',
'        AND CM.CodCia = :P147_CODCIA',
'        AND CM.CodEmpresa = :P147_CODEMPRESA',
'        AND EXISTS (',
'            SELECT 1 ',
'            FROM DETALLE_POLIZA_COTIZ DP',
'            WHERE DP.CodCia = CM.CodCia',
'              AND DP.CodEmpresa = CM.CodEmpresa',
'              AND DP.IdCotizacion = CM.IdCotizacion',
'              AND DP.IDetCotizacion = CM.IDetCotizacion',
'              AND DP.CodCia = :P147_CODCIA',
'              AND DP.CodEmpresa = :P147_CODEMPRESA',
'              AND DP.IdPoliza = :P147_IDPOLIZA',
'              AND DP.IDetPol = :P147_IDETPOL',
'        )',
'    )',
'',
'WHERE CS.CodCia = :P147_CODCIA',
'  AND CS.IdTipoSeg = :P147_TIPOSEGURO',
'  AND CS.PlanCob = :P147_PLAN',
'  AND CS.StsCobertura = ''ACT'' ',
' '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P147_IDPOLIZA,P147_CODCIA,P147_CODEMPRESA,P147_IDETPOL,P147_COD_ASEG'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'REPORTE'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
