wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(598123714163585615)
,p_plug_name=>'Coberturas'
,p_parent_plug_id=>wwv_flow_imp.id(597667637969877321)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT CS.IDTIPOSEG, ',
'             CS.PLANCOB, ',
'             CS.CODCOBERT, ',
'             CS.DESCCOBERT, ',
'             NVL(CA.SumaAsegCalculada,CA.SumaAseg_Moneda) SumaAseg,',
'             NVL(CA.SalarioMensual,0) as MENSUAL, ',
'             NVL(CA.VecesSalario,0)  AS VSALARIO,',
'             NVL(CA.Edad_Minima,CS.Edad_Minima) as EDAD_MINIMA, ',
'             NVL(CA.Edad_Maxima,CS.Edad_Maxima) as EDAD_MAXIMA, ',
'             NVL(CA.Edad_Exclusion, CS.Edad_Exclusion) as EDAD_EXCLUSION,',
'             NVL(CA.SumaAseg_Minima,CS.SumaAsegMinima) as SUMAASEGMINIMA,',
'             NVL(CA.SumaAseg_Maxima,CS.SumaAsegMaxima) as SUMAASEGMAXIMA,',
'             NVL(CA.PorcExtraPrimaDet,0), ',
'             NVL(CA.MontoExtraPrimaDet,0),',
'             NVL(CA.SumaIngresada,CA.SumaAseg_Moneda),',
'             NVL(CA.Franquiciaingresado,0),',
'             NVL(CA.Montodiario,0),',
'             CA.Dias_cal, ',
'              CS.MONTODEDUCIBLE, ',
'              CS.PORC_TASA, ',
'              CS.PRIMA_COBERT,',
'              CS.COBERTURA_BASICA',
'        FROM COBERT_ACT_ASEG CA, COBERTURAS_DE_SEGUROS CS',
'       WHERE CA.CodCia         = 1',
'         AND CA.CodEmpresa     = 1',
'         AND CA.IdPoliza       = :P147_IDPOLIZA',
'         AND CA.IDetPol        = 1',
'         AND CA.Cod_Asegurado  = :P147_COD_ASEG',
'         AND CS.CodCia         = CA.CodCia',
'         AND CS.IdTipoSeg      = CA.IdTipoSeg',
'         AND CS.PlanCob        = CA.PlanCob',
'         AND CS.CodCobert      = CA.CodCobert;'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
