,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var region = apex.region("coberturas");',
'var grid = region.widget().interactiveGrid("getViews","grid");',
'var model = grid.model;',
'',
'var sumaFija = $v("P147_FIJA_COBERTURA");',
'',
unistr('if (!confirm("\00BFDesea Calcular Todas las Coberturas Master con la Suma Fija de " + sumaFija + "?")) {'),
'    return;',
'}',
'',
'model.forEach(function(record){',
'',
'    var salario = Number(model.getValue(record,"SALARIOMENSUAL")) || 0;',
'    var veces   = Number(model.getValue(record,"VECESSALARIO")) || 0;',
'    var min     = Number(model.getValue(record,"SUMAASEGMINIMA")) || 0;',
'    var max     = Number(model.getValue(record,"SUMAASEGMAXIMA")) || 0;',
'',
'    var sumaCot = (salario * veces) + Number(sumaFija);',
'',
'    if (min > 0){',
'        sumaCot = Math.max(sumaCot, min);',
'    }',
'',
'    if (max > 0){',
'        sumaCot = Math.min(sumaCot, max);',
'    }',
'',
'    model.setValue(record,"SUMAFIJA", sumaFija);',
'    model.setValue(record,"INDASIGNAR", "S");',
'    model.setValue(record,"SUMACOTIZACION", sumaCot);',
'',
'});',
'',
'model.save();',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(598122775636585606)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SetValores'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN ',
'',
'BEGIN',
'      SELECT NVL(DeducibleIngresado,0), CuotaPromedio, PrimaPromedio',
'        INTO :P147_DEDUCIBLE, :P147_CUOTA_PROMEDIO, :P147_PRIMA_PROMEDIO',
'        FROM COTIZACIONES_COBERT_MASTER CM, DETALLE_POLIZA_COTIZ DP',
'       WHERE CM.CodCia         = DP.CodCia',
'         AND CM.CodEmpresa     = DP.CodEmpresa',
'         AND CM.IdCotizacion   = DP.IdCotizacion',
'         AND CM.IDetCotizacion = DP.IDetCotizacion',
'         AND DP.CodCia         = 1',
'         AND DP.CodEmpresa     = 1',
'         AND DP.IdPoliza       = :P147_IDPOLIZA',
'         AND DP.IDetPol        = :P147_IDETPOL',
'         AND CM.CodCobert      = :P147_COBERTURA;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         :P147_DEDUCIBLE := 0;',
'         :P147_CUOTA_PROMEDIO     := 0;',
'         :P147_PRIMA_PROMEDIO     := 0;',
'   END;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>59746240166930505
);
end;
