'',
'    FOR i IN 1 .. l_lista.COUNT LOOP',
'',
'        /*BEGIN',
'            INSERT INTO SICAS_OC.ASISTENCIAS_ASEGURADO',
'                    (CodCia, CodEmpresa, IdPoliza, IDetPol, Cod_Asegurado, CodAsistencia,',
'                     CodMoneda, MontoAsistLocal, MontoAsistMoneda, StsAsistencia,',
