 p_id=>wwv_flow_imp.id(598492140408013947)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Cargar_Lista_Asegurados'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  lArchivoBinario  BLOB; ',
'BEGIN',
unistr('  -- Validaci\00F3n: archivo seleccionado'),
'    IF :P151_FILE IS NULL THEN',
'        apex_error.add_error(',
'            p_message          => ''Debe seleccionar un archivo .txt para cargar.'',',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'        RETURN;',
'    END IF;',
'',
'  -- Obtener BLOB del archivo subido (File Browse -> APEX_APPLICATION_TEMP_FILES)',
'    SELECT blob_content',
'        INTO lArchivoBinario',
'        FROM apex_application_temp_files',
'        WHERE name = :P151_FILE;',
'',
'  -- Llamar al procedimiento',
'    OC_CAMBIA_LISTA_ASEGMODELO_ACCIONES.CARGA_LAYOUT_LISTA_ASEGURADOS(',
'        nCodCia         => :P151_CODCIA,       ',
'        nCodEmpresa     => :P151_CODEMPRESA,   ',
'        nIdPoliza       => :P151_IDPOLIZA,     ',
'        lArchivoBinario => lArchivoBinario',
'    );',
'',
'  -- Mensaje OK',
'    apex_application.g_print_success_message := ''Archivo cargado correctamente.'';',
'',
'    -- Limpieza del archivo temporal',
'    delete from apex_application_temp_files',
'     where name = :P151_FILE;',
'',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    apex_error.add_error(',
unistr('      p_message          => ''No se encontr\00F3 el archivo en APEX_APPLICATION_TEMP_FILES. Vuelva a cargarlo.'','),
'      p_display_location => apex_error.c_inline_in_notification',
'    );',
'    RAISE;',
'  WHEN OTHERS THEN',
'    apex_error.add_error(',
'      p_message          => ''Error en carga: '' || SQLERRM,',
'      p_display_location => apex_error.c_inline_in_notification',
'    );',
'    RAISE;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(598491590275013941)
,p_internal_uid=>60115604938358846
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(598492245308013948)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_CALCULA_RFC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  nFilas NUMBER := 0;',
'BEGIN',
'    UPDATE TEMP_LISTADO_ASEGURADOS t',
'        SET t.NumDocIdentificacion =',
'            OC_PERSONA_NATURAL_JURIDICA.NUMERO_TRIBUTARIO_RFC(',
'                t.NombreAseg,',
'                t.ApellidoPaternoAseg,',
'                t.ApellidoMaternoAseg,',
'                t.FechaNacimiento,',
'                ''FISICA''',
'            )',
'    WHERE t.CodCia     = :P151_CODCIA',
'        AND t.CodEmpresa = :P151_CODEMPRESA',
'        AND t.IdPoliza   = :P151_IDPOLIZA',
'        AND t.NumDocIdentificacion IS NULL',
'        AND t.IDASEGURADO IN (',
'            SELECT TO_NUMBER(column_value) FROM TABLE(apex_string.split(:P151_LISTA_ASEGURADOS_SELECCIONADOS, '':'')));',
'',
'    nFilas := SQL%ROWCOUNT;',
'    COMMIT;',
'',
unistr('    apex_application.g_print_success_message := ''Actualizaci\00F3n completada. Filas actualizadas: ''||nFilas||''.'';'),
'',
'    EXCEPTION',
'      WHEN OTHERS THEN',
'        ROLLBACK;',
'        apex_error.add_error(',
'          p_message          => ''Error al actualizar RFC: ''||SQLERRM,',
'          p_display_location => apex_error.c_inline_in_notification',
'        );',
'        RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(598491084509013936)
,p_internal_uid=>60115709838358847
);
