wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(600533335008061431)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Emitir_Endoso_EAD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cReqGenFact VARCHAR2(1);',
'    set_url     VARCHAR2(1000);',
'BEGIN',
'    OC_MANTENIMIENTO_ENDOSOS_ACCIONES.EMITIR_ENDOSO_A_DECLARACION(',
'        nIdPoliza    => :P152_IDPOLIZA,',
'        nIdEndoso    => :P152_IDENDOSO,',
'        cIdsFactura  => :P152_IDS_FACTURA',
'    );',
'',
'    cReqGenFact := OC_MANTENIMIENTO_ENDOSOS_ACCIONES.VALIDA_GENERA_FACT_ELECT(:P152_IDPOLIZA,:P152_IDENDOSO);',
'    IF cReqGenFact = ''S'' THEN',
'            APEX_UTIL.SET_SESSION_STATE(',
'                p_name  => ''P100_IDPOLIZA_BUSQD'',',
'                p_value => :P152_IDPOLIZA',
'            );',
'',
