wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(544512715292556629)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BTN_Cambiar_Fecha'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   CURSOR TransacSiniestros IS ',
'      SELECT CodSubProceso,',
'             TO_NUMBER(VALOR1) nIdSiniestro,',
'             TO_NUMBER(VALOR2) nIdPoliza,',
'             VALOR3 CodCobert,',
'             TO_NUMBER(VALOR4) nNumMod',
'        FROM DETALLE_TRANSACCION',
'       WHERE IdTransaccion = :P154_TRANSACCION',
'         AND VALOR2 IS NOT NULL',
'         AND VALOR3 IS NOT NULL',
'         AND VALOR4 IS NOT NULL;',
'',
'BEGIN',
'',
'   -- =========================',
'   -- TRANSACCION',
'   -- =========================',
'   UPDATE TRANSACCION',
'      SET FechaTransaccion = :P154_NUEVA_FECHA_TRANSACCION',
'    WHERE IdTransaccion = :P154_TRANSACCION;',
'',
'   UPDATE COMPROBANTES_DETALLE',
'      SET FecDetalle = :P154_NUEVA_FECHA_TRANSACCION',
'    WHERE NumComprob IN (',
'          SELECT NumComprob',
'            FROM COMPROBANTES_CONTABLES',
'           WHERE NumTransaccion = :P154_TRANSACCION',
'   );',
'',
'   UPDATE COMPROBANTES_CONTABLES',
'      SET FecComprob = :P154_NUEVA_FECHA_TRANSACCION,',
'          FecSts     = :P154_NUEVA_FECHA_TRANSACCION',
'    WHERE NumTransaccion = :P154_TRANSACCION;',
'',
'   -- =========================',
'   -- SINIESTROS',
'   -- =========================',
'   IF :P154_PROCESO = 6 THEN',
'',
'      FOR i IN TransacSiniestros LOOP',
'',
'         IF i.CodSubProceso = ''EMIRES'' THEN',
'',
'            -- COBERTURA',
'            UPDATE COBERTURA_SINIESTRO_ASEG',
'               SET FecRes = :P154_NUEVA_FECHA_TRANSACCION',
'             WHERE IdTransaccion = :P154_TRANSACCION;',
'',
'            -- OBSERVACION ',
'            BEGIN',
'               UPDATE OBSERVACION_SINIESTRO',
'                  SET FECOBSERV = :P154_NUEVA_FECHA_TRANSACCION',
'                WHERE INSTR(Descripcion,',
'                      ''Emite la Reserva de la Cobertura ''||i.CodCobert||',
'                      '' de la Modificacion ''||i.nNumMod) > 0;',
'',
'               IF SQL%ROWCOUNT = 0 THEN',
'                  BEGIN',
'                     UPDATE OBSERVACION_SINIESTRO',
'                        SET FECOBSERV = :P154_NUEVA_FECHA_TRANSACCION',
'                      WHERE INSTR(Descripcion,''Emite la Reserva'') > 0',
'                        AND INSTR(Descripcion,',
'                             '' de la Modificacion ''||i.nNumMod) > 0;',
'',
'                     IF SQL%ROWCOUNT = 0 THEN',
'                        UPDATE OBSERVACION_SINIESTRO',
'                           SET FECOBSERV = :P154_NUEVA_FECHA_TRANSACCION',
'                         WHERE INSTR(Descripcion,',
'                               ''Emite la Reserva de la Cobertura '') > 0',
'                           AND FECOBSERV = :P154_FECHA_TRANSACCION;',
'                     END IF;',
'',
'                  END;',
'               END IF;',
'',
'            END;',
'',
'         ELSIF i.CodSubProceso = ''APRSIN'' THEN',
'',
'            -- APROBACION',
'            UPDATE APROBACION_ASEG',
'               SET FecPago = :P154_NUEVA_FECHA_TRANSACCION',
'             WHERE IdTransaccion = :P154_TRANSACCION;',
'',
'            -- OBSERVACION ',
'            BEGIN',
'               UPDATE OBSERVACION_SINIESTRO',
'                  SET FECOBSERV = :P154_NUEVA_FECHA_TRANSACCION',
'                WHERE INSTR(Descripcion,',
unistr('                      ''Efect\00FAa el Pago del Siniestro de la Aprobacion No ''||i.CodCobert) > 0;'),
'',
'               IF SQL%ROWCOUNT = 0 THEN',
'                  BEGIN',
'                     UPDATE OBSERVACION_SINIESTRO',
'                        SET FECOBSERV = :P154_NUEVA_FECHA_TRANSACCION',
'                      WHERE INSTR(Descripcion,',
unistr('                            ''Efect\00FAa el Pago del Siniestro de la Aprobacion'') > 0'),
'                        AND FECOBSERV = :P154_FECHA_TRANSACCION;',
'',
'                     IF SQL%ROWCOUNT = 0 THEN',
'                        apex_error.add_error(',
unistr('                           p_message => ''No se encontr\00F3 observaci\00F3n para actualizar APRSIN'','),
'                           p_display_location => apex_error.c_inline_in_notification',
'                        );',
'                     END IF;',
'',
'                  END;',
'               END IF;',
'',
'            END;',
'',
'         END IF;',
'',
'      END LOOP;',
'',
'   END IF;',
'',
'   -- =========================',
'   -- CANCELACION',
'   -- =========================',
'   IF :P154_PROCESO = 2 THEN',
'',
'      UPDATE FACTURAS',
'         SET FecSts = :P154_NUEVA_FECHA_TRANSACCION',
'       WHERE IdTransaccionAnu = :P154_TRANSACCION;',
'',
'   END IF;',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      apex_error.add_error(',
'         p_message => ''Error al actualizar fechas: '' || SQLERRM,',
'         p_display_location => apex_error.c_inline_in_notification',
'      );',
'      RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(544512395586556625)
,p_process_success_message=>unistr('Se modific\00F3 correctamente la fecha de la transacci\00F3n')
,p_internal_uid=>105421018461485106
);
