wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(756743052755128703)
,p_plug_name=>'IG_COBERT_MASTER'
,p_region_name=>'IG_COBERT_MASTER'
,p_parent_plug_id=>wwv_flow_imp.id(756742600810128699)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P155_IDTIPOSEG IN (''GMINDC'',''GMINDI'') THEN',
'return q''~',
'select  CS.CODCOBERT CODCOBERT,',
'        CS.DESCCOBERT,',
'        CS.SUMAASEGURADA SUMAASEGURADA,',
'        CS.PORC_TASA PORC_TASA,',
'        CS.PRIMA_COBERT PRIMA_COBERT,',
'        CS.ORDENIMPRESION,',
'        CASE WHEN CS.COBERTURA_BASICA = ''S'' THEN ',
'            ''<div class="apex-item-single-checkbox">',
'                <input type="checkbox" checked="" tabindex="0" aria-labelledby="R317651355924057180_ig_grid_vc_ctx R317651355924057180_ig_grid_vc_cur">',
'                <span class="u-checkbox" aria-hidden="true"></span>',
'                <span class="u-vh" aria-hidden="true">Activado</span>',
'            </div>''',
'        ELSE ',
'            ''<div class="apex-item-single-checkbox">',
'                <input type="checkbox" tabindex="0" aria-labelledby="R317651355924057180_ig_grid_vc_ctx R317651355924057180_ig_grid_vc_cur">',
'                <span class="u-checkbox" aria-hidden="true"></span>',
'                <span class="u-vh" aria-hidden="true">Desactivado</span>',
'            </div>''',
'        END AS COBERTBASIC_HTML,',
'        0 nSumaAsegCalculada,',
'        -- --------------------------------------------------------------',
'        0 nSalarioMensual,',
'        0 nVecesSalario,',
'        0 nPorcExtraPrima,',
'        0 nMontoExtraPrima,',
'        CS.SumaAsegMinima nSumaAsegMinima,',
'        CS.SumaAsegMaxima nSumaAsegMaxima,',
'        CS.Edad_Minima nEdad_Minima, ',
'        CS.Edad_Maxima nEdad_Maxima,',
'        CS.Edad_Exclusion nEdad_Exclusion,',
'        -- ---------------------------------------------------',
'        CS.SUMAASEGURADA nSumaCotizacion,',
'        -- ----------------',
'        CS.SUMAASEGURADA nSumaAseg,',
'        ''N'' ESTADO_COBERTURA',
'FROM COBERTURAS_DE_SEGUROS CS',
'WHERE CS.IdTipoSeg = :P155_IDTIPOSEG',
'AND CS.PlanCob     = :P155_PLANCOB',
'~'';',
'ELSE',
'return q''~',
'select  CS.CODCOBERT CODCOBERT,',
'        CS.DESCCOBERT,',
'        CS.SUMAASEGURADA SUMAASEGURADA,',
'        CS.PORC_TASA PORC_TASA,',
'        CS.PRIMA_COBERT PRIMA_COBERT,',
'        CS.ORDENIMPRESION,',
'        CASE WHEN CS.COBERTURA_BASICA = ''S'' THEN ',
'            ''<div class="apex-item-single-checkbox">',
'                <input type="checkbox" checked="" tabindex="0" aria-labelledby="R317651355924057180_ig_grid_vc_ctx R317651355924057180_ig_grid_vc_cur">',
'                <span class="u-checkbox" aria-hidden="true"></span>',
'                <span class="u-vh" aria-hidden="true">Activado</span>',
'            </div>''',
'        ELSE ',
'            ''<div class="apex-item-single-checkbox">',
'                <input type="checkbox" tabindex="0" aria-labelledby="R317651355924057180_ig_grid_vc_ctx R317651355924057180_ig_grid_vc_cur">',
'                <span class="u-checkbox" aria-hidden="true"></span>',
'                <span class="u-vh" aria-hidden="true">Desactivado</span>',
'            </div>''',
'        END AS COBERTBASIC_HTML,',
'        NVL(CA.SumaAsegCalculada,CA.SumaAseg_Moneda) nSumaAsegCalculada,',
'        -- --------------------------------------------------------------',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            0',
'        ELSE  NVL(CA.SalarioMensual,0) END nSalarioMensual,',
'        -- NVL(CA.SalarioMensual,0) nSalarioMensual,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            0',
'        ELSE NVL(CA.VecesSalario,0) END nVecesSalario,',
'        -- NVL(CA.VecesSalario,0) nVecesSalario,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            0',
'        ELSE NVL(CA.PorcExtraPrimaDet,0) END nPorcExtraPrima,',
'        -- NVL(CA.PorcExtraPrimaDet,0) nPorcExtraPrima,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            0',
'        ELSE NVL(CA.MontoExtraPrimaDet,0) END nMontoExtraPrima,',
'        -- NVL(CA.MontoExtraPrimaDet,0) nMontoExtraPrima,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            CS.SumaAsegMinima',
'        ELSE NVL(CA.SumaAseg_Minima,CS.SumaAsegMinima) END nSumaAsegMinima, ',
'        -- NVL(CA.SumaAseg_Minima,CS.SumaAsegMinima) nSumaAsegMinima,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            CS.SumaAsegMaxima',
'        ELSE NVL(CA.SumaAseg_Maxima,CS.SumaAsegMaxima) END nSumaAsegMaxima,',
'        -- NVL(CA.SumaAseg_Maxima,CS.SumaAsegMaxima) nSumaAsegMaxima,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            CS.Edad_Minima',
'        ELSE NVL(CA.Edad_Minima,CS.Edad_Minima) END nEdad_Minima,',
'        -- NVL(CA.Edad_Minima,CS.Edad_Minima) nEdad_Minima, ',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            CS.Edad_Maxima',
'        ELSE NVL(CA.Edad_Maxima,CS.Edad_Maxima) END nEdad_Maxima,',
'        -- NVL(CA.Edad_Maxima,CS.Edad_Maxima) nEdad_Maxima,',
'        CASE WHEN CA.CodCobert IS NULL THEN',
'            CS.Edad_Exclusion',
'        ELSE NVL(CA.Edad_Exclusion, CS.Edad_Exclusion) END nEdad_Exclusion,',
'        -- NVL(CA.Edad_Exclusion, CS.Edad_Exclusion) nEdad_Exclusion,',
'        -- ---------------------------------------------------',
'        -- NVL(CA.SumaIngresada,CA.SumaAseg_Moneda) nSumaAseg,',
'        CASE WHEN NVL(CA.SumaAsegCalculada,CA.SumaAseg_Moneda) != 0 THEN',
'            NVL(CA.SumaAsegCalculada,CA.SumaAseg_Moneda)',
'        ELSE',
'            CASE WHEN (NVL(CA.SalarioMensual,0) * NVL(CA.VecesSalario,0) + NVL(CA.SumaIngresada,CA.SumaAseg_Moneda)) < NVL(CA.SumaAseg_Minima,CS.SumaAsegMinima) THEN',
'                    NVL(CA.SumaAseg_Minima,CS.SumaAsegMinima)',
'                WHEN (NVL(CA.SalarioMensual,0) * NVL(CA.VecesSalario,0) + NVL(CA.SumaIngresada,CA.SumaAseg_Moneda)) > NVL(CA.SumaAseg_Maxima,CS.SumaAsegMaxima) THEN',
'                    NVL(CA.SumaAseg_Maxima,CS.SumaAsegMaxima)',
'                ELSE',
'                    NVL(CA.SalarioMensual,0) * NVL(CA.VecesSalario,0) + NVL(CA.SumaIngresada,CA.SumaAseg_Moneda)',
'                END',
'        END nSumaCotizacion,',
'        -- ----------------',
'        CASE WHEN (NVL(CA.SumaIngresada,CA.SumaAseg_Moneda) = 0) AND (NVL(CA.SumaAsegCalculada,CA.SumaAseg_Moneda) = 0) THEN',
'            CS.SUMAASEGURADA',
'        ELSE ',
'            NVL(CA.SumaIngresada,CA.SumaAseg_Moneda)',
'        END nSumaAseg,',
'        CASE WHEN CA.CodCobert IS NULL THEN ''N''',
'            ELSE ''S''',
'        END AS ESTADO_COBERTURA',
'FROM COBERTURAS_DE_SEGUROS CS',
'LEFT JOIN COBERT_ACT CA',
'    ON CA.CodCia       = CS.CodCia',
'    AND CA.IdTipoSeg   = CS.IdTipoSeg',
'    AND CA.PlanCob     = CS.PlanCob',
'    AND CA.CodCobert   = CS.CodCobert',
'    AND CA.CodCia      = 1',
'    AND CA.CodEmpresa  = 1',
'    AND CA.IdPoliza    = :P155_IDPOLIZA',
'    AND CA.IDetPol     = :P155_IDETPOL',
'    AND CA.Cod_Asegurado = :P155_COD_ASEGURADO',
'WHERE CS.IdTipoSeg = :P155_IDTIPOSEG',
'AND CS.PlanCob     = :P155_PLANCOB',
'~'';',
'END IF;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P155_IDTIPOSEG,P155_PLANCOB,P155_IDPOLIZA,P155_IDETPOL,P155_COD_ASEGURADO'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'IG_COBERT_MASTER'
