wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(545524534770168635)
,p_event_id=>wwv_flow_imp.id(545523737146168627)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'SET_VALUES'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT NVL(DeducibleIngresado,0), CuotaPromedio, PrimaPromedio',
'    INTO :P155_DeducibleIngresado, :P155_CuotaPromedio, :P155_PrimaPromedio',
'    FROM COTIZACIONES_COBERT_MASTER CM, DETALLE_POLIZA_COTIZ DP',
'    WHERE CM.CodCia         = DP.CodCia',
'    AND CM.CodEmpresa     = DP.CodEmpresa',
'    AND CM.IdCotizacion   = DP.IdCotizacion',
'    AND CM.IDetCotizacion = DP.IDetCotizacion',
'    AND DP.CodCia         = 1',
'    AND DP.CodEmpresa     = 1',
'    AND DP.IdPoliza       = :P155_IDPOLIZA',
'    AND DP.IDetPol        = :P155_IDETPOL',
'    AND CM.CodCobert      = :P155_CODCOBERT;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            :P155_DeducibleIngresado := 0;',
'            :P155_CuotaPromedio      := 0;',
'            :P155_PrimaPromedio      := 0;',
'END;'))
,p_attribute_02=>'P155_IDPOLIZA,P155_IDETPOL,P155_CODCOBERT'
,p_attribute_03=>'P155_DEDUCIBLEINGRESADO,P155_CUOTAPROMEDIO,P155_PRIMAPROMEDIO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
