wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(546189175291474524)
,p_event_id=>wwv_flow_imp.id(545528389739168673)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var ig = apex.region("IG_COBERT_MASTER").widget();',
'var grid = ig.interactiveGrid("getViews", "grid");',
'var model = grid.model;',
'',
'var valorItem = $v("P155_CODCOBERT");',
'var filaBase = null;',
'',
'// 1. Buscar la fila que coincide',
'model.forEach(function(record) {',
'    if (model.getValue(record, "CODCOBERT") == valorItem) {',
'        filaBase = record;',
'    }',
'});',
'',
unistr('// 2. Si encontr\00F3 la fila, copiar valores'),
'if (filaBase) {',
'',
unistr('    // \00BF Lista de columnas a copiar'),
'    var columnas = [',
'        "NSUMAASEG",',
'        "NSUMACOTIZACION",',
'        "ESTADO_COBERTURA"',
'    ];',
'',
'    model.forEach(function(record) {',
'',
'        // Evitar copiar sobre la misma fila base',
'        if (record !== filaBase) {',
'',
'            columnas.forEach(function(col) {',
'                var valor = model.getValue(filaBase, col);',
'                model.setValue(record, col, valor);',
'            });',
'',
'            model.setValue(record, "ESTADO_COBERTURA", "S");',
'',
'        }',
'    });',
'',
'}'))
);
