'            CODCOBERT:          model.getValue(record, "CODCOBERT"),',
'            NSALARIOMENSUAL:    model.getValue(record, "NSALARIOMENSUAL"),',
'            NVECESSALARIO:      model.getValue(record, "NVECESSALARIO"),',
'            NSUMACOTIZACION:    model.getValue(record, "NSUMACOTIZACION"),',
'            NEDAD_MINIMA:       model.getValue(record, "NEDAD_MINIMA"),',
'            NEDAD_MAXIMA:       model.getValue(record, "NEDAD_MAXIMA"),',
'            NEDAD_EXCLUSION:    model.getValue(record, "NEDAD_EXCLUSION"),',
'            NSUMAASEGMINIMA:    model.getValue(record, "NSUMAASEGMINIMA"),',
'            NSUMAASEGMAXIMA:    model.getValue(record, "NSUMAASEGMAXIMA"),',
'            NSUMAASEG:          model.getValue(record, "NSUMAASEG")',
'        });',
'    }',
'});',
'',
'if (dataArray.length === 0) {',
'    apex.message.alert("No ha Seleccionado Ninguna Cobertura");',
'    return;',
'}',
'',
'if (contadorChecked === 0) {',
unistr('    apex.message.alert("NO ha Seleccionado una Cobertura B\00E1sica");'),
'    return;',
'}',
'',
'if (contadorChecked > 1) {',
unistr('    apex.message.alert("Seleccion\00F3 M\00E1s de una Cobertura B\00E1sica");'),
'    return;',
'}',
'',
'// Guardar en item oculto',
'$s("P155_JSON", JSON.stringify(dataArray));',
'                    ',
'',
unistr('apex.message.confirm("\00BFEsta Seguro de Generar las Coberturas Seleccionadas para el Asegurado No."+ codAsegurado +" ?", function(okPressed) {'),
'',
'    if (okPressed) {',
'',
'        var spinner = apex.util.showSpinner();',
'',
'        apex.server.process("INSERT_COBERT", {',
'            // x01: $v("P155_JSON"),',
'            x02: $v("P155_IDTIPOSEG"),',
'            x03: $v("P155_PLANCOB"),',
