wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(546189774494474530)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_COBERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json CLOB         := :P155_JSON;',
'    cIdTipoSeg          COBERT_ACT_ASEG.IDTIPOSEG%TYPE  := APEX_APPLICATION.g_x02;',
'    cPlanCob            COBERT_ACT_ASEG.PLANCOB%TYPE    := APEX_APPLICATION.g_x03;',
'    nIdPoliza           COBERT_ACT_ASEG.IDPOLIZA%TYPE   := APEX_APPLICATION.g_x04;',
'    nIDetPol            COBERT_ACT_ASEG.IDETPOL%TYPE    := APEX_APPLICATION.g_x05;',
'    nTasaCambio         COBERT_ACT_ASEG.TASA%TYPE       := APEX_APPLICATION.g_x06;',
'    nPorcExtraPrimaDet  COBERT_ACT_ASEG.PorcExtraPrimaDet%TYPE;',
'    nMontoExtraPrimaDet COBERT_ACT_ASEG.MontoExtraPrimaDet%TYPE;',
'    CONCATENACION VARCHAR2(150);',
'BEGIN',
'',
'    IF l_json IS NULL THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''ERROR'');',
'        apex_json.write(''mensaje'', ''No se recibieron datos; '');',
'        apex_json.close_object;',
'        RETURN;',
'    END IF;',
'',
'    FOR rec IN (',
'        SELECT *',
'        FROM JSON_TABLE(l_json, ''$[*]''',
'            COLUMNS (',
'                nPorcExtraPrima     NUMBER          PATH ''$.NPORCEXTRAPRIMA'',',
'                nMontoExtraPrima    NUMBER          PATH ''$.NMONTOEXTRAPRIMA'',',
'                CodCobert           VARCHAR2(50)    PATH ''$.CODCOBERT'',',
'                nSalarioMensual     NUMBER          PATH ''$.NSALARIOMENSUAL'',',
'                nVecesSalario       NUMBER          PATH ''$.NVECESSALARIO'',',
'                nSumaCotizacion     NUMBER          PATH ''$.NSUMACOTIZACION'',',
'                nEdad_Minima        NUMBER          PATH ''$.NEDAD_MINIMA'',',
'                nEdad_Maxima        NUMBER          PATH ''$.NEDAD_MAXIMA'',',
'                nEdad_Exclusion     NUMBER          PATH ''$.NEDAD_EXCLUSION'',',
'                nSumaAsegMinima     NUMBER          PATH ''$.NSUMAASEGMINIMA'',',
'                nSumaAsegMaxima     NUMBER          PATH ''$.NSUMAASEGMAXIMA'',',
'                nSumaAseg           NUMBER          PATH ''$.NSUMAASEG''',
'            )',
'        )',
'    ) LOOP',
'        BEGIN',
'            ',
'            IF NVL(rec.nPorcExtraPrima,0) != 0 OR NVL(rec.nMontoExtraPrima,0) != 0 THEN',
'                nPorcExtraPrimaDet  := NVL(rec.nPorcExtraPrima,0);',
'                nMontoExtraPrimaDet := NVL(rec.nMontoExtraPrima,0);',
'            ELSE',
'                nPorcExtraPrimaDet  := 0;',
'                nMontoExtraPrimaDet := 0;',
'            END IF;',
'',
'            OC_COBERT_ACT.CARGAR_COBERTURAS(1,1,cIdTipoSeg,cPlanCob,nIdPoliza, nIDetPol, ',
'                                               nTasaCambio, rec.CodCobert,',
'                                               NVL(rec.nSumaCotizacion,0), NVL(rec.nSalarioMensual,0),',
'                                               NVL(rec.nVecesSalario,0), rec.nEdad_Minima, ',
'                                               rec.nEdad_Maxima, rec.nEdad_Exclusion,',
'                                               rec.nSumaAsegMinima, rec.nSumaAsegMaxima,',
'                                               nPorcExtraPrimaDet, nMontoExtraPrimaDet, NVL(rec.nSumaAseg,0));',
'            ',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    apex_json.open_object;',
'                    apex_json.write(''status'', ''ERROR'');',
'                    apex_json.write(''mensaje'', ''Error: ''|| '' - '' || SQLERRM);',
'                    apex_json.close_object;',
'                    RETURN;',
'        END;',
'',
'    END LOOP;',
'',
'    OC_DETALLE_POLIZA.ACTUALIZA_VALORES(1,nIdPoliza, nIDetPol, 0);',
'    OC_POLIZAS.ACTUALIZA_VALORES(1,nIdPoliza, 0);',
'',
'    apex_json.open_object;',
'    apex_json.write(''status'', ''OK'');',
'    apex_json.close_object;',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            apex_json.open_object;',
'            apex_json.write(''status'', ''ERROR'');',
unistr('            -- apex_json.write(''mensaje'', ''Error en validaci\00F3n'');'),
'            apex_json.write(''mensaje'', ''Error general: '' || SQLERRM);',
'            apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>107098077663403007
);
end;
