,p_plug_display_sequence=>90
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    IDNCR,',
'    NUMNCR,',
'    FECDEVOL,',
'    CTALIQUIDADORA,',
'    CODMONEDA,',
'    NVL2(',
'        CTALIQUIDADORA,',
'        OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''CTASLIQ'', CTALIQUIDADORA),',
'        NULL',
'    ) AS DESCRIPCION,',
'     CASE ',
'        WHEN CTALIQUIDADORA IS NULL THEN ''NC_SIN_CTA_LIQ''',
'        ELSE NULL',
'    END AS COLOR',
'FROM NOTAS_DE_CREDITO ',
'WHERE IDPOLIZA = :P161_IDPOLIZA',
'AND StsNcr = ''EMI'';'))
