wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(555693941387035157)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GENERA_FACTURA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_zip           BLOB;',
'    v_pdf_blob      BLOB;',
'    v_xml_blob      BLOB;',
'    v_pdfbase64     CLOB;',
'    v_xmlbase64     CLOB;',
'    v_IDAGRUPAENV   NUMBER;',
'    v_filename      VARCHAR2(200);',
'    v_count         NUMBER := 0;',
'    l_warning       INTEGER;',
'    vl_dest         INTEGER := 1;',
'    vl_src          INTEGER := 1;',
'    l_lang_ctx      INTEGER := DBMS_LOB.default_lang_ctx;',
'    v_nomarchivo    VARCHAR2(200);',
'',
'    CURSOR CONSULTA IS',
'        SELECT IDAGRUPAENV,',
'               IDFACTURA,',
'               IDNCR,',
'               DOCTOPDF,',
'               DOCTOXML,',
'               NOMBARCHZIP',
'          FROM FACT_ELECT_DOCTOS_TIMBRE',
'         WHERE (',
'                    IDFACTURA IN (',
'                        SELECT IDFACTURA',
'                          FROM FACTURAS',
'                         WHERE IDPOLIZA = :P165_IDPOLIZA',
'                           AND IDTIMBRE = :P165_ID_TIMBRE',
'                    )',
'                 OR',
'                    IDNCR IN (',
'                        SELECT IDNCR',
'                          FROM NOTAS_DE_CREDITO',
'                         WHERE IDPOLIZA = :P165_IDPOLIZA',
'                           AND IDTIMBRE = :P165_ID_TIMBRE',
'                    )',
'               )',
'           AND DOCTOPDF IS NOT NULL',
'           AND DOCTOXML IS NOT NULL;',
'',
'BEGIN',
'',
'    DBMS_LOB.createtemporary(v_zip, FALSE);',
'',
'    IF :P165_ID_TIMBRE IS NULL AND :P165_IDNCR IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
unistr('            ''No Existen Timbrados para Generar Facturaci\00F3n'''),
'        );',
'    END IF;',
'',
'    FOR factura IN CONSULTA LOOP',
'',
'        vl_dest := 1;',
'        vl_src  := 1;',
'        l_lang_ctx := DBMS_LOB.default_lang_ctx;',
'',
'        v_nomarchivo := factura.NOMBARCHZIP;',
'',
'        DBMS_LOB.createtemporary(v_xml_blob, FALSE);',
'',
'        v_count := v_count + 1;',
'        v_IDAGRUPAENV := factura.IDAGRUPAENV;',
'',
'        IF NVL(factura.IDNCR, 0) > 0 THEN',
'            v_filename := ''NOTA_CREDITO_'' || factura.IDNCR;',
'        ELSE',
'            v_filename := ''FACTURA_'' || factura.IDFACTURA;',
'        END IF;',
'',
'        IF factura.DOCTOPDF IS NOT NULL THEN',
'',
'            v_pdf_blob := APEX_WEB_SERVICE.clobbase642blob(factura.DOCTOPDF);',
'',
'            IF DBMS_LOB.GETLENGTH(v_pdf_blob) >= 0 THEN',
'',
'                APEX_ZIP.ADD_FILE(',
'                    p_zipped_blob => v_zip,',
'                    p_file_name   => v_filename || ''.pdf'',',
'                    p_content     => v_pdf_blob',
'                );',
'',
'            ELSE',
'',
'                v_pdf_blob := NULL;',
'                RAISE_APPLICATION_ERROR(-20002, ''ERROR DOCTOPDF'');',
'',
'            END IF;',
'',
'        ELSE',
'',
'            v_pdf_blob := NULL;',
'            RAISE_APPLICATION_ERROR(-20002, ''ERROR DOCTOPDF_2'');',
'',
'        END IF;',
'',
'        IF factura.DOCTOXML IS NOT NULL THEN',
'',
'            DBMS_LOB.CONVERTTOBLOB(',
'                dest_lob     => v_xml_blob,',
'                src_clob     => factura.DOCTOXML,',
'                amount       => DBMS_LOB.LOBMAXSIZE,',
'                dest_offset  => vl_dest,',
'                src_offset   => vl_src,',
'                blob_csid    => DBMS_LOB.DEFAULT_CSID,',
'                lang_context => l_lang_ctx,',
'                warning      => l_warning',
'            );',
'',
'            IF DBMS_LOB.GETLENGTH(v_xml_blob) >= 0 THEN',
'',
'                APEX_ZIP.ADD_FILE(',
'                    p_zipped_blob => v_zip,',
'                    p_file_name   => v_filename || ''.xml'',',
'                    p_content     => v_xml_blob',
'                );',
'',
'            ELSE',
'',
'                v_xml_blob := NULL;',
'                RAISE_APPLICATION_ERROR(-20002, ''ERROR DOCTOXML'');',
'',
'            END IF;',
'',
'        ELSE',
'',
'            v_xml_blob := NULL;',
'            RAISE_APPLICATION_ERROR(-20002, ''ERROR DOCTOXML_2'');',
'',
'        END IF;',
'',
'        DBMS_LOB.FREETEMPORARY(v_xml_blob);',
'',
'    END LOOP;',
'',
'    IF v_nomarchivo IS NULL THEN',
'',
'        IF :P165_IDNCR IS NOT NULL THEN',
'            v_nomarchivo := ''Doctos_Nota_Credito_'' || :P165_IDPOLIZA ||',
'                    ''_'' ||',
'                    UPPER(:P165_CODPROCESO);',
'        ELSE',
'            v_nomarchivo := ''Doctos_Factura_'' || :P165_IDPOLIZA ||',
'                    ''_'' ||',
'                    UPPER(:P165_CODPROCESO);',
'        END IF;',
'',
'    END IF;',
'',
'    IF DBMS_LOB.GETLENGTH(v_zip) >= 0 THEN',
'',
'        APEX_ZIP.FINISH(',
'            p_zipped_blob => v_zip',
'        );',
'',
'        HTP.INIT;',
'',
'        OWA_UTIL.MIME_HEADER(',
'            ''application/zip'',',
'            FALSE',
'        );',
'',
'        HTP.P(',
'            ''Content-length: '' || DBMS_LOB.GETLENGTH(v_zip)',
'        );',
'',
'        HTP.P(',
'            ''Content-Disposition: attachment; filename="'' ||',
'            v_nomarchivo ||',
'            ''.zip"''',
'        );',
'',
'        OWA_UTIL.HTTP_HEADER_CLOSE;',
'',
'    ELSE',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''ERROR AL GENERAR FACTURACION''',
'        );',
'',
'    END IF;',
'',
'    BEGIN',
'',
'        WPG_DOCLOAD.DOWNLOAD_FILE(v_zip);',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20003,',
'                SQLERRM',
'            );',
'    END;',
'',
'    DBMS_LOB.FREETEMPORARY(v_zip);',
'',
'    APEX_APPLICATION.STOP_APEX_ENGINE;',
'',
'EXCEPTION',
'',
'    WHEN APEX_APPLICATION.E_STOP_APEX_ENGINE THEN',
'        RAISE;',
'',
'    WHEN OTHERS THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20003,',
'            SQLERRM',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(555693005156035148)
,p_process_success_message=>unistr('Facturaci\00F3n Electr\00F3nica Generada Correctamente')
,p_required_patch=>wwv_flow_imp.id(690440983571095281)
,p_internal_uid=>116602244555963634
);
end;
/
