 p_id=>wwv_flow_imp.id(641357471051670269)
,p_plug_name=>'AGENTES_DISTRIBUCION_P'
,p_region_name=>'ig_distribucion'
,p_parent_plug_id=>wwv_flow_imp.id(708198459001432064)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>100
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select CODCIA,',
'       IDPOLIZA,',
'       COD_AGENTE,',
'       CODNIVEL,',
'       COD_AGENTE_DISTR,',
'       PORC_COMISION_AGENTE,',
'       PORC_COM_DISTRIBUIDA,',
'       PORC_COMISION_PLAN,',
'       PORC_COM_PROPORCIONAL,',
'       COD_AGENTE_JEFE,',
'       PORC_COM_POLIZA,',
'       ORIGEN, ',
'       (SELECT A.CODTIPO',
'           FROM AGENTES A',
'           WHERE A.COD_AGENTE = COD_AGENTE_DISTR) TIPO_AGENTE,',
'        ORIGEN || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''IDCONCEP'', ORIGEN) DESC_ORIGEN,',
'       COD_AGENTE_JEFE || '' - '' || OC_AGENTES.NOMBRE_AGENTE(CODCIA, COD_AGENTE_JEFE) DESC_COD_AGENTE_JEFE, ',
'            NVL(',
'         (SELECT DECODE(A.INDEXCLUIRHONORARIO,''N'',''S'',''N'')',
'            FROM AGENTES A',
'           WHERE A.COD_AGENTE = COD_AGENTE_DISTR',
'             AND A.CODTIPO IN (''HONPM'',''HONPF'',''HONORM'',''HONORF'')',
'         ),',
'         ''N'') AS CALC_AUTOM',
'  from AGENTES_DISTRIBUCION_POLIZA_T',
'  WHERE IDPOLIZA = :P190_NUM_POLIZA ',
'AND COD_AGENTE = :P190_COD_AGENTE'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P190_NUM_POLIZA,P190_COD_AGENTE'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'AGENTES_DISTRIBUCION_P'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
