wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(542003802126926807)
,p_event_id=>wwv_flow_imp.id(542003331290926807)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nsuma               number;',
'    vdistribuido        number;',
'    vproporcional       number;',
'    cCodTipoPlan        varchar2(100); ',
'    cDescRamo           varchar2(100);',
'    vComdistribuida     number;',
'    vComproporcional    number;',
'    cexcluiragente      AGENTES.INDEXCLUIRHONORARIO%TYPE;',
'    cCodTipoAge         varchar2(100);',
'BEGIN',
'    OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION_t (nCodCia    => :P190_CODCIA,',
'                                                                 nIdPoliza  => :P190_NUM_POLIZA,',
'                                                                 nCodAgente => :P190_COD_AGENTE',
'                                                                );',
'  /*',
'    select',
'    SUM(NVL(PORC_COM_DISTRIBUIDA,0))',
'    into nsuma',
'    from AGENTES_DISTRIBUCION_POLIZA_t',
'    where IDPOLIZA = :P190_NUM_POLIZA;',
'    ',
'    UPDATE DETALLE_POLIZA',
'    set PORCCOMIS = nsuma',
'    where IDPOLIZA = :P190_NUM_POLIZA ;',
'',
'    SELECT CODTIPO, INDEXCLUIRHONORARIO',
'    INTO cCodTipoAge, cexcluiragente',
'    FROM AGENTES',
'    WHERE COD_AGENTE = :P190_COD_AGENTE_DISTR;',
'    */',
'END;'))
,p_attribute_02=>'P190_CODCIA,P190_NUM_POLIZA,P190_COD_AGENTE,P190_COD_AGENTE_DIST'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(560004262042946469)
,p_event_id=>wwv_flow_imp.id(542003331290926807)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_total_regs        NUMBER;',
'    v_regs_en_cero       NUMBER;',
'    v_primer_rowid       ROWID;',
'',
'BEGIN',
'    OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION_T(nCodCia    => :P190_CODCIA',
'                                                             ,nIdPoliza  => :P190_NUM_POLIZA',
'                                                             ,nCodAgente => :P190_COD_AGENTE);',
'',
'',
'    SELECT COUNT(*),',
'           COUNT(CASE WHEN PORC_COM_DISTRIBUIDA = 0 THEN 1 END)',
'    INTO v_total_regs, v_regs_en_cero',
'    FROM AGENTES_DISTRIBUCION_POLIZA_T',
'    WHERE IDPOLIZA = :P190_NUM_POLIZA',
'    AND COD_AGENTE =: P190_COD_AGENTE;',
'    ',
'    IF v_total_regs = v_regs_en_cero AND v_total_regs > 0 THEN',
'',
'        SELECT ROWID',
'          INTO v_primer_rowid',
'          FROM (',
'                SELECT ROWID',
'                  FROM AGENTES_DISTRIBUCION_POLIZA_T',
'                 WHERE IDPOLIZA = :P190_NUM_POLIZA',
'                 AND COD_AGENTE =: P190_COD_AGENTE',
'',
'                 ORDER BY CODNIVEL DESC, COD_AGENTE DESC',
'               )',
'         WHERE ROWNUM = 1;',
'',
'        UPDATE AGENTES_DISTRIBUCION_POLIZA_T',
'           SET PORC_COM_PROPORCIONAL = 100',
'         WHERE ROWID = v_primer_rowid',
'         AND COD_AGENTE =: P190_COD_AGENTE;',
'',
'    END IF;',
'',
'END; ',
'    '))
,p_attribute_02=>'P190_NUM_POLIZA,P190_CODCIA,P190_COD_AGENTE'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'VAL_OF_ITEM_IN_COND_NOT_EQ_COND2'
,p_server_condition_expr1=>'P190_IVA'
,p_server_condition_expr2=>'S'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(560001248345946439)
,p_event_id=>wwv_flow_imp.id(542003331290926807)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_tipo              VARCHAR2(200);',
'    nTotalProporcional  NUMBER;',
'    nDiferencia         NUMBER;',
'    nsuma               NUMBER;',
'    cCodTipoAg          VARCHAR2(200);',
'    cCodTipoAge         VARCHAR2(200);',
'    cExcluirAgente      VARCHAR2(200);',
'    v_iva               VARCHAR2(200);',
'',
'    v_total_regs        NUMBER;',
'    v_regs_en_cero       NUMBER;',
'    v_primer_rowid       ROWID;',
'BEGIN ',
'',
'    SELECT A.CODTIPO',
'    into v_tipo ',
'    FROM AGENTES A',
'    WHERE A.COD_AGENTE = :P190_COD_AGENTE_DISTR;',
'',
'        BEGIN',
'            SELECT DECODE(A.INDEXCLUIRHONORARIO, ''N'', ''S'', ''N'')',
'              INTO v_iva',
'              FROM AGENTES A',
'             WHERE A.COD_AGENTE = :P190_COD_AGENTE_DISTR',
'               AND A.CODTIPO IN (''HONPM'', ''HONPF'', ''HONORM'', ''HONORF'');',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                v_iva := ''N''; ',
'        END;',
'   iF v_tipo IN (''HONPF'', ''HONPM'', ''UDISPF'', ''UDISPM'', ''HONORF'' , ''HONORM'') THEN',
'            IF :P110_CODTIPOPLAN = ''010'' THEN ',
'                   IF v_iva = ''S'' THEN',
'                    UPDATE AGENTES_DISTRIBUCION_POLIZA_T ADPT',
'                       SET PORC_COM_DISTRIBUIDA   = (PORC_COM_DISTRIBUIDA / 1.16),',
'                           PORC_COM_PROPORCIONAL  = ROUND(',
'                                                        (PORC_COM_DISTRIBUIDA / :P190_PORC_COM_POLIZA) * 100',
'                                                    , 2)',
'                     WHERE ADPT.IDPOLIZA          = :P190_NUM_POLIZA',
'                       AND ADPT.COD_AGENTE_DISTR  = :P190_COD_AGENTE_DISTR;',
'',
'                    COMMIT;',
'                    OC_AGENTES_DISTRIBUCION_POLIZA.AJUSTA_PORCENTAJE_COMISION_T(',
'                        nCodCia    => :P190_CODCIA,',
'                       nIdPoliza  => :P190_NUM_POLIZA,',
'                        nCodAgente => :P190_COD_AGENTE',
'                  );',
'',
'                    SELECT COUNT(*),',
'                           COUNT(CASE WHEN PORC_COM_DISTRIBUIDA = 0 THEN 1 END)',
'                    INTO v_total_regs, v_regs_en_cero',
'                    FROM AGENTES_DISTRIBUCION_POLIZA_T',
'                    WHERE IDPOLIZA = :P190_NUM_POLIZA',
'                    AND COD_AGENTE =: P190_COD_AGENTE;',
'                    ',
'                    IF v_total_regs = v_regs_en_cero AND v_total_regs > 0 THEN',
'',
'                        SELECT ROWID',
'                          INTO v_primer_rowid',
'                          FROM (',
'                                SELECT ROWID',
'                                  FROM AGENTES_DISTRIBUCION_POLIZA_T',
'                                 WHERE IDPOLIZA = :P190_NUM_POLIZA',
'                                 AND COD_AGENTE =: P190_COD_AGENTE',
'',
'                                 ORDER BY CODNIVEL DESC, COD_AGENTE DESC',
'                               )',
'                         WHERE ROWNUM = 1;',
'',
'                        UPDATE AGENTES_DISTRIBUCION_POLIZA_T',
'                           SET PORC_COM_PROPORCIONAL = 100',
'                         WHERE ROWID = v_primer_rowid',
'                         AND COD_AGENTE =: P190_COD_AGENTE;',
'',
'                    END IF;',
'',
'                    ELSE',
'                        NULL; ',
'                    END IF;',
'        ELSE',
'                NULL; ',
'            END IF;',
'    ELSE',
'        NULL; ',
'    END IF;',
'',
'END;',
' '))
,p_attribute_02=>'P190_NUM_POLIZA,P190_COD_AGENTE_DISTR,P190_IVA,P190_CODCIA,P190_COD_AGENTE'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
