wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(542012774737940454)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Aplica_ajuste'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_TextoInicial VARCHAR2(4000);',
'BEGIN',
'	    :P190_COUNT   := 0;',
'    SELECT COUNT(*)',
'    INTO :P190_COUNT',
'    FROM FACTURAS F',
'    WHERE F.CODCIA   = 1',
'    AND F.IDPOLIZA = :P190_NUM_POLIZA',
'    AND F.STSFACT  IN (''EMI'',''PAG'')',
'    AND F.FECVENC  = :P190_FEC_DESDE;',
'    ',
'        IF :P190_COUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-300,''La fecha DESDE no existe'');',
'        END IF; ',
'        --',
'        IF :P190_FEC_DESDE IS NULL THEN',
'            RAISE_APPLICATION_ERROR(-301,''La fecha DESDE es obligatoria'');',
'        ELSE',
'            BEGIN',
'',
'              v_TextoInicial := '''';',
'',
'            FOR R IN (',
'                SELECT ADP.COD_AGENTE_DISTR,',
'                       ADP.PORC_COM_DISTRIBUIDA',
'                  FROM AGENTES_DISTRIBUCION_POLIZA ADP',
'                 WHERE ADP.IDPOLIZA = :P190_NUM_POLIZA',
'                   AND ADP.CODCIA   = 1',
'                 ORDER BY ADP.COD_AGENTE_DISTR',
'            ) LOOP',
'',
'                v_TextoInicial :=',
'                    v_TextoInicial ||',
'                    RPAD(TRIM(TO_CHAR(R.COD_AGENTE_DISTR)),6,'' '') ||',
'                    LPAD(TRIM(TO_CHAR(R.PORC_COM_DISTRIBUIDA)),3,'' '') || ''%'' ||',
'                    CHR(10);',
'',
'            END LOOP;',
'',
'                OC_FACTURAS.CAMBIO_COMISIONES(1, 1, :P190_NUM_POLIZA, :P190_APLICAR_RECIBOS, :P190_FEC_DESDE);',
'',
'',
'            ---ejecuta el enedoso sin valor ',
'            OC_MANTENIMIENTO_BOTONES_POLIZA.ENVIA_ENDOSO_SIN_VALOR (',
'            1, 1,:P190_NUM_POLIZA, :P190_FEC_DESDE, v_TextoInicial',
'            ) ;',
'            ',
'            DELETE AGENTE_POLIZA_T',
'            WHERE IdPoliza = :P190_NUM_POLIZA',
'            AND CodCia   = 1;',
'            --',
'            DELETE AGENTES_DISTRIBUCION_POLIZA_T',
'            WHERE IdPoliza = :P190_NUM_POLIZA',
'            AND CodCia   = 1;',
'           ',
'        EXCEPTION',
'   	      WHEN OTHERS THEN',
'   	            RAISE_APPLICATION_ERROR(-302,''Error al Aplicar Ajuste a Comisiones'');',
'   	        END;',
'        END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(542108353430316790)
,p_internal_uid=>102921077906868931
);
end;
