wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(543643264329188626)
,p_event_id=>wwv_flow_imp.id(543643022380188624)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCodAseg    NUMBER;',
'    cExistAseg  VARCHAR2(1);',
'BEGIN',
'    :P300_SHOW_ERROR       := NULL;',
'    :P300_COD_ASEGURADO    := NULL;',
'',
'    IF :P300_ASEG_COD_ASEGURADO  IS NOT NULL THEN',
'        :P300_COD_ASEGURADO := :P300_ASEG_COD_ASEGURADO;',
'    ELSE',
'        cExistAseg := OC_PERSONA_NATURAL_JURIDICA.EXISTE_PERSONA(',
'            :P300_ASEG_TIPO_DOC_IDENTIFICACION,',
'            :P300_ASEG_NUM_DOC_IDENTIFICACION',
'        );',
'',
'        IF cExistAseg = ''S'' THEN',
'            nCodAseg := OC_ASEGURADO.CODIGO_ASEGURADO(',
'                1, 1,',
'                :P300_ASEG_TIPO_DOC_IDENTIFICACION,',
'                :P300_ASEG_NUM_DOC_IDENTIFICACION',
'            );',
'',
'            IF nCodAseg = 0 THEN',
'                nCodAseg := OC_MANTENIMIENTO_ASEGURADO_EMISION.INSERTAR_ASEGURADO(',
'                    NVL(:P300_CODCIA,1),',
'                    NVL(:P300_CODEMPRESA,1),',
'                    :P300_ASEG_TIPO_DOC_IDENTIFICACION,',
'                    :P300_ASEG_NUM_DOC_IDENTIFICACION,',
'                    :P300_ASEG_CODPARENT',
'                );',
'            END IF;',
'',
'            :P300_COD_ASEGURADO := nCodAseg;',
'        -- ELSE',
