'        IF cCEXISTASEG = ''N'' THEN',
'            :P300_ASEG_CNOMCLIENTE := ''Persona no Existe en Persona Natural Juridica'';',
'            :P300_ASEG_COD_ASEGURADO := '''';',
'        ELSE',
'            IF :P300_ASEG_TIPO_DOC_IDENTIFICACION IS NOT NULL',
'                AND :P300_ASEG_NUM_DOC_IDENTIFICACION IS NOT NULL',
'                THEN',
'                nCodasegurado := OC_ASEGURADO.CODIGO_ASEGURADO(1,1,:P300_ASEG_TIPO_DOC_IDENTIFICACION,:P300_ASEG_NUM_DOC_IDENTIFICACION);',
'                IF nCodasegurado != 0 THEN',
'                    :P300_ASEG_COD_ASEGURADO := nCodasegurado;',
'                END IF;',
'            END IF;',
'',
'           :P300_ASEG_CNOMCLIENTE := OC_PERSONA_NATURAL_JURIDICA.NOMBRE_COMPLETO(:P300_ASEG_TIPO_DOC_IDENTIFICACION,:P300_ASEG_NUM_DOC_IDENTIFICACION);',
'        END IF;',
'    ELSE',
'        :P300_ASEG_COD_ASEGURADO := '''';',
'        :P300_ASEG_CNOMCLIENTE := ''Seleccioanr Tipo de Documento'';',
'    END IF;',
'',
'    :P300_CEXISTASEG := cCEXISTASEG;',
'    :P300_CEXISTASEG_1 := cCEXISTASEG;',
'END;'))
,p_attribute_02=>'P300_ASEG_TIPO_DOC_IDENTIFICACION,P300_ASEG_NUM_DOC_IDENTIFICACION'
,p_attribute_03=>'P300_CEXISTASEG,P300_ASEG_CNOMCLIENTE,P300_ASEG_COD_ASEGURADO'
