wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623770348930241534)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_POST_INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nSumaLocal          DETALLE_POLIZA.Suma_Aseg_Local%TYPE;',
'    nSumaMoneda         DETALLE_POLIZA.Suma_Aseg_Moneda%TYPE;',
'    nPrimaLocal         DETALLE_POLIZA.Prima_Local%TYPE;',
'    nPrimaMoneda        DETALLE_POLIZA.Prima_Moneda%TYPE;',
'    nPorcGtoAdmin       POLIZAS.PorcGtoAdmin%TYPE;',
'    nPorcUtilidad       POLIZAS.PorcUtilidad%TYPE;',
'    nPorcGtoAdqui       POLIZAS.PorcGtoAdqui%TYPE;',
'    nPorcDescuento      PLAN_COBERTURAS.PorcDescuento%TYPE;',
'    nPorcExtraPrima     PLAN_COBERTURAS.PorcExtraPrima%TYPE;',
'    nMontoExtraPrima    PLAN_COBERTURAS.MontoExtraPrima%TYPE;',
'    nFactorAjuste       PLAN_COBERTURAS.FactorAjuste%TYPE;',
'    nMontoDeducible     PLAN_COBERTURAS.MontoDeducible%TYPE;',
'    nFactFormulaDeduc   PLAN_COBERTURAS.FactFormulaDeduc%TYPE;',
'    nDiasVig            POLIZAS.DiasVig%TYPE  := 365;',
'    nHorasVig           POLIZAS.HorasVig%TYPE := 24;',
'    cPrefijoPol         PLAN_COBERTURAS.PrefijoPol%TYPE;',
'    cNumPolUnico        POLIZAS.NumPolUnico%TYPE;',
'',
'    CURSOR REQ_Q IS',
'        SELECT R.CodRequisito',
'          FROM REQUISITOS_SEGUROS S, REQUISITOS R',
'         WHERE R.UsoRequisito IN (''T'',''E'')',
'           AND R.IndOblig     = ''S''',
'           AND S.CodRequisito = R.CodRequisito',
'           AND S.CodCia       = :P300_CODCIA',
'           AND S.CodEmpresa   = :P300_CODEMPRESA',
'           AND S.IdTipoSeg    = :P300_IDTIPOSEG;',
'BEGIN',
'    SELECT SUM(Suma_Aseg_Local), SUM(Suma_Aseg_Moneda),',
'           SUM(Prima_Local), SUM(Prima_Moneda)',
'      INTO nSumaLocal, nSumaMoneda,',
'           nPrimaLocal, nPrimaMoneda',
'      FROM DETALLE_POLIZA',
'     WHERE IdPoliza  = :P300_IDPOLIZA',
'       AND CodCia    = :P300_CODCIA;',
'',
'    UPDATE POLIZAS',
'       SET SumaAseg_Local   = nSumaLocal,',
'           SumaAseg_Moneda  = nSumaMoneda,',
'           PrimaNeta_Local  = nPrimaLocal,',
'           PrimaNeta_Moneda = nPrimaMoneda',
'     WHERE IdPoliza  = :P300_IDPOLIZA',
'       AND CodCia    = :P300_CODCIA;',
'',
'    OC_PROCEDIMIENTOS_MANTENIMIENTO_POLIZA.PROC_INSREQ(:P300_IDPOLIZA, :P300_IDETPOL, :P300_IDTIPOSEG,1);',
'    OC_POLIZAS.INSERTA_CLAUSULAS(:P300_CODCIA, :P300_CODEMPRESA, :P300_IDPOLIZA);',
'',
'    IF :P300_POLIZA_STSPOLIZA = ''EMI'' AND NVL(:P300_STSDETALLE,''SOL'') IN (''SOL'',''XRE'') THEN',
'        OC_AGENTES_DETALLES_POLIZAS.COPIAR_DISTR_INCLUSION_CERT(:P300_CODCIA, :P300_IDPOLIZA, :P300_IDETPOL, :P300_IDTIPOSEG);',
'    END IF;',
'',
'    IF NVL(:P300_POLIZA_NUM_COTIZACION,0) = 0 THEN',
'        SELECT NVL(PorcGtoAdmin,0), NVL(PorcUtilidad,0), NVL(PorcGtoAdqui,0)',
'          INTO nPorcGtoAdmin, nPorcUtilidad, nPorcGtoAdqui',
'          FROM POLIZAS',
'         WHERE IdPoliza  = :P300_IDPOLIZA',
'           AND CodCia    = :P300_CODCIA;',
'',
'        IF NVL(nPorcGtoAdmin,0) = 0 AND NVL(nPorcUtilidad,0) = 0 AND NVL(nPorcGtoAdqui,0) = 0 THEN',
'            BEGIN',
'                SELECT NVL(PorcGtoAdmin,0), NVL(PorcUtilidad,0), NVL(PorcGtoAdqui,0), NVL(PorcDescuento,0),',
'                       NVL(PorcExtraPrima,0), NVL(MontoExtraPrima,0), NVL(FactorAjuste,0), NVL(MontoDeducible,0),',
'                       NVL(FactFormulaDeduc,0)',
'                  INTO nPorcGtoAdmin, nPorcUtilidad, nPorcGtoAdqui,',
'                       nPorcDescuento, nPorcExtraPrima, nMontoExtraPrima,',
'                       nFactorAjuste, nMontoDeducible, nFactFormulaDeduc',
'                  FROM PLAN_COBERTURAS',
'                 WHERE CodCia       = :P300_CODCIA',
'                   AND CodEmpresa   = :P300_CODEMPRESA',
'                   AND IdTipoSeg    = :P300_IDTIPOSEG',
'                   AND PlanCob      = :P300_PLANCOB;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                    nPorcGtoAdmin     := 0;',
'                    nPorcUtilidad     := 0;',
'                    nPorcGtoAdqui     := 0;',
'                    nPorcDescuento    := 0;',
'                    nPorcExtraPrima   := 0;',
'                    nMontoExtraPrima  := 0;',
'                    nFactorAjuste     := 0;',
'                    nMontoDeducible   := 0;',
'                    nFactFormulaDeduc := 0;',
'            END;',
'',
'            UPDATE POLIZAS',
'               SET PorcGtoAdmin     = nPorcGtoAdmin,',
'                   PorcUtilidad     = nPorcUtilidad,',
'                   PorcGtoAdqui     = nPorcGtoAdqui,',
'                   PorcDescuento    = nPorcDescuento,',
'                   FactorAjuste     = nFactorAjuste,',
'                   MontoDeducible   = nMontoDeducible,',
'                   FactFormulaDeduc = nFactFormulaDeduc,',
'                   DiasVig          = nDiasVig,',
'                   HorasVig         = nHorasVig',
'             WHERE IdPoliza  = :P300_IDPOLIZA',
'               AND CodCia    = :P300_CODCIA;',
'        END IF;',
'    END IF;',
'',
'    --Crear asistencias',
'    OC_ASISTENCIAS_DETALLE_POLIZA.CARGAR_ASISTENCIAS(1,1,:P300_IDTIPOSEG,:P300_PLANCOB,:P300_IDPOLIZA,:P300_IDETPOL,:P300_TASA_CAMBIO,''PS'',TO_dATE(:P300_FECFINVIG,''DD/MM/YYYY''),TO_dATE(:P300_FECFINVIG,''DD/MM/YYYY''));',
'',
'    IF GT_FAI_FONDOS_DETALLE_POLIZA.EXISTEN_FONDOS(:P300_CODCIA, :P300_CODEMPRESA, :P300_IDPOLIZA, :P300_IDETPOL, :P300_COD_ASEGURADO) = ''S'' THEN',
'        GT_FAI_FONDOS_DETALLE_POLIZA.ACTUALIZA_APORTE_INICIAL(:P300_CODCIA, :P300_CODEMPRESA, :P300_IDPOLIZA, :P300_IDETPOL, :P300_COD_ASEGURADO);',
'',
'        UPDATE POLIZAS',
'           SET IndManejaFondos = ''S''',
'         WHERE IdPoliza  = :P300_IDPOLIZA',
'           AND CodCia    = :P300_CODCIA;',
'    END IF;',
'',
'    cPrefijoPol := OC_PLAN_COBERTURAS.PREFIJO_POLIZA(:P300_CODCIA, :P300_CODEMPRESA, :P300_IDTIPOSEG, :P300_PLANCOB);',
'',
'    IF cPrefijoPol IS NOT NULL THEN',
'        cNumPolUnico := TRIM(cPrefijoPol) || ''-'' || TRIM(TO_CHAR(:P300_IDPOLIZA)) || ''-'' || TRIM(TO_CHAR(:P300_POLIZA_NUMRENOV,''00''));',
'        UPDATE POLIZAS',
'           SET NumPolUnico = cNumPolUnico',
'         WHERE IdPoliza  = :P300_IDPOLIZA',
'           AND CodCia    = :P300_CODCIA;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(608654338875975500)
,p_internal_uid=>52193142346382849
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(624772548897837887)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_POST_UDATE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nSumaLocal          DETALLE_POLIZA.Suma_Aseg_Local%TYPE;',
'    nSumaMoneda         DETALLE_POLIZA.Suma_Aseg_Moneda%TYPE;',
'    nPrimaLocal         DETALLE_POLIZA.Prima_Local%TYPE;',
