wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(640709666729710368)
,p_name=>'P303_TIPO'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(640588946496261776)
,p_prompt=>'Tipo'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT C.CodClausula, DescClausula',
'     FROM CLAUSULAS_TIPOS_SEGUROS CTS, CLAUSULAS C',
'    WHERE CTS.IdTipoSeg        = :P303_IDETIPOSEG',
'      AND CTS.CodCia           = 1',
'      AND CTS.CodEmpresa       = 1',
'      AND C.CodClausula        = CTS.CodClausula',
'      AND C.CodCia             = CTS.CodCia',
'      AND C.CodEmpresa         = CTS.CodEmpresa',
'      AND ((C.TipoAdministracion = :P303_TIPOADMINISTRACION',
'      AND  C.AplicaTipoAdministracion = ''S'')',
'       OR C.TipoAdministracion IS NULL)',
'      AND C.StsClausula        = ''ACTIVA''',
'    UNION',
'   SELECT C.CodClausula, DescClausula',
'     FROM CLAUSULAS_PLAN_COBERTURAS CTS, CLAUSULAS C',
'    WHERE CTS.PlanCob          = :P303_PLANCOB',
'      AND CTS.IdTipoSeg        = :P303_IDETIPOSEG',
'      AND CTS.CodCia           = 1',
'      AND CTS.CodEmpresa       = 1',
'      AND C.CodClausula        = CTS.CodClausula',
'      AND C.CodCia             = CTS.CodCia',
'      AND C.CodEmpresa         = CTS.CodEmpresa',
'      AND ((C.TipoAdministracion = :P303_TIPOADMINISTRACION',
'      AND  C.AplicaTipoAdministracion = ''S'')',
'       OR C.TipoAdministracion IS NULL)',
'      AND C.StsClausula        = ''ACTIVA''',
'    MINUS',
'   SELECT CP.Tipo_Clausula, SUBSTR(OC_CLAUSULAS.DESCRIPCION(CP.CodCia, 1, CP.Tipo_Clausula),1,200) DescClausula',
'     FROM CLAUSULAS_POLIZA CP',
'    WHERE CP.IdPoliza  = :P303_NUM_POLIZA',
'      AND CP.CodCia    = 1',
'    MINUS',
'   SELECT CD.Tipo_Clausula, SUBSTR(OC_CLAUSULAS.DESCRIPCION(CD.CodCia, 1, CD.Tipo_Clausula),1,200) DescClausula',
'     FROM CLAUSULAS_DETALLE CD',
'    WHERE CD.IdPoliza  = :P303_NUM_POLIZA',
'      AND CD.CodCia    = 1'))
,p_lov_display_null=>'YES'
,p_cSize=>30
,p_field_template=>wwv_flow_imp.id(690615442111096203)
