,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       cap.CODASISTENCIA,',
'       OC_ASISTENCIAS.DESCRIPCION_ASISTENCIA(',
'           cap.CODCIA,',
'           cap.CODEMPRESA,',
'           cap.CODASISTENCIA',
'       ) AS DESCRIPCION_ASISTENCIA',
'  FROM CONFIG_ASISTENCIAS_PLANCOB cap',
' WHERE cap.CODCIA        = 1',
'   AND cap.CODEMPRESA    = 1',
'   AND cap.IDTIPOSEG     = :P307_IDTIPOSEG',
'   AND cap.PLANCOB       = :P307_PLANCOB',
'   AND cap.STSPLANCOBASIST = ''ACTIVA''',
'   AND NOT EXISTS (',
'       SELECT 1',
'         FROM ASISTENCIAS_DETALLE_POLIZA adp',
'        WHERE adp.IDPOLIZA     = :P307_IDPOLIZA',
'          AND adp.IDETPOL      = :P307_IDETPOL',
'          AND adp.CODASISTENCIA = cap.CODASISTENCIA',
'   )',
''))
