,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CrearAsistencias'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_lista apex_t_varchar2;',
'BEGIN',
'',
'    l_lista := apex_string.split(:P307_CODASISTENCIA, '':'');',
'',
'    FOR i IN 1 .. l_lista.COUNT LOOP',
'        INSERT INTO ASISTENCIAS_DETALLE_POLIZA ',
'        (CODCIA,CODEMPRESA,IDPOLIZA,IDETPOL,CODASISTENCIA,CODMONEDA,MONTOASISTLOCAL,MONTOASISTMONEDA,STSASISTENCIA,FECSTS,IDENDOSO)',
'        VALUES (1,1,:P307_IDPOLIZA,:P307_IDETPOL,l_lista(i),''PS'',0,0,''SOLICI'',SYSDATE,0);',
'    END LOOP;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(440812884428266740)
,p_internal_uid=>89531000597363443
);
