,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargarDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'idtiposeg, plancob',
'into',
':P307_IDTIPOSEG,:P307_PLANCOB',
'from detalle_poliza ',
'where idpoliza = :P307_IDPOLIZA ',
'and idetpol = :P307_IDETPOL;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>89528546303363418
);
