'  if :APEX$ROW_STATUS in (''C'',''U'') then',
'    select count(*)',
'      into l_cnt',
'      from filiales',
'     where codfilial  = :CODFILIAL',
'       and codcia     = :CODCIA',
'       and codgrupoec = :CODGRUPOEC',
'       and ( :ROWID is null or rowid <> :ROWID );',
'',
'    if l_cnt > 0 then',
unistr('      return ''Ya existe una filial con el mismo C\00F3digo Filial'';'),
'    end if;',
'  end if;',
'',
'  return null;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_associated_column=>'CODFILIAL'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
