 p_id=>wwv_flow_imp.id(538598244541557043)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_CargaMasiva'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_blob                  blob;',
'    l_filename              varchar2(4000);',
'    l_temp_name             varchar2(4000);',
'    l_filiales_insertadas   number;',
'    l_categorias_insertadas number;',
'    l_total_insertadas      number;',
'begin',
'    select',
'        blob_content,',
'        filename,',
'        name',
'    into',
'        l_blob,',
'        l_filename,',
'        l_temp_name',
'    from apex_application_temp_files',
'    where name = :P308_FILE_LAYOUT;',
'--Carga masiva',
'    OC_MANTENIMIENTO_DETALLE_POLIZA.CARGA_MASIVA_FILIALES_Y_CATEGORIAS(',
'        nCodCia               => :P308_CODCIA,',
'        cCodGrupoEc           => :P308_POLIZA_CODGRUPOEC,',
'        lArchivoBinario       => l_blob,',
'        cNombreArchivo        => l_filename,',
'        cTempFileName         => l_temp_name,',
'        nFilialesInsertadas   => l_filiales_insertadas,',
'        nCategoriasInsertadas => l_categorias_insertadas,',
'        nFilasInsertadas      => l_total_insertadas',
'    );',
'',
'    apex_application.g_print_success_message :=',
'          ''Carga realizada correctamente. ''',
'        || ''Filiales: '' || l_filiales_insertadas',
unistr('        || '' - Categor\00EDas: '' || l_categorias_insertadas'),
'        || '' - Total: '' || l_total_insertadas;',
'',
'exception',
'    when no_data_found then',
unistr('        raise_application_error(-20001, ''No se encontr\00F3 el archivo cargado en P308_FILE_LAYOUT.'');'),
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(538597586001557036)
,p_internal_uid=>99506547710485520
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(539829951771104756)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DESCARGA_FILIAL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lctx    apex_exec.t_context;',
'    lexport apex_data_export.t_export;',
'BEGIN',
'    lctx := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => q''[',
'            SELECT',
unistr('                CAST(NULL AS VARCHAR2(200)) "C\00D3DIGO FILIAL",'),
'                CAST(NULL AS VARCHAR2(200)) "TIPO IDENTIFICACION",',
'                CAST(NULL AS VARCHAR2(200)) "NUM IDENTIFICACION",',
unistr('                CAST(NULL AS VARCHAR2(200)) "DESCRIPCI\00D3N",'),
'                CAST(NULL AS VARCHAR2(200)) "NOMBRE FILIAL"',
'            FROM dual WHERE 1 = 0   -- <- sin filas',
'        ]''',
'    );',
'',
'    lexport := apex_data_export.export(',
'        p_context   => lctx,',
'        p_format    => apex_data_export.c_format_xlsx,',
'        p_file_name => ''LayoutFiliales.xlsx''',
'    );',
'',
'    apex_exec.close(lctx);',
'',
'    apex_data_export.download(p_export => lexport);',
'    apex_application.stop_apex_engine;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'DESCARGA_FILIAL'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>100738254940033233
);
end;
