wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(621092880846210931)
,p_validation_name=>'PORC_DISTRIBUCION_CREATE'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nPorcePart  number;',
'BEGIN',
'    SELECT NVL(SUM(PorcePart),0) ',
'    INTO nPorcePart',
'    FROM BENEFICIARIO',
'    WHERE IdPoliza      = :P310_IDPOLIZA',
'    AND IDetPol         = :P310_IDETPOL',
'    AND Cod_Asegurado   = :P310_COD_ASEGURADO',
'    AND ESTADO = ''ACTIVO'';',
'',
'    nPorcePart := nPorcePart + :P310_PORCEPART;',
'',
'    IF nPorcePart <= 100 THEN ',
'        RETURN TRUE;',
'    ELSE',
'        RETURN FALSE;',
'    END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('El porcentaje de distribuci\00F3n acumulado debe ser igual o menor al 100%.')
,p_always_execute=>'Y'
,p_when_button_pressed=>wwv_flow_imp.id(611468686515771792)
,p_associated_item=>wwv_flow_imp.id(611457001905771783)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
