,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nPorcePart  number;',
'BEGIN',
'    SELECT NVL(SUM(PorcePart),0) ',
'    INTO nPorcePart',
'    FROM BENEFICIARIO',
'    WHERE IdPoliza      = :P310_IDPOLIZA',
'    AND IDetPol         = :P310_IDETPOL',
'    AND Cod_Asegurado   = :P310_COD_ASEGURADO',
'    AND BENEF           != :P310_BENEF;',
'',
'    nPorcePart := nPorcePart + :P310_PORCEPART;',
