'       AND ((C.TipoAdministracion = :P312_TIPOADMINISTRACION',
'             AND C.AplicaTipoAdministracion = ''S'')',
'            OR C.TipoAdministracion IS NULL)',
'       AND C.StsClausula  = ''ACTIVA''',
'',
'    UNION',
'',
'    SELECT C.CodClausula, C.DescClausula',
'      FROM CLAUSULAS_PLAN_COBERTURAS CTS, CLAUSULAS C',
'     WHERE CTS.PlanCob    = :P312_PLANCOB',
'       AND CTS.IdTipoSeg  = :P312_IDTIPOSEG',
'       AND CTS.CodCia     = 1',
'       AND CTS.CodEmpresa = 1',
'       AND C.CodClausula  = CTS.CodClausula',
'       AND C.CodCia       = CTS.CodCia',
'       AND C.CodEmpresa   = CTS.CodEmpresa',
'       AND ((C.TipoAdministracion = :P312_TIPOADMINISTRACION',
'             AND C.AplicaTipoAdministracion = ''S'')',
'            OR C.TipoAdministracion IS NULL)',
'       AND C.StsClausula  = ''ACTIVA''',
'',
'    MINUS',
'',
'    SELECT CP.Tipo_Clausula,',
'           SUBSTR(OC_CLAUSULAS.DESCRIPCION(CP.CodCia,1,CP.Tipo_Clausula),1,200)',
'      FROM CLAUSULAS_POLIZA CP',
'     WHERE CP.IdPoliza = :P312_IDPOLIZA',
'       AND CP.CodCia   = 1',
'',
'    MINUS',
'',
'    SELECT CD.Tipo_Clausula,',
'           SUBSTR(OC_CLAUSULAS.DESCRIPCION(CD.CodCia,1,CD.Tipo_Clausula),1,200)',
'      FROM CLAUSULAS_DETALLE CD',
'     WHERE CD.IdPoliza = :P312_IDPOLIZA',
'       AND CD.CodCia   = 1',
')',
'ORDER BY CodClausula;'))
,p_lov_display_null=>'YES'
,p_cSize=>1050
,p_cMaxlength=>6
