 p_id=>wwv_flow_imp.id(539830147520104758)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DescargaLayoutFilialCategorias'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    lctx    apex_exec.t_context;',
'    lexport apex_data_export.t_export;',
'begin',
'    lctx := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => q''[',
'            select',
'                ''FILIAL''         as "TIPO_REGISTRO",',
'                ''FIL_MX_01''      as "CODIGO_FILIAL",',
'                ''RFC''            as "TIPO_IDENTIFICACION",',
'                ''ZATR550907549''  as "NUM_IDENTIFICACION",',
unistr('                ''Filial Ciudad de M\00E9xico'' as "DESCRIPCION_FILIAL",'),
'                cast(null as varchar2(200)) as "CODIGO_CATEGORIA",',
'                cast(null as varchar2(200)) as "DESCRIPCION_CATEGORIA"',
'            from dual',
'',
'            union all',
'',
'            select',
'                ''FILIAL''         as "TIPO_REGISTRO",',
'                ''FIL_MX_02''      as "CODIGO_FILIAL",',
'                ''RFC''            as "TIPO_IDENTIFICACION",',
'                ''MASJ700521U31''  as "NUM_IDENTIFICACION",',
'                ''Filial Guadalajara'' as "DESCRIPCION_FILIAL",',
'                cast(null as varchar2(200)) as "CODIGO_CATEGORIA",',
'                cast(null as varchar2(200)) as "DESCRIPCION_CATEGORIA"',
'            from dual',
'',
'            union all',
'',
'            select',
'                ''CATEGORIA''      as "TIPO_REGISTRO",',
'                ''FIL_MX_01''      as "CODIGO_FILIAL",',
'                cast(null as varchar2(200)) as "TIPO_IDENTIFICACION",',
'                cast(null as varchar2(200)) as "NUM_IDENTIFICACION",',
'                cast(null as varchar2(200)) as "DESCRIPCION_FILIAL",',
'                ''CAT01''          as "CODIGO_CATEGORIA",',
'                ''Retail''         as "DESCRIPCION_CATEGORIA"',
'            from dual',
'',
'            union all',
'',
'            select',
'                ''CATEGORIA''      as "TIPO_REGISTRO",',
'                ''FIL_MX_01''      as "CODIGO_FILIAL",',
'                cast(null as varchar2(200)) as "TIPO_IDENTIFICACION",',
'                cast(null as varchar2(200)) as "NUM_IDENTIFICACION",',
'                cast(null as varchar2(200)) as "DESCRIPCION_FILIAL",',
'                ''CAT02''          as "CODIGO_CATEGORIA",',
'                ''Mayorista''      as "DESCRIPCION_CATEGORIA"',
'            from dual',
'',
'            union all',
'',
'            select',
'                ''CATEGORIA''      as "TIPO_REGISTRO",',
'                ''FIL_MX_02''      as "CODIGO_FILIAL",',
'                cast(null as varchar2(200)) as "TIPO_IDENTIFICACION",',
'                cast(null as varchar2(200)) as "NUM_IDENTIFICACION",',
'                cast(null as varchar2(200)) as "DESCRIPCION_FILIAL",',
'                ''CAT01''          as "CODIGO_CATEGORIA",',
'                ''General''        as "DESCRIPCION_CATEGORIA"',
'            from dual',
'        ]''',
'    );',
'',
'    lexport := apex_data_export.export(',
'        p_context   => lctx,',
'        p_format    => apex_data_export.c_format_xlsx,',
'        p_file_name => ''Layout_Demo_Filiales_y_Categorias.xlsx''',
'    );',
'',
'    apex_exec.close(lctx);',
'',
'    apex_data_export.download(',
'        p_export => lexport',
'    );',
'',
'    apex_application.stop_apex_engine;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'DESCARGA_FILIAL_CATEGORIA'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
