wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(564564316322173130)
,p_validation_name=>'VAL_FONDO'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   l_valida     VARCHAR2(1);',
'   l_stspoliza  POLIZAS.StsPoliza%TYPE;',
'BEGIN',
'   SELECT StsPoliza',
'     INTO l_stspoliza',
'     FROM POLIZAS',
'    WHERE IDPOLIZA = :P320_IDPOLIZA;',
'',
'    IF l_stspoliza IN (''SOL'', ''XRE'') THEN',
'        l_valida := GT_FAI_FONDOS_DETALLE_POLIZA.VALIDA_FONDOS(:P320_CODCIA,:P320_CODEMPRESA,',
'                     :P320_IDPOLIZA,:P320_IDETPOL,:P320_CODASEGURADO);',
'',
'      IF NVL(l_valida, ''N'') <> ''S'' THEN',
'         RETURN ''No se pudo validar fondos.'';',
'      END IF;',
'   END IF;',
'',
'   RETURN NULL; -- Esto deja continuar y ejecutar el branch',
'',
'EXCEPTION',
'   WHEN NO_DATA_FOUND THEN',
unistr('      RETURN ''No se encontr\00F3 la p\00F3liza '' || :P320_IDPOLIZA || ''.'';'),
'',
'   WHEN OTHERS THEN',
'      RETURN REPLACE(SQLERRM, ''ORA-20200: '', '''');',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(564564129767173128)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
