wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(559370721807621027)
,p_event_id=>wwv_flow_imp.id(554889297960608669)
,p_event_result=>'TRUE'
,p_action_sequence=>60
,p_execute_on_page_init=>'N'
,p_name=>'SVALUE_DETF'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cCodmoneda VARCHAR2(100);',
'BEGIN',
'    SELECT CODEMPLEADO, EDADBENEFICIOS, EDADJUBILACION, ENVIOESTCTA, FECEMISION, FECFINAPLICBONO,',
'           FECFINPREFERENCIAL, FECHACONF, FECTASACAMBIO, IDFONDO, INDAPLICACOBDIFERIDO,',
'           INDAPLICCOBOPCIONAL, INDBONOPOLIZAEMP, INDDESCPRIMACOB, INDFONDOCONTRAT,',
'           INDREVALUAAPORTCOMP, MESESPREFERENCIAL, MTOAPORTEINILOCAL, MTOAPORTEINIMONEDA,',
'           NUMNIP, NUMREFER, NUMSOLICITUD, PLAZOCOMPROMETIDO, PLAZOOBLIGADO, PORCBONOEMP,',
'           PORCFONDO, REGLARETIROS, TASACAMBIOMOV, TASAINTGAR, TASAPREFERENCIAL,',
'           TIPOFONDO, TIPORANGOAPORTES, TIPOTASA',
'      INTO :P320_DETF_CODEMPLEADO, :P320_DETF_EDADBENEFICIOS, :P320_DETF_EDADJUBILACION,',
'           :P320_DETF_ENVIOESTCTA, :P320_DETF_FECEMISION, :P320_DETF_FECFINAPLICBONO,',
'           :P320_DETF_FECFINPREFERENCIAL, :P320_DETF_FECHACONF, :P320_DETF_FECTASACAMBIO,',
'           :P320_DETF_IDFONDO, :P320_DETF_INDAPLICACOBDIFERIDO, :P320_DETF_INDAPLICCOBOPCIONAL,',
'           :P320_DETF_INDBONOPOLIZAEMP, :P320_DETF_INDDESCPRIMACOB, :P320_DETF_INDFONDOCONTRAT,',
'           :P320_DETF_INDREVALUAAPORTCOMP, :P320_DETF_MESESPREFERENCIAL,',
'           :P320_DETF_MTOAPORTEINILOCAL, :P320_DETF_MTOAPORTEINIMONEDA, :P320_DETF_NUMNIP,',
'           :P320_DETF_NUMREFER, :P320_DETF_NUMSOLICITUD, :P320_DETF_PLAZOCOMPROMETIDO,',
'           :P320_DETF_PLAZOOBLIGADO, :P320_DETF_PORCBONOEMP, :P320_DETF_PORCFONDO,',
'           :P320_DETF_REGLARETIROS, :P320_DETF_TASACAMBIOMOV, :P320_DETF_TASAINTGAR,',
'           :P320_DETF_TASAPREFERENCIAL, :P320_DETF_TIPOFONDO, :P320_DETF_TIPORANGOAPORTES,',
'           :P320_DETF_TIPOTASA',
'      FROM FAI_FONDOS_DETALLE_POLIZA',
'     WHERE CODCIA = :P320_CODCIA',
'       AND CODEMPRESA = :P320_CODEMPRESA',
'       AND IDPOLIZA = :P320_IDPOLIZA',
'       AND CODASEGURADO = :P320_CODASEGURADO',
'       AND IDFONDO = :P320_IDFONDO;',
'',
'    :P320_DETFC_CNOMTIPOFONDO := :P320_DETF_TIPOFONDO || '' - '' ||',
'        GT_FAI_TIPOS_DE_FONDOS.DESCRIPCION(:P320_CODCIA, :P320_CODEMPRESA, :P320_DETF_TIPOFONDO);',
'',
'    cCodmoneda := GT_FAI_TIPOS_DE_FONDOS.MONEDA_FONDO(:P320_CODCIA, :P320_CODEMPRESA, :P320_DETF_TIPOFONDO);',
'',
'    :P320_DETFC_CNOMMONEDA := cCodmoneda || '' - '' || OC_MONEDA.DESCRIPCION_MONEDA(cCodmoneda);',
'',
'    :P320_DETFC_CNOMAPORTINI :=',
'        GT_FAI_TIPOS_DE_FONDOS.CODIGO_APORTE_INICIAL(:P320_CODCIA, :P320_CODEMPRESA, :P320_DETF_TIPOFONDO);',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        NULL;',
'    WHEN TOO_MANY_ROWS THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''Se encontr\00F3 m\00E1s de un registro para el fondo indicado.'');'),
'END;'))
,p_attribute_02=>'P320_CODCIA, P320_CODEMPRESA, P320_IDPOLIZA, P320_CODASEGURADO, P320_IDFONDO'
,p_attribute_03=>'P320_DETF_CODEMPLEADO, P320_DETF_EDADBENEFICIOS, P320_DETF_EDADJUBILACION, P320_DETF_ENVIOESTCTA, P320_DETF_FECEMISION, P320_DETF_FECFINAPLICBONO, P320_DETF_FECFINPREFERENCIAL, P320_DETF_FECHACONF, P320_DETF_FECTASACAMBIO, P320_DETF_IDFONDO, P320_DET'
||'F_INDAPLICACOBDIFERIDO, P320_DETF_INDAPLICCOBOPCIONAL, P320_DETF_INDBONOPOLIZAEMP, P320_DETF_INDDESCPRIMACOB, P320_DETF_INDFONDOCONTRAT, P320_DETF_INDREVALUAAPORTCOMP, P320_DETF_MESESPREFERENCIAL, P320_DETF_MTOAPORTEINILOCAL, P320_DETF_MTOAPORTEINIMO'
||'NEDA, P320_DETF_NUMNIP, P320_DETF_NUMREFER, P320_DETF_NUMSOLICITUD, P320_DETF_PLAZOCOMPROMETIDO, P320_DETF_PLAZOOBLIGADO, P320_DETF_PORCBONOEMP, P320_DETF_PORCFONDO, P320_DETF_REGLARETIROS, P320_DETF_TASACAMBIOMOV, P320_DETF_TASAINTGAR, P320_DETF_TAS'
||'APREFERENCIAL, P320_DETF_TIPOFONDO, P320_DETF_TIPORANGOAPORTES, P320_DETF_TIPOTASA, P320_DETFC_CNOMTIPOFONDO, P320_DETFC_CNOMMONEDA, P320_DETFC_CNOMAPORTINI'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_da_action_comment=>unistr('Agregar valores de items de informaci\00F3n de fondos')
);
end;
/
