'           :P320_DETF_INDBONOPOLIZAEMP, :P320_DETF_INDDESCPRIMACOB, :P320_DETF_INDFONDOCONTRAT,',
'           :P320_DETF_INDREVALUAAPORTCOMP, :P320_DETF_MESESPREFERENCIAL,',
'           :P320_DETF_MTOAPORTEINILOCAL, :P320_DETF_MTOAPORTEINIMONEDA, :P320_DETF_NUMNIP,',
'           :P320_DETF_NUMREFER, :P320_DETF_NUMSOLICITUD, :P320_DETF_PLAZOCOMPROMETIDO,',
'           :P320_DETF_PLAZOOBLIGADO, :P320_DETF_PORCBONOEMP, :P320_DETF_PORCFONDO,',
'           :P320_DETF_REGLARETIROS, :P320_DETF_TASACAMBIOMOV, :P320_DETF_TASAINTGAR,',
