wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(551483563742444129)
,p_name=>'P321_TIPOFONDO'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(551480418072444116)
,p_item_source_plug_id=>wwv_flow_imp.id(551480418072444116)
,p_prompt=>'Tipo Fondo'
,p_source=>'TIPOFONDO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'FP.TipoFondo ||''-''||TF.DescFondo D, ',
'FP.TipoFondo R',
'  FROM FAI_TIPOS_FONDOS_PRODUCTOS FP,',
'       DETALLE_POLIZA DP,',
'       FAI_TIPOS_DE_FONDOS TF',
' WHERE TF.CodCia        = FP.CodCia',
'   AND TF.CodEmpresa    = FP.CodEmpresa',
'   AND TF.TipoFondo     = FP.TipoFondo',
'   AND FP.CodCia        = DP.CodCia',
'   AND FP.CodEmpresa    = DP.CodEmpresa',
'   AND FP.IdTipoSeg     = DP.IdTipoSeg',
'   AND FP.PlanCob       = DP.PlanCob',
'   AND DP.CodCia        = :P321_CODCIA',
'   AND DP.CodEmpresa    = :P321_CODEMPRESA',
'   AND DP.IdPoliza      = :P321_IDPOLIZA',
'   AND DP.IDetPol       = :P321_IDETPOL',
'   AND DP.Cod_Asegurado = :P321_CODASEGURADO',
'   AND NOT EXISTS (SELECT 1',
'                    FROM FAI_FONDOS_DETALLE_POLIZA FDP',
'                   WHERE FDP.CodCia       = FP.CodCia',
'                     AND FDP.CodEmpresa   = FP.CodEmpresa',
'                     AND FDP.IdPoliza     = DP.IdPoliza',
'                     AND FDP.IDetPol      = DP.IDetPol',
'                     AND FDP.CodAsegurado = DP.Cod_Asegurado',
'                     AND FDP.TipoFondo    = FP.TipoFondo)'))
,p_lov_display_null=>'YES'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(690616768967096209)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
