wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(552905635732508932)
,p_plug_name=>'IG_COPIA_APORTACIONES'
,p_parent_plug_id=>wwv_flow_imp.id(552905320733508929)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT F1.IdPoliza, F1.IdFondo, F2.IdFondo Fondo_Origen, A.Periodicidad,',
'A.MontoAporteLocal, A.MontoAporte, T.DescFondo, T.ClaseFondo, F1.TipoFondo, ',
'F1.FecTasaCambio, F1.TasaCambioMov ',
'FROM FAI_FONDOS_DETALLE_POLIZA F1, FAI_FONDOS_DETALLE_POLIZA F2, ',
'FAI_CONFIG_APORTE_FONDO A, FAI_TIPOS_DE_FONDOS T ',
'WHERE T.TipoFondo = F1.TipoFondo AND F2.IdFondo = A.IdFondo ',
'AND F1.IdPoliza = F2.IdPoliza AND NOT EXISTS ',
'(SELECT 1 FROM FAI_CONFIG_APORTE_FONDO WHERE IdFondo = F1.IdFondo)',
'AND F2.IdFondo = :P323_FONDO_ORIGEN'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P323_FONDO_ORIGEN'
