,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT STSCONFAPORTES || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSCONFAPORTES) DESC_STSCONFAPORTES',
'FROM FAI_CONFIG_APORTE_FONDO',
