wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(567548839612527336)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'BeforeHeader'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    :P323_NOMASEGURADO  :=  :P323_CODASEGURADO ||'' - ''|| OC_ASEGURADO.NOMBRE_ASEGURADO(1,1, :P323_CODASEGURADO);',
' ',
'    BEGIN',
'        SELECT CODTIPOAPORTE,',
'               MONTOAPORTE,',
'               MONTOAPORTELOCAL,',
'               PERIODICIDAD,',
'               INDRECORDATORIO,',
'               STSCONFAPORTES,',
'               FECSTATUS,',
'               DECODE(',
'                   CODTIPOAPORTE,',
'                   NULL, NULL,',
'                   CODTIPOAPORTE ||'' - ''|| OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPOAPOR'', CODTIPOAPORTE)',
'               ),',
'               DECODE(',
'                   PERIODICIDAD,',
'                   NULL, NULL,',
'                   PERIODICIDAD ||'' - ''|| OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''FRECINTE'', PERIODICIDAD)',
'               ),',
'               DECODE(',
'                   STSCONFAPORTES,',
'                   NULL, NULL,',
'                   STSCONFAPORTES ||'' - ''|| OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', STSCONFAPORTES)',
'               )',
'          INTO :P323_AF_CODTIPOAPORTE,',
'               :P323_AF_MONTOAPORTE,',
'               :P323_AF_MONTOAPORTELOCAL,',
'               :P323_AF_PERIODICIDAD,',
'               :P323_AF_INDRECORDATORIO,',
'               :P323_AF_STSCONFAPORTES,',
'               :P323_AF_FECSTATUS,',
'               :P323_AF_DESCTIPOAPORTE,',
'               :P323_AF_DESCPERIODICIDAD,',
'               :P323_AF_DESCSTSCONFAPORT',
'          FROM FAI_CONFIG_APORTE_FONDO',
'         WHERE CODCIA       = :P323_CODCIA',
'           AND CODEMPRESA   = :P323_CODEMPRESA',
'           AND IDPOLIZA     = :P323_IDPOLIZA',
'           AND IDETPOL      = :P323_IDETPOL',
'           AND CODASEGURADO = :P323_CODASEGURADO',
'           AND IDFONDO      = :P323_IDFONDO',
'           AND ROWNUM       = 1;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            :P323_AF_CODTIPOAPORTE    := NULL;',
'            :P323_AF_MONTOAPORTE      := NULL;',
'            :P323_AF_MONTOAPORTELOCAL := NULL;',
'            :P323_AF_PERIODICIDAD     := NULL;',
'            :P323_AF_INDRECORDATORIO  := NULL;',
'            :P323_AF_STSCONFAPORTES   := NULL;',
'            :P323_AF_FECSTATUS        := NULL;',
'            :P323_AF_DESCTIPOAPORTE   := NULL;',
'            :P323_AF_DESCPERIODICIDAD := NULL;',
'            :P323_AF_DESCSTSCONFAPORT := NULL;',
'    END;',
'',
'    BEGIN',
'        SELECT F.FECTASACAMBIO,',
'               F.TASACAMBIOMOV',
'          INTO :P323_AF_FECTASACAMBIO,',
'               :P323_AF_TASACAMBIO',
'          FROM FAI_FONDOS_DETALLE_POLIZA F',
'         WHERE CODCIA       = :P323_CODCIA',
'           AND CODEMPRESA   = :P323_CODEMPRESA',
'           AND IDPOLIZA     = :P323_IDPOLIZA',
'           AND IDETPOL      = :P323_IDETPOL',
'           AND CODASEGURADO = :P323_CODASEGURADO',
'           AND IDFONDO      = :P323_IDFONDO;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            :P323_AF_FECTASACAMBIO := NULL;',
'            :P323_AF_TASACAMBIO    := NULL;',
'    END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>128457142781455813
);
end;
