'    :P327_SALDO_FECMOV          := :P327_FECEFECTIVA;',
'',
'    :P327_SALDOS_NPRESTAMO      := GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(:P327_CODCIA,:P327_CODEMPRESA,:P327_NUMPRESTAMO,''CAPPTM'');',
'    :P327_SALDOS_INTERESESVEN   := GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(:P327_CODCIA,:P327_CODEMPRESA,:P327_NUMPRESTAMO,''INTVEN'');',
'    :P327_SALDOS_TERESESANT     := GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(:P327_CODCIA,:P327_CODEMPRESA,:P327_NUMPRESTAMO,''INTANT'');',
'    :P327_SALDOS_ABONOS          := GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(:P327_CODCIA,:P327_CODEMPRESA,:P327_NUMPRESTAMO,''T'');',
'',
'    :P327_SALDOS_CAPI           := :P327_SALDOS_NUMPRESTAMO - :P327_SALDOS_ABONOS;',
'    :P327_SALDOS_TOTAL          := :P327_SALDOS_CAPI - :P327_SALDOS_INTERESESVEN;',
'',
'END;',
''))
