 p_id=>wwv_flow_imp.id(553493625847067862)
,p_event_id=>wwv_flow_imp.id(553493204372067858)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nPrestamo      NUMBER;',
'    nInteresesVen  NUMBER;',
'    nInteresesAnt  NUMBER;',
'    nAbonos        NUMBER;',
'BEGIN',
'    SELECT ',
'        SUM(NVL(GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(CodCia, CodEmpresa, NumPrestamo, ''CAPPTM''),0)),',
'        SUM(NVL(GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(CodCia, CodEmpresa, NumPrestamo, ''INTVEN''),0)),',
'        SUM(NVL(GT_FAI_PRESTAMOS_MOV.MONTO_MOVIMIENTO(CodCia, CodEmpresa, NumPrestamo, ''INTANT''),0)),',
'        SUM(NVL(GT_FAI_PRESTAMOS_MOV.MONTO_ABONOS(CodCia, CodEmpresa, NumPrestamo, ''T''),0))',
'    INTO ',
'        nPrestamo,nInteresesVen,nInteresesAnt,nAbonos',
'    FROM FAI_PRESTAMOS',
'    WHERE StsPrestamo = ''ACTIVO''',
'      AND CodAsegurado = :P327_ASEGURADO_CTRL_LP;',
'',
'    :P327_SALDOS_NPRESTAMO    := NVL(nPrestamo,0);',
'    :P327_SALDOS_INTERESESVEN := NVL(nInteresesVen,0);',
'    :P327_SALDOS_TERESESANT   := NVL(nInteresesAnt,0);',
'    :P327_SALDOS_ABONOS       := NVL(nAbonos,0);',
'',
unistr('    -- C\00E1lculos finales'),
'    :P327_SALDOS_CAPI  := :P327_SALDOS_NPRESTAMO - :P327_SALDOS_ABONOS;',
'    :P327_SALDOS_TOTAL := :P327_SALDOS_CAPI - :P327_SALDOS_INTERESESVEN;',
'',
'END;',
''))
,p_attribute_02=>'P327_ASEGURADO_LP,P327_ASEGURADO_CTRL_LP'
,p_attribute_03=>'P327_SALDOS_NPRESTAMO, P327_SALDOS_INTERESESVEN, P327_SALDOS_TERESESANT, P327_SALDOS_ABONOS, P327_SALDOS_CAPI, P327_SALDOS_TOTAL'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
