,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       c.CODCOBERT || '' - '' || c.DESCCOBERT AS d,',
'       c.CODCOBERT AS r',
'FROM COBERTURAS_DE_SEGUROS c',
'WHERE c.IDTIPOSEG = :P500_IDTIPOSEG',
'  AND c.PLANCOB   = :P500_PLANCOB',
'  AND (',
'        :P500_ROWID IS NOT NULL',
'        OR NOT EXISTS (',
'            SELECT 1',
'            FROM COBERT_ACT ca',
'            WHERE ca.CODCOBERT = c.CODCOBERT',
'              AND ca.IDPOLIZA  = :P500_IDPOLIZA',
'              AND ca.IDETPOL   = :P500_IDETPOL',
'        )',
'      )',
'ORDER BY 1;',
''))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(690616768967096209)
