wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(722582982499659004)
,p_plug_name=>'IG_FACTURAS'
,p_region_name=>'IG_FACTURAS'
,p_parent_plug_id=>wwv_flow_imp.id(722582180848658996)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>100
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'--Valores Visualizados en Grid',
'F.IDFACTURA,',
'F.NUMCUOTA,',
'F.NUMFACT,',
'F.COD_MONEDA,',
'F.FECVENC,',
'F.FECFINVIG,',
'F.STSFACT,',
'F.MONTO_FACT_LOCAL,',
'F.MTOCOMISI_LOCAL,',
'',
'--Valores en pagina ',
'F.IDPOLIZA,',
'F.IDETPOL,',
'F.IDENDOSO,',
'F.NUMPRESTAMO,		',
'F.MONTOPRIMACOMPMONEDA,',
'F.TASA_CAMBIO,',
'F.MONTOPRIMACOMPLOCAL,',
'',
'--Color de estado',
'DECODE(',
'    F.STSFACT,      ',
'    ''EMI'', ''VA_EMITIDA'',',
'    ''ANU'', ''VA_ANULADO'',',
'    ''SUS'', ''VA_SUSPENDIDA'',',
'    ''PAG'', ''VA_PAGADO'',',
'    ''PRE'', ''VA_SOLICITUD'',',
'    NULL)  AS COLOR',
'FROM FACTURAS F WHERE 1 = 1',
'AND (:P600_BUSQ_IDFACTURA   IS NULL OR F.IdFactura  = :P600_BUSQ_IDFACTURA)',
'AND (:P600_BUSQ_CRECIBOPAGO IS NULL OR F.ReciboPago = :P600_BUSQ_CRECIBOPAGO)',
'AND (:P600_BUSQ_IDPOLIZA    IS NULL OR F.IdPoliza   = :P600_BUSQ_IDPOLIZA)',
'AND (:P600_BUSQ_IDETPOL     IS NULL OR F.IDetPol    = :P600_BUSQ_IDETPOL)',
'AND (:P600_BUSQ_IDENDOSO    IS NULL OR F.IdEndoso   = :P600_BUSQ_IDENDOSO)',
'AND (:P600_BUSQ_FECANUL     IS NULL OR TRUNC(F.FecAnul) = TO_DATE(:P600_BUSQ_FECANUL,''DD/MM/YYYY''))',
'AND (:P600_BUSQ_STSFACT     IS NULL OR F.StsFact IN (',
'        SELECT column_value FROM TABLE(apex_string.split(:P600_BUSQ_STSFACT, '':''))))',
'AND (:P600_BUSQ_FECVENC     IS NULL OR TRUNC(F.FecVenc) = TO_DATE(:P600_BUSQ_FECVENC,''DD/MM/YYYY''))        '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P600_BUSQ_IDFACTURA, P600_BUSQ_CRECIBOPAGO, P600_BUSQ_IDPOLIZA, P600_BUSQ_IDETPOL, P600_BUSQ_IDENDOSO, P600_BUSQ_FECANUL, P600_BUSQ_STSFACT, P600_BUSQ_FECVENC, P600_BUSQ_CODCLIENTE'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'IG_FACTURAS'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
