,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DF.CODCPTO',
'      ,DF.CODCPTO || '' - '' || OC_CATALOGO_DE_CONCEPTOS.DESCRIPCION_CONCEPTO(1, CODCPTO) DESC_CODCPTO',
'      ,DF.MONTO_DET_LOCAL',
'      ,DF.MONTO_DET_MONEDA',
'      ,DF.INDCPTOPRIMA',
'      ,DF.SALDO_DET_LOCAL',
'      ,DF.SALDO_DET_MONEDA',
'      ,DF.MTOORIGDETLOCAL',
'      ,DF.MTOORIGDETMONEDA',
'      ,DF.FECPAGOSERVICIO',
'      ,DF.INDPAGOSERVICIO',
'      ,DF.CODPROVEEDOR',
'      ,C.IndCptoServicio',
'FROM DETALLE_FACTURAS DF',
'INNER JOIN CATALOGO_DE_CONCEPTOS C ON C.CODCONCEPTO = DF.CODCPTO',
'WHERE IDFACTURA = :P600_RP_IDFACTURA;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P600_RP_IDFACTURA'
