wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(563781687364540672)
,p_event_id=>wwv_flow_imp.id(557203063484832350)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'ESSC_SetItemDescription'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   :P601_CDESCFORMPAGO := NULL;',
'   :P601_CDESCOBRADOR  := NULL;',
'   :P601_CDESCENTPAGO  := NULL;',
'',
'   SELECT NULLIF(',
'             OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''FORMPAGO'', F.FormPago),',
'             ''Invalida''',
'          ),',
'          (',
'             SELECT P.Nombre || '' '' || P.Apellido',
'               FROM COBRADORES C',
'               JOIN PERSONA_NATURAL_JURIDICA P',
'                 ON P.Tipo_Doc_Identificacion = C.Tipo_Doc_Identificacion',
'                AND P.Num_Doc_Identificacion  = C.Num_Doc_Identificacion',
'              WHERE C.CodCobrador = F.CodCobrador',
'                AND C.CodCia      = F.CodCia',
'          ),',
'          NULLIF(',
'             OC_ENTIDAD_FINANCIERA.DESCRIPCION(F.CodCia, F.EntPago),',
'             ''ENTIDAD FINANCIERA NO EXISTE''',
'          )',
'     INTO :P601_CDESCFORMPAGO,',
'          :P601_CDESCOBRADOR,',
'          :P601_CDESCENTPAGO',
'     FROM FACTURAS F',
'    WHERE F.IdFactura = :P601_IDFACTURA;',
'',
'EXCEPTION',
'   WHEN NO_DATA_FOUND THEN',
'      :P601_CDESCFORMPAGO := NULL;',
'      :P601_CDESCOBRADOR  := NULL;',
'      :P601_CDESCENTPAGO  := NULL;',
'END;'))
,p_attribute_02=>'P601_IDFACTURA'
,p_attribute_03=>'P601_CDESCFORMPAGO, P601_CDESCOBRADOR, P601_CDESCENTPAGO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
