 p_id=>wwv_flow_imp.id(724124380959921626)
,p_plug_name=>'IG_NOTAS_DE_CREDITO'
,p_region_name=>'IG_NOTAS_DE_CREDITO'
,p_parent_plug_id=>wwv_flow_imp.id(724123106120921613)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'--Datos Visualizados',
'IDNCR',
',NUMNCR',
unistr(',ID_A\00D1O_POLIZA'),
',CODMONEDA',
',FECDEVOL',
',MONTO_NCR_LOCAL',
',MTOCOMISI_LOCAL',
',NUMPRESTAMO ',
'--Datos usados',
',IDPOLIZA',
',IDETPOL',
',IDENDOSO',
',CODCLIENTE',
',STSNCR',
'--Color de estado',
',DECODE(',
'    STSNCR,      ',
'    ''EMI'', ''VA_EMITIDA'',',
'    ''ANU'', ''VA_ANULADO'',',
'    ''SUS'', ''VA_SUSPENDIDA'',',
'    ''PAG'', ''VA_PAGADO'',',
'    ''PRE'', ''VA_SOLICITUD'',',
'    ''APL'', ''VA_APLICADA'',',
'    NULL)  AS COLOR',
'FROM NOTAS_DE_CREDITO',
'WHERE 1=1',
'AND (:P700_BUSQ_IDNCR IS NULL OR IDNCR = :P700_BUSQ_IDNCR)',
'AND (:P700_BUSQ_IDPOLIZA IS NULL OR IDPOLIZA = :P700_BUSQ_IDPOLIZA)',
'AND (:P700_BUSQ_NUMNCR IS NULL OR NUMNCR = :P700_BUSQ_NUMNCR)',
'AND (:P700_BUSQ_IDENDOSO IS NULL OR IDENDOSO = :P700_BUSQ_IDENDOSO)',
'AND (:P700_BUSQ_CODCLIENTE IS NULL OR CODCLIENTE = :P700_BUSQ_CODCLIENTE)',
'AND (:P700_BUSQ_STSNCR IS NULL OR STSNCR IN (',
'        SELECT column_value',
'        FROM TABLE(apex_string.split(:P700_BUSQ_STSNCR, '':''))',
'))',
'AND (:P700_BUSQ_FECDEVOL IS NULL OR TRUNC(FECDEVOL) = TO_DATE(:P700_BUSQ_FECDEVOL, ''DD/MM/YYYY''))',
'AND (:P700_BUSQ_FECANUL IS NULL OR TRUNC(FECANUL) = TO_DATE(:P700_BUSQ_FECANUL, ''DD/MM/YYYY''))'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P700_BUSQ_IDNCR,P700_BUSQ_IDPOLIZA,P700_BUSQ_NUMNCR,P700_BUSQ_IDENDOSO,P700_BUSQ_CODCLIENTE,P700_BUSQ_STSNCR,P700_BUSQ_FECDEVOL,P700_BUSQ_FECANUL'
,p_prn_content_disposition=>'ATTACHMENT'
