,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    OC_NOTAS_DE_CREDITO.REVERTIR_APLICACION(:P100_CODCIA,:P100_CODEMPRESA,:P100_IDNCR);',
'    COMMIT;',
'',
