,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_NCR_Rehabilitar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    OC_MANTENIMIENTO_NOTAS_DE_CREDITO.REHABILITAR_NOTA_CREDITO(',
'        in_nCodCia     => :P100_CODCIA,',
