wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(557541457873779842)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P700_NOTAS_DE_CREDITO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin ',
'/*CUENTA NOTAS */',
'    select  COUNT (IDNCR)',
'    INTO :P700_NOTAS_DE_CREDITO',
'    FROM NOTAS_DE_CREDITO',
'WHERE 1=1',
'AND (:P700_BUSQ_IDNCR IS NULL OR IDNCR = :P700_BUSQ_IDNCR)',
'AND (:P700_BUSQ_IDPOLIZA IS NULL OR IDPOLIZA = :P700_BUSQ_IDPOLIZA)',
'AND (:P700_BUSQ_NUMNCR IS NULL OR NUMNCR = :P700_BUSQ_NUMNCR)',
'AND (:P700_BUSQ_IDENDOSO IS NULL OR IDENDOSO = :P700_BUSQ_IDENDOSO)',
'AND (:P700_BUSQ_CODCLIENTE IS NULL OR CODCLIENTE = :P700_BUSQ_CODCLIENTE)',
'AND (:P700_BUSQ_STSNCR IS NULL OR STSNCR IN (',
'        SELECT column_value',
'        FROM TABLE(apex_string.split(:P700_BUSQ_STSNCR, '':''))',
'))',
'AND (:P700_BUSQ_FECDEVOL IS NULL OR TRUNC(FECDEVOL) = TO_DATE(:P700_BUSQ_FECDEVOL, ''DD/MM/YYYY''))',
'AND (:P700_BUSQ_FECANUL IS NULL OR TRUNC(FECANUL) = TO_DATE(:P700_BUSQ_FECANUL, ''DD/MM/YYYY''));',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>118449761042708319
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(556186963651953825)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AJAX_ESTADO_BTN_NOTAS_CREDITO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lJsonBotones    CLOB;',
'BEGIN',
'    lJsonBotones := OC_MANTENIMIENTO_NOTAS_DE_CREDITO.ESTADOS_BTN_NOTAS_CREDITO(',
'        :P700_IDNCR',
'    );',
'',
'    HTP.P(lJsonBotones);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>117095266820882302
);
