wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(606005815333192700)
,p_plug_name=>'COMISIONES'
,p_region_name=>'IG_COMISIONES'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>90
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT C.IDPOLIZA',
'      ,C.COD_AGENTE',
'      ,C.COD_AGENTE || '' - '' || OC_AGENTES.NOMBRE_AGENTE(1, C.COD_AGENTE) DESC_COD_AGENTE',
'      ,C.IDCOMISION',
'      ,C.COMISION_MONEDA',
'      ,C.TASA_CAMBIO',
'      ,C.COMISION_LOCAL',
'      ,C.FEC_GENERACION',
'      ,C.OBSERVACION',
'      ,C.IDNOMINA',
'      ,C.ESTADO',
'      ,C.IDETPOL',
'      --,ESTADO || '' - '' ||  OC_AGENTES.NOMBRE_AGENTE(1, ESTADO) DESC_ESTADO',
'      ,C.FEC_ESTADO',
'      ,C.NUM_RECIBO',
'      ,C.FEC_LIQUIDACION',
'      ,C.USUARIO_GENERO',
'      ,C.USUARIO_GENERO || '' - '' || OC_GENERALES.FUN_NOMBREUSUARIO(1, C.USUARIO_GENERO) DESC_USUARIO_GENERO',
'      ,C.ORIGEN',
'      ,C.ORIGEN || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''IDCONCEP'', C.ORIGEN) DESC_ORIGEN',
'      ,AD.PORC_COM_DISTRIBUIDA',
'      ,NVL(F.IDENDOSO, NC.IDENDOSO) AS IDENDOSO',
'      ,CASE',
'           WHEN F.STSFACT = ''ANU''',
'             OR NC.STSNCR = ''ANU''',
'           THEN ''VA_ANULADO''',
'       END AS COLOR',
'FROM COMISIONES C',
'LEFT JOIN AGENTES_DISTRIBUCION_POLIZA AD ON C.IDPOLIZA = AD.IDPOLIZA',
'AND C.COD_AGENTE = AD.COD_AGENTE_DISTR',
'LEFT JOIN FACTURAS F',
'    ON C.IDFACTURA = F.IDFACTURA',
'LEFT JOIN NOTAS_DE_CREDITO NC',
'    ON C.IDNCR = NC.IDNCR',
' WHERE C.IDPOLIZA = :P702_NUM_POLIZA',
'    AND (',
'          C.IDFACTURA = :P702_NUM_RECIBO',
'       OR C.IDNCR = :P702_NOTA_CREDITO',
'    );'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P702_NUM_POLIZA,P702_NUM_RECIBO,P702_NOTA_CREDITO'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
