 p_id=>wwv_flow_imp.id(549036313091997537)
,p_validation_name=>'BTN_Genera_Detalle'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   nCantDet NUMBER;',
'BEGIN',
'   SELECT COUNT(*)',
'     INTO nCantDet',
'     FROM DETALLE_COMISION',
'    WHERE CodCia     = :P702_CODCIA',
'      AND IdComision = :P702_ID_COMISI;',
'',
'   IF NVL(nCantDet,0) = 0 AND :P702_ESTADO != ''LIQ'' THEN',
'      RETURN TRUE;',
'   ELSE',
'      RETURN FALSE;',
'   END IF;',
'',
'   EXCEPTION ',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN FALSE;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('No se puede generar la comisi\00F3n porque ya existen detalles o ya est\00E1n liquidadas')
