'    var primeraFila = document.querySelector("#" + gridId + " .a-GV-row td");',
'    if (primeraFila) {',
'        primeraFila.click();',
'       //console.log("Registro seleccionado en " + igId);',
'    } else {',
'        //console.log("Fila no encontrada en " + igId + ", reintentando...");',
'        setTimeout(function () { seleccionarPrimerRegistro(igId, gridId); }, 300);',
'    }',
