'apex.region("IG_COMISIONES").widget().on("apexafterrefresh", function () {',
'    setTimeout(function () { seleccionarPrimerRegistro("IG_COMISIONES", "IG_COMISIONES_ig_grid_vc"); }, 300);',
'});',
'setTimeout(function () { ',
'    seleccionarPrimerRegistro("IG_COMISIONES", "IG_COMISIONES_ig_grid_vc"); ',
'    }, ',
'400);',
''))
);
