,p_name=>'EJSC_VAL_CTALIQUIDADORA'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var ig$ = apex.region("IG_NOTAS_DE_CREDITO").widget();',
'var view = ig$.interactiveGrid("getViews", "grid");',
'var model = view.model;',
'var selected = view.getSelectedRecords();',
'',
'selected.forEach(function(rec) {',
'    var cta = model.getValue(rec, "CTALIQUIDADORA");',
'',
'    if (!cta) {',
'        // Desmarcar fila',
'        view.setSelectedRecords(',
'            view.getSelectedRecords().filter(r => r !== rec)',
'        );',
'',
'        // Mensaje',
'        apex.message.showErrors([',
'            {',
'                type: "error",',
'                location: "page",',
'                message: "Debe Asignar la Cuenta Liquidadora para Marcarla para Aplicar",',
'                unsafe: false',
'            }',
'        ]);',
'    }',
'});'))
);
