 p_id=>wwv_flow_imp.id(550104604232461449)
,p_event_id=>wwv_flow_imp.id(550104583162461448)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'BEGIN ',
'   -- TOTAL GENERAL',
'   SELECT NVL(SUM(Monto_Fact_Moneda),0),',
'          NVL(SUM(Monto_Fact_Local),0),',
'          NVL(SUM(MtoComisi_Moneda),0),',
'          NVL(SUM(MtoComisi_Local),0),',
'          COUNT(*)',
'     INTO :P704_TOTALFACTMONEDA,',
'          :P704_TOTALFACTLOCAL,',
'          :P704_TOTCOMISIMONEDA,',
'          :P704_TOTCOMISILOCAL,',
'          :P704_RECIBOSTOTAL',
'     FROM FACTURAS',
'    WHERE CodCia   = :P704_CODCIA',
'      AND IdPoliza = :P704_IDPOLIZA;',
'',
'   -- ANULADOS',
'   SELECT NVL(SUM(Monto_Fact_Moneda),0),',
'          NVL(SUM(Monto_Fact_Local),0),',
'          NVL(SUM(MtoComisi_Moneda),0),',
'          NVL(SUM(MtoComisi_Local),0),',
'          COUNT(*)',
'     INTO :P704_TOTANULADOMONEDA,',
'          :P704_TOTANULADOLOCAL,',
'          :P704_TOTCOMISANULMON,',
'          :P704_TOTCOMISANULLOC,',
'          :P704_RECIBOSANUL',
'     FROM FACTURAS',
'    WHERE CodCia   = :P704_CODCIA',
'      AND IdPoliza = :P704_IDPOLIZA',
'      AND StsFact  = ''ANU'';',
'',
'   -- PAGADOS',
'   SELECT NVL(SUM(Monto_Fact_Moneda),0),',
'          NVL(SUM(Monto_Fact_Local),0),',
'          NVL(SUM(MtoComisi_Moneda),0),',
'          NVL(SUM(MtoComisi_Local),0),',
'          COUNT(*)',
'     INTO :P704_TOTPAGADOMONEDA,',
'          :P704_TOTPAGADOLOCAL,',
'          :P704_TOTCOMISPAGMON,',
'          :P704_TOTCOMISPAGLOC,',
'          :P704_RECIBOSPAG',
'     FROM FACTURAS',
'    WHERE CodCia   = :P704_CODCIA',
'      AND IdPoliza = :P704_IDPOLIZA',
'      AND StsFact  = ''PAG'';',
'',
'   -- ABONOS (se suman a pagados)',
'   SELECT (NVL(SUM(Monto_Fact_Moneda),0) - NVL(SUM(Saldo_Moneda),0)) + :P704_TOTPAGADOMONEDA,',
'          (NVL(SUM(Monto_Fact_Local),0)  - NVL(SUM(Saldo_Local),0)) + :P704_TOTPAGADOLOCAL,',
'          COUNT(*) + :P704_RECIBOSPAG',
'     INTO :P704_TOTPAGADOMONEDA,',
'          :P704_TOTPAGADOLOCAL,',
'          :P704_RECIBOSPAG',
'     FROM FACTURAS',
'    WHERE CodCia   = :P704_CODCIA',
'      AND IdPoliza = :P704_IDPOLIZA',
'      AND StsFact  = ''ABO'';',
'',
'   -- PENDIENTES',
'   SELECT NVL(SUM(Monto_Fact_Moneda),0),',
'          NVL(SUM(Monto_Fact_Local),0),',
'          NVL(SUM(MtoComisi_Moneda),0),',
'          NVL(SUM(MtoComisi_Local),0),',
'          COUNT(*)',
'     INTO :P704_TOTPENDIENTEMONEDA,',
'          :P704_TOTPENDIENTELOCAL,',
'          :P704_TOTCOMISPENMON,',
'          :P704_TOTCOMISPENLOC,',
'          :P704_RECIBOSPEND',
'     FROM FACTURAS',
'    WHERE CodCia   = :P704_CODCIA',
'      AND IdPoliza = :P704_IDPOLIZA',
'      AND StsFact  = ''EMI'';',
'',
'EXCEPTION',
'   WHEN OTHERS THEN',
'      -- Manejo de error en APEX',
'      APEX_ERROR.ADD_ERROR(',
'         p_message => SQLERRM,',
'         p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'      );',
'END;'))
,p_attribute_02=>'P704_IDPOLIZA,P704_CODCIA'
,p_attribute_03=>'P704_TOTALFACTMONEDA,P704_TOTALFACTLOCAL,P704_TOTCOMISIMONEDA,P704_TOTCOMISILOCAL,P704_RECIBOSTOTAL,P704_TOTANULADOMONEDA,P704_TOTANULADOLOCAL,P704_TOTCOMISANULMON,P704_TOTCOMISANULLOC,P704_RECIBOSANUL,P704_TOTPAGADOMONEDA,P704_TOTPAGADOLOCAL,P704_TO'
||'TCOMISPAGMON,P704_TOTCOMISPAGLOC,P704_RECIBOSPAG,P704_TOTPENDIENTEMONEDA,P704_TOTPENDIENTELOCAL,P704_TOTCOMISPENMON,P704_TOTCOMISPENLOC,P704_RECIBOSPEND'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
