,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT F.NUMCUOTA, ',
'       F.RECIBOPAGO,',
'       F.MONTO_FACT_MONEDA,',
'       F.SALDO_MONEDA,',
'       F.CODCOBRADOR,',
'       F.FORMPAGO,',
'       F.ENTPAGO,',
'       F.INDPAGPROD,',
'       P.MONEDA,',
'       P.NUMDOC,',
'       P.MONTO,',
'       F.IDETPOL,',
'       F.IDENDOSO,',
'       F.IDFACTURA,',
'       F.FECSTS,',
'       F.NUMFACT, ',
