wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(550666908131261843)
,p_event_id=>wwv_flow_imp.id(550666806569261842)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   nIdFondo   FAI_FONDOS_DETALLE_POLIZA.IdFondo%TYPE;',
'   vIdTipoSeg DETALLE_POLIZA.IdTipoSeg%TYPE;',
'BEGIN',
'',
unistr('   -- Fecha \00FAltimo pago'),
'   SELECT NVL(MAX(Fecha), TRUNC(SYSDATE))',
'     INTO :P706_FECHAPAGO',
'     FROM PAGOS',
'    WHERE IdFactura = :P706_NUM_RECIBO;',
'',
'   -- Datos del asegurado',
'   BEGIN',
'      SELECT D.Cod_Asegurado,',
'             D.IdFormaCobro,',
'             A.Tipo_Doc_Identificacion,',
'             A.Num_Doc_Identificacion,',
'             D.IdTipoSeg',
'        INTO :P706_COD_ASEGURADO,',
'             :P706_FORMPAGO,',
'             :P706_TIPO_DOC,',
'             :P706_NUM_DOC,',
'             vIdTipoSeg',
'        FROM DETALLE_POLIZA D',
'        JOIN ASEGURADO A',
'          ON A.Cod_Asegurado = D.Cod_Asegurado',
'         AND A.CodEmpresa    = D.CodEmpresa',
'         AND A.CodCia        = D.CodCia',
'       WHERE D.IDetPol  = :P706_IDETPOL',
'         AND D.IdPoliza = :P706_IDPOLIZA',
'         AND D.CodCia   = :P706_CODCIA;',
'',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'         :P706_COD_ASEGURADO := NULL;',
'   END;',
'',
unistr('   -- Descripci\00F3n forma de pago'),
'   IF :P706_FORMPAGO IS NOT NULL THEN',
'      :P706_DESC_FORMAPAGO := ',
'         OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''FORMPAGO'', :P706_FORMPAGO);',
'   END IF;',
'',
'   -- Cobrador',
'   IF :P706_CODCOBRADOR IS NOT NULL THEN',
'      BEGIN',
'         SELECT P.Nombre || '' '' || P.Apellido',
'           INTO :P706_DESC_COBRADOR',
'           FROM COBRADORES C',
'           JOIN PERSONA_NATURAL_JURIDICA P',
'             ON C.TIPO_DOC_IDENTIFICACION = P.TIPO_DOC_IDENTIFICACION',
'            AND C.NUM_DOC_IDENTIFICACION  = P.NUM_DOC_IDENTIFICACION',
'          WHERE C.CodCobrador = :P706_CODCOBRADOR',
'            AND C.CodCia      = :P706_CODCIA;',
'',
'      EXCEPTION',
'         WHEN NO_DATA_FOUND THEN',
'            :P706_DESC_COBRADOR := ''NO EXISTE'';',
'      END;',
'   END IF;',
'',
'   -- Entidad de pago',
'   IF :P706_ENTPAGO IS NOT NULL THEN',
'      :P706_DESC_ENTPAGO :=',
'         OC_ENTIDAD_FINANCIERA.DESCRIPCION(',
'            :P706_CODCIA,',
'            :P706_ENTPAGO',
'         );',
'   END IF;',
'',
unistr('   -- Indicador factura electr\00F3nica'),
'   :P706_IND_FACT_ELECT := ''S'';',
'',
unistr('   -- L\00F3gica de fondos'),
'   IF GT_FAI_FONDOS_DETALLE_POLIZA.EXISTEN_FONDOS(',
'         :P706_CODCIA,',
'         :P706_CODEMPRESA,',
'         :P706_IDPOLIZA,',
'         :P706_IDETPOL,',
'         :P706_COD_ASEGURADO',
'      ) = ''S'' THEN',
'',
'      -- Aporte fondo',
'      :P706_APORTEAHORRO :=',
'         OC_DETALLE_POLIZA.MONTO_APORTE_FONDOS(',
'            :P706_CODCIA,',
'            :P706_CODEMPRESA,',
'            :P706_IDPOLIZA,',
'            :P706_IDETPOL',
'         );',
'',
'      -- Obtener fondo',
'      nIdFondo :=',
'         GT_FAI_FONDOS_DETALLE_POLIZA.FONDO_PAGO_PRIMA(',
'            :P706_CODCIA,',
'            :P706_CODEMPRESA,',
'            :P706_IDPOLIZA,',
'            :P706_IDETPOL,',
'            :P706_COD_ASEGURADO',
'         );',
'',
'      IF NVL(nIdFondo, 0) > 0 THEN',
'',
'         IF OC_POLIZAS.ALTURA_CERO(',
'               :P706_CODCIA,',
'               :P706_CODEMPRESA,',
'               :P706_IDPOLIZA',
'            ) = ''S''',
'            AND OC_POLIZAS.APLICA_RETIRO_PRIMA_NIVELADA(',
'               :P706_CODCIA,',
'               :P706_CODEMPRESA,',
'               :P706_IDPOLIZA',
'            ) = ''S''',
'            AND OC_TIPOS_DE_SEGUROS.MANEJA_FONDOS(',
'               :P706_CODCIA,',
'               :P706_CODEMPRESA,',
'               vIdTipoSeg',
'            ) = ''S'' THEN',
'',
'            :P706_PRIMACOMP := 0;',
'',
'         ELSE',
'',
'            :P706_PRIMACOMP :=',
'               GT_FAI_CONFIG_APORTE_FONDO_DET.MONTO_APORTE_ESPECIFICO(',
'                  :P706_CODCIA,',
'                  :P706_CODEMPRESA,',
'                  :P706_IDPOLIZA,',
'                  :P706_IDETPOL,',
'                  :P706_COD_ASEGURADO,',
'                  nIdFondo,',
'                  :P706_CUOTA',
'               );',
'',
'         END IF;',
'',
'      ELSE',
'         :P706_PRIMACOMP := 0;',
'      END IF;',
'',
'   ELSE',
'      :P706_APORTEAHORRO := 0;',
'      :P706_PRIMACOMP    := 0;',
'   END IF;',
'',
'END;'))
,p_attribute_02=>'P706_CODCIA, P706_CODEMPRESA, P706_IDPOLIZA, P706_IDETPOL, P706_COD_ASEGURADO, P706_NUM_RECIBO, P706_ENTPAGO, P706_CODCOBRADOR, P706_FORMPAGO, P706_CUOTA'
,p_attribute_03=>'P706_APORTEAHORRO, P706_PRIMACOMP, P706_FECHAPAGO, P706_DESC_FORMAPAGO, P706_DESC_COBRADOR, P706_DESC_ENTPAGO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
