wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(550668203819261856)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Llenado_Cabecera_0'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nIdFondo   FAI_FONDOS_DETALLE_POLIZA.IdFondo%TYPE;',
'    vIdTipoSeg DETALLE_POLIZA.IdTipoSeg%TYPE;',
'BEGIN',
'    SELECT NumCuota, FormPago, CodCobrador, EntPago',
'      INTO :P706_CUOTA, :P706_FORMPAGO, :P706_CODCOBRADOR, :P706_ENTPAGO',
'      FROM FACTURAS',
'     WHERE IDFACTURA = :P706_NUM_RECIBO',
'     ORDER BY IDPOLIZA DESC;',
'',
unistr('    -- Fecha \00FAltimo pago'),
'    SELECT NVL(MAX(Fecha), TRUNC(SYSDATE))',
'      INTO :P706_FECHAPAGO',
'      FROM PAGOS',
'     WHERE IdFactura = :P706_NUM_RECIBO;',
'',
'    -- Datos del asegurado',
'    BEGIN',
'        SELECT D.Cod_Asegurado, D.IdFormaCobro, A.Tipo_Doc_Identificacion,',
'               A.Num_Doc_Identificacion, D.IdTipoSeg',
'          INTO :P706_COD_ASEGURADO, :P706_FORMPAGO, :P706_TIPO_DOC,',
'               :P706_NUM_DOC, vIdTipoSeg',
'          FROM DETALLE_POLIZA D',
'          JOIN ASEGURADO A',
'            ON A.Cod_Asegurado = D.Cod_Asegurado',
'           AND A.CodEmpresa = D.CodEmpresa',
'           AND A.CodCia = D.CodCia',
'         WHERE D.IDetPol = :P706_IDETPOL',
'           AND D.IdPoliza = :P706_IDPOLIZA',
'           AND D.CodCia = NVL(:P706_CODCIA, 1);',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            :P706_COD_ASEGURADO := NULL;',
'    END;',
'',
unistr('    -- Descripci\00F3n forma de pago'),
'    IF :P706_FORMPAGO IS NOT NULL THEN',
'        :P706_DESC_FORMAPAGO := OC_VALORES_DE_LISTAS.BUSCA_LVALOR(',
'            ''FORMPAGO'', :P706_FORMPAGO',
'        );',
'    END IF;',
'',
'    -- Cobrador',
'    IF :P706_CODCOBRADOR IS NOT NULL THEN',
'        BEGIN',
'            SELECT P.Nombre || '' '' || P.Apellido',
'              INTO :P706_DESC_COBRADOR',
'              FROM COBRADORES C',
'              JOIN PERSONA_NATURAL_JURIDICA P',
'                ON C.TIPO_DOC_IDENTIFICACION = P.TIPO_DOC_IDENTIFICACION',
'               AND C.NUM_DOC_IDENTIFICACION = P.NUM_DOC_IDENTIFICACION',
'             WHERE C.CodCobrador = :P706_CODCOBRADOR',
'               AND C.CodCia = NVL(:P706_CODCIA, 1);',
'',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                :P706_DESC_COBRADOR := ''NO EXISTE'';',
'        END;',
'    END IF;',
'',
'    -- Entidad de pago',
'    IF :P706_ENTPAGO IS NOT NULL THEN',
'        :P706_DESC_ENTPAGO := OC_ENTIDAD_FINANCIERA.DESCRIPCION(',
'            NVL(:P706_CODCIA, 1), :P706_ENTPAGO',
'        );',
'    END IF;',
'',
unistr('    -- Indicador factura electr\00F3nica'),
'    :P706_IND_FACT_ELECT := ''S'';',
'',
unistr('    -- L\00F3gica de fondos'),
'    IF GT_FAI_FONDOS_DETALLE_POLIZA.EXISTEN_FONDOS(',
'        NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1), :P706_IDPOLIZA,',
'        :P706_IDETPOL, :P706_COD_ASEGURADO',
'    ) = ''S'' THEN',
'        -- Aporte fondo',
'        :P706_APORTEAHORRO := OC_DETALLE_POLIZA.MONTO_APORTE_FONDOS(',
'            NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1),',
'            :P706_IDPOLIZA, :P706_IDETPOL',
'        );',
'',
'        -- Obtener fondo',
'        nIdFondo := GT_FAI_FONDOS_DETALLE_POLIZA.FONDO_PAGO_PRIMA(',
'            NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1), :P706_IDPOLIZA,',
'            :P706_IDETPOL, :P706_COD_ASEGURADO',
'        );',
'',
'        IF NVL(nIdFondo, 0) > 0 THEN',
'            IF OC_POLIZAS.ALTURA_CERO(',
'                NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1), :P706_IDPOLIZA',
'            ) = ''S''',
'            AND OC_POLIZAS.APLICA_RETIRO_PRIMA_NIVELADA(',
'                NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1), :P706_IDPOLIZA',
'            ) = ''S''',
'            AND OC_TIPOS_DE_SEGUROS.MANEJA_FONDOS(',
'                NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1), vIdTipoSeg',
'            ) = ''S'' THEN',
'                :P706_PRIMACOMP := 0;',
'            ELSE',
'                :P706_PRIMACOMP := GT_FAI_CONFIG_APORTE_FONDO_DET.MONTO_APORTE_ESPECIFICO(',
'                    NVL(:P706_CODCIA, 1), NVL(:P706_CODEMPRESA, 1), :P706_IDPOLIZA,',
'                    :P706_IDETPOL, :P706_COD_ASEGURADO, nIdFondo, :P706_CUOTA',
'                );',
'            END IF;',
'        ELSE',
'            :P706_PRIMACOMP := 0;',
'        END IF;',
'    ELSE',
'        :P706_APORTEAHORRO := 0;',
'        :P706_PRIMACOMP := 0;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_required_patch=>wwv_flow_imp.id(690440983571095281)
,p_internal_uid=>111576506988190333
);
