'FROM ENDOSOS',
'WHERE IDPOLIZA = :P800_IDPOLIZA'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P800_IDPOLIZA'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
