 p_id=>wwv_flow_imp.id(558259092026875156)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Endoso_Emitir_Aumento'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cNaturalidad  VARCHAR2(2);',
'    cValida       VARCHAR2(1);',
'BEGIN',
'    -- Valida si el endoso puede emitirse',
'    cValida := OC_ENDOSO.VALIDA_ENDOSO(:P800_CODCIA,:P800_IDPOLIZA,:P800_IDENDOSO,cNaturalidad);',
'',
'    IF  OC_ENDOSO.VALIDA_ENDOSO(:P800_CODCIA,:P800_IDPOLIZA,:P800_IDENDOSO,cNaturalidad) = ''S'' THEN',
'            OC_ENDOSO.EMITIR_AUMENTO(:P800_CODCIA,:P800_CODEMPRESA,',
'                :P800_IDPOLIZA,:P800_IDETPOL,:P800_IDENDOSO,:P800_TIPO_ENDOSO);',
'        COMMIT;',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        RAISE_APPLICATION_ERROR(-20001, ''Error: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(558171102264777912)
