begin
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(558259485102875160)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Endoso_Reversa'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'dFecHoy       DATE;',
'nRegis        NUMBER(6);',
'nSumaAseg     NUMBER(14,2);',
'cNaturalidad  VARCHAR2(1);',
'nExiste       NUMBER(5);',
'',
'nCodCia     endosos.CodCia%type     := :P800_CODCIA;',
'nIdPoliza   endosos.idpoliza%type   := :P800_IDPOLIZA;',
'nIDetPol    endosos.IDetPol%type    := :P800_DET_POLIZA;',
'nIdEndoso   endosos.IdEndoso%type   := :P800_IDENDOSO;',
'nCodEmpresa endosos.CODEMPRESA%type := :P800_CODEMPRESA;',
'cTipoEndoso endosos.TIPOENDOSO%type := :P800_TIPO_ENDOSO_VALUE;',
'',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO nExiste',
'    FROM ENDOSOS',
'    WHERE IdPoliza  = nIdPoliza',
'    AND IdEndoso  > nIdEndoso',
'    AND StsEndoso = ''EMI'';',
'',
'    IF NVL(nExiste,0) != 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Debe Revertir primero los Endosos Emitidos Posteriormente a este Endoso'');',
'    END IF;',
'',
'    IF CTipoEndoso != ''EAD'' THEN',
'        IF OC_ENDOSO.VALIDA_ENDOSO(nCodCia, nIdPoliza, nIdEndoso, cNaturalidad) = ''S'' THEN',
'         ',
'            BEGIN',
'               OC_ENDOSO.REVERTIR_EMISION(nCodCia, nCodEmpresa, nIdPoliza, nIDetPol, nIdEndoso, CTipoEndoso);',
'',
'            EXCEPTION',
'               WHEN OTHERS THEN',
'                    RAISE_APPLICATION_ERROR(-20002, SQLERRM);',
'            END;',
'            COMMIT;',
'         ',
'        END IF;',
'    ELSE',
unistr('        RAISE_APPLICATION_ERROR(-20003, ''NO Puede Revertir la Emisi\00F3n del Endoso No. '' || RTRIM(LTRIM(TO_CHAR(nIdEndoso))) ||'),
unistr('                                '' Porque es a Declaraci\00F3n.  Debe realizar otro Endoso a Declaraci\00F3n o Cancelarlo.'');'),
'    END IF;',
'',
'DECLARE',
'',
'    set_url VARCHAR2(1000);',
'',
'    BEGIN',
'        set_url := APEX_PAGE.GET_URL(',
'            p_page      => 800,',
'            p_request   => ''BTN_REVERSA_ENDOSO'',',
'            p_items  => ''P800_CONSECUTIVO_EP'',',
'            p_values => :P800_CONSECUTIVO_EP',
'        );',
'        apex_util.redirect_url ( p_url => set_url );',
'',
'    END;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RAISE_APPLICATION_ERROR(-20004,SQLERRM); ',
'END;       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(558171498811777912)
,p_required_patch=>wwv_flow_imp.id(690440983571095281)
,p_internal_uid=>119167788271803637
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(558259291910875158)
,p_process_sequence=>140
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_Endoso_Rehabilita'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    OC_ENDOSO.REHABILITACION(:P800_CODCIA,:P800_CODEMPRESA,:P800_IDPOLIZA,:P800_IDENDOSO);',
'EXCEPTION',
'    WHEN OTHERS THEN',
unistr('        raise_application_error(-20001,''Error en Rehabilitaci\00F3n de Endoso: '' || SQLERRM);'),
'END;',
'       '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(558169543562777910)
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Endoso No. &P800_ID_ENDOSO.',
'REHABILITADO Correctamente'))
,p_required_patch=>wwv_flow_imp.id(690440983571095281)
,p_internal_uid=>119167595079803635
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(558258600063875152)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
