,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('/*Procesos para asignaci\00F3n es estados activos/inactivos de botones*/'),
'BEGIN',
'    HTP.P(OC_MANTENIMIENTO_ENDOSOS_ACCIONES.ESTADOS_BTN_ENDOSOS(1,1,:P800_IDPOLIZA,:P800_IDENDOSO));',
'END;'))
,p_process_clob_language=>'PLSQL'
