wwv_flow_imp_page.create_page_branch(
 p_id=>wwv_flow_imp.id(553494785061067873)
,p_branch_name=>'GO_Cambio_Asegurado'
,p_branch_action=>unistr('DECLARE'||wwv_flow.LF||
'    cNumPolUnico    polizas.NUMPOLUNICO%TYPE;'||wwv_flow.LF||
'    cCodCliente     polizas.CODCLIENTE%TYPE;'||wwv_flow.LF||
'    dFECINIVIG      polizas.FECINIVIG%TYPE;'||wwv_flow.LF||
'    cCod_Asegurado  detalle_poliza.COD_ASEGURADO%TYPE;'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    SELECT NUMPOLUNICO, CODCLIENTE, FECINIVIG'||wwv_flow.LF||
'      INTO cNumPolUnico, cCodCliente, dFECINIVIG'||wwv_flow.LF||
'      FROM polizas'||wwv_flow.LF||
'     WHERE idpoliza = :P1000_IDPOLIZA;'||wwv_flow.LF||
''||wwv_flow.LF||
'    SELECT COD_ASEGURADO'||wwv_flow.LF||
'      INTO cCod_Asegurado'||wwv_flow.LF||
'      FROM detalle_poliza'||wwv_flow.LF||
'     WHERE idpoliza = :P1000_IDPOLIZA'||wwv_flow.LF||
'       AND idetpol  = NVL(:P1000_IDETPOL, 1);'||wwv_flow.LF||
''||wwv_flow.LF||
'    RETURN apex_page.get_url('||wwv_flow.LF||
'        p_page               => 113,'||wwv_flow.LF||
'        p_clear_cache        => ''113'','||wwv_flow.LF||
'        p_request            => ''MODIFPOL'','||wwv_flow.LF||
'        p_triggering_element => ''$(''''#BTN_GENERAR_ESV'''')'','||wwv_flow.LF||
'        p_items              => ''P113_NUMPOLUNICO,P113_IDPOLIZA,P113_CERTIFICADO,P113_ASEG_ACTUAL,P113_CLIENTE_ACTUAL,P113_CODCIA,P113_CODEMPRESA,P113_FINVIG'','||wwv_flow.LF||
'        p_values             => cNumPolUnico'||wwv_flow.LF||
'                                || '','' || :P1000_IDPOLIZA'||wwv_flow.LF||
'                                || '','' || NVL(:P1000_IDETPOL, 1)'||wwv_flow.LF||
'                                || '','' || cCod_Asegurado'||wwv_flow.LF||
'                                || '','' || cCodCliente'||wwv_flow.LF||
'                                || '','' || :P1000_CODCIA'||wwv_flow.LF||
'                                || '','' || :P1000_CODEMPRESA'||wwv_flow.LF||
'                                || '','' || TO_CHAR(dFECINIVIG, ''YYYY-MM-DD'')'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN NO_DATA_FOUND THEN'||wwv_flow.LF||
'        RETURN NULL;'||wwv_flow.LF||
'    WHEN TOO_MANY_ROWS THEN'||wwv_flow.LF||
'        RAISE_APPLICATION_ERROR(-20001, ''La consulta devolvi\00F3 m\00E1s de un registro.'');'||wwv_flow.LF||
'END;')
,p_branch_point=>'BEFORE_PROCESSING'
,p_branch_type=>'BRANCH_TO_FUNCTION_RETURNING_URL'
,p_branch_language=>'PLSQL'
,p_branch_when_button_id=>wwv_flow_imp.id(593393642414208330)
,p_branch_sequence=>10
,p_branch_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_branch_condition=>'P1000_CORRCONF'
,p_branch_condition_text=>'1'
,p_branch_comment=>'Direccionamiento a pagina para endoso sin valor de cambio de Asegurado'
);
