 p_id=>wwv_flow_imp.id(622706780952221294)
,p_name=>'P1000_CODPLANPAGO'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(622709950291221326)
,p_item_source_plug_id=>wwv_flow_imp.id(622489357092055932)
,p_prompt=>'Plan de Pago'
,p_source=>'CODPLANPAGO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov_language=>'PLSQL'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    s_qly   VARCHAR2(1000);',
'BEGIN',
'    s_qly   := ''SELECT CODPLANPAGO || '''' - '''' || DESCPLAN DESC_PLAN_PAGOS',
'                ,CODPLANPAGO',
'                FROM PLAN_DE_PAGOS',
'                WHERE   CodCia      = 1',
'                AND     CodEmpresa  = 1',
'                AND     StsPlan     = ''''ACT'''''';',
'',
'    IF :P1000_TIPOENDOSO IN (''RSS'',''NSS'') THEN',
'        s_qly := s_qly || '' AND CODPLANPAGO IN  (SELECT CODVALOR',
'                                                FROM   VALORES_DE_LISTAS',
'                                                WHERE  CODLISTA = ''''PLANPAGST'''')'';',
'',
'        RETURN s_qly;',
'    ELSE',
'        RETURN s_qly;',
'    END IF;',
'',
'END;    '))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'-- Seleccionar --'
,p_lov_cascade_parent_items=>'P1000_TIPOENDOSO'
,p_ajax_items_to_submit=>'P1000_TIPOENDOSO'
,p_ajax_optimize_refresh=>'Y'
