wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(622708036158221307)
,p_name=>'P1000_MOTIVO_ENDOSO'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(622709950291221326)
,p_item_source_plug_id=>wwv_flow_imp.id(622489357092055932)
,p_prompt=>'Motivo Endoso'
,p_source=>'MOTIVO_ENDOSO'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'    v.codvalor || '' - '' || v.descvallst    as display_value,',
'    v.codvalor                             as return_value     ',
'from valores_de_listas v',
'where (',
'        v.codlista = case',
'                       when :P1000_TIPOENDOSO in (''EXC'',''DIS'',''EXA'',''NSS'') then ''MTOENDIS''',
'                       when :P1000_TIPOENDOSO in (''INC'',''AUM'',''INA'',''RSS'',''EAD'') then ''MTOENDAU''',
'                       else ''MTOENDSV''',
'                     end',
'      )',
'  and (',
'        :P1000_TIPOENDOSO <> ''CFV''',
'        or (v.codlista = ''MTOENDSV''',
'            and v.descvallst like ''MODIFICACION%VIGENCIA%'')',
'      )',
'order by v.codvalor;',
''))
,p_lov_cascade_parent_items=>'P1000_TIPOENDOSO'
,p_ajax_items_to_submit=>'P1000_TIPOENDOSO'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_cMaxlength=>6
,p_field_template=>wwv_flow_imp.id(690616768967096209)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_attribute_01=>'POPUP'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
,p_item_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Lista de motivo de endoso deacuerdo al tipo de endoso.',
'',
'1. ''EXC'',''DIS'',''EXA'',''NSS''',
'select codvalor,descvallst',
'from valores_de_listas',
'where codlista= ''MTOENDIS'';',
'',
'2.''INC'',''AUM'',''INA'',''RSS'',''EAD''',
'select codvalor,descvallst',
'from valores_de_listas',
'where codlista= ''MTOENDAU'';',
'',
'3. CFV',
'SELECT CODVALOR,DESCVALLST',
'FROM VALORES_DE_LISTAS',
'WHERE CODLISTA = ''MTOENDSV''',
'AND DESCVALLST LIKE ''MODIFICACION%VIGENCIA%''',
'',
'4. ELSE',
'select codvalor,descvallst',
'from valores_de_listas',
'where codlista= ''MTOENDSV'''))
);
