wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(596755755773793611)
,p_validation_name=>'VAL_PRE_UPDATE_INSERT'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'RETURN OC_MANTENIMIENTO_ENDOSOS_ACCIONES.VALIDA_GENERAL_ENDOSO(',
'    cTipoEndoso        => :P1000_TIPOENDOSO,',
'    nPrimaNetaMoneda   => REGEXP_REPLACE(:P1000_PRIMA_NETA_MONEDA, ''[$,]'', ''''),',
'    nSumaAsegMoneda    => REGEXP_REPLACE(:P1000_SUMA_ASEG_MONEDA, ''[$,]'', ''''),',
'    dFecIniVig         => :P1000_FECINIVIG,',
'    dFecFinVig         => :P1000_FECFINVIG,',
'    dFecIniVigPoliza   => :P1000_FECINIVIG_POLIZA,',
'    dFecFinVigPoliza   => :P1000_FECFINVIG_POLIZA',
');'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_validation_condition=>'SAVE,CREATE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_validation_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'VALIDACIONES APLICADAS AL ENDOSO ',
'',
'1. Prima Neta obligatoria',
'-Para tipos: NSS, RSS, EAD y CFP.',
'-No se permite Prima Neta igual a 0.',
'',
'2.Suma Asegurada restringida',
'-Para tipos: NSS, RSS y EAD.',
'-No se permite ingresar Suma Asegurada distinta de 0.',
'',
'3. Validaciones de Fechas',
'',
'3.Inicio de Vigencia',
unistr('-No puede ser menor al inicio de vigencia de la p\00F3liza (excepto CFV).'),
unistr('-No puede ser mayor al fin de vigencia de la p\00F3liza.'),
'',
'4.Fechas del Endoso',
'-Fin no puede ser igual al inicio.',
'-Fin no puede ser menor al inicio.',
'',
unistr('5.Fin de Vigencia vs P\00F3liza'),
unistr('-No puede ser mayor al fin de vigencia de la p\00F3liza (excepto CFV).')))
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(540976671217621858)
,p_validation_name=>'VAL_PRE_UPDATE_INSERT_1'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  cMensajeError  varchar2(4000);',
'BEGIN',
'    -- FUNC_VALIDA_DATOS',
'    IF :P1000_NUMENDREF IS NULL THEN',
'        apex_error.add_error (',
'            p_message          => ''Debe Asignar No. de Referencia'',',
'            p_display_location => apex_error.c_inline_with_field,',
'            p_page_item_name   => ''P1000_NUMENDREF''',
'        );',
'        cMensajeError := ''Debe asignarle el No. de REFERENCIA al Endoso que desea Emitir'';',
'    END IF;',
'',
'    IF :P1000_TIPOENDOSO NOT IN (''ESV'', ''ESVTL'', ''APS'', ''CFP'') AND :P1000_CODPLANPAGO IS NULL THEN',
'        apex_error.add_error (',
'            p_message          => ''Seleccionar Plan de Pagos'',',
'            p_display_location => apex_error.c_inline_with_field,',
'            p_page_item_name   => ''P1000_CODPLANPAGO''',
'        );',
'        cMensajeError := ''Tiene que Elegir un Plan de Pagos para el Endoso'';',
'    END IF;',
'',
'    IF :P1000_TIPOENDOSO NOT IN (''ESV'', ''ESVTL'', ''EXA'',''CFP'',''INA'') THEN',
'        IF NVL(REGEXP_REPLACE(:P1000_SUMA_ASEG_LOCAL, ''[$,]'', ''''),0) = 0 AND :P1000_TIPOENDOSO NOT IN (''RSS'', ''NSS'',''EAD'') THEN',
'            apex_error.add_error (',
'                p_message          => ''Colocar Suma Asegurada'',',
'                p_display_location => apex_error.c_inline_with_field,',
'                p_page_item_name   => ''P1000_SUMA_ASEG_LOCAL''',
'            );',
'            cMensajeError := ''Debe colocar la Suma Asegurada del Endoso'';   ',
'        ELSIF NVL(REGEXP_REPLACE(:P1000_PRIMA_NETA_LOCAL, ''[$,]'', ''''),0) = 0 THEN',
'            apex_error.add_error (',
'                p_message          => ''Colocar Prima Neta del Endoso'',',
'                p_display_location => apex_error.c_inline_with_field,',
'                p_page_item_name   => ''P1000_PRIMA_NETA_LOCAL''',
'            );',
'            cMensajeError := ''Debe Colocar la Prima Neta del Endoso'';',
'        END IF;',
'    END IF;',
'',
'    -- Endoso ''EXC''',
'    IF :P1000_TIPOENDOSO = ''EXC'' AND :P1000_FECEXC IS NULL THEN',
'        apex_error.add_error (',
unistr('            p_message          => ''Ingresar Fecha de Exclusi\00D3n'','),
'            p_display_location => apex_error.c_inline_with_field,',
'            p_page_item_name   => ''P1000_FECEXC''',
'        );',
unistr('        cMensajeError := ''Debe Ingresar la Fecha de Exclusi\00D3n para el certificado No: ''||:P1000_IDETPOL;'),
'    END IF;',
'',
'    RETURN cMensajeError;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_validation_condition=>'SAVE,CREATE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
