,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    getFecVigencias   SICAS_OC.fechasDeVigencia;',
'BEGIN',
'    IF :P1000_TIPOENDOSO = ''CFV'' THEN',
'        IF :P1000_MOTIVO_ENDOSO = ''027'' THEN',
'            getFecVigencias := SICAS_OC.OC_ENDOSO_SERVICIOS_WEB.CONSULTA_FECHAS_VIGENCIA_DOCS(:P1000_IDPOLIZA,:P1000_IDETPOL,''01'');',
'',
'            :P1000_NFECHVIGINI := getFecVigencias.fechaIniVig;',
'            :P1000_NFECHVIGFIN := getFecVigencias.fechaFinVig;',
'        END IF;',
'',
'        IF :P1000_MOTIVO_ENDOSO = ''029'' THEN',
'            getFecVigencias := SICAS_OC.OC_ENDOSO_SERVICIOS_WEB.CONSULTA_FECHAS_VIGENCIA_DOCS(:P1000_IDPOLIZA,:P1000_IDETPOL,''02'');',
'            ',
'            :P1000_NFECHVIGINI := getFecVigencias.fechaIniVig;',
'            :P1000_NFECHVIGFIN := getFecVigencias.fechaFinVig;',
'',
'        END IF;',
'',
'        IF :P1000_MOTIVO_ENDOSO NOT IN (''029'',''027'') THEN',
'            :P1000_NFECHVIGINI := NULL;',
'			:P1000_NFECHVIGFIN := NULL;',
'        END IF;',
'    END IF;',
'',
'END;'))
,p_attribute_02=>'P1000_TIPOENDOSO,P1000_MOTIVO_ENDOSO,P1000_IDENDOSO,P1000_NUMENDREF_1,P1000_IDPOLIZA,P1000_IDETPOL'
,p_attribute_03=>'P1000_PRUEBA_INCIO,P1000_PRUEBA_FINAL,P1000_NFECHVIGINI,P1000_NFECHVIGFIN'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
