,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    vardFecFinVig   endosos.FECFINVIG%TYPE;',
'    vardFecIniVig   endosos.FECINIVIG%TYPE;',
'BEGIN',
'    :P1000_SHOW_ERROR := NULL;',
'    vardFecFinVig := :P1000_FECFINVIG;',
'    vardFecIniVig := :P1000_FECINIVIG;',
'',
'    OC_MANTENIMIENTO_ENDOSOS_ACCIONES.ENDOSO_CAMBIO_FECHA (',
'            -- Ingreso de Datos',
'            in_nIdEndoso            => :P1000_IDENDOSO,',
'            in_nCodCia              => 1,',
'            in_nCodEmpresa          => 1,',
'            in_nIdPoliza            => :P1000_IDPOLIZA,',
'            in_nIDetPol             => :P1000_IDETPOL,',
'            in_cTipoEndoso          => :P1000_TIPOENDOSO,',
'            in_cMotivoEndoso        => :P1000_MOTIVO_ENDOSO,',
'            in_cNUMENDREF           => :P1000_NUMENDREF,',
'            in_cCodPlan             => :P1000_CODPLANPAGO,',
'            -- Region Cambio de Fecha',
'            in_nNumEndoso           => :P1000_NUMENDOSO_CF,',
'            in_cCheckFechaVigIni    => :P1000_CHECKFECHAVIGINI,',
'            in_cCheckFechaVigFin    => :P1000_CHECKFECHAVIGFIN,',
'            in_dNFechVigIni         => :P1000_NFECHVIGINI,',
'            in_dNFechVigFin         => :P1000_NFECHVIGFIN,',
'            in_nNumCF               => :P1000_NUMNCF,',
'            in_cCheckFechaVigIniD   => :P1000_CHECKFECHAVIGINID,',
'            in_cCheckFechaVigFinD   => :P1000_CHECKFECHAVIGFIND,',
'            in_dNFechVigIniD        => :P1000_NFECHVIGINID,',
'            in_dNFechVigFinD        => :P1000_NFECHVIGFIND,',
'            in_dFecFinVig           => vardFecFinVig,',
'            in_dFecIniVig           => vardFecIniVig,',
'            in_CodCambioFecha       => :P1000_COD_CAMBIO_FECHA,',
'            -- Salida de Datos',
'            out_dFecIniVig          => :P1000_FECINIVIG,',
'            out_dFecFinVig          => :P1000_FECFINVIG,',
'            out_cDescEndoso         => :P1000_DESCENDOSO,',
'            -- Control de Errores',
'            cShowError              => :P1000_SHOW_ERROR',
'        );',
'',
'    IF :P1000_SHOW_ERROR IS NOT NULL THEN',
'        IF :P1000_FECINIVIG IS NULL THEN',
'            :P1000_FECINIVIG := vardFecIniVig;',
'        END IF;',
'',
'        IF :P1000_FECFINVIG IS NULL THEN',
'            :P1000_FECFINVIG := vardFecFinVig;',
'        END IF;',
'    END IF;',
'END;'))
,p_attribute_02=>'P1000_IDPOLIZA,P1000_IDETPOL,P1000_MOTIVO_ENDOSO,P1000_CHECKFECHAVIGINI,P1000_CHECKFECHAVIGFIN,P1000_NFECHVIGINI,P1000_NFECHVIGFIN,P1000_NUMNCF,P1000_CHECKFECHAVIGINID,P1000_CHECKFECHAVIGFIND,P1000_NFECHVIGINID,P1000_NFECHVIGFIND,P1000_IDENDOSO,P1000'
