wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623766311296241494)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_PRE-INSERT_ENDOSO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nIdEndoso  NUMBER;',
'    nIDetPol   NUMBER;',
'BEGIN',
'',
'    :P1000_SUMA_ASEG_LOCAL      := REGEXP_REPLACE(:P1000_SUMA_ASEG_LOCAL, ''[$,]'', '''');',
'    :P1000_SUMA_ASEG_MONEDA     := REGEXP_REPLACE(:P1000_SUMA_ASEG_MONEDA, ''[$,]'', '''');',
'    :P1000_PRIMA_NETA_LOCAL     := REGEXP_REPLACE(:P1000_PRIMA_NETA_LOCAL, ''[$,]'', '''');',
'    :P1000_PRIMA_NETA_MONEDA    := REGEXP_REPLACE(:P1000_PRIMA_NETA_MONEDA, ''[$,]'', '''');',
'    ',
'    SELECT NVL(MAX(IdEndoso),0) + 1',
'        INTO nIdEndoso',
'        FROM ENDOSOS',
'        WHERE IdPoliza = :P1000_IDPOLIZA;',
'',
'    :P1000_IDENDOSO := nIdEndoso;',
'',
'    IF :P1000_INDCALCDERECHOEMIS IS NULL THEN',
'        :P1000_INDCALCDERECHOEMIS := ''N'';',
'    END IF;',
'    ',
'    IF :P1000_TIPOENDOSO IN (''ESV'',''ESVTL'',''APS'') THEN',
'',
'        UPDATE DETALLE_ENDOSO_SV',
'            SET IdEndoso = :P1000_IDENDOSO',
'            WHERE IdPoliza = :P1000_IDPOLIZA',
'            AND IdEndoso IS NULL;',
'',
'        BEGIN',
'            SELECT NVL(MIN(IDetPol),1)',
'                INTO nIDetPol',
'                FROM DETALLE_POLIZA',
'                WHERE CodCia     = :P1000_CODCIA',
'                AND IdPoliza     = :P1000_IDPOLIZA',
'                AND StsDetalle   IN (''EMI'',''REN'');',
'        EXCEPTION',
'            WHEN NO_DATA_FOUND THEN',
'                nIDetPol := 1;',
'        END;',
'',
'    END IF;',
'',
unistr('    -- si no se asigna subgrupo se asignar\00E1 el valor m\00EDnimo del subgrupo'),
'    IF :P1000_IDETPOL IS NULL THEN',
'        :P1000_IDETPOL := nIDetPol;',
'    END IF;',
'',
'    :P1000_SUMA_ASEG_LOCAL  := NVL(:P1000_SUMA_ASEG_MONEDA,0) * NVL(:P1000_TASA_CAMBIO,1);',
'    :P1000_PRIMA_NETA_LOCAL := NVL(:P1000_PRIMA_NETA_MONEDA,0) * NVL(:P1000_TASA_CAMBIO,1);',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(622709569868221322)
,p_internal_uid=>52189104712382809
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623766559565241496)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_PRE-UPDATE_ENDOSO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  cTextoEndoso Endoso_Txt_Det.Texto%TYPE;',
'BEGIN',
'',
'    :P1000_SUMA_ASEG_LOCAL      := REGEXP_REPLACE(:P1000_SUMA_ASEG_LOCAL, ''[$,]'', '''');',
'    :P1000_SUMA_ASEG_MONEDA     := REGEXP_REPLACE(:P1000_SUMA_ASEG_MONEDA, ''[$,]'', '''');',
'    :P1000_PRIMA_NETA_LOCAL     := REGEXP_REPLACE(:P1000_PRIMA_NETA_LOCAL, ''[$,]'', '''');',
'    :P1000_PRIMA_NETA_MONEDA    := REGEXP_REPLACE(:P1000_PRIMA_NETA_MONEDA, ''[$,]'', '''');',
'    ',
'  -- Recalcular importes locales',
'  :P1000_SUMA_ASEG_LOCAL   := NVL(:P1000_SUMA_ASEG_MONEDA,0) * NVL(:P1000_TASA_CAMBIO,1);',
'  :P1000_PRIMA_NETA_LOCAL  := NVL(:P1000_PRIMA_NETA_MONEDA,0) * NVL(:P1000_TASA_CAMBIO,1);',
'',
'  -- Caso especial EAAF: insertar texto de endoso',
'  IF :P1000_TIPOENDOSO IN (''EAAF'') THEN',
'    SELECT TD.Texto',
'    INTO cTextoEndoso',
'    FROM Endoso_Txt_Enc TE',
'    JOIN Endoso_Txt_Det TD',
'        ON TE.CodCia     = TD.CodCia',
'        AND TE.CodEndoso  = TD.CodEndoso',
'    WHERE TE.CodEndoso   = ''AJUAPORTE''',
'    AND TE.IndUsoTexto = ''ENDOSO''',
'    AND TE.Estado      = ''ACTIVO'';',
'',
'    OC_ENDOSO_TEXTO.INSERTA(:P1000_IDPOLIZA, :P1000_IDENDOSO, cTextoEndoso);',
'  END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(622709491481221321)
,p_internal_uid=>52189352981382811
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623766745195241498)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_PREDELETE_ENDOSO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  -- Detalle: COBERTURAS',
'  DELETE FROM COBERTURAS C',
'   WHERE C.IDPOLIZA = :P1000_IDPOLIZA',
'     AND C.IDETPOL  = :P1000_IDETPOL',
'     AND C.IDENDOSO = :P1000_IDENDOSO;',
'',
'  -- Detalle: DETALLE_ENDOSO_SV',
'  DELETE FROM DETALLE_ENDOSO_SV E',
'   WHERE E.IDPOLIZA = :P1000_IDPOLIZA',
'     AND E.IDENDOSO = :P1000_IDENDOSO;',
'',
'  -- Detalle: ENDOSO_TEXTO',
'  DELETE FROM ENDOSO_TEXTO E',
'   WHERE E.IDPOLIZA = :P1000_IDPOLIZA',
'     AND E.IDENDOSO = :P1000_IDENDOSO;',
'',
'  -- Limpieza adicional por tipo de endoso',
'  IF :P1000_TIPOENDOSO = ''EXA'' THEN',
'',
'    DELETE COBERTURA_ASEG',
'     WHERE IdPoliza = :P1000_IDPOLIZA',
'       AND IdEndoso = :P1000_IDENDOSO',
'       AND Cod_Asegurado IN (',
'            SELECT Cod_Asegurado',
'              FROM ASEGURADO_CERTIFICADO',
'             WHERE IdPoliza      = :P1000_IDPOLIZA',
'               AND IdEndosoExclu = :P1000_IDENDOSO',
'               AND CodCia        = :P1000_CODCIA',
'          );',
'',
'    UPDATE ASEGURADO_CERTIFICADO',
'       SET FecAnulExclu   = NULL,',
'           MotivAnulExclu = NULL,',
'           IdEndosoExclu  = NULL',
'     WHERE IdPoliza      = :P1000_IDPOLIZA',
'       AND IdEndosoExclu = :P1000_IDENDOSO',
'       AND CodCia        = :P1000_CODCIA;',
'',
'  ELSE',
'',
'    DELETE COBERTURA_ASEG',
'     WHERE IdPoliza = :P1000_IDPOLIZA',
'       AND IdEndoso = :P1000_IDENDOSO',
'       AND Cod_Asegurado IN (',
'            SELECT Cod_Asegurado',
'              FROM ASEGURADO_CERTIFICADO',
'             WHERE IdPoliza      = :P1000_IDPOLIZA',
'               AND IdEndosoExclu = :P1000_IDENDOSO',
'               AND CodCia        = :P1000_CODCIA',
'          );',
'',
'    DELETE COBERT_ACT_ASEG',
'     WHERE IdPoliza = :P1000_IDPOLIZA',
'       AND IdEndoso = :P1000_IDENDOSO',
'       AND Cod_Asegurado IN (',
'            SELECT Cod_Asegurado',
'              FROM ASEGURADO_CERTIFICADO',
'             WHERE IdPoliza      = :P1000_IDPOLIZA',
'               AND IdEndosoExclu = :P1000_IDENDOSO',
'               AND CodCia        = :P1000_CODCIA',
'          );',
'',
'    DELETE ASISTENCIAS_ASEGURADO',
'     WHERE IdPoliza = :P1000_IDPOLIZA',
'       AND IdEndoso = :P1000_IDENDOSO',
'       AND Cod_Asegurado IN (',
'            SELECT Cod_Asegurado',
'              FROM ASEGURADO_CERTIFICADO',
'             WHERE IdPoliza      = :P1000_IDPOLIZA',
'               AND IdEndosoExclu = :P1000_IDENDOSO',
'               AND CodCia        = :P1000_CODCIA',
'          );',
'',
'    DELETE ASEGURADO_CERTIFICADO',
'     WHERE IdPoliza      = :P1000_IDPOLIZA',
'       AND IdEndosoExclu = :P1000_IDENDOSO',
'       AND CodCia        = :P1000_CODCIA;',
'',
'  END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(622709325369221320)
,p_internal_uid=>52189538611382813
);
