wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623768226975241513)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_POSTINSERT_ENDOSO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  cTexto  VARCHAR2(4000);',
'BEGIN',
'  cTexto := NULL;',
'',
'    IF :P1000_TIPOENDOSO = ''CFP'' THEN',
'        cTexto :=',
'            ''Cambio de Forma de Pago '' || OC_PLAN_DE_PAGOS.DESCRIPCION_PLAN(',
'               :P1000_CODCIA, :P1000_CODEMPRESA,',
'               OC_POLIZAS.PLAN_DE_PAGOS(:P1000_CODCIA, :P1000_CODEMPRESA, :P1000_IDPOLIZA))',
'          || '' A Forma de Pago ''',
'          || OC_PLAN_DE_PAGOS.DESCRIPCION_PLAN(:P1000_CODCIA, :P1000_CODEMPRESA, :P1000_CODPLANPAGO);',
'',
'    ELSIF :P1000_TIPOENDOSO IN (''EAAF'') THEN',
'        SELECT TD.Texto',
'        INTO cTexto',
'        FROM Endoso_Txt_Enc TE',
'        JOIN Endoso_Txt_Det TD',
'            ON TE.CodCia    = TD.CodCia',
'            AND TE.CodEndoso = TD.CodEndoso',
'        WHERE TE.CodEndoso   = ''AJUAPORTE''',
'        AND TE.IndUsoTexto = ''ENDOSO''',
'        AND TE.Estado      = ''ACTIVO'';',
'    END IF;',
'',
'    IF :P1000_TIPOENDOSO = ''ESVTL'' THEN',
'           SELECT Texto',
'             INTO cTexto',
'             FROM	ENDOSO_TXT_DET',
'            WHERE CodEndoso = :P1000_CODENDOSO_TXT;   ',
'            ',
'            OC_ENDOSO_TEXTO.INSERTA(:P1000_IDPOLIZA, :P1000_IDENDOSO, ''Endoso Sin Valor de Texto Libre de '' ||cTexto);',
'',
'    END IF;',
'',
'    IF cTexto IS NOT NULL AND :P1000_TIPOENDOSO IN (''ESV'',''APS'',''CFP'',''EAAF'') THEN',
'        OC_ENDOSO_TEXTO.INSERTA(:P1000_IDPOLIZA, :P1000_IDENDOSO, cTexto);',
'    END IF;',
'',
'    if cTexto is null AND :P1000_TIPOENDOSO IN (''ESV'',''ESVTL'') THEN',
'        OC_ENDOSO_TEXTO.INSERTA(:P1000_IDPOLIZA, :P1000_IDENDOSO, null);',
'    END IF;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(622709569868221322)
,p_internal_uid=>52191020391382828
);
