wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623765909530241490)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AsignarValoresPoliza'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    BEGIN',
'        SELECT STSPOLIZA, NUMPOLUNICO, CODCLIENTE,',
'               FECINIVIG, FECFINVIG, COD_MONEDA -- , CODPLANPAGO',
'        INTO   :P1000_STSPOLIZA_POLIZA, :P1000_NUMPOLUNICO_POLIZA, :P1000_CODCLIENTE_POLIZA,',
'               :P1000_FECINIVIG_POLIZA, :P1000_FECFINVIG_POLIZA, :P1000_COD_MONEDA_POLIZA -- , :P1000_CODPLANPAGO',
'        FROM   POLIZAS',
'        WHERE  CODCIA = 1',
'        AND    IDPOLIZA = :P1000_IDPOLIZA;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            :P1000_STSPOLIZA_POLIZA    := NULL;',
'            :P1000_NUMPOLUNICO_POLIZA := NULL;',
'            :P1000_CODCLIENTE_POLIZA  := NULL;',
'            :P1000_FECINIVIG_POLIZA   := NULL;',
'            :P1000_FECFINVIG_POLIZA   := NULL;',
'            :P1000_COD_MONEDA_POLIZA  := NULL;',
'    END;',
'',
'    BEGIN',
'        SELECT INDASEGMODELO',
'        INTO   :P1000_INDASEGMODELO_DETALLE_POLIZA',
'        FROM   DETALLE_POLIZA',
'        WHERE  CODCIA = 1',
'        AND    IDPOLIZA = :P1000_IDPOLIZA;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND  THEN :P1000_INDASEGMODELO_DETALLE_POLIZA := ''N'';',
'        WHEN TOO_MANY_ROWS THEN :P1000_INDASEGMODELO_DETALLE_POLIZA := ''S'';',
'',
'    END;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P1000_IDENDOSO'
,p_process_when_type=>'ITEM_IS_NULL'
,p_internal_uid=>52188702946382805
,p_process_comment=>unistr('Asignaci\00F3n de valores de p\00F3liza para realizaci\00F3n de procesos y validaciones que requieran informaci\00F3n de la p\00F3liza.')
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(623767102394241501)
,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Post-Query'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  cTipoAdministracion  varchar2(20);',
'BEGIN',
'  -- 1) Total de asegurados ',
'  :P1000_TOTASEGURADOS := OC_ENDOSO.TOTAL_ASEGURADOS(:P1000_CODCIA,:P1000_CODEMPRESA,:P1000_IDPOLIZA,:P1000_IDETPOL,:P1000_IDENDOSO);',
'',
'  -- 2) TipoAdministracion ',
'    BEGIN',
'        SELECT TipoAdministracion',
'          INTO cTipoAdministracion',
'          FROM POLIZAS',
'         WHERE CodCia     = :P1000_CODCIA',
'           AND CodEmpresa = :P1000_CODEMPRESA',
'           AND IdPoliza   = :P1000_IDPOLIZA;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'          cTipoAdministracion := NULL;',
'    END;',
'',
unistr('  -- 3) Datos de detalle p\00F3liza que NO son cat\00E1logo'),
'    BEGIN',
'        SELECT  IdTipoSeg,          PlanCob,        OC_ASEGURADO.NOMBRE_ASEGURADO(CodCia, CodEmpresa, Cod_Asegurado)',
'        INTO    :P1000_IDTIPOSEG,   :P1000_PLANCOB, :P1000_NOMASEGURADO   ',
'        FROM DETALLE_POLIZA',
'    WHERE CodCia     = :P1000_CODCIA',
'        AND CodEmpresa = :P1000_CODEMPRESA',
'        AND IdPoliza   = :P1000_IDPOLIZA',
'        AND IDetPol    = :P1000_IDETPOL;',
'    EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P1000_IDTIPOSEG    := NULL;',
'        :P1000_PLANCOB      := NULL;',
'        :P1000_NOMASEGURADO := NULL;',
'    END;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>52189895810382816
);
end;
