wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(562091527040162468)
,p_plug_name=>'IG_POLIZAS'
,p_parent_plug_id=>wwv_flow_imp.id(562088238374162435)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cQry VARCHAR2(32767);',
'BEGIN',
'',
'    IF :P1100_LPNJ_TIPO_DOC_IDENTIFICACION IS NULL',
'       OR :P1100_LPNJ_NUM_DOC_IDENTIFICACION IS NULL THEN',
'',
'        RETURN q''[',
'            SELECT',
'                   CAST(NULL AS VARCHAR2(50))  AS NUMPOLUNICO,',
'                   CAST(NULL AS NUMBER)        AS IDPOLIZA,',
'                   CAST(NULL AS NUMBER)        AS IDETPOL,',
'                   CAST(NULL AS NUMBER)        AS COD_ASEGURADO,',
'                   CAST(NULL AS VARCHAR2(50))  AS IDTIPOSEG,',
'                   CAST(NULL AS VARCHAR2(50))  AS PLANCOB,',
'                   CAST(NULL AS DATE)          AS FECINIVIG,',
'                   CAST(NULL AS DATE)          AS FECFINVIG,',
'                   CAST(NULL AS DATE)          AS FECPAGO,',
'                   CAST(NULL AS VARCHAR2(200)) AS CDESCSTATUS,',
'                   CAST(NULL AS VARCHAR2(50))  AS STPOLIZA,',
'                   CAST(NULL AS VARCHAR2(50))  AS INDPOLCOL,',
'                   CAST(NULL AS VARCHAR2(50))  AS NUMPOLREF',
'              FROM DUAL',
'             WHERE 1 = 0',
'        ]'';',
'',
'    END IF;',
'',
'    cQry := q''[',
'',
'SELECT DISTINCT',
'       P.NUMPOLUNICO,',
'       DP.IDPOLIZA,',
'       DP.IDETPOL,',
'       DP.COD_ASEGURADO,',
'       DP.IDTIPOSEG,',
'       DP.PLANCOB,',
'       DP.FECINIVIG,',
'       DP.FECFINVIG,',
'',
'       CASE',
'           WHEN P.INDFACTURAPOL = ''S'' THEN',
'                (',
'                    SELECT MAX(F.FECFINVIG)',
'                      FROM FACTURAS F',
'                     WHERE F.CODCIA   = P.CODCIA',
'                       AND F.IDPOLIZA = P.IDPOLIZA',
'                       AND F.STSFACT  = ''PAG''',
'                )',
'           ELSE',
'                (',
'                    SELECT MAX(F.FECFINVIG)',
'                      FROM FACTURAS F',
'                     WHERE F.CODCIA   = P.CODCIA',
'                       AND F.IDPOLIZA = P.IDPOLIZA',
'                       AND F.IDETPOL  = DP.IDETPOL',
'                       AND F.STSFACT  = ''PAG''',
'                )',
'       END AS FECPAGO,',
'',
'       OC_VALORES_DE_LISTAS.BUSCA_LVALOR(',
'            ''ESTADOS'',',
'            DP.STSDETALLE',
'       ) AS CDESCSTATUS,',
'',
'       CASE',
'           WHEN (',
'                CASE',
'                    WHEN P.INDFACTURAPOL = ''S'' THEN',
'                         (',
'                             SELECT MAX(F.FECFINVIG)',
'                               FROM FACTURAS F',
'                              WHERE F.CODCIA   = P.CODCIA',
'                                AND F.IDPOLIZA = P.IDPOLIZA',
'                                AND F.STSFACT  = ''PAG''',
'                         )',
'                    ELSE',
'                         (',
'                             SELECT MAX(F.FECFINVIG)',
'                               FROM FACTURAS F',
'                              WHERE F.CODCIA   = P.CODCIA',
'                                AND F.IDPOLIZA = P.IDPOLIZA',
'                                AND F.IDETPOL  = DP.IDETPOL',
'                                AND F.STSFACT  = ''PAG''',
'                         )',
'                END',
'           ) IS NOT NULL THEN ''PAGADA''',
'',
'           WHEN P.STSPOLIZA = ''ANU'' THEN ''ANULADA''',
'',
'           WHEN P.STSPOLIZA IN (''EMI'',''REN'',''XRE'') THEN ''PENDIENTE''',
'',
'           ELSE P.STSPOLIZA',
'       END AS STPOLIZA,',
'',
'       CASE',
'           WHEN P.INDPOLCOL = ''N'' THEN ''INDIVIDUAL''',
'           WHEN P.INDPOLCOL = ''S'' THEN ''COLECTIVA''',
'           ELSE NULL',
'       END AS INDPOLCOL,',
'',
'       P.NUMPOLREF',
'',
'FROM POLIZAS P,',
'     DETALLE_POLIZA DP,',
'     AGENTE_POLIZA AP',
'',
'WHERE DP.IDPOLIZA   = P.IDPOLIZA',
'  AND DP.CODEMPRESA = P.CODEMPRESA',
'  AND DP.CODCIA     = P.CODCIA',
'',
'  AND AP.CODCIA        = P.CODCIA',
'  AND AP.IDPOLIZA      = P.IDPOLIZA',
'  AND AP.IND_PRINCIPAL = ''S''',
'',
'  AND P.CODCIA = :P1100_CODCIA',
'',
'  AND (',
'         :P1100_BUSQ_IDPOLIZA IS NULL',
'      OR P.IDPOLIZA = :P1100_BUSQ_IDPOLIZA',
'  )',
'',
'  AND (',
'         :P1100_BUSQ_NUMPOLREF IS NULL',
'      OR P.NUMPOLREF = :P1100_BUSQ_NUMPOLREF',
'  )',
'',
'  AND (',
'         :P1100_BUSQ_NUMPOLUNICO IS NULL',
'      OR P.NUMPOLUNICO = :P1100_BUSQ_NUMPOLUNICO',
'  )',
'',
'  AND (P.IDPOLIZA, DP.IDETPOL) IN (',
'',
'        SELECT DISTINCT',
'               AC.IDPOLIZA,',
'               AC.IDETPOL',
'          FROM ASEGURADO A,',
'               ASEGURADO_CERTIFICADO AC',
'         WHERE AC.CODCIA = A.CODCIA',
'           AND AC.COD_ASEGURADO = A.COD_ASEGURADO',
'           AND AC.CODCIA = :P1100_CODCIA',
'           AND A.TIPO_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_TIPO_DOC_IDENTIFICACION',
'           AND A.NUM_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_NUM_DOC_IDENTIFICACION',
'',
'        UNION',
'',
'        SELECT DISTINCT',
'               AC.IDPOLIZA,',
'               AC.IDETPOL',
'          FROM ASEGURADO A,',
'               ASEGURADO_CERT AC',
'         WHERE AC.CODCIA = A.CODCIA',
'           AND AC.COD_ASEGURADO = A.COD_ASEGURADO',
'           AND AC.CODCIA = :P1100_CODCIA',
'           AND A.TIPO_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_TIPO_DOC_IDENTIFICACION',
'           AND A.NUM_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_NUM_DOC_IDENTIFICACION',
'',
'        UNION',
'',
'        SELECT DISTINCT',
'               D.IDPOLIZA,',
'               D.IDETPOL',
'          FROM ASEGURADO A,',
'               DETALLE_POLIZA D',
'         WHERE OC_ASEGURADO_CERTIFICADO.TIENE_ASEGURADOS(',
'                   D.CODCIA,',
'                   D.IDPOLIZA,',
'                   D.IDETPOL,',
'                   0',
'               ) = ''N''',
'           AND D.CODCIA = A.CODCIA',
'           AND D.COD_ASEGURADO = A.COD_ASEGURADO',
'           AND D.CODCIA = :P1100_CODCIA',
'           AND A.TIPO_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_TIPO_DOC_IDENTIFICACION',
'           AND A.NUM_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_NUM_DOC_IDENTIFICACION',
'',
'        UNION',
'',
'        SELECT DISTINCT',
'               D.IDPOLIZA,',
'               D.IDETPOL',
'          FROM CLIENTES C,',
'               POLIZAS P2,',
'               DETALLE_POLIZA D',
'         WHERE D.IDPOLIZA = P2.IDPOLIZA',
'           AND D.CODCIA   = P2.CODCIA',
'           AND P2.CODCLIENTE = C.CODCLIENTE',
'           AND P2.CODCIA = :P1100_CODCIA',
'           AND C.TIPO_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_TIPO_DOC_IDENTIFICACION',
'           AND C.NUM_DOC_IDENTIFICACION =',
'               :P1100_LPNJ_NUM_DOC_IDENTIFICACION',
'  )',
'',
'ORDER BY DP.IDPOLIZA DESC,',
'         DP.IDETPOL ASC',
'',
']'';',
'',
'    RETURN cQry;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        RETURN ''',
'            SELECT',
'                   CAST(NULL AS VARCHAR2(50))  AS NUMPOLUNICO,',
'                   CAST(NULL AS NUMBER)        AS IDPOLIZA,',
'                   CAST(NULL AS NUMBER)        AS IDETPOL,',
'                   CAST(NULL AS NUMBER)        AS COD_ASEGURADO,',
'                   CAST(NULL AS VARCHAR2(50))  AS IDTIPOSEG,',
'                   CAST(NULL AS VARCHAR2(50))  AS PLANCOB,',
'                   CAST(NULL AS DATE)          AS FECINIVIG,',
'                   CAST(NULL AS DATE)          AS FECFINVIG,',
'                   CAST(NULL AS DATE)          AS FECPAGO,',
'                   '''''' || REPLACE(SQLERRM,'''''''','''''''''''') || '''''' AS CDESCSTATUS,',
'                   CAST(NULL AS VARCHAR2(50))  AS STPOLIZA,',
'                   CAST(NULL AS VARCHAR2(50))  AS INDPOLCOL,',
'                   CAST(NULL AS VARCHAR2(50))  AS NUMPOLREF',
'              FROM DUAL'';',
'',
'END;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1100_LPNJ_TIPO_DOC_IDENTIFICACION, P1100_LPNJ_NUM_DOC_IDENTIFICACION, P1100_CODCIA, P1100_BUSQ_IDPOLIZA, P1100_BUSQ_NUMPOLUNICO, P1100_BUSQ_NUMPOLREF'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'IG_POLIZAS'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
