wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(562088634632162439)
,p_plug_name=>'IG_PNJ_ASEGURADOS'
,p_parent_plug_id=>wwv_flow_imp.id(562250119665481539)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cQry   VARCHAR2(32767);',
'    cWhere VARCHAR2(32767);',
'',
'    PROCEDURE add_and IS',
'    BEGIN',
'        IF cWhere IS NOT NULL THEN',
'            cWhere := cWhere || '' AND '';',
'        END IF;',
'    END;',
'BEGIN',
'    cQry :=',
'''SELECT DISTINCT',
'        PN.TIPO_DOC_IDENTIFICACION,',
'        PN.NUM_DOC_IDENTIFICACION,',
'        PN.TIPO_PERSONA,',
'        TRIM(PN.NOMBRE) || '''' '''' ||',
'        TRIM(PN.APELLIDO_PATERNO) || '''' '''' ||',
'        TRIM(PN.APELLIDO_MATERNO) AS NOMBRE',
'   FROM PERSONA_NATURAL_JURIDICA PN'';',
'',
'    IF :P1100_BUSQ_NOMBRE_PARCIAL IS NOT NULL THEN',
'        add_and;',
'        cWhere := cWhere ||',
'        ''UPPER(TRIM(PN.NOMBRE) || '''' '''' || TRIM(PN.APELLIDO_PATERNO) || '''' '''' || TRIM(PN.APELLIDO_MATERNO)) LIKE ''''%'' ||',
'        UPPER(REPLACE(:P1100_BUSQ_NOMBRE_PARCIAL, '''''''', '''''''''''')) || ''%'''''';',
'    END IF;',
'',
'    IF :P1100_BUSQ_NOMBRE IS NOT NULL THEN',
'        add_and;',
'        cWhere := cWhere ||',
'        ''UPPER(PN.NOMBRE) LIKE ''''%'' ||',
'        UPPER(REPLACE(:P1100_BUSQ_NOMBRE, '''''''', '''''''''''')) || ''%'''''';',
'    END IF;',
'',
'    IF :P1100_BUSQ_APELLIDO_PATERNO IS NOT NULL THEN',
'        add_and;',
'        cWhere := cWhere ||',
'        ''UPPER(PN.APELLIDO_PATERNO) LIKE ''''%'' ||',
'        UPPER(REPLACE(:P1100_BUSQ_APELLIDO_PATERNO, '''''''', '''''''''''')) || ''%'''''';',
'    END IF;',
'',
'    IF :P1100_BUSQ_APELLIDO_MATERNO IS NOT NULL THEN',
'        add_and;',
'        cWhere := cWhere ||',
'        ''UPPER(PN.APELLIDO_MATERNO) LIKE ''''%'' ||',
'        UPPER(REPLACE(:P1100_BUSQ_APELLIDO_MATERNO, '''''''', '''''''''''')) || ''%'''''';',
'    END IF;',
'',
'    IF :P1100_BUSQ_IDPOLIZA IS NOT NULL THEN',
'        add_and;',
'        cWhere := cWhere || ''',
'EXISTS (',
'    SELECT 1',
'      FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'     WHERE AC.CODCIA = A.CODCIA',
'       AND AC.COD_ASEGURADO = A.COD_ASEGURADO',
'       AND AC.IDPOLIZA = '' || TO_NUMBER(:P1100_BUSQ_IDPOLIZA) || ''',
'       AND AC.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND AC.IDETPOL > 0',
'       AND AC.COD_ASEGURADO > 0',
'       AND A.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND A.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
'',
'    UNION',
'',
'    SELECT 1',
'      FROM ASEGURADO A, ASEGURADO_CERT AC',
'     WHERE AC.CODCIA = A.CODCIA',
'       AND AC.COD_ASEGURADO = A.COD_ASEGURADO',
'       AND AC.IDPOLIZA = '' || TO_NUMBER(:P1100_BUSQ_IDPOLIZA) || ''',
'       AND AC.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND AC.IDETPOL > 0',
'       AND AC.COD_ASEGURADO > 0',
'       AND A.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND A.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
'',
'    UNION',
'',
'    SELECT 1',
'      FROM ASEGURADO A, DETALLE_POLIZA D',
'     WHERE OC_ASEGURADO_CERTIFICADO.TIENE_ASEGURADOS(D.CODCIA, D.IDPOLIZA, D.IDETPOL, 0) = ''''N''''',
'       AND D.CODCIA = A.CODCIA',
'       AND D.COD_ASEGURADO = A.COD_ASEGURADO',
'       AND D.IDPOLIZA = '' || TO_NUMBER(:P1100_BUSQ_IDPOLIZA) || ''',
'       AND D.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND D.IDETPOL > 0',
'       AND A.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND A.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
'',
'    UNION',
'',
'    SELECT 1',
'      FROM POLIZAS P, CLIENTES C',
'     WHERE P.IDPOLIZA = '' || TO_NUMBER(:P1100_BUSQ_IDPOLIZA) || ''',
'       AND P.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND C.CODCLIENTE = P.CODCLIENTE',
'       AND C.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND C.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
')'';',
'    END IF;',
'',
'    IF :P1100_BUSQ_NUMPOLUNICO IS NOT NULL THEN',
'        add_and;',
'        cWhere := cWhere || ''',
'EXISTS (',
'    SELECT 1',
'      FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC, POLIZAS P',
'     WHERE P.NUMPOLUNICO = '''''' || REPLACE(:P1100_BUSQ_NUMPOLUNICO, '''''''', '''''''''''') || ''''''',
'       AND P.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND P.IDPOLIZA = AC.IDPOLIZA',
'       AND P.CODCIA = A.CODCIA',
'       AND AC.CODCIA = A.CODCIA',
'       AND AC.COD_ASEGURADO = A.COD_ASEGURADO',
'       AND A.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND A.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
'',
'    UNION',
'',
'    SELECT 1',
'      FROM ASEGURADO A, ASEGURADO_CERT AC, POLIZAS P',
'     WHERE P.NUMPOLUNICO = '''''' || REPLACE(:P1100_BUSQ_NUMPOLUNICO, '''''''', '''''''''''') || ''''''',
'       AND P.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND P.IDPOLIZA = AC.IDPOLIZA',
'       AND P.CODCIA = AC.CODCIA',
'       AND AC.CODCIA = A.CODCIA',
'       AND AC.COD_ASEGURADO = A.COD_ASEGURADO',
'       AND A.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND A.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
'',
'    UNION',
'',
'    SELECT 1',
'      FROM ASEGURADO A, DETALLE_POLIZA D, POLIZAS P',
'     WHERE P.NUMPOLUNICO = '''''' || REPLACE(:P1100_BUSQ_NUMPOLUNICO, '''''''', '''''''''''') || ''''''',
'       AND P.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND P.IDPOLIZA = D.IDPOLIZA',
'       AND P.CODCIA = D.CODCIA',
'       AND OC_ASEGURADO_CERTIFICADO.TIENE_ASEGURADOS(D.CODCIA, D.IDPOLIZA, D.IDETPOL, 0) = ''''N''''',
'       AND D.CODCIA = A.CODCIA',
'       AND D.COD_ASEGURADO = A.COD_ASEGURADO',
'       AND A.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND A.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
'',
'    UNION',
'',
'    SELECT 1',
'      FROM POLIZAS P, CLIENTES C',
'     WHERE P.NUMPOLUNICO = '''''' || REPLACE(:P1100_BUSQ_NUMPOLUNICO, '''''''', '''''''''''') || ''''''',
'       AND P.CODCIA = '' || TO_NUMBER(:P1100_CODCIA) || ''',
'       AND C.CODCLIENTE = P.CODCLIENTE',
'       AND C.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'       AND C.NUM_DOC_IDENTIFICACION = PN.NUM_DOC_IDENTIFICACION',
')'';',
'    END IF;',
'',
'    IF cWhere IS NOT NULL THEN',
'        RETURN cQry || '' WHERE '' || cWhere;',
'    ELSE',
'        RETURN cQry || '' WHERE 1 = 0'';',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''SELECT',
'                    CAST(NULL AS VARCHAR2(30))   AS TIPO_DOC_IDENTIFICACION,',
'                    CAST(NULL AS VARCHAR2(50))   AS NUM_DOC_IDENTIFICACION,',
'                    CAST(NULL AS VARCHAR2(30))   AS TIPO_PERSONA,',
'                    CAST(NULL AS VARCHAR2(4000)) AS NOMBRE',
'                FROM DUAL',
'                WHERE 1 = 0'';',
'END;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1100_BUSQ_NOMBRE_PARCIAL, P1100_BUSQ_NOMBRE, P1100_BUSQ_APELLIDO_PATERNO, P1100_BUSQ_APELLIDO_MATERNO, P1100_BUSQ_IDPOLIZA, P1100_BUSQ_NUMPOLUNICO, P1100_CODCIA'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
