wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(544154890842309352)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PR_imprimir_pdf'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob  BLOB;',
'    l_size  INTEGER;',
'    l_nombre varchar2(5000);',
'BEGIN',
'    apex_debug.info(''ingresa a pagina 1390 con idpoliza: '' || :P1390_ID_REPORTE);',
'',
'    SELECT ARCHIVO, DBMS_LOB.GETLENGTH(ARCHIVO), NOMBRE',
'      INTO l_blob, l_size, l_nombre',
'      FROM REPORTES_PDF',
'     WHERE ID = TO_NUMBER(:P1390_ID_REPORTE);',
'',
'    IF l_size IS NULL OR l_size <= 54 THEN',
'        APEX_ERROR.ADD_ERROR(',
unistr('            p_message          => ''El archivo ZIP est\00E1 vac\00EDo, no se puede descargar.'','),
'            p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'    ELSE',
'        OWA_UTIL.MIME_HEADER(''application/zip'', FALSE);',
'        HTP.P(''Content-Length: '' || l_size);',
'        HTP.P(''Content-Disposition: attachment; filename=''|| l_nombre ||''.zip'');',
'        OWA_UTIL.HTTP_HEADER_CLOSE;',
'        WPG_DOCLOAD.DOWNLOAD_FILE(l_blob);',
'        APEX_APPLICATION.STOP_APEX_ENGINE;',
'    END IF;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        APEX_ERROR.ADD_ERROR(',
unistr('            p_message          => ''No se encontr\00F3 el archivo.'','),
'            p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>105063194011237829
);
end;
