wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(594076518201952203)
,p_plug_name=>'Actualiza_emision_asegurados'
,p_parent_plug_id=>wwv_flow_imp.id(593348979276320947)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       a.CodCia        AS compa,',
'       a.IdPoliza      AS Poliza,',
'       COUNT(a.Cod_Asegurado) AS registros,',
'       w.Descober2, ',
'       OC_ACTUSUMAS.DESC_DE_SEGURO (a.codcia,a.idpoliza,a.idetpol) desc2,',
'       APEX_ITEM.TEXT(1, NULL, 10, 10 , ''class="factor-input" placeholder="%" '') AS FACTOR_PORCENTAJE, ',
'       APEX_ITEM.TEXT(2, w.Cober2, 10, 10, ''class="factor" readonly'') AS COBERTURA_HIDDEN,',
'       APEX_ITEM.TEXT(3, a.IDetPol, 10, 10, ''class="factor" readonly'') AS SUBGRUPO_HIDDEN',
'',
'FROM asegurado_certificado a',
'JOIN (',
'        SELECT DISTINCT',
'               h.codcia     AS cia2,',
'               h.idpoliza   AS pol2,',
'               h.idetpol    AS subgrupo,',
'               h.codcobert  AS Cober2,',
'               i.desccobert AS Descober2',
'        FROM cobert_act_aseg h',
'        JOIN coberturas_de_seguros i',
'             ON i.codcia    = h.codcia',
'            AND i.idtiposeg = h.idtiposeg',
'            AND i.plancob   = h.plancob',
'            AND i.codcobert = h.codcobert',
'        WHERE h.codcia   = :P1600_IDCODCIA',
'          AND h.idpoliza = :P1600_IDPOLIZA',
'     ) w',
'     ON w.cia2     = a.codcia',
'    AND w.pol2     = a.idpoliza',
'    AND w.subgrupo = a.idetpol',
'WHERE a.codcia   = :P1600_IDCODCIA',
'  AND a.IdPoliza = :P1600_IDPOLIZA',
'GROUP BY',
'       a.CodCia,',
'       a.IdPoliza,',
'       a.IDetPol,',
'       w.Cober2,',
'       w.Descober2',
'',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1600_IDPOLIZA,P1600_IDCODCIA'
,p_prn_content_disposition=>'ATTACHMENT'
