wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(593977060821876729)
,p_event_id=>wwv_flow_imp.id(593976363747876722)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_mensaje VARCHAR2(200);',
'  Errores NUMBER;',
'  wINDPOLCOL  POLIZAS.INDPOLCOL%TYPE;',
'        Dummy       NUMBER(5);',
'',
'BEGIN ',
'    BEGIN',
'        SELECT a.numpolunico,  nvl(a.fecinivig, a.fecfinvig)  , a.fecfinvig, a.stspoliza, a.fecsts, b.descplan, d.nombre||'' ''||d.apellido_paterno||'' ''||d.apellido_materno, CUANTOSSON',
'        		INTO :P1600_NUMPOLUNICO, ',
'                :P1600_FECINVIG',
'                , :P1600_FECFINVIG, :P1600_STSPOLIZA, :P1600_FECSTS, :P1600_PLANPAGO, :P1600_CONTRATANTE, :P1600_NCERTIFICADOS',
'',
'    	FROM polizas a,',
'    		plan_de_pagos        b,',
'    		clientes             c,',
'    		persona_natural_juridica d,',
'    			(SELECT SUM(COUNT(*)) CUANTOSSON',
'    			          FROM asegurado_certificado             ',
'    			         WHERE CodCia            = :P1600_IDCODCIA',
'    			           AND IdPoliza          = :P1600_IDPOLIZA',
'    			         GROUP BY CodCia,IdPoliza, IDetPol) CUANTOSSON          ',
'    	WHERE a.idpoliza                = :P1600_IDPOLIZA',
'    	AND NVL(a.indpolcol,''N'')      = ''S''',
'    	AND b.codplanpago             = a.codplanpago',
'    	AND c.codcliente              = a.codcliente',
'    	AND d.tipo_doc_identificacion = c.tipo_doc_identificacion',
'    	AND d.num_doc_identificacion  = c.num_doc_identificacion;',
'        EXCEPTION ',
'              WHEN NO_DATA_FOUND THEN',
'                Errores := 2;',
unistr('                v_mensaje := ''La p\00F3liza no tiene Asegurados. Intente con otra p\00F3liza.'';'),
'                ',
'              WHEN OTHERS THEN',
'                Errores := 2;',
unistr('                v_mensaje := ''La p\00F3liza no tiene Asegurados. Intente con otra p\00F3liza.'';'),
'    END;',
'    DECLARE',
'    wINDPOLCOL VARCHAR2(1);',
'BEGIN',
'    -- Primer intento: obtener directamente de POLIZAS',
'    BEGIN',
'        SELECT LTRIM(RTRIM(B.INDPOLCOL)) ',
'        INTO wINDPOLCOL',
'        FROM POLIZAS B                        ',
'        WHERE B.IDPOLIZA = :P1600_IDPOLIZA',
'        AND B.INDPOLCOL IS NOT NULL',
'        AND B.INDPOLCOL IN (''S'',''N'');',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            wINDPOLCOL := NULL;',
'        WHEN TOO_MANY_ROWS THEN',
'            -- En caso de duplicados, tomar el primero',
'            SELECT LTRIM(RTRIM(B.INDPOLCOL)) ',
'            INTO wINDPOLCOL',
'            FROM POLIZAS B                        ',
'            WHERE B.IDPOLIZA = :P1600_IDPOLIZA',
'            AND B.INDPOLCOL IS NOT NULL',
'            AND B.INDPOLCOL IN (''S'',''N'')',
'            AND ROWNUM = 1;',
'    END;',
'    ',
unistr('    -- Segundo intento: obtener mediante joins si no se encontr\00F3'),
'    IF wINDPOLCOL IS NULL THEN',
'        BEGIN ',
'            SELECT DECODE(VL.DESCVALLST, ''INDIVIDUAL'', ''N'', ''S'')',
'            INTO wINDPOLCOL',
'            FROM POLIZAS P,',
'                 DETALLE_POLIZA DP,',
'                 PLAN_COBERTURAS PC,',
'                 VALORES_DE_LISTAS VL',
'            WHERE P.IDPOLIZA = :P1600_IDPOLIZA',
'            AND P.STSPOLIZA IN (''EMI'',''REN'')',
'            AND DP.IDPOLIZA = P.IDPOLIZA',
'            AND DP.IDETPOL = 1 ',
'            AND PC.CODCIA = DP.CODCIA',
'            AND PC.CODEMPRESA = DP.CODEMPRESA',
'            AND PC.IDTIPOSEG = DP.IDTIPOSEG',
'            AND PC.PLANCOB = DP.PLANCOB',
'            AND VL.CODLISTA = ''TIPORAMO''',
'            AND VL.CODVALOR = PC.CODTIPOPLAN',
'            AND ROWNUM = 1; -- Prevenir TOO_MANY_ROWS',
'        EXCEPTION  ',
'            WHEN NO_DATA_FOUND THEN',
'                wINDPOLCOL := NULL;',
'            WHEN OTHERS THEN',
'                wINDPOLCOL := NULL;',
'        END;',
'    END IF;',
'    ',
'    -- Validar y asignar el resultado',
'    IF wINDPOLCOL IS NULL THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''IndPolCol Error en la P\00F3liza '' || :P1600_IDPOLIZA);'),
'    ELSE',
'        IF wINDPOLCOL = ''N'' THEN ',
'            :P1600_TIPO := ''INDIVIDUAL'';',
'        ELSIF wINDPOLCOL = ''S'' THEN ',
'            :P1600_TIPO := ''COLECTIVO'';',
'        ELSE',
unistr('            RAISE_APPLICATION_ERROR(-20002, ''Valor inv\00E1lido de IndPolCol: '' || wINDPOLCOL);'),
'        END IF;',
'        ',
unistr('        -- Actualizar el estado de sesi\00F3n en APEX'),
'        apex_util.set_session_state(''P1600_TIPO'', :P1600_TIPO);',
'    END IF;',
'END;',
'',
'END;'))
,p_attribute_02=>'P1600_IDPOLIZA,P1600_IDCODCIA'
,p_attribute_03=>'P1600_NUMPOLUNICO,P1600_FECFINVIG,P1600_STSPOLIZA,P1600_FECSTS,P1600_PLANPAGO,P1600_CONTRATANTE,P1600_NCERTIFICADOS,P1600_TIPO,P1600_FECINVIG,P1600_IDPOLIZA,P1600_IDCODCIA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
