wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(594720260782222428)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_VALIDA_COLECCIONES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_debug CLOB := '''';',
'BEGIN',
'    v_debug := ''G_F01.COUNT = '' || NVL(APEX_APPLICATION.G_F01.COUNT, 0) || CHR(10);',
'    v_debug := v_debug || ''G_F02.COUNT = '' || NVL(APEX_APPLICATION.G_F02.COUNT, 0) || CHR(10);',
'    v_debug := v_debug || ''G_F03.COUNT = '' || NVL(APEX_APPLICATION.G_F03.COUNT, 0) || CHR(10);',
'    ',
'    FOR i IN 1..LEAST(3, NVL(APEX_APPLICATION.G_F01.COUNT, 0)) LOOP',
'        v_debug := v_debug || ''Fila '' || i || '': '';',
'        v_debug := v_debug || ''F01='' || NVL(APEX_APPLICATION.G_F01(i), ''NULL'') || '', '';',
'        v_debug := v_debug || ''F02='' || NVL(APEX_APPLICATION.G_F02(i), ''NULL'') || '', '';',
'        v_debug := v_debug || ''F03='' || NVL(APEX_APPLICATION.G_F03(i), ''NULL'') || CHR(10);',
'    END LOOP;',
'    ',
'    APEX_ERROR.ADD_ERROR(p_message => v_debug, p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(593974777467876706)
,p_required_patch=>wwv_flow_imp.id(690440983571095281)
,p_internal_uid=>56343725312567327
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(594720837486222434)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_ActSumas'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_factor NUMBER;',
'    v_count NUMBER := 0;',
'    v_count_errors NUMBER := 0;',
'    ',
'    v_cod_cobertura VARCHAR2(10);',
'    v_idetpol NUMBER;',
'    ',
unistr('    -- Auditor\00EDa'),
'    v_user VARCHAR2(30);',
'    v_terminal VARCHAR2(30);',
'    v_fecha VARCHAR2(50);',
'    ',
'BEGIN',
'    SELECT USER, USERENV(''TERMINAL''), TO_CHAR(SYSDATE,''DD/MM/YYYY HH24:MI:SS'')',
'    INTO v_user, v_terminal, v_fecha',
'    FROM DUAL;',
'    ',
'    -- Procesar cada subgrupo-cobertura del reporte',
'    FOR i IN 1..APEX_APPLICATION.G_F01.COUNT LOOP',
'        ',
'        BEGIN',
unistr('            -- VALIDACI\00D3N: Factor debe existir, no estar vac\00EDo Y ser mayor a 0'),
'            IF APEX_APPLICATION.G_F01(i) IS NOT NULL AND ',
'               LENGTH(TRIM(APEX_APPLICATION.G_F01(i))) > 0 AND',
'               TO_NUMBER(APEX_APPLICATION.G_F01(i)) > 0 THEN',
'                ',
'                v_factor := TO_NUMBER(APEX_APPLICATION.G_F01(i));',
'                v_cod_cobertura := APEX_APPLICATION.G_F02(i);',
'                v_idetpol := TO_NUMBER(APEX_APPLICATION.G_F03(i));',
'                ',
'                -- Actualizar todos los asegurados de este subgrupo-cobertura',
'                FOR aseg IN (',
'                    SELECT ac.cod_asegurado,',
'                            DECODE(NVL(caa.sumaaseg_local,0),0,AC.CAMPO1,caa.sumaaseg_local) suma_aseg',
'                           --NVL(NVL(caa.sumaaseg_local,AC.CAMPO1), 0) AS suma_aseg',
'                    FROM asegurado_certificado ac',
'                    JOIN cobert_act_aseg caa',
'                         ON caa.codcia = ac.codcia',
'                        AND caa.idpoliza = ac.idpoliza',
'                        AND caa.idetpol = ac.idetpol',
'                        AND caa.cod_asegurado = ac.cod_asegurado',
'                        AND caa.codcobert = v_cod_cobertura',
'                    WHERE ac.codcia = :P1600_IDCODCIA',
'                      AND ac.idpoliza = :P1600_IDPOLIZA',
'                      AND ac.idetpol = v_idetpol',
'                ) LOOP',
'                    ',
'                    -- Actualizar cobertura del asegurado',
'                    UPDATE cobert_act_aseg',
'                    SET SUMAASEG_LOCAL = DECODE(NVL(SUMAASEG_LOCAL,0),0,aseg.suma_aseg,SUMAASEG_LOCAL),',
'                        SUMAASEG_MONEDA = DECODE(NVL(SUMAASEG_MONEDA,0),0,aseg.suma_aseg,SUMAASEG_MONEDA),',
'                        prima_local = aseg.suma_aseg * v_factor,',
'                        prima_moneda = aseg.suma_aseg * v_factor,',
'                        tasa = v_factor',
'                    WHERE codcia = :P1600_IDCODCIA',
'                      AND idpoliza = :P1600_IDPOLIZA',
'                      AND idetpol = v_idetpol',
'                      AND cod_asegurado = aseg.cod_asegurado',
'                      AND codcobert = v_cod_cobertura;',
'                    ',
'                    IF SQL%ROWCOUNT > 0 THEN',
unistr('                        -- Auditor\00EDa'),
'                        UPDATE asegurado_certificado',
'                        SET campo95 = SUBSTR(campo95 || ''('' || v_factor || ''-'' || v_cod_cobertura || '')'', 1, 500),',
'                            campo96 = SUBSTR(campo96 || ''-'' || v_fecha, 1, 500),',
'                            campo97 = SUBSTR(campo97 || ''-'' || v_user, 1, 500),',
'                            campo98 = SUBSTR(campo98 || ''-'' || v_terminal, 1, 500)',
'                        WHERE codcia = :P1600_IDCODCIA',
'                          AND idpoliza = :P1600_IDPOLIZA',
'                          AND idetpol = v_idetpol',
'                          AND cod_asegurado = aseg.cod_asegurado;',
'                        ',
'                        -- Actualizar valores',
'                        OC_ASEGURADO_CERTIFICADO.ACTUALIZA_VALORES(:P1600_IDCODCIA, 1, :P1600_IDPOLIZA, v_idetpol, aseg.cod_asegurado);',
'                        OC_ASEGURADO_CERTIFICADO.ACTUALIZA_ASISTENCIAS(:P1600_IDCODCIA, 1, :P1600_IDPOLIZA, v_idetpol, aseg.cod_asegurado);',
'                        ',
'                        v_count := v_count + 1;',
'                    END IF;',
'                    ',
'                END LOOP;',
'                ',
'                -- Actualizar subgrupo',
'                IF v_count > 0 THEN',
'                    OC_DETALLE_POLIZA.ACTUALIZA_VALORES(:P1600_IDCODCIA, :P1600_IDPOLIZA, v_idetpol, 0);',
'                END IF;',
'                ',
'            END IF;',
'            ',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                v_count_errors := v_count_errors + 1;',
'        END;',
'        ',
'    END LOOP;',
'    ',
'',
'    IF v_count > 0 THEN',
'        OC_POLIZAS.ACTUALIZA_VALORES(:P1600_IDCODCIA, :P1600_IDPOLIZA, 0);',
'        COMMIT;',
'        ',
'     ',
'        APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ',
'           '' asegurado(s) actualizado(s)'' ||',
'            CASE WHEN v_count_errors > 0 THEN '' ('' || v_count_errors || '' error(es))'' END;',
'    ELSE',
'       ',
'        APEX_ERROR.ADD_ERROR(',
unistr('            p_message => ''No se actualiz\00F3 ning\00FAn registro. Debe ingresar un factor v\00E1lido mayor a 0'','),
'            p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'    END IF;',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
unistr('        -- \00BF MENSAJE ROJO (ERROR)'),
'        APEX_ERROR.ADD_ERROR(',
'            p_message => ''Error en el proceso: '' || SQLERRM,',
'            p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(593974777467876706)
,p_internal_uid=>56344302016567333
);
end;
/
