wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(595080000815937523)
,p_plug_name=>'IG_SOLICITUD_EMISION'
,p_region_name=>'IG_SOLICITUD_EMISION'
,p_parent_plug_id=>wwv_flow_imp.id(592438311475521649)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>110
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    SE.CODCIA,',
'    SE.CODEMPRESA,',
'    SE.IDSOLICITUD,',
'    SE.TIPO_DOC_IDENTIFICACION,',
'    SE.NUM_DOC_IDENTIFICACION,',
'    SE.TIPODOCIDENTIFASEG,',
'    SE.NUMDOCIDENTIFASEG,',
'    SE.FECINIVIG,',
'    SE.FECFINVIG,',
'    SE.IDTIPOSEG,',
'    SE.PLANCOB,',
'    SE.NUMPOLUNICOASIG,',
'    SE.NUMFOLIOPORTAL,',
'    ',
'    SE.STSSOLICITUD || '' - '' ||',
'    SICAS_OC.OC_VALORES_DE_LISTAS.BUSCA_LVALOR(',
'            ''ESTADOS'',',
'            SE.STSSOLICITUD',
'        ) DESC_STSSOLICITUD,',
'',
'    SE.TIPO_DOC_IDENTIFICACION || '' - '' ||',
'    SE.NUM_DOC_IDENTIFICACION || '' - '' ||',
'    SICAS_OC.OC_PERSONA_NATURAL_JURIDICA.NOMBRE_COMPLETO(',
'        SE.TIPO_DOC_IDENTIFICACION,',
'        SE.NUM_DOC_IDENTIFICACION',
'    ) AS CONTRATANTE,',
'',
'    SE.TIPODOCIDENTIFASEG || '' - '' ||',
'    SE.NUMDOCIDENTIFASEG || '' - '' ||',
'    SICAS_OC.OC_PERSONA_NATURAL_JURIDICA.NOMBRE_COMPLETO(',
'        SE.TIPODOCIDENTIFASEG,',
'        SE.NUMDOCIDENTIFASEG',
'    ) AS ASEGURADO,',
'',
'    SE.IDPOLIZA,',
'    SE.NUMCOTIZACION,',
'',
'    SE.IDTIPOSEG || '' - '' ||',
'    SICAS_OC.OC_TIPOS_DE_SEGUROS.TIPO_DE_SEGURO(',
'        SE.CODCIA,',
'        SE.CODEMPRESA,',
'        SE.IDTIPOSEG',
'    ) AS DESC_IDTIPOSEG,',
'',
'    SE.PLANCOB || '' - '' ||',
'    SICAS_OC.OC_PLAN_COBERTURAS.NOMBRE_PLANCOB(',
'        SE.CODCIA,',
'        SE.CODEMPRESA,',
'        SE.IDTIPOSEG,',
'        SE.PLANCOB',
'    ) AS DESC_PLANCOB,',
'',
'    SE.CODAGRUPADOR || '' - '' ||',
'    SICAS_OC.OC_VALORES_DE_LISTAS.BUSCA_LVALOR(',
'        ''AGRUPA'',',
'        SE.CODAGRUPADOR',
'    ) AS DESC_CODAGRUPADOR,',
'',
'    SE.TIPOADMINISTRACION || '' - '' ||',
'    SICAS_OC.OC_VALORES_DE_LISTAS.BUSCA_LVALOR(',
'        ''ADMINPOL'',',
'        SE.TIPOADMINISTRACION',
'    ) AS DESC_TIPOADMINISTRACION,',
'',
'    SE.CODPLANPAGO || '' - '' ||',
'    SICAS_OC.OC_PLAN_DE_PAGOS.DESCRIPCION_PLAN(',
'        SE.CODCIA,',
'        SE.CODEMPRESA,',
'        SE.CODPLANPAGO',
'    ) AS DESC_CODPLANPAGO,',
'',
'    SE.COD_MONEDA || '' - '' ||',
'    SICAS_OC.OC_MONEDA.DESCRIPCION_MONEDA(',
'        SE.COD_MONEDA',
'    ) AS DESC_COD_MONEDA,',
'',
'    SE.INDFACTURAPOL,',
'    SE.INDFACTSUBGRUPO,',
'    SE.INDCALCDERECHOEMIS,',
'    SE.INDFACTELECTRONICA,',
'    SE.INDASEGMODELO,',
'    SE.INDPRIMIN,',
'    SE.PRIMANETAPOL,',
'    SE.TASACAMBIO,',
'    SE.FECSTSSOL,',
'    SE.STSSOLICITUD,',
'',
'    CASE',
'        WHEN SE.STSSOLICITUD = ''XENVIA''',
'        THEN ''<i class="fa fa-edit"></i>''',
'    END AS ETIQUETA_SOLICITUD_EMISION,',
'',
'    DECODE( SE.STSSOLICITUD,',
'        ''XENVIA'', ''VA_SOLICITUD'',',
'        ''ANULAD'', ''VA_ANULADO'',',
'        ''EMITID'', ''VA_EMITIDA'',',
'        NULL',
'    ) AS COLOR',
'    ',
'FROM SOLICITUD_EMISION SE',
'',
'WHERE 1=1',
'--AND SE.CODUSUARIO = :APP_USER',
'AND (SE.CODUSUARIO = :APP_USER OR SE.CODUSUARIO = DECODE(:APP_USER,''JIBARRA'',''DVITE'',:APP_USER))',
'AND (:P1700_BUSCA_IDSOLICITUD IS NULL OR SE.IDSOLICITUD = :P1700_BUSCA_IDSOLICITUD)',
'AND (:P1700_BUSCA_STSSOLICITUD IS NULL OR SE.STSSOLICITUD = :P1700_BUSCA_STSSOLICITUD)',
'AND (:P1700_BUSCA_NUMPOLUNICOASIG IS NULL OR SE.NUMPOLUNICOASIG = :P1700_BUSCA_NUMPOLUNICOASIG)',
'AND (:P1700_BUSCA_NUMFOLIOPORTAL IS NULL OR SE.NUMFOLIOPORTAL = :P1700_BUSCA_NUMFOLIOPORTAL)',
'AND (:P1700_BUSCA_TIPO_DOC_IDENTIFICACION IS NULL OR SE.TIPODOCIDENTIFASEG = :P1700_BUSCA_TIPO_DOC_IDENTIFICACION)',
'AND (:P1700_BUSCA_NUM_DOC_IDENTIFICACION IS NULL OR SE.NUMDOCIDENTIFASEG = :P1700_BUSCA_NUM_DOC_IDENTIFICACION)',
'AND (:P1700_BUSCA_FECINIVIG IS NULL OR SE.FECINIVIG = :P1700_BUSCA_FECINIVIG)',
'AND (:P1700_BUSCA_FECFINVIG IS NULL OR SE.FECFINVIG = :P1700_BUSCA_FECFINVIG);',
'',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1700_BUSCA_IDSOLICITUD,P1700_BUSCA_STSSOLICITUD,P1700_BUSCA_NUMPOLUNICOASIG,P1700_BUSCA_NUMFOLIOPORTAL,P1700_BUSCA_TIPO_DOC_IDENTIFICACION,P1700_BUSCA_NUM_DOC_IDENTIFICACION,P1700_BUSCA_FECINIVIG,P1700_BUSCA_FECFINVIG'
