 p_id=>wwv_flow_imp.id(595291477826214508)
,p_plug_name=>'SOLICITUD_COBERTURAS'
,p_region_name=>'SOLICITUD_COBERTURAS'
,p_parent_plug_id=>wwv_flow_imp.id(595212337159341208)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CODCIA,',
'       CODEMPRESA,',
'       IDSOLICITUD,',
'       IDETSOL,',
'       CODCOBERT,',
'       --CODCOBERT || '' - '' || OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(CODCIA, CODEMPRESA, /*VIENE DE LS*/IDTIPOSEG,/*VIENE DE LS*/PLANCOB, CODCOBERT) DESC_COBERT,',
'       SUMAASEG_LOCAL,',
'       SUMAASEG_MONEDA,',
'       TASA,',
'       PRIMA_MONEDA,',
'       PRIMA_LOCAL,',
'       DEDUCIBLE_LOCAL,',
'       DEDUCIBLE_MONEDA,',
'       SALARIOMENSUAL,',
'       VECESSALARIO,',
'       FACTORREGLASUMAASEG,',
'       (SELECT DISTINCT C.DESCCOBERT',
'       FROM COBERTURAS_DE_SEGUROS C',
'            WHERE C.IDTIPOSEG  = :P1700_IDTIPOSEG',
'            AND C.PLANCOB    = :P1700_PLANCOB',
'            AND C.CODCOBERT = SC.CODCOBERT) DESCCOBERT',
'FROM SOLICITUD_COBERTURAS SC',
'-- WHERE IDSOLICITUD = :P1700_DE_IDSOLICITUD',
'-- AND IDETSOL = :P1700_IDETSOL_DE_SP',
'WHERE IDSOLICITUD = :P1700_DE_IDSOLICITUD',
'AND IDETSOL = :P1700_IDETSOL_DE_SP'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1700_DE_IDSOLICITUD,P1700_IDETSOL_DE_SP,P1700_IDTIPOSEG,P1700_PLANCOB'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
