wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(545156608349638137)
,p_process_sequence=>100
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRC_LA_Carga_Asegurado'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob              BLOB;',
'    l_filename          VARCHAR2(4000);',
'    n_filas_insertadas  NUMBER := 0;',
'    n_dupl_archivo      NUMBER := 0;',
'    n_dupl_destino      NUMBER := 0;',
'    l_msg               VARCHAR2(4000);',
'BEGIN',
'    SELECT blob_content, filename',
'      INTO l_blob, l_filename',
'      FROM apex_application_temp_files',
'     WHERE name = :P1700_ARCHIVO_ASEG;',
'',
'    OC_MANTENIMIENTO_EMIFACIL.CARGA_ASEG_LAYOUT(',
'        nCodCia => :P1700_CODCIA,',
'        nCodEmpresa => :P1700_CODEMPRESA,',
'        nIdSolicitud => :P1700_IDSOLICITUD,',
'        lArchivoBinario => l_blob,',
'        cNombreArchivo => l_filename,',
'        nFilasInsertadas => n_filas_insertadas,',
'        nDuplicadosArchivo => n_dupl_archivo,',
'        nDuplicadosDestino => n_dupl_destino',
'    );',
'',
'    l_msg := ''Carga realizada correctamente. Registros insertados: '' || n_filas_insertadas;',
'',
'    IF NVL(n_dupl_archivo,0) > 0 OR NVL(n_dupl_destino,0) > 0 THEN',
'        l_msg := l_msg',
'              || ''<br><strong>Advertencia:</strong> Se detectaron posibles duplicidades.''',
'              || ''<br>Duplicados dentro del archivo: '' || NVL(n_dupl_archivo,0)',
'              || ''<br>Duplicados contra registros existentes: '' || NVL(n_dupl_destino,0)',
unistr('              || ''<br>Favor de revisar la informaci\00F3n cargada.'';'),
'    END IF;',
'',
'    apex_application.g_print_success_message := l_msg;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''No se encontr\00F3 el archivo cargado.'');'),
'    WHEN OTHERS THEN',
'        RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(545156830929638139)
,p_internal_uid=>106064911518566614
);
