'',
'    OC_MANTENIMIENTO_EMIFACIL.DESCARGA_REPORTE_SOLICITUD_EMISION(nArchivo_id);',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
unistr('            RAISE_APPLICATION_ERROR(-20001, ''No se encontr\00F3 archivo para descargar.'');'),
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'DESCARGA_REPORTE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>103166609111664946
