wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(558715292992794539)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DescargarDuplicados'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lctx    apex_exec.t_context;',
'    lexport apex_data_export.t_export;',
'BEGIN',
'    lctx := apex_exec.open_query_context(',
'        p_location  => apex_exec.c_location_local_db,',
'        p_sql_query => q''[',
'            SELECT CODCIA,',
'                   CODEMPRESA,',
'                   IDSOLICITUD,',
'                   IDETSOL,',
'                   IDASEGURADO,',
'                   TIPODOCIDENTIFICACION,',
'                   NUMDOCIDENTIFICACION,',
'                   NOMBREASEG,',
'                   APELLIDOPATERNOASEG,',
'                   APELLIDOMATERNOASEG,',
'                   FECHANACIMIENTO,',
'                   DECODE(SEXOASEG,''M'',''Masculino'',''F'',''Femenino'',''NA'',''No Aplica'',SEXOASEG) SEXOASEG,',
'                   DIRECRESASEG,',
'                   CODIGOPOSTALASEG,',
'                   SALARIOMENSUAL,',
'                   NUTRA',
'              FROM SOLICITUD_DETALLE_ASEG sda',
'             WHERE sda.IDSOLICITUD = TO_NUMBER(apex_util.get_session_state(''P1700_IDSOLICITUDASEG_CRTL''))',
'               AND EXISTS (',
'                    SELECT 1',
'                      FROM SOLICITUD_DETALLE_ASEG sda2',
'                     WHERE sda2.CODCIA = sda.CODCIA',
'                       AND sda2.CODEMPRESA = sda.CODEMPRESA',
'                       AND sda2.IDSOLICITUD = sda.IDSOLICITUD',
'                       AND TRIM(sda2.TIPODOCIDENTIFICACION) = TRIM(sda.TIPODOCIDENTIFICACION)',
'                       AND TRIM(sda2.NUMDOCIDENTIFICACION) = TRIM(sda.NUMDOCIDENTIFICACION)',
'                     GROUP BY sda2.CODCIA,',
'                              sda2.CODEMPRESA,',
'                              sda2.IDSOLICITUD,',
'                              TRIM(sda2.TIPODOCIDENTIFICACION),',
'                              TRIM(sda2.NUMDOCIDENTIFICACION)',
'                    HAVING COUNT(*) > 1',
'               )',
'             ORDER BY TRIM(sda.TIPODOCIDENTIFICACION),',
'                      TRIM(sda.NUMDOCIDENTIFICACION),',
'                      sda.IDASEGURADO',
'        ]''',
'    );',
'',
'    lexport := apex_data_export.export(',
'        p_context   => lctx,',
'        p_format    => apex_data_export.c_format_xlsx,',
'        p_file_name => ''Duplicados_Asegurados''',
'    );',
'',
'    apex_exec.close(lctx);',
'',
'    apex_data_export.download(p_export => lexport);',
'    apex_application.stop_apex_engine;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'DUPLICADOS'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>119623596161723016
,p_process_comment=>'Descargar reporte de Asegurados en solicitud que se encuentran duplicados para la misma solicitud.'
);
