,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AJAX_COUNT_ASIST'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nCount NUMBER := 0;',
'BEGIN',
'    SELECT NVL(COUNT(*),0)',
'    INTO nCount',
'    FROM SOLICITUD_ASISTENCIAS',
'    WHERE 1=1',
'    AND CodCia        = 1',
'    AND CodEmpresa    = 1',
'    AND IdSolicitud   = TO_NUMBER(APEX_APPLICATION.g_x01);',
'',
'    APEX_JSON.OPEN_OBJECT;',
'    IF nCount > 0 THEN',
'        APEX_JSON.WRITE(''status'',''ok'');',
'    ELSE',
'        APEX_JSON.WRITE(''status'',''nok'');',
'    END IF;',
'    APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>133231544553776414
);
