wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(595767782296267630)
,p_plug_name=>'IG_SOLICITUD_AGENTES_DISTRIB'
,p_region_name=>'IG_SOLICITUD_AGENTES_DISTRIB'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>100
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SAD.CODCIA,',
'       SAD.CODEMPRESA,',
'       SAD.IDSOLICITUD,',
'       SAD.COD_AGENTE,',
'       SAD.CODNIVEL,',
'       (SELECT A.CODTIPO',
'          FROM AGENTES A',
'         WHERE A.COD_AGENTE = SAD.COD_AGENTE_DISTR) TIPO_AGENTE,',
'       SAD.COD_AGENTE_DISTR,',
'       SAD.PORC_COMISION_AGENTE,',
'       SAD.PORC_COM_DISTRIBUIDA,',
'       SAD.PORC_COMISION_PLAN,',
'       SAD.PORC_COM_PROPORCIONAL,',
'       SAD.COD_AGENTE_JEFE,',
'       SAD.COD_AGENTE_JEFE || '' - '' ||',
'       OC_AGENTES.NOMBRE_AGENTE(',
'            SAD.CODCIA,',
'            SAD.COD_AGENTE_JEFE',
'       ) DESC_COD_AGENTE_JEFE,',
'       SAD.PORC_COM_SOLICITUD,',
'       SAD.ORIGEN,',
'       OC_MANTENIMIENTO_EMIFACIL_AGENTES.OBTIENE_CALC_AUTOM(',
'            SAD.COD_AGENTE_DISTR,',
'            SAD.IDSOLICITUD',
'       ) CALC_AUTOM',
'FROM SOLICITUD_AGENTES_DISTRIB SAD',
'WHERE SAD.IDSOLICITUD = :P1701_NUM_SOLICITUD',
'  AND SAD.COD_AGENTE   = :P1701_COD_AGENTE'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P1701_NUM_SOLICITUD,P1701_COD_AGENTE'
