,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    nSumaAseg_Moneda      NUMBER;',
'    nSumaAseg_Usuario     NUMBER;',
'BEGIN',
'    nSumaAseg_Usuario := :P1704_SUMAASEG_MONEDA;',
'    nSumaAseg_Moneda  := :P1704_SUMAASEG_MONEDA;',
'',
'    :P1704_SHOW_ERROR := NULL;',
'',
'    OC_MANTENIMIENTO_EMIFACIL.ACCIONES_COBERT_SUMAASEG_MONEDA(',
'        in_nCodCia               => :P1704_CODCIA,',
'        in_nCodEmpresa           => :P1704_CODEMPRESA,',
'        in_nIdSolicitud          => :P1704_IDSOLICITUD,',
'        in_nIdetSol              => :P1704_IDETSOL,',
'        in_cCodCobert            => :P1704_CODCOBERT,',
'        in_out_nSumaAseg_Moneda  => nSumaAseg_Moneda,',
'        out_nTasa                => :P1704_TASA,',
'        out_nSumaAseg_Local      => :P1704_SUMAASEG_LOCAL,',
'        out_nPrima_Moneda        => :P1704_PRIMA_MONEDA,',
'        out_nPrima_Local         => :P1704_PRIMA_LOCAL,',
'        out_cError               => :P1704_SHOW_ERROR',
'    );',
'',
unistr('    -- Solo actualizar el item si el procedure devuelve un valor \00FAtil'),
'    IF NVL(nSumaAseg_Moneda, 0) <> 0 THEN',
'        :P1704_SUMAASEG_MONEDA := nSumaAseg_Moneda;',
'    ELSE',
'        :P1704_SUMAASEG_MONEDA := nSumaAseg_Usuario;',
'    END IF;',
'END;'))
,p_attribute_02=>'P1704_CODCIA, P1704_CODEMPRESA, P1704_IDSOLICITUD, P1704_IDETSOL, P1704_CODCOBERT, P1704_SUMAASEG_MONEDA'
,p_attribute_03=>'P1704_SUMAASEG_MONEDA, P1704_TASA, P1704_SUMAASEG_LOCAL, P1704_PRIMA_MONEDA, P1704_PRIMA_LOCAL, P1704_SHOW_ERROR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(690440983571095281)
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(442858674329584904)
,p_event_id=>wwv_flow_imp.id(555664419454888230)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cSexo               PERSONA_NATURAL_JURIDICA.Sexo%TYPE;',
'    cRiesgo             ACTIVIDADES_ECONOMICAS.RiesgoActividad%TYPE;',
'    cCodActividad       PERSONA_NATURAL_JURIDICA.CodActividad%TYPE := NULL;',
'    nSumaAsegMinima     COBERTURAS_DE_SEGUROS.SumaAsegMinima%TYPE;',
'    nSumaAsegMaxima     COBERTURAS_DE_SEGUROS.SumaAsegMaxima%TYPE;',
'    nSumaAsegMaxIndiv   COBERTURAS_DE_SEGUROS.SumaAsegMaxIndiv%TYPE;',
'    nIdTarifa           TARIFA_CONTROL_VIGENCIAS.IdTarifa%TYPE;',
'    nEdad               NUMBER(5);',
'BEGIN',
'    :P1704_SHOW_ERROR := NULL;',
'    IF OC_COBERTURAS_DE_SEGUROS.CODIGO_TARIFA   (1, 1, :P1704_TIPOSEG,:P1704_PLANCOB, :P1704_CODCOBERT) IS NOT NULL THEN',
'        IF OC_TARIFA_DINAMICA.TARIFA_VIGENTE(1, 1, :P1704_TIPOSEG,',
'                                            :P1704_PLANCOB, TRUNC(SYSDATE)) = 0 THEN',
'            cSexo         := ''U'';',
'            nEdad         := :P1704_DET_SOL_EDADLIMITE;',
'            cRiesgo       := OC_ACTIVIDADES_ECONOMICAS.RIESGO_ACTIVIDAD(cCodActividad);',
'            nIdTarifa     := GT_TARIFA_CONTROL_VIGENCIAS.TARIFA_VIGENTE(1, 1, :P1704_TIPOSEG,',
'                                                                        :P1704_PLANCOB, :P1704_SOL_FECINIVIG);',
'',
'            :P1704_SUMAASEG_MONEDA  := OC_TARIFA_SEXO_EDAD_RIESGO.SUMA_ASEGURADA(1, 1, :P1704_TIPOSEG,',
'                                                                                  :P1704_PLANCOB, :P1704_CODCOBERT, nEdad, cSexo, cRiesgo, nIdTarifa, NULL);',
'            :P1704_PRIMA_MONEDA     := OC_TARIFA_SEXO_EDAD_RIESGO.PRIMA_TARIFA(1, 1, :P1704_TIPOSEG,',
'                                                                                :P1704_PLANCOB, :P1704_CODCOBERT, nEdad, cSexo, cRiesgo,',
'                                                                                :P1704_SUMAASEG_MONEDA, nIdTarifa, NULL);',
'            :P1704_PRIMA_LOCAL := :P1704_PRIMA_MONEDA * :P1704_SOL_TASACAMBIO;',
'',
'            IF NVL(:P1704_SUMAASEG_MONEDA,0) != 0 THEN',
'                :P1704_TASA := NVL(:P1704_PRIMA_MONEDA,0) / NVL(:P1704_SUMAASEG_MONEDA,1);',
'            END IF;',
'        END IF;',
'    ELSE',
'        :P1704_SUMAASEG_LOCAL := :P1704_SUMAASEG_MONEDA * :P1704_SOL_TASACAMBIO;',
'    END IF;',
'',
'    nSumaAsegMinima   :=  OC_COBERTURAS_DE_SEGUROS.SUMA_ASEGURADA(1, 1, :P1704_TIPOSEG,',
'                                                                 :P1704_PLANCOB, :P1704_CODCOBERT, ''MIN'');',
'    nSumaAsegMaxima   :=  OC_COBERTURAS_DE_SEGUROS.SUMA_ASEGURADA(1, 1, :P1704_TIPOSEG,',
'                                                                 :P1704_PLANCOB, :P1704_CODCOBERT, ''MAX'');',
'    nSumaAsegMaxIndiv :=  OC_COBERTURAS_DE_SEGUROS.SUMA_ASEGURADA(1, 1, :P1704_TIPOSEG,',
'                                                                 :P1704_PLANCOB, :P1704_CODCOBERT, ''SAMI'');',
'',
'    IF :P1704_SUMAASEG_MONEDA < nSumaAsegMinima AND nSumaAsegMinima > 0 THEN',
unistr('        :P1704_SHOW_ERROR := ''Suma Asegurada NO puede ser Menor a la Suma Asegurada M\00EDnima de Cobertura'';'),
'',
'    END IF;',
'    IF :P1704_SUMAASEG_MONEDA > nSumaAsegMaxima AND nSumaAsegMaxima > 0 THEN',
unistr('        :P1704_SHOW_ERROR := ''Suma Asegurada NO puede ser Mayor a la Suma Asegurada M\00E1xima de Cobertura'';'),
'',
'    END IF;',
'',
'    IF :P1704_SUMAASEG_MONEDA > nSumaAsegMaxIndiv AND nSumaAsegMaxIndiv > 0 THEN',
'        :P1704_SHOW_ERROR := ''Suma Asegurada Es Mayor al SAMI Configurado para la Cobertura y va a requerir Reaseguro'';',
'    END IF;',
'    ',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            :P1704_SHOW_ERROR := (SQLERRM);',
'END;'))
,p_attribute_02=>'P1704_TIPOSEG,P1704_PLANCOB,P1704_CODCOBERT,P1704_DET_SOL_EDADLIMITE,P1704_SOL_FECINIVIG,P1704_CODCOBERT,P1704_SOL_TASACAMBIO,P1704_SUMAASEG_MONEDA,P1704_SOL_TASACAMBIO,P1704_SUMAASEG_MONEDA'
,p_attribute_03=>'P1704_SUMAASEG_MONEDA,P1704_PRIMA_MONEDA,P1704_PRIMA_LOCAL,P1704_TASA,P1704_SUMAASEG_LOCAL,P1704_SHOW_ERROR'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_build_option_id=>wwv_flow_imp.id(690440983571095281)
);
