,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    :P1704_PRIMA_LOCAL := :P1704_PRIMA_MONEDA * NVL(:P1704_TASACAMBIO,1);',
