wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(555665399505888240)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Asigna_ValoresApoyo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT TASACAMBIO, FECINIVIG, TASACAMBIO',
'INTO :P1704_TASACAMBIO, :P1704_SOL_FECINIVIG, :P1704_SOL_TASACAMBIO',
'FROM SOLICITUD_EMISION',
'WHERE 1=1',
'AND CODCIA = NVL(:P1704_CODCIA,1)',
'AND CODEMPRESA = NVL(:P1704_CODEMPRESA,1)',
'AND IDSOLICITUD = :P1704_IDSOLICITUD;',
'',
'SELECT EDADLIMITE',
'INTO :P1704_DET_SOL_EDADLIMITE',
'FROM SOLICITUD_DETALLE',
'WHERE 1=1',
'AND CODCIA = NVL(:P1704_CODCIA,1)',
'AND CODEMPRESA = NVL(:P1704_CODEMPRESA,1)',
'AND IDSOLICITUD = :P1704_IDSOLICITUD',
'AND IDETSOL = :P1704_IDETSOL;',
'',
'IF :P1704_CODCOBERT IS NOT NULL THEN',
'    DECLARE',
'        cPLANCOB    SICAS_OC.SOLICITUD_EMISION.PLANCOB%TYPE;',
'        cIDTIPOSEG  SICAS_OC.SOLICITUD_EMISION.IDTIPOSEG%TYPE;',
'    BEGIN',
'        BEGIN',
'            SELECT IDTIPOSEG, PLANCOB',
'            INTO cIDTIPOSEG, cPLANCOB',
'            FROM SOLICITUD_EMISION            ',
'            WHERE IDSOLICITUD = :P1704_IDSOLICITUD;',
'',
'            EXCEPTION ',
'                WHEN NO_DATA_FOUND THEN',
'                    cPLANCOB := :P1700_IDTIPOSEG;',
'                    cIDTIPOSEG := :P1700_PLANCOB;',
'',
'                WHEN TOO_MANY_ROWS THEN',
'                    cPLANCOB := :P1700_IDTIPOSEG;',
'                    cIDTIPOSEG := :P1700_PLANCOB;',
'        END;',
'',
'        :P1704_TIPOSEG := cIDTIPOSEG;',
'        :P1704_PLANCOB := cPLANCOB;',
'',
'        SELECT DISTINCT DESCCOBERT',
'        INTO :P1704_DESC_COBERTURA',
'        FROM COBERTURAS_DE_SEGUROS C',
'        WHERE CODCIA    = 1',
'        AND CODEMPRESA  = 1',
'        AND IDTIPOSEG   = cIDTIPOSEG',
'        AND PLANCOB     = cPLANCOB',
'        AND CODCOBERT   = :P1704_CODCOBERT;',
'',
'        EXCEPTION ',
'            WHEN NO_DATA_FOUND THEN',
unistr('                :P1704_DESC_COBERTURA := ''No se encontro descripci\00F3n de Cobertura'';'),
'            ',
'            WHEN OTHERS THEN',
unistr('                :P1704_DESC_COBERTURA := ''No se encontro descripci\00F3n de Cobertura'';'),
'',
'    END;',
'END IF;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>116573702674816717
);
end;
