wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(555692255453035140)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PR_SetValue'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT CODTIPONEGOCIO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPNEGO'', CODTIPONEGOCIO) DESC_CODTIPONEGOCIO',
'          ,CODCATEGO || '' - '' || GT_CATEGORIAS.CONSULTA_DESCRIP(1, 1, CODTIPONEGOCIO, CODCATEGO) DESC_CODCATEGO',
'          ,INDCONCENTRADA',
'          ,TIPORIESGO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''TIPRIESG'', TIPORIESGO) DESC_TIPORIESGO',
'          ,FORMAVENTA || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''FORMVENT'', FORMAVENTA) DESC_FORMAVENTA',
'          ,CODUSOCFDI || '' - '' || OC_FACT_ELECT_USO_CFDI.DESCRIPCION(1, CODUSOCFDI) DESC_CODUSOCFDI',
'          ,CODOBJETOIMP || '' - '' || OC_FACT_ELECT_OBJETO_IMPUESTO.DESCRIPCION(1, CODOBJETOIMP) DESC_CODOBJETOIMP',
'          ,NUMCOTIZACION || '' - '' || GT_COTIZACIONES.NUMERO_UNICO_COTIZACION(1, 1, NUMCOTIZACION) DESC_NUMCOTIZACION',
'          ,PORCGTOADMIN',
'          ,PORCUTILIDAD   ',
'          ,PORCDESCUENTO',
'          ,PORCGTOADQUI',
'          ,PORCENCONTRIBUTORIO',
'          ,INDEXTRAPRIMA',
'          ,CODRIESGOREA || '' - '' || GT_REA_RIESGOS.DESCRIPCION_RIESGO(1, CODRIESGOREA) DESC_CODRIESGOREA',
'          ,FUENTERECURSOSPRIMA || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''FUENTEREC'', FUENTERECURSOSPRIMA) DESC_FUENTERECURSOSPRIMA',
'          ,ASEGADHERIDOSPOR || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''PRESCONT'', ASEGADHERIDOSPOR) DESC_ASEGADHERIDOSPOR',
'          ,CODTIPOBONO || '' - '' || OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''CLASEBONO'', CODTIPOBONO) DESC_CODTIPOBONO',
'          ,FACTORAJUSTE',
'          ,HORASVIG',
'          ,FACTFORMULADEDUC',
'          ,DIASVIG',
'          ,MONTODEDUCIBLE',
'          ,NVL(SAMISOLICITUD,0) SAMI',
'    INTO ',
'        :P1708_TIPO_NEGOCIO,',
'        :P1708_CATEGORIA,',
'        :P1708_CONCENTRA_SESAS,',
'        :P1708_TIPO_RIESGO,',
'        :P1708_CANAL_VENTA,',
'        :P1708_CFDI,',
'        :P1708_OBJETO_IMPUESTO,',
'        :P1708_NUM_COTIZACION,',
'        :P1708_GTOS_ADMINISTRA,',
'        :P1708_UTILIDAD,',
'        :P1708_DESCUENTO,',
'        :P1708_GTOS_ADQUISI,',
'        :P1708_CONTRIBUTORIO,',
'        :P1708_EXTRA_PRIMA,',
'        :P1708_TIPO_REASEGURO,',
'        :P1708_FUENTE_RECURSO,',
'        :P1708_ADHERIDOS,',
'        :P1708_TIPO_BONO,',
'        :P1708_FACTOR_AJUSTE,',
'        :P1708_HORA_VIGENCIA,',
'        :P1708_FACTOR_DEDUC,',
'        :P1708_DIAS_VIGENCIA,',
'        :P1708_MTO_DEDUCIBLE,',
'        :P1708_SAMI_SOLICITUD',
'    FROM SOLICITUD_EMISION SE',
'    WHERE IDSOLICITUD = :P1708_NUM_SOLICI;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>116600558621963617
);
end;
