wwv_flow_imp_page.create_page(
 p_id=>1711
,p_name=>'Datos del Contratante'
,p_alias=>'DATOS-DEL-CONTRATANTE'
,p_page_mode=>'MODAL'
,p_step_title=>'Datos del Contratante'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Este c\00F3digo va en una acci\00F3n din\00E1mica tipo "Execute JavaScript Code"'),
unistr('// que se ejecuta DESPU\00C9S de la acci\00F3n "Execute PL/SQL Code"'),
'',
'var rfcGenerado = apex.item(''P1711_RFC_GENERADO'').getValue();',
'var flagDoc     = apex.item(''P1700_CONFIRM_FLAG'').getValue();',
'var flagTrib    = apex.item(''P1711_CONFIRM_FLAG'').getValue();',
'',
unistr('// -- Validaci\00F3n: RFC generado ------------------------------------------'),
'if (!rfcGenerado || rfcGenerado.trim() === '''') {',
'    apex.message.showErrors([{',
'        type:     ''error'',',
'        location: ''page'',',
unistr('        message:  ''El proceso no gener\00F3 ning\00FAn RFC. Verifique los datos ingresados.'''),
'    }]);',
'    return;',
'}',
'',
unistr('// -- Confirmaci\00F3n Documento de Identificaci\00F3n --------------------------'),
'if (flagDoc === ''CONFIRM_DOC'') {',
'    apex.message.confirm(',
unistr('        ''\00BFDesea reemplazar el Documento de Identificaci\00F3n con el RFC generado: '' + rfcGenerado + ''?'','),
'        function (okPressed) {',
'            if (okPressed) {',
'                apex.item(''P1711_NUM_DOC_IDENTIFICACION'').setValue(rfcGenerado);',
unistr('                apex.message.showPageSuccess(''RFC asignado en Documento de Identificaci\00F3n: '' + rfcGenerado);'),
'            } else {',
'                apex.message.showErrors([{',
'                    type:     ''error'',',
'                    location: ''page'',',
unistr('                    message:  ''Operaci\00F3n cancelada. El Documento de Identificaci\00F3n no fue modificado.'''),
'                }]);',
'            }',
'        }',
'    );',
'    return;',
'}',
'',
unistr('// -- Confirmaci\00F3n N\00FAmero Tributario ------------------------------------'),
'if (flagTrib === ''CONFIRM_TRIB'') {',
'    apex.message.confirm(',
unistr('        ''\00BFDesea reemplazar el N\00FAmero Tributario con el RFC generado: '' + rfcGenerado + ''?'','),
'        function (okPressed) {',
'            if (okPressed) {',
'                apex.item(''P1711_NUM_TRIBUTARIO'').setValue(rfcGenerado);',
unistr('                apex.message.showPageSuccess(''RFC asignado en N\00FAmero Tributario: '' + rfcGenerado);'),
'            } else {',
'                apex.message.showErrors([{',
'                    type:     ''error'',',
'                    location: ''page'',',
unistr('                    message:  ''Operaci\00F3n cancelada. El N\00FAmero Tributario no fue modificado.'''),
'                }]);',
'            }',
'        }',
'    );',
'    return;',
'}',
'',
'// -- DONE: ambos campos ya asignados por el PL/SQL ---------------------',
'apex.message.showPageSuccess(''RFC generado y asignado correctamente: '' + rfcGenerado);'))
,p_page_template_options=>'#DEFAULT#:ui-dialog--stretch'
,p_protection_level=>'C'
,p_page_component_map=>'02'
,p_last_updated_by=>'LRAMOS'
,p_last_upd_yyyymmddhh24miss=>'20260401163345'
);
