wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(546970052578008472)
,p_event_id=>wwv_flow_imp.id(546965865145008430)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_name=>'JS_REQUERIDO'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var errores = [];',
'',
'if ($v(''P1711_TIPO_PERSONA'') !== ''FISICA'') {',
'    return false;',
'}',
'',
'if (!$v(''P1711_APELLIDO_PATERNO'')) {',
'    errores.push({',
'        type:     "error",',
'        location: "inline",',
'        pageItem: "P1711_APELLIDO_PATERNO",',
'        message:  "Apellido Paterno es requerido",',
'        unsafe:   false',
'    });',
'}',
'',
'if (!$v(''P1711_APELLIDO_MATERNO'')) {',
'    errores.push({',
'        type:     "error",',
'        location: "inline",',
'        pageItem: "P1711_APELLIDO_MATERNO",',
'        message:  "Apellido Materno es requerido",',
'        unsafe:   false',
'    });',
'}',
'',
'if (errores.length > 0) {',
'    apex.message.clearErrors();',
'    apex.message.showErrors(errores);',
'    return false;',
'}'))
,p_client_condition_type=>'EQUALS'
,p_client_condition_element=>'P1711_TIPO_PERSONA'
,p_client_condition_expression=>'FISICA'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(547661036890579930)
,p_event_id=>wwv_flow_imp.id(546965865145008430)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cNum_Tributario VARCHAR2(200);',
'    vl_Total        NUMBER := 0;',
'BEGIN',
'    IF :P1700_DOC_FISCAL_DC = ''RFC'' OR :P1700_TIPO_DOC_DC = ''RFC'' THEN',
'        IF :P1711_FECNACIMIENTO IS NULL THEN      ',
'            RAISE_APPLICATION_ERROR(-20203, ''Debe Ingresar la Fecha de Nacimiento.'');',
'        END IF;',
'        IF :P1711_NOMBRE IS NULL THEN',
'            RAISE_APPLICATION_ERROR(-20203, ''Debe Ingresar el Nombre de la Persona..'');',
'        END IF;',
'        IF :P1711_TIPO_PERSONA = ''FISICA'' AND :P1700_AP_PATERNO_DC IS NULL THEN',
'            RAISE_APPLICATION_ERROR(-20203, ''Debe Ingresar el Apellido Paterno.'');',
'            ',
'        END IF;',
'        cNum_Tributario := OC_PERSONA_NATURAL_JURIDICA.NUMERO_TRIBUTARIO_RFC(',
'            :P1711_NOMBRE,',
'            :P1711_APELLIDO_PATERNO,',
'            :P1711_APELLIDO_MATERNO,',
'            :P1711_FECNACIMIENTO,',
'            :P1711_TIPO_PERSONA',
'        );',
'',
'        :P1711_RFC_GENERADO  := cNum_Tributario;',
'               IF :P1711_TIPO_DOC_IDENTIFICACION = ''RFC'' THEN',
'',
'            SELECT COUNT(1)',
'              INTO vl_Total',
'              FROM SICAS_OC.PERSONA_NATURAL_JURIDICA',
'             WHERE TIPO_DOC_IDENTIFICACION = :P1711_TIPO_DOC_IDENTIFICACION',
'               AND NUM_DOC_IDENTIFICACION  = cNum_Tributario',
'               AND ROWNUM <= 1;',
'',
'            IF NVL(:P1711_TIPO_DOC_IDENTIFICACION, ''NO_DATA'') = cNum_Tributario THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20203, ''El RFC generado (''||cNum_Tributario||'') es id\00E9ntico al que ya est\00E1 capturado en Documento de Identificaci\00F3n.'');'),
'            ELSIF vl_Total > 0 THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20203,  ''El RFC generado (''||cNum_Tributario||'') es id\00E9ntico al que ya est\00E1 capturado en Documento de Identificaci\00F3n.'');'),
'            ELSE',
'                :P1700_CONFIRM_FLAG := ''CONFIRM_DOC'';   ',
'            END IF;',
'        END IF;',
'        IF :P1711_NUM_TRIBUTARIO IS NOT NULL THEN',
'            IF NVL(:P1711_NUM_TRIBUTARIO, ''NO_DATA'') = cNum_Tributario THEn',
unistr('                                    RAISE_APPLICATION_ERROR(-20203,   ''El RFC generado (\00AB''||cNum_Tributario||''\00BB) es id\00E9ntico al que ya est\00E1 capturado en N\00FAmero Tributario.'');'),
'',
'            ELSE',
'                :P1711_CONFIRM_FLAG := ''CONFIRM_TRIB'';',
'            END IF;',
'',
'        END IF;',
'        IF :P1711_NUM_DOC_IDENTIFICACION IS NULL AND :P1711_NUM_TRIBUTARIO IS NULL THEN',
'            :P1711_NUM_DOC_IDENTIFICACION    := cNum_Tributario;',
'            :P1711_NUM_TRIBUTARIO := cNum_Tributario;',
'            :P1711_CONFIRM_FLAG  := ''DONE'';',
'        END IF;',
'',
'    ELSE',
'',
unistr('        RAISE_APPLICATION_ERROR(-20203,    ''Funci\00F3n habilitada solo para Tipo de Documento o Identificaci\00F3n Tributaria RFC.'');'),
'',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'  ',
unistr('RAISE_APPLICATION_ERROR(-20203,   ''Ocurri\00F3 un error: '' || SQLERRM);'),
'',
'END;'))
,p_attribute_02=>'P1711_TIPO_DOC_IDENTIFICACION,P1711_TIPO_ID_TRIBUTARIA,P1711_FECNACIMIENTO,P1711_TIPO_PERSONA,P1711_NOMBRE,P1711_APELLIDO_PATERNO,P1711_APELLIDO_MATERNO,P1711_NUM_TRIBUTARIO'
,p_attribute_03=>'1711_NUM_TRIBUTARIO,P1711_CONFIRM_FLAG,P1711_RFC_GENERADO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
