wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(546192732315474560)
,p_validation_name=>'VALIDATION_PREINSERT'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cMensajeError   VARCHAR2(4000);',
'    nCantPol        NUMBER;',
'BEGIN',
'    IF :P1751_FecIniVig IS NULL THEN',
'      cMensajeError := ''Debe Ingresar la Fecha Inicio de Vigencia'';',
'',
'    ELSIF :P1751_FecFinVig IS NULL THEN',
'        cMensajeError := ''Debe Ingresar la Fecha Fin de Vigencia'';',
'',
'    ELSIF :P1751_IdTipoSeg IS NULL THEN',
unistr('        cMensajeError := ''Debe Ingresar un Tipo de Seguro para la P\00F3liza'';'),
'',
'    ELSIF :P1751_PlanCob IS NULL THEN',
unistr('        cMensajeError := ''Debe Ingresar un Plan de Coberturas V\00E1lido'';'),
'      ',
'    ELSIF :P1751_Tipo_Doc_Identificacion IS NULL THEN',
unistr('        cMensajeError := ''Debe Ingresar un Tipo de Documento de Identificaci\00F3n para el Contratante'';'),
'      ',
'    ELSIF :P1751_Num_Doc_Identificacion IS NULL THEN',
unistr('        cMensajeError := ''Debe Ingresar un No. Documento de Identificaci\00F3n para el Contratante'';'),
'      ',
'    ELSIF :P1751_TipoDocIdentifAseg IS NULL THEN',
unistr('        cMensajeError := ''Debe Ingresar un Tipo de Documento de Identificaci\00F3n para el Asegurado'';'),
'      ',
'    ELSIF :P1751_NumDocIdentifAseg IS NULL THEN',
unistr('        cMensajeError := ''Debe Ingresar un No. Documento de Identificaci\00F3n para el Asegurado'';'),
'      ',
'    ELSIF :P1751_NUMPOLUNICOASIG IS NOT NULL THEN',
'        SELECT COUNT(*)',
'        INTO nCantPol',
'        FROM POLIZAS',
'        WHERE CodCia     = 1',
'        AND NumPolUnico  = :P1751_NUMPOLUNICOASIG',
'        AND StsPoliza   IN (''EMI'',''SOL'');',
'',
'        IF NVL(nCantPol,0) > 0 THEN',
unistr('            cMensajeError := ''No. de P\00F3liza Unico YA fue Asignado para otra P\00F3liza. Por Favor Verificar'';'),
'        END IF;',
'    END IF;',
'',
'    RETURN cMensajeError;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
