wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(546790203901972258)
,p_event_id=>wwv_flow_imp.id(546790119900972257)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT PorcDescuento, PorcGtoAdmin, PorcGtoAdqui, PorcUtilidad,',
'            FactorAjuste, MontoDeducible, FactFormulaDeduc,',
'            CodRiesgoRea, CodTipoBono, HorasVig, DiasVig,',
'            IndExtraPrima, AsegAdheridosPor, PorcenContributorio,',
'            FuenteRecursosPrima',
'        INTO',
'            :P1751_PORCDESCUENTO,:P1751_PORCGTOADMIN,:P1751_PORCGTOADQUI,:P1751_PORCUTILIDAD,',
'            :P1751_FACTORAJUSTE,:P1751_MONTODEDUCIBLE,:P1751_FACTFORMULADEDUC,',
'            :P1751_CODRIESGOREA,:P1751_CODTIPOBONO,:P1751_HORASVIG,:P1751_DIASVIG,',
'            :P1751_INDEXTRAPRIMA,:P1751_ASEGADHERIDOSPOR,:P1751_PORCENCONTRIBUTORIO,',
'            :P1751_FUENTERECURSOSPRIMA',
'    FROM COTIZACIONES',
'    WHERE CodCia        = 1',
'    AND CodEmpresa      = 1',
'    AND IdCotizacion    = :P1751_NUMCOTIZACION;',
'',
