wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(547627295230489902)
,p_event_id=>wwv_flow_imp.id(547626708856489902)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    cNum_Tributario  PERSONA_NATURAL_JURIDICA.Num_Tributario%TYPE;',
'    vl_Total        NUMBER := 0;',
'BEGIN ',
'    --:P1754_RFCDEPASO := ''A'';',
'    IF (:P1754_TIPO_DOC_IDENTIFICACION = ''RFC'' OR :P1754_TIPO_ID_TRIBUTARIA = ''RFC'') AND (:P1754_TIPO_PERSONA = ''FISICA'') THEN',
'        cNum_Tributario := SICAS_OC.OC_GENERARFC.GENERAPRINCIPAL(:P1754_NOMBRE,:P1754_APELLIDO_PATERNO,:P1754_APELLIDO_MATERNO,:P1754_FECNACIMIENTO);',
'        --:P1754_NUM_TRIBUTARIO := ''''||cNum_Tributario; ',
'        --:P1754_RFCDEPASO :=''A''|| cNum_Tributario;',
'  /*  ELSIF :P1754_TIPO_PERSONA IS NULL  THEN',
unistr('            apex_error.add_error(p_message => ''Solamente se Genera el RFC para Personas F\00EDsicas.'',p_display_location => apex_error.c_inline_in_notification);'),
'            */',
'        IF :P1754_TIPO_DOC_IDENTIFICACION = ''RFC'' OR :P1754_TIPO_ID_TRIBUTARIA = ''RFC'' THEN',
'            --:P1754_RFCDEPASO := cNum_Tributario;',
'',
'            SELECT COUNT(1)',
'            INTO vl_Total',
'         	FROM SICAS_OC.PERSONA_NATURAL_JURIDICA ',
'         	WHERE TIPO_DOC_IDENTIFICACION = :P1754_TIPO_DOC_IDENTIFICACION AND NUM_DOC_IDENTIFICACION = :P1754_NUM_DOC_IDENTIFICACION AND ROWNUM <= 1;',
'',
'            IF (NVL(:P1754_NUM_DOC_IDENTIFICACION,''NO_DATA'') != cNum_Tributario AND vl_Total = 0) THEN',
'                :P1754_RFCDEPASO := ''C''||cNum_Tributario;',
'                :P1754_NUM_TRIBUTARIO  := cNum_Tributario;',
'                apex_error.add_error(p_message => cNum_Tributario||'' ''||:P1754_NUM_DOC_IDENTIFICACION ,p_display_location => apex_error.c_inline_in_notification);',
unistr('                raise_application_error(-20201,''El N\00FAmero Generado es Id\00E9ntico al Capturado en Documento de Identificaci\00F3n.'');   	 '),
'            ELSIF (vl_Total >= 1) THEN',
'                :P1754_NUM_TRIBUTARIO := cNum_Tributario;',
'                apex_error.add_error(p_message => cNum_Tributario||'' ''||:P1754_NUM_DOC_IDENTIFICACION ,p_display_location => apex_error.c_inline_in_notification);',
unistr('                raise_application_error(-20201,''El N\00FAmero Generado es Id\00E9ntico al Capturado en Documento de Identificaci\00F3n.'');   	  '),
'            ELSE',
'                :P1754_RFCDEPASO := ''C''||cNum_Tributario;',
'                :P1754_NUM_TRIBUTARIO := cNum_Tributario;',
unistr('                apex_error.add_error(p_message => cNum_Tributario||''  El N\00FAmero Generado es Id\00E9ntico al Capturado en Documento de Identificaci\00F3n.'' ,p_display_location => apex_error.c_inline_in_notification);'),
unistr('  	    	    raise_application_error(-20201,''El N\00FAmero Generado es Id\00E9ntico al Capturado en Documento de Identificaci\00F3n.'');   	  		 	          '),
'	        END IF;',
'        END IF;',
'    ELSE',
unistr('        apex_error.add_error(p_message => ''Esta funci\00F3n solo aplica para personas Morales.'' ,p_display_location => apex_error.c_inline_in_notification);'),
unistr('  	    raise_application_error(-20201,''Esta funci\00F3n solo aplica para personas Morales.'');   '),
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN ',
unistr('        apex_error.add_error(p_message => ''Ocurri\00F3 un error: ''||SQLERRM,p_display_location => apex_error.c_inline_in_notification);'),
'END;'))
,p_attribute_02=>'P1754_RFCDEPASO,P1754_TIPO_DOC_IDENTIFICACION,P1754_TIPO_ID_TRIBUTARIA,P1754_FECNACIMIENTO,P1754_TIPO_PERSONA,P1754_NOMBRE,P1754_APELLIDO_PATERNO,P1754_APELLIDO_MATERNO,P1754_NUM_TRIBUTARIO'
,p_attribute_03=>'P1754_NUM_TRIBUTARIO'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
end;
