'// True Action: Execute JavaScript Code',
'apex.message.confirm(',
unistr('    ''\00BFDesea Generar la P\00F3liza de la Cotizaci\00F3n Seleccionada?'','),
'    function(okPressed) {',
'        if (okPressed) {',
'            apex.page.submit({ request: ''GENERAR_POLIZA'' });',
'        }',
'    }',
');'))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(544775786436064336)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GENERAR_POLIZA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P1800_CLIE_DEFINITIVO_GP IS NULL OR :P1800_ASEG_DEFINITIVO_GP IS NULL THEN',
'    APEX_ERROR.ADD_ERROR(',
'        p_message          => ''Debe Ingresar el Cliente y Asegurado'',',
'        p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'    );',
'ELSE',
'    BEGIN',
'        :P1800_IdPoliza := GT_COTIZACIONES.CREAR_POLIZA(',
'            1,',
'            1,',
'            :P1800_ID_COTIZACION,',
'            :P1800_CLIE_DEFINITIVO_GP,',
'            :P1800_ASEG_DEFINITIVO_GP',
'        );',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            APEX_ERROR.ADD_ERROR(',
unistr('                p_message          => ''Error al generar la p\00F3liza: '' || SQLERRM,'),
'                p_display_location => APEX_ERROR.C_INLINE_IN_NOTIFICATION',
'            );',
'    END;',
'END IF;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'GENERAR_POLIZA'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>105684089604992813
);
end;
