wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(545994280964252564)
,p_event_id=>wwv_flow_imp.id(545994174094252563)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P2000_DESC_POLCOMIS_RP,P2000_FORMATO_RP'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var checkboxValue   = $v(''P2000_REP_POLCOMIS_RP'');',
'var vFormatoArchivo = $v(''P2000_FORMATO_RP'');',
'',
'if (checkboxValue === "S") {',
'',
'    var today  = new Date();',
'    var day    = today.getDate().toString().padStart(2, ''0'');',
'    var month  = (today.getMonth() + 1).toString().padStart(2, ''0'');',
'    var year   = today.getFullYear();',
'    var formattedDate = day + month + year;',
'    var extension = (vFormatoArchivo === ''EXCEL'') ? ''.XLS'' : ''.TXT'';',
'    var description = ''POLIZAS_COMISIONES_'' + formattedDate + extension;',
'',
'    $s(''P2000_DESC_POLCOMIS_RP'', description);',
'',
'} else {',
'',
'    $s(''P2000_DESC_POLCOMIS_RP'', '''');',
'',
'}'))
);
