'   vIdReporte NUMBER;',
'BEGIN',
'   SELECT NVL(MAX(IDEXTRACCION),0) + 1',
'   INTO vIdReporte',
'   FROM SICAS_OC.EXTRACCION_DE_REPORTES;',
'',
'   INSERT INTO SICAS_OC.EXTRACCION_DE_REPORTES (',
'      IDEXTRACCION,',
'      TIPO_REPORTE,',
'      CODUSR,',
'      FECREPORTE,',
'      STATUS,',
'      REPORTE,',
'      FILE_NAME',
'   ) VALUES (',
'      vIdReporte,',
'      ''REP_POL_COMISIONES'',',
'      :APP_USER,',
'      SYSDATE,',
'      ''GEN'',',
'      EMPTY_BLOB(),',
'      :P2000_DESC_POLCOMIS_RP',
'   );',
'',
'   OC_REPORTES_POLIZAS.REP_POL_COMISIONES (',
'      cNomArchivo   => :P2000_DESC_POLCOMIS_RP,',
'      cFormato      => :P2000_FORMATO_RP,',
'      nIdReporte    => vIdReporte,',
'      cIdTipoSeg    => :P2000_TIPO_SEG_RP,',
'      cPlanCob      => :P2000_PLANCOB_RP,',
'      cCodMoneda    => :P2000_MONEDA_RP,',
'      cCodAgente    => :P2000_AGENTE_RP,',
'      dFecDesde     => :P2000_FEC_INI_RP,',
'      dFecHasta     => :P2000_FEC_FIN_RP ',
'   );',
'END;'))
