 p_id=>wwv_flow_imp.id(546420056857579825)
,p_plug_name=>'IG_POL_RENOV'
,p_region_name=>'IG_POL_RENOV'
,p_parent_plug_id=>wwv_flow_imp.id(545878940737642134)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>110
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT P.IDPOLIZA, ',
'P.NUMPOLUNICO, ',
'P.NUMPOLREF, ',
'SICAS_OC.OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE) AS CODCLIENTE, ',
'P.FECINIVIG, ',
'P.FECFINVIG, ',
'P.FECRENOVACION,  ',
'NULL AS SOLICITUD,',
'''N'' AS INDSUBGRUPOS,',
'''N'' AS INDASEGURADOS,',
'''N'' AS INDPOLREN',
'FROM POLIZAS P',
'WHERE P.CodCia = :P5000_CODCIA ',
'  AND P.StsPoliza = ''EMI'' ',
'  AND SUBSTR(P.NUMPOLUNICO,1,3) != ''TRD'' ',
'  AND P.FecRenovacion >= :P5000_FECINICIO ',
' AND P.FecRenovacion <= :P5000_FECHASTA ',
'  AND EXISTS (',
'        SELECT 1',
'        FROM DETALLE_POLIZA D, AGENTES_DISTRIBUCION_COMISION A',
'        WHERE ((A.Cod_Agente_Distr = :P5000_CODAGENTE AND :P5000_CODAGENTE != ''%'')',
'            OR (A.Cod_Agente_Distr LIKE :P5000_CODAGENTE AND :P5000_CODAGENTE = ''%''))',
'          AND A.IDetPol = D.IDetPol',
'          AND A.IdPoliza = D.IdPoliza',
'          AND A.CodCia = D.CodCia',
'          AND ((D.IdTipoSeg = :P5000_IDTIPOSEG AND :P5000_IDTIPOSEG != ''%'')',
'            OR (D.IdTipoSeg LIKE :P5000_IDTIPOSEG AND :P5000_IDTIPOSEG = ''%''))',
'          AND D.IdPoliza = P.IdPoliza',
'          AND D.CodCia = P.CodCia',
'  )',
' AND :P5000_BUSCAR = ''S'';'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P5000_CODCIA,P5000_FECINICIO,P5000_FECHASTA,P5000_IDTIPOSEG,P5000_CODAGENTE,P5000_BUSCAR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
