 p_id=>wwv_flow_imp.id(653872131818129092)
,p_plug_name=>'IG_POL_RENOV'
,p_region_name=>'IG_POL_RENOV'
,p_parent_plug_id=>wwv_flow_imp.id(653331015698191401)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>110
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT P.IDPOLIZA, ',
'P.NUMPOLUNICO, ',
'P.NUMPOLREF, ',
'SICAS_OC.OC_CLIENTES.NOMBRE_CLIENTE(P.CODCLIENTE) AS CODCLIENTE, ',
'P.FECINIVIG, ',
'P.FECFINVIG, ',
'P.FECRENOVACION,  ',
'NULL AS SOLICITUD,',
'''N'' AS INDPOLREN',
'FROM POLIZAS P',
'WHERE P.CodCia      = :P6000_CODCIA ',
'AND P.StsPoliza   = ''EMI'' ',
'AND SUBSTR(P.NUMPOLUNICO,1,3) != ''TRD'' ',
'AND P.FecRenovacion >= :P6000_FECINICIO',
'AND P.FecRenovacion <= :P6000_FECHASTA ',
'AND EXISTS (SELECT ''S''',
'          FROM DETALLE_POLIZA D, AGENTES_DISTRIBUCION_COMISION A',
'         WHERE ((A.Cod_Agente_Distr    = :P6000_CODAGENTE AND :P6000_CODAGENTE != ''%'')',
'            OR  (A.Cod_Agente_Distr LIKE :P6000_CODAGENTE AND :P6000_CODAGENTE = ''%''))',
'           AND A.IDetPol               = D.IDetPol',
'           AND A.IdPoliza              = D.IdPoliza',
'           AND A.CodCia                = D.CodCia',
'           AND ((D.IdTipoSeg           = :P6000_IDTIPOSEG AND :P6000_IDTIPOSEG != ''%'')',
'            OR  (D.IdTipoSeg        LIKE :P6000_IDTIPOSEG AND :P6000_IDTIPOSEG = ''%''))',
'           AND D.IdPoliza              = P.IdPoliza',
'           AND D.CodCia                = P.CodCia) ',
'AND NOT EXISTS',
'(SELECT * FROM RENOVACIONES',
'',
'WHERE CODCIA  = :P6000_CODCIA',
'AND CODEMPRESA  = :P6000_CODEMPRESA',
'',
'AND IDPOLIZA  = P.IdPoliza ',
'AND NUMRENOV = P.NUMRENOV',
')',
'  AND :P6000_BUSCAR = ''S'';'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P6000_CODCIA,P6000_FECINICIO,P6000_FECHASTA,P6000_IDTIPOSEG,P6000_CODAGENTE,P6000_BUSCAR,P6000_CODEMPRESA'
,p_prn_content_disposition=>'ATTACHMENT'
