,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT P.FECHA_INICIO, ',
'       P.TIPOPROCESO,',
'       P.NOMBRE_PROCESO, ',
'       V1.DescValLst AS NOMBRE_PROCESO1,',
'       P.FRECUENCIA,',
'       P.NOM_JOB,',
'       V2.DescValLst AS DESC_ESTATUS,',
'       P.STSPROCESO,',
'       P.FECSTS,',
'       P.REPETIR',
'FROM PARAM_PROCESOS_MASIVOS P',
'LEFT JOIN VALORES_DE_LISTAS V1',
'  ON V1.CodValor = P.TIPOPROCESO',
' AND V1.CodLista = ''TIPOPROC''',
'LEFT JOIN VALORES_DE_LISTAS V2',
'  ON V2.CodValor = P.STSPROCESO',
' AND V2.CodLista = ''ESTADOS'';'))
