,p_process_name=>'BTN_ActProceso'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN ',
'         OC_JOB.CREAR(:P7000_NOMJOB,:P7000_FECINICIO,:P7000_FRECUENCIA,:P7000_NOMBREJOB);',
'         UPDATE PARAM_PROCESOS_MASIVOS',
'            SET StsProceso  = ''VIG'' ',
'          WHERE TipoProceso =  :P7000_TIPOPROCESO',
'            AND CodCia      =  1',
'            AND CodEmpresa  =  1',
'            AND StsProceso  =  ''SOL'' ; ',
'   	  EXCEPTION',
'   	  	   WHEN OTHERS THEN',
'            RAISE_APPLICATION_ERROR(-20001, ''Error en activar proceso'');',
'      END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(546423916491579864)
