wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(304114915180926427)
,p_plug_name=>unistr('Listado de P\00F3lizas')
,p_region_name=>'polizas'
,p_parent_plug_id=>wwv_flow_imp.id(304095841780785602)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690539339353096000)
,p_plug_display_sequence=>80
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT P.CodCliente,',
'                REPLACE(OC_CLIENTES.NOMBRE_CLIENTE(P.CodCliente), '','') NomContratante,',
'                P.NumPolUnico,',
'                DP.IdPoliza,',
'                DP.IDetPol,',
'                sicas_apex.get_fecha_pago(1, DP.IdPoliza) fecpago,',
'                DP.FecIniVig,',
'                DP.FecFinVig,',
'                DP.IdTipoSeg,',
'                DP.PlanCob,',
'                DP.StsDetalle,',
'                DP.CodEmpresa,',
'                P.IndPolCol,',
'                OC_TIPOS_DE_SEGUROS.TIPO_DE_SEGURO(DP.CodCia,',
'                                                   DP.CodEmpresa,',
'                                                   DP.IdTipoSeg) DescTipoSeg,',
'                OC_PLAN_COBERTURAS.NOMBRE_PLANCOB(DP.CodCia,',
'                                                  DP.CodEmpresa,',
'                                                  DP.IdTipoSeg,',
'                                                  DP.PlanCob) DescPlanCob,',
'                OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', DP.StsDetalle) DescStatus',
'                ',
'                --,OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'',FA.STSFACT) DescStatusPOL,  --P.STSPOLIZA)   DescStatusPOL',
'               ,',
'                P.NUMPOLREF,',
'                --reporte_siniestros.agente(:P9000_TIPO_DOC,:P9000_NUM_DOC,p.idpoliza,dp.idetpol) AS COD_ASEGURADO,',
'                P.CodCia CodCia,',
'                OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ADMINPOL'',',
'                                                  P.TipoAdministracion) TipoAdmon,',
'                OC_PLAN_DE_PAGOS.DESCRIPCION_PLAN(DP.CodCia,',
'                                                  DP.CodEmpresa,',
'                                                  DP.CodPlanPago) PlanPago,',
'                OC_PLAN_DE_PAGOS.FRECUENCIA_PAGOS(DP.CodCia,',
'                                                  DP.CodEmpresa,',
'                                                  DP.CodPlanPago) FrecPago,',
'                P.CodGrupoEc CodGrupoEc,',
'                DP.CodFilial CodFilial,',
'                DP.CodCategoria CodCategoria,',
'                P.DescPoliza,',
'                AP.Cod_Agente CodAgente,',
'                OC_AGENTES.NOMBRE_AGENTE(DP.CodCia, AP.Cod_Agente) NomAgente,',
'                P.FecRenovacion FecRenovacion,',
'                SICAS_APEX.GET_ESTATUS_PAGO(p.CODCIA,P.IDPOLIZA) StsPoliza,',
'                P.IndFacturaPol,',
'                P.CodAgrupador,',
'                OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''AGRUPA'', P.CodAgrupador) DescAgrupador,',
'                SICAS_APEX.TRAE_NOMBRE_SUBGRUPO(DP.CodCia,DP.CodFilial,P.CodGrupoEc) DESC_SUBGRUPO,',
'                OC_FILIALES_CATEGORIAS.DESCRIPCION_CATEGORIA(DP.CODCIA,',
'                                                             CODGRUPOEC,',
'                                                             CODFILIAL,',
'                                                             CODCATEGORIA) AS DESC_CATEGORIA,',
'                (SELECT AC2.IDENDOSO',
'                   FROM ASEGURADO A2, ASEGURADO_CERTIFICADO AC2, POLIZAS P2',
'                  WHERE P2.IDPOLIZA = P.IDPOLIZA',
'                    AND P2.IDPOLIZA = AC2.IDPOLIZA',
'                    AND P2.CODCIA = A2.CODCIA',
'                    AND AC2.CODCIA = A2.CODCIA',
'                    AND AC2.COD_ASEGURADO = A2.COD_ASEGURADO',
'                    AND AC2.IDETPOL = DP.IDETPOL',
'                    AND A2.TIPO_DOC_IDENTIFICACION = :P9000_TIPO_DOC',
'                    AND ((A2.NUM_DOC_IDENTIFICACION)) =  ((:P9000_NUM_DOC))) AS IDENDOSO,',
'                (SELECT AC2.CAMPO3 AS NUTRA',
'                   FROM ASEGURADO A2, ASEGURADO_CERTIFICADO AC2, POLIZAS P2',
'                  WHERE P2.IDPOLIZA = P.IDPOLIZA',
'                    AND P2.IDPOLIZA = AC2.IDPOLIZA',
'                    AND P2.CODCIA = A2.CODCIA',
'                    AND AC2.CODCIA = A2.CODCIA',
'                    AND AC2.COD_ASEGURADO = A2.COD_ASEGURADO',
'                    AND AC2.IDETPOL = DP.IDETPOL',
'                    AND A2.TIPO_DOC_IDENTIFICACION = :P9000_TIPO_DOC',
'                    AND A2.NUM_DOC_IDENTIFICACION = ((:P9000_NUM_DOC))) AS NUTRA,',
'                (SELECT AC2.ESTADO',
'                   FROM ASEGURADO A2, ASEGURADO_CERTIFICADO AC2, POLIZAS P2',
'                  WHERE P2.IDPOLIZA = P.IDPOLIZA',
'                    AND P2.IDPOLIZA = AC2.IDPOLIZA',
'                    AND P2.CODCIA = A2.CODCIA',
'                    AND AC2.CODCIA = A2.CODCIA',
'                    AND AC2.COD_ASEGURADO = A2.COD_ASEGURADO',
'                    AND AC2.IDETPOL = DP.IDETPOL',
'                    AND A2.TIPO_DOC_IDENTIFICACION = :P9000_TIPO_DOC',
'                    AND ((A2.NUM_DOC_IDENTIFICACION)) = ((:P9000_NUM_DOC))) AS STATUS_ASEG,',
'CASE',
'    WHEN NVL(P.StsPoliza, ''EMI'') = ''ANU'' THEN',
'        ''VA_ANULADA''',
'',
'    WHEN NVL(P.StsPoliza, ''EMI'') = ''SOL''',
'         AND OC_SOLICITUD_EMISION.SOLICITUD_POLIZA(',
'                 P.CodCia,',
'                 P.CodEmpresa,',
'                 P.IdPoliza',
'             ) = 0',
'    THEN',
'        ''VA_SOLICITUD''',
'',
'    WHEN NVL(P.StsPoliza, ''EMI'') = ''SOL''',
'         AND OC_SOLICITUD_EMISION.SOLICITUD_POLIZA(',
'                 P.CodCia,',
'                 P.CodEmpresa,',
'                 P.IdPoliza',
'             ) <> 0',
'    THEN',
'        ''VA_SOL_REGIONAL''',
'',
'    WHEN EXISTS (',
'        SELECT 1',
'          FROM SINIESTRO S',
'         WHERE S.IdPoliza = P.IdPoliza',
'           AND S.CodCia = P.CodCia',
'           AND S.Sts_Siniestro NOT IN (''ANU'')',
'           AND S.Monto_Reserva_Moneda <> 0',
'    ) THEN',
'        ''VA_SINIESTRO''',
'',
'    WHEN NVL(P.StsPoliza, ''EMI'') = ''XRE''',
'         OR (',
'             P.FecRenovacion <= TRUNC(SYSDATE)',
'             AND NVL(P.StsPoliza, ''EMI'') = ''EMI''',
'         )',
'    THEN',
'        ''VA_X_RENOV''',
'',
'    WHEN NVL(P.StsPoliza, ''EMI'') = ''REN'' THEN',
'        ''VA_RENOV''',
'',
'    WHEN NVL(P.StsPoliza, ''EMI'') = ''CAD'' THEN',
'        ''VA_CADUCADA''',
'',
'    WHEN EXISTS (',
'        SELECT 1',
'          FROM FACTURAS F',
'         WHERE F.IdPoliza = P.IdPoliza',
'           AND F.CodCia = P.CodCia',
'           AND F.StsFact = ''XEM''',
'    ) THEN',
'        ''VA_FACT_XEM''',
'',
'    WHEN EXISTS (',
'        SELECT 1',
'          FROM NOTAS_DE_CREDITO NC',
'         WHERE NC.IdPoliza = P.IdPoliza',
'           AND NC.CodCia = P.CodCia',
'           AND NC.StsNcr = ''XEM''',
'    ) THEN',
'        ''VA_NC_XEM''',
'END AS COLOR',
'',
'  FROM POLIZAS P, DETALLE_POLIZA DP, AGENTE_POLIZA AP',
' WHERE DP.IdPoliza = P.IdPoliza',
'   AND DP.CodEmpresa = P.CodEmpresa',
'   AND DP.CodCia = P.CodCia',
'--and reporte_siniestros.agente(:P9000_TIPO_DOC,:P9000_NUM_DOC,p.idpoliza,dp.idetpol) is not null',
'   AND P.CodCia = 1',
'   AND (P.IdPoliza, DP.IDetPol) IN',
'       (SELECT DISTINCT AC.IdPoliza, AC.IDetPol',
'          FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'         WHERE AC.CodCia = A.CodCia',
'           AND AC.Cod_Asegurado = A.Cod_Asegurado',
'           AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'           AND A.NUM_DOC_IDENTIFICACION = upper(:P9000_NUM_DOC)',
'        UNION',
'        SELECT DISTINCT AC.IdPoliza, AC.IDetPol',
'          FROM ASEGURADO A, ASEGURADO_CERT AC',
'         WHERE AC.CodCia = A.CodCia',
'           AND AC.Cod_Asegurado = A.Cod_Asegurado',
'           AND A.Tipo_Doc_Identificacion  = :P9000_TIPO_DOC',
'           AND A.NUM_DOC_IDENTIFICACION = upper(:P9000_NUM_DOC)',
'        UNION',
'        SELECT DISTINCT D.IdPoliza, D.IDetPol',
'          FROM ASEGURADO A, DETALLE_POLIZA D',
'         WHERE OC_ASEGURADO_CERTIFICADO.TIENE_ASEGURADOS(D.CodCia,',
'                                                         D.IdPoliza,',
'                                                         D.IDetPol,',
'                                                         0) = ''N''',
'           AND D.CodCia = A.CodCia',
'           AND D.Cod_Asegurado = A.Cod_Asegurado',
'           AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'           AND A.NUM_DOC_IDENTIFICACION = upper(:P9000_NUM_DOC)',
'        UNION',
'        SELECT DISTINCT D.IdPoliza, D.IDetPol',
'          FROM CLIENTES C, POLIZAS P, DETALLE_POLIZA D',
'         WHERE D.IdPoliza = P.IdPoliza',
'           AND D.CodCia = P.CodCia',
'           AND P.CodCliente = C.CodCliente',
'           AND C.Tipo_Doc_Identificacion  = :P9000_TIPO_DOC',
'           AND c.NUM_DOC_IDENTIFICACION = upper(((:P9000_NUM_DOC))))',
'      --',
'   AND AP.CODCIA = P.CODCIA',
'   AND AP.IDPOLIZA = P.IDPOLIZA',
'   AND AP.IND_PRINCIPAL = ''S''',
'   AND ((P.IdPoliza = :P9000_IDPOLIZA_Q AND :P9000_IDPOLIZA_Q IS NOT NULL) OR',
'       P.IdPoliza = P.IdPoliza AND :P9000_IDPOLIZA_Q IS NULL)',
'   AND ((P.NumPolRef = :P9000_NUMREF_SIN_Q AND :P9000_NUMREF_SIN_Q IS NOT NULL) OR',
'       NVL(P.NumPolRef, '' '') = NVL(P.NumPolRef, '' '') AND',
'       :P9000_NUMREF_SIN_Q IS NULL)',
'   AND ((P.NumPolUnico = :P9000_NUMPOLUNICO_Q AND',
'       :P9000_NUMPOLUNICO_Q IS NOT NULL) OR',
'       P.NumPolUnico = P.NumPolUnico AND :P9000_NUMPOLUNICO_Q IS NULL)',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P9000_TIPO_DOC,P9000_NUM_DOC,P9000_IDPOLIZA_Q,P9000_NUMREF_SIN_Q,P9000_NUMPOLUNICO_Q'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>unistr('Listado de P\00F3lizas')
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
end;
