wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(304390218792808032)
,p_plug_name=>'Coberturas'
,p_parent_plug_id=>wwv_flow_imp.id(304262330564053014)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' SELECT DISTINCT CA.CodCobert, CA.SumaAseg_Local, CA.SumaAseg_Moneda, 0 Tasa, ',
'         0 Prima_Local, 0 Prima_Moneda, CA.Cod_Moneda,',
'         CA.Deducible_Local, CA.Deducible_Moneda, CA.StsCobertura,',
'         OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', CA.StsCobertura) cDescStatus,',
'         OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(CA.CodCia, CA.CodEmpresa, CA.IdTipoSeg, CA.PlanCob, CA.CodCobert) DescCobertura,',
'         DP.CodFilial CodSubGrupo, DP.CodCategoria CodCategoria,',
'         OC_FILIALES.NOMBRE_FILIAL(CA.CodCia, PO.CodGrupoEC, DP.CodFilial) DesSubgrupo,',
'         OC_FILIALES_CATEGORIAS.DESCRIPCION_CATEGORIA(CA.CodCia, PO.CodGrupoEC, DP.CodFilial, DP.CodCategoria) DesCategoria,',
'         CA.CodEmpresa, CA.IdTipoSeg, CA.PlanCob,CA.Cod_Asegurado',
'    FROM COBERT_ACT_ASEG CA, POLIZAS PO, DETALLE_POLIZA DP',
'   WHERE CA.IdPoliza      = PO.IdPoliza',
'     AND CA.IdPoliza      = DP.IdPoliza',
'     AND CA.IDetPol       = DP.IDetPol',
'     and CA.CodCia        = :P9000_CODCIA',
'     AND CA.CodEmpresa    = :P9000_COD_EMPRESA',
'     AND CA.IdPoliza      = :P9000_IDPOLIZA',
'     AND CA.IDetPol       = :P9000_CERTIFICADO',
'     AND CA.IdTipoSeg     = :P9000_IDTIPOSEG',
'     AND CA.PlanCob       = :P9000_PLANCOB',
'    AND CA.Cod_Asegurado IN (SELECT DISTINCT AC.Cod_Asegurado',
'                                FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'                               WHERE AC.CodCia                 = A.CodCia',
'                                 AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'                                 AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'                                 AND A.Num_Doc_Identificacion  = :P9000_NUM_DOC)                           ',
'  UNION',
'  SELECT DISTINCT CT.CodCobert, CT.SumaAseg_Local, CT.SumaAseg_Moneda, 0 Tasa, ',
'         0 Prima_Local, 0 Prima_Moneda, CT.Cod_Moneda,',
'         CT.Deducible_Local, CT.Deducible_Moneda, CT.StsCobertura,',
'         OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', CT.StsCobertura) cDescStatus,',
'         OC_COBERTURAS_DE_SEGUROS.DESCRIPCION_COBERTURA(CT.CodCia, CT.CodEmpresa, CT.IdTipoSeg, CT.PlanCob, CT.CodCobert) DescCobertura,',
'         DP.CodFilial CodSubGrupo, DP.CodCategoria CodCategoria,',
'         OC_FILIALES.NOMBRE_FILIAL(CT.CodCia, PO.CodGrupoEC, DP.CodFilial) DesSubgrupo,',
'         OC_FILIALES_CATEGORIAS.DESCRIPCION_CATEGORIA(CT.CodCia, PO.CodGrupoEC, DP.CodFilial, DP.CodCategoria) DesCategoria,',
'         CT.CodEmpresa, CT.IdTipoSeg, CT.PlanCob, CT.Cod_Asegurado',
'    FROM COBERT_ACT CT, POLIZAS PO, DETALLE_POLIZA DP',
'   WHERE CT.CodCia        = :P9000_CODCIA',
'     AND CT.CodEmpresa    = :P9000_COD_EMPRESA',
'     AND CT.IdPoliza      = :P9000_IDPOLIZA',
'     AND CT.IDetPol       = :P9000_CERTIFICADO',
'     AND CT.IdTipoSeg     = :P9000_IDTIPOSEG',
'     AND CT.PlanCob       = :P9000_PLANCOB',
'     AND CT.IdPoliza      = PO.IdPoliza',
'     AND CT.IdPoliza      = DP.IdPoliza',
'     AND CT.IDetPol       = DP.IDetPol     ',
'     AND CT.Cod_Asegurado IN (SELECT DISTINCT D.Cod_Asegurado',
'                                FROM ASEGURADO A, DETALLE_POLIZA D',
'                               WHERE D.CodCia                  = A.CodCia',
'                                AND D.Cod_Asegurado           = A.Cod_Asegurado',
'                                 AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
