wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(304492499145649651)
,p_plug_name=>'Asistencias'
,p_parent_plug_id=>wwv_flow_imp.id(304262416795053015)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>50
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CodAsistencia, CodMoneda, MontoAsistLocal, MontoAsistMoneda, FecSts, StsAsistencia,',
'         OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', StsAsistencia) cDescStatus, IdEndoso,',
'         OC_ASISTENCIAS.DESCRIPCION_ASISTENCIA(CodCia, CodEmpresa, CodAsistencia) DescAsistencia,',
'         OC_MONEDA.DESCRIPCION_MONEDA(CodMoneda) DescMoneda, CodCia, CodEmpresa',
'    FROM ASISTENCIAS_ASEGURADO',
'   WHERE CodCia        = :P9000_CODCIA',
'     AND CodEmpresa    = :P9000_CODEMPRESA_ASISTENCIA',
'     AND IdPoliza      = :P9000_IDPOLIZA',
'     AND IDetPol       = :P9000_CERTIFICADO',
'     AND Cod_Asegurado IN (SELECT DISTINCT AC.Cod_Asegurado',
'                             FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'                            WHERE AC.CodCia                 = A.CodCia',
'                              AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'                              AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'                              AND A.Num_Doc_Identificacion  = :P9000_NUM_DOC',
'                           UNION',
'                           SELECT DISTINCT AC.Cod_Asegurado -- Asegurado Modelo',
'                             FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'                            WHERE AC.CodCia                 = A.CodCia',
'                              AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'                              AND A.Tipo_Doc_Identificacion = ''RFC''',
'                              AND A.Num_Doc_Identificacion  = ''MOAS19830601'')',
'  UNION',
'  SELECT CodAsistencia, CodMoneda, MontoAsistLocal, MontoAsistMoneda, FecSts, StsAsistencia,',
'         OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', StsAsistencia) cDescStatus, IdEndoso,',
'         OC_ASISTENCIAS.DESCRIPCION_ASISTENCIA(CodCia, CodEmpresa, CodAsistencia) DescAsistencia,',
'         OC_MONEDA.DESCRIPCION_MONEDA(CodMoneda) DescMoneda, CodCia, CodEmpresa',
'    FROM ASISTENCIAS_DETALLE_POLIZA',
'   WHERE CodCia        = :P9000_CODCIA',
'     AND CodEmpresa    = :P9000_CODEMPRESA_ASISTENCIA',
'     AND IdPoliza      = :P9000_IDPOLIZA',
'     AND IDetPol       = :P9000_CERTIFICADO;'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Asistencias'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
