 p_id=>wwv_flow_imp.id(304588725015364523)
,p_plug_name=>'Clausulas'
,p_parent_plug_id=>wwv_flow_imp.id(304262503151053016)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT Cod_Clausula, Tipo_Clausula',
'        ,OC_CLAUSULAS.DESCRIPCION(nvl(:P9000_CODCIA,1) ,1, Tipo_Clausula) AS DESCTIPO',
'        , Inicio_Vigencia, Fin_Vigencia,',
'          OC_VALORES_DE_LISTAS.BUSCA_LVALOR (''TIPCLAUS'', Tipo_Clausula) DescClausula',
'                  ,ESTADO',
'',
'     FROM CLAUSULAS_DETALLE',
'    WHERE CodCia        = :P9000_CODCIA',
'      AND IdPoliza      = :P9000_IDPOLIZA',
'      AND IDetPol       = :P9000_CERTIFICADO',
'    UNION',
'SELECT DISTINCT Cod_Clausula, Tipo_Clausula,OC_CLAUSULAS.DESCRIPCION(nvl(:P9000_CODCIA,1) ,1, Tipo_Clausula) AS DESCTIPO',
'        , Inicio_Vigencia, Fin_Vigencia',
'        ,OC_VALORES_DE_LISTAS.BUSCA_LVALOR (''TIPCLAUS'', Tipo_Clausula) DescClausula',
'        ,ESTADO',
'     FROM CLAUSULAS_POLIZA',
'    WHERE CodCia        = :P9000_CODCIA',
'      AND IdPoliza      = :P9000_IDPOLIZA;'))
,p_plug_source_type=>'NATIVE_IG'
