wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(306021353357870428)
,p_plug_name=>'Siniestros'
,p_parent_plug_id=>wwv_flow_imp.id(304262651680053017)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690529533917095992)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT S.IdSiniestro, S.Fec_Ocurrencia, S.Fec_Notificacion, S.Sts_Siniestro, ',
'       S2.MONTO_RESERVADO_LOCAL Monto_Reserva_Local ,S2.MONTO_RESERVADO_MONEDA Monto_Reserva_Moneda',
'       , S2.MONTO_PAGADO_LOCAL Monto_Pago_Local, S2.MONTO_PAGADO_MONEDA Monto_Pago_Moneda, ',
'       S.Cod_Asegurado,',
'       OC_ASEGURADO.NOMBRE_ASEGURADO(S.CodCia, S.CodEmpresa, S.Cod_Asegurado) cDescCodAsegurado,',
'       S.Motivo_de_Siniestro, OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''CAUSIN'', S.Motivo_de_Siniestro) DescMotivo,',
'       OC_VALORES_DE_LISTAS.BUSCA_LVALOR(''ESTADOS'', S.Sts_Siniestro) DescStatus,',
'       S.NumSiniRef, S.IDetPol, S.IdPoliza         ',
'       --,f_get_ult_fecha_pago(S.IdSiniestro)  as ultfecpago',
'       ,sysdate   as ultfecpago',
'     FROM SINIESTRO S,',
'          DETALLE_SINIESTRO_ASEG  S2',
'    WHERE S.CodCia         = :P9000_CODCIA',
'    AND   S.IdPoliza       = :P9000_IDPOLIZA',
'    AND (S.IdPoliza, S.IDetPol, S.Cod_Asegurado)',
'                                    IN (SELECT DISTINCT AC.IdPoliza, AC.IDetPol, AC.Cod_Asegurado',
'                                          FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'                                         WHERE AC.CodCia                 = A.CodCia',
'                                           AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'                                           AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'                                           AND A.Num_Doc_Identificacion  = :P9000_NUM_DOC',
'                                         UNION',
'                                        SELECT DISTINCT AC.IdPoliza, AC.IDetPol, AC.Cod_Asegurado',
'                                          FROM ASEGURADO A, ASEGURADO_CERT AC',
'                                         WHERE AC.CodCia                 = A.CodCia',
'                                           AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'                                           AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'                                           AND A.Num_Doc_Identificacion  = :P9000_NUM_DOC',
'                                         UNION',
'                                        SELECT DISTINCT D.IdPoliza, D.IDetPol, D.Cod_Asegurado',
'                                          FROM ASEGURADO A, DETALLE_POLIZA D',
'                                         WHERE D.CodCia                  = A.CodCia',
'                                           AND D.Cod_Asegurado           = A.Cod_Asegurado',
'                                           AND A.Tipo_Doc_Identificacion = :P9000_TIPO_DOC',
'                                           AND A.Num_Doc_Identificacion  = :P9000_NUM_DOC',
'                                           )',
'  AND  S2.IDSINIESTRO  = S.IDSINIESTRO                                           ',
'  AND  S2.IDPOLIZA     = S.IDPOLIZA      ',
'  AND  S2.IDDETSIN  = 1; ',
'  '))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P9000_CODCIA,P9000_IDPOLIZA_CLAU,P9000_NUM_DOC,P9000_TIPO_DOC'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
