,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT E.IDPOLIZA           IDPOLIZA',
'      ,E.IDENDOSO           IDENDOSO     ',
'      ,E.TIPOENDOSO         TIPOENDOSO',
'      ,E.NUMENDREF          NUMENDREF',
'      ,E.FECINIVIG          FECINIVIG',
'      ,E.FECFINVIG          FECFINVIG',
'      ,E.FECSOLICITUD       FECSOLICITUD',
'      ,E.FECEMISION         FECEMISION',
'      ,E.STSENDOSO          STSENDOSO',
'      ,E.FECSTS             FECSTS',
'      ,E.CODPLANPAGO        CODPLANPAGO',
'      ,E.FECANUL            FECANUL',
'      ,E.MOTIVANUL          MOTIVANUL',
'      ,E.SUMA_ASEG_LOCAL    SUMA_ASEG_LOCAL',
'      ,E.SUMA_ASEG_MONEDA   SUMA_ASEG_MONEDA',
'      ,E.PRIMA_NETA_LOCAL   PRIMA_NETA_LOCAL',
'      ,E.DESCENDOSO         DESCENDOSO',
'      ,E.PRIMA_NETA_MONEDA  PRIMA_NETA_MONEDA',
'      ,E.PORCCOMIS          PORCCOMIS',
'      ,E.CODEMPRESA         CODEMPRESA',
'      ,E.CODCIA             CODCIA',
'      ,E.IDETPOL            IDETPOL',
'      ,E.NUM_BIEN           NUM_BIEN',
'      ,E.MOTIVO_ENDOSO      MOTIVO_ENDOSO',
'      ,E.FECEXC             FECEXC',
'      ,E.INDCALCDERECHOEMIS INDCALCDERECHOEMIS',
'      ,NULL  fecpago',
'FROM ENDOSOS                E',
'    ,ASEGURADO_CERTIFICADO AC',
'WHERE E.CODCIA    = :P9000_CODCIA',
'AND   E.IDPOLIZA  = :P9000_IDPOLIZA',
'AND   E.TIPOENDOSO  IN (''INA'',''ESV'')',
'AND AC.IDPOLIZA  = E.IDPOLIZA',
'AND AC.COD_ASEGURADO = :P9000_CODASEGURADO_END',
'AND AC.IDENDOSO      = E.IDENDOSO'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P9000_CODCIA,P9000_IDPOLIZA_CLAU,P9000_CODASEGURADO_END'
