,p_action_sequence=>100
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P9000_TIPO_DOCUMENTO := :P9000_TIPO_DOC;',
':P9000_NUM_DOC_IDENTIFICACION := :P9000_NUM_DOC;',
':P9000_CDESCCODASEG_END := :P9000_NOMBRE_PERSONA;',
'',
'select pnj.tipo_persona,nombre,apellido_paterno,apellido_materno,sexo,estadocivil,fecnacimiento',
',DIRECRES,numexterior,numinterior,CODPOSRES,CODCOLRES,CODPAISRES,CODPROVRES,CODDISTRES,CODCORRRES',
',LADATELRES,telres,EMAIL,CODACTIVIDAD,FECINGRESO,TIPO_ID_TRIBUTARIA,NUM_TRIBUTARIO',
'into :P9000_TIPO_PERSONA,:P9000_NOMBRE,:P9000_APELLIDO_PATERNO,:P9000_APELLIDO_MATERNO,:P9000_SEXO,:P9000_ESTADO_CIVIL,:P9000_FECNAC',
'    ,:P9000_DIRECCION,:P9000_EXT,:P9000_INT,:P9000_CODPOSRES,:P9000_CODCOLRES,:P9000_CODPAIRES,:P9000_CODPROVRES,:P9000_CODDITRES,:P9000_CODCORRRES',
'    ,:P9000_LADA,:P9000_TELEFONO,:P9000_EMAIL,:P9000_COD_ACTIVIDAD,:P9000_FECINGRESO,:P9000_TIPO_ID_TRIBUTARIA,:P9000_NO_DE_DOCUMENTO',
'from PERSONA_NATURAL_JURIDICA Pnj ',
'where TIPO_DOC_IDENTIFICACION = :P9000_TIPO_DOCUMENTO ',
'and num_doc_identificacion = :P9000_NUM_DOC_IDENTIFICACION; ',
'',
':P9000_DESCPOSRES := SICAS_APEX.FUNC_CODPOSTAL(:P9000_CODPOSRES);',
':P9000_DESCPAIRES := SICAS_APEX.FUNC_PAIS(:P9000_CODPAIRES);',
':P9000_DESCPROVRES := SICAS_APEX.FUNC_PROVINCIA(:P9000_CODPAIRES,:P9000_CODPROVRES);',
':P9000_DESCDISTRES := SICAS_APEX.FUNC_DISTRITO(:P9000_CODPAIRES,:P9000_CODPROVRES,:P9000_CODDITRES);',
':P9000_DESCCORRRES := SICAS_APEX.FUNC_CORREGIMIENTO(:P9000_CODPAIRES,:P9000_CODPROVRES,:P9000_CODDITRES,:P9000_CODCORRRES);',
':P9000_DESCCOLRES := SICAS_APEX.FUNC_COLONIA(:P9000_CODPOSRES,:P9000_CODCOLRES,:P9000_CODPAIRES,:P9000_CODPROVRES,:P9000_CODDITRES,:P9000_CODCORRRES);',
'',
' IF :P9000_COD_ACTIVIDAD IS NOT NULL THEN',
'  :P9000_DESCACTIVIDAD  := OC_ACTIVIDADES_ECONOMICAS.DESCRIPCION(:P9000_COD_ACTIVIDAD);',
'END IF;'))
,p_attribute_02=>'P9000_TIPO_DOCUMENTO,P9000_NUM_DOC_IDENTIFICACION,P9000_TIPO_PERSONA,P9000_NOMBRE,P9000_APELLIDO_PATERNO,P9000_APELLIDO_MATERNO,P9000_SEXO,P9000_ESTADO_CIVIL,P9000_FECNAC,P9000_DIRECCION,P9000_EXT,P9000_INT,P9000_CODPOSRES,P9000_CODCOLRES,P9000_CODPA'
||'IRES,P9000_CODPROVRES,P9000_CODDITRES,P9000_CODCORRRES,P9000_LADA,P9000_TELEFONO,P9000_EMAIL,P9000_COD_ACTIVIDAD,P9000_FECINGRESO,P9000_TIPO_ID_TRIBUTARIA,P9000_NO_DE_DOCUMENTO,P9000_DESCPOSRES,P9000_DESCPAIRES,P9000_DESCPROVRES,P9000_DESCDISTRES,P90'
||'00_DESCCORRRES,P9000_DESCCOLRES,P9000_DESCACTIVIDAD'
,p_attribute_03=>'P9000_TIPO_DOCUMENTO,P9000_NUM_DOC_IDENTIFICACION,P9000_TIPO_PERSONA,P9000_NOMBRE,P9000_APELLIDO_PATERNO,P9000_APELLIDO_MATERNO,P9000_SEXO,P9000_ESTADO_CIVIL,P9000_FECNAC,P9000_DIRECCION,P9000_EXT,P9000_INT,P9000_CODPOSRES,P9000_CODCOLRES,P9000_CODPA'
||'IRES,P9000_CODPROVRES,P9000_CODDITRES,P9000_CODCORRRES,P9000_LADA,P9000_TELEFONO,P9000_EMAIL,P9000_COD_ACTIVIDAD,P9000_FECINGRESO,P9000_TIPO_ID_TRIBUTARIA,P9000_NO_DE_DOCUMENTO,P9000_DESCPOSRES,P9000_DESCPAIRES,P9000_DESCPROVRES,P9000_DESCDISTRES,P90'
