wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(99180197565974990)
,p_event_id=>wwv_flow_imp.id(99177619288974989)
,p_event_result=>'TRUE'
,p_action_sequence=>60
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'   nMtoReserva        	 NUMBER(28,2) := 0;',
'  nMtoPagado           NUMBER(28,2) := 0;',
'  nMtoSaldoSACobert    NUMBER(28,2) := 0; ',
'  nMto_Rva_Moneda      COBERTURA_SINIESTRO.Monto_Reservado_Local%TYPE := 0;',
'  nMonto_Rva_Local     COBERTURA_SINIESTRO.Monto_Reservado_Local%TYPE := 0;',
'  nMonto_Pagado_Moneda COBERTURA_SINIESTRO.Monto_Pagado_Moneda%TYPE 	:= 0; ',
'  nMonto_Pagado_Local  COBERTURA_SINIESTRO.Monto_Pagado_Local%TYPE 		:= 0;',
'  nDummy	NUMBER;',
'CURSOR SIN_Q IS',
'    SELECT S.IdSiniestro,S.IdPoliza,DS.IdDetSin',
'      FROM SINIESTRO S,DETALLE_SINIESTRO DS',
'     WHERE S.CodCia        = :P9000_CODCIA',
'       AND S.CodEmpresa    = :P9000_CODEMPRESA_COB',
'       AND S.IdPoliza      = :P9000_IDPOLIZA',
'       AND S.IDetPol       = :P9000_CERTIFICADO',
'       AND S.IdSiniestro 	 = DS.IdSiniestro;',
'       ',
'CURSOR SIN_ASEG_Q IS',
'    SELECT S.IdSiniestro,S.IdPoliza,DS.IdDetSin',
'      FROM SINIESTRO S,DETALLE_SINIESTRO_ASEG DS',
'     WHERE S.CodCia        = :P9000_CODCIA',
'       AND S.CodEmpresa    = :P9000_CODEMPRESA_COB',
'       AND S.IdPoliza      = :P9000_IDPOLIZA',
'       AND S.IDetPol       = :P9000_CERTIFICADO',
'       AND S.IdSiniestro = DS.IdSiniestro; ',
'BEGIN',
'    FOR W IN SIN_Q LOOP',
'    	OC_COBERTURA_SINIESTRO.MONTO_RESERVA(W.IdSiniestro, W.IdPoliza, W.IdDetSin, :P9000_CODCOBERT, nMto_Rva_Moneda, nMonto_Rva_Local);',
'    	nMtoReserva := nMtoReserva + NVL(nMto_Rva_Moneda,0);',
'    	OC_COBERTURA_SINIESTRO.MONTO_PAGADO(W.IdSiniestro, W.IdPoliza, W.IdDetSin, :P9000_CODCOBERT, nMonto_Pagado_Moneda, nMonto_Pagado_Local);',
'    	nMtoPagado  := nMtoPagado + NVL(nMonto_Pagado_Moneda,0);',
'    END LOOP;',
'    FOR W IN SIN_ASEG_Q LOOP',
'    	OC_COBERTURA_SINIESTRO_ASEG.MONTO_RESERVA(W.IdSiniestro, W.IdPoliza, W.IdDetSin, :P9000_COD_ASEGURADO,:P9000_CODCOBERT, nMto_Rva_Moneda, nMonto_Rva_Local);',
'    	nMtoReserva := nMtoReserva + NVL(nMto_Rva_Moneda,0);',
'    	OC_COBERTURA_SINIESTRO_ASEG.MONTO_PAGADO(W.IdSiniestro, W.IdPoliza, W.IdDetSin, :P9000_COD_ASEGURADO, :P9000_CODCOBERT, nMonto_Pagado_Moneda, nMonto_Pagado_Local);',
'    	nMtoPagado  := nMtoPagado + NVL(nMonto_Pagado_Moneda,0);',
'    END LOOP;',
'   :P9000_SUMA_ASEG_LOCAL := to_number(:P9000_SUMA_ASEG_LOCAL); ',
'    nMtoSaldoSACobert 					 	 := nvl(:P9000_SUMA_ASEG_LOCAL,0) - ((nvl(nMtoReserva,0) - nvl(nMtoPagado,0)) + nvl(nMtoPagado,0));',
'    :P9000_MONTO_RESERVA   := NVL(nMtoReserva,0);',
'    :P9000_MONTO_PAGADO    := NVL(nMtoPagado,0);',
'    :P9000_SALDO_SUMA_ASEGURADA := NVL(nMtoSaldoSACobert,:P9000_SUMA_ASEG_LOCAL);',
'END;'))
,p_attribute_02=>'P9000_MONTO_RESERVA,P9000_MONTO_PAGADO,P9000_SALDO_SUMA_ASEGURADA'
,p_attribute_03=>'P9000_MONTO_RESERVA,P9000_MONTO_PAGADO,P9000_SALDO_SUMA_ASEGURADA'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
