wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(99161965868974978)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('compa\00F1ia')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'cqry varchar2(5000);',
'cqryF varchar2(5000);',
'cwhere varchar2(5000);',
'cDefault VARCHAR2(4000);',
'begin',
':P9000_NOMCIA := oc_empresas.nombre_compania(nvl(:codcia,1));',
':P9000_CODCIA := NVL(:CODCIA,1);',
':P9000_INDINSTRUCESPEC:=''N'';',
'   IF :P9000_IDPOLIZA_Q IS NOT NULL THEN',
'',
'    cDefault := ''EXISTS (SELECT 1',
'	                                          FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC',
'	                                         WHERE AC.CodCia                 = A.CodCia',
'	                                           AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'	                                           AND AC.IdPoliza               = '' || :P9000_IDPOLIZA_Q ||',
'	                                         '' AND AC.CodCia                 = '' || :CODCIA ||',
'	                                         '' AND AC.IDetPol                > 0',
'	                                           AND AC.Cod_Asegurado           > 0 '' ||',
'	                                         '' AND A.Tipo_Doc_Identificacion = PN.Tipo_Doc_Identificacion',
'	                                           AND A.Num_Doc_Identificacion  = PN.Num_Doc_Identificacion',
'	                                         UNION',
'	                                        SELECT 1',
'	                                          FROM ASEGURADO A, ASEGURADO_CERT AC',
'	                                         WHERE AC.CodCia                 = A.CodCia',
'	                                           AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'	                                           AND AC.IdPoliza               = '' || :P9000_IDPOLIZA_Q ||',
'	                                         '' AND AC.CodCia                 = '' || :CODCIA ||',
'	                                         '' AND AC.IDetPol                > 0',
'	                                           AND AC.Cod_Asegurado           > 0 '' ||',
'	                                         '' AND A.Tipo_Doc_Identificacion = PN.Tipo_Doc_Identificacion',
'	                                           AND A.Num_Doc_Identificacion  = PN.Num_Doc_Identificacion',
'	                                         UNION',
'	                                        SELECT 1',
'	                                          FROM ASEGURADO A, DETALLE_POLIZA D',
'	                                         WHERE OC_ASEGURADO_CERTIFICADO.TIENE_ASEGURADOS(D.CodCia, D.IdPoliza, D.IDetPol, 0) = '' || CHR(39) || ''N'' || CHR(39) ||',
'	                                          ''AND D.CodCia                  = A.CodCia',
'	                                           AND D.Cod_Asegurado           = A.Cod_Asegurado',
'	                                           AND D.IdPoliza                = '' || :P9000_IDPOLIZA_Q ||',
'	                                         '' AND D.CodCia                  = '' || :CODCIA ||',
'	                                         '' AND D.IDetPol                 > 0 '' ||',
'	                                         '' AND A.Tipo_Doc_Identificacion = PN.Tipo_Doc_Identificacion',
'	                                           AND A.Num_Doc_Identificacion  = PN.Num_Doc_Identificacion',
'	                                         UNION',
'	                                        SELECT 1',
'	                                          FROM POLIZAS P, CLIENTES C',
'	                                         WHERE P.IdPoliza                = '' || :P9000_IDPOLIZA_Q ||',
'	                                         '' AND P.CodCia                  = '' || :CODCIA ||',
'	                                         '' AND C.CODCLIENTE              = P.CODCLIENTE',
'	                                           AND C.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'	                                           AND C.NUM_DOC_IDENTIFICACION  = PN.NUM_DOC_IDENTIFICACION)'';',
'',
'       end if;',
'	   IF :P9000_NOMBRE_PARCIAL IS NOT NULL THEN  	 	',
'	 	    IF cDefault IS NOT NULL THEN ',
'	 	       cDefault := cDefault || '' AND '';',
'	      END IF;',
'	  	   cDefault := cDefault ||''Nombre '' || ''||'' ||'' Apellido_Paterno ''|| ''||'' || '' Apellido_Materno LIKE  ''|| ',
'	  	               CHR(39) || ''%''|| :P9000_NOMBRE_PARCIAL ||''%''|| CHR(39); ',
'	   END IF;',
'     --  ',
'	   IF :P9000_NOMBRE_Q IS NOT NULL THEN  	 	',
'	 	    IF cDefault IS NOT NULL THEN ',
'	 	       cDefault := cDefault || '' AND '';',
'	      END IF;',
'	      cDefault := cDefault || ''Nombre LIKE  ''|| CHR(39) || ''%''|| :P9000_NOMBRE_Q ||''%''|| CHR(39); ',
'	   END IF;',
'	   -- ',
'	   IF :P9000_APELLIDO_PATERNO_Q IS NOT NULL THEN  	 	',
'	 	    IF cDefault IS NOT NULL THEN ',
'	 	       cDefault := cDefault || '' AND '';',
'	      END IF;',
'           cDefault := cDefault || ''Apellido_Paterno LIKE ''|| CHR(39) || ''%''||  :P9000_APELLIDO_PATERNO_Q ||''%'' || CHR(39); ',
'	   END IF;',
'	   -- ',
'	   IF :P9000_APELLIDO_MATERNO_Q IS NOT NULL THEN',
'	 	    IF cDefault IS NOT NULL THEN ',
'	 	       cDefault := cDefault || '' AND '';',
'	 	    END IF;',
'	   	  cDefault := cDefault || ''Apellido_Materno LIKE ''|| CHR(39) || ''%''|| :P9000_APELLIDO_MATERNO_Q ||''%'' || CHR(39); ',
'	   END IF;',
'',
'	   IF :P9000_NUMPOLUNICO_Q IS NOT NULL THEN  	 	',
'		    IF cDefault IS NOT NULL THEN ',
'		 	     cDefault := cDefault || '' AND '';',
'		 	  END IF;',
'	      cDefault := cDefault ||''EXISTS (SELECT 1',
'	                                          FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC, POLIZAS P',
'	                                         WHERE P.NumPolUnico             = '' || CHR(39) || :P9000_NUMPOLUNICO_Q || CHR(39) ||',
'	                                         '' AND P.CodCia                  = '' || :CodCia ||',
'	                                         '' AND P.IdPoliza                = AC.IdPoliza',
'	                                           AND P.CodCia                  = A.CodCia',
'	                                           AND AC.CodCia                 = A.CodCia',
'	                                           AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'	                                           AND A.Tipo_Doc_Identificacion = PN.Tipo_Doc_Identificacion',
'	                                           AND A.Num_Doc_Identificacion  = PN.Num_Doc_Identificacion',
'	                                         UNION',
'	                                        SELECT 1',
'	                                          FROM ASEGURADO A, ASEGURADO_CERT AC, POLIZAS P',
'	                                         WHERE P.NumPolUnico             = '' || CHR(39) || :P9000_NUMPOLUNICO_Q || CHR(39) ||',
'	                                         '' AND P.CodCia                  = '' || :CodCia ||',
'	                                         '' AND P.IdPoliza                = AC.IdPoliza',
'	                                           AND P.CodCia                  = AC.CodCia',
'	                                           AND AC.CodCia                 = A.CodCia',
'	                                           AND AC.Cod_Asegurado          = A.Cod_Asegurado',
'	                                           AND A.Tipo_Doc_Identificacion = PN.Tipo_Doc_Identificacion',
'	                                           AND A.Num_Doc_Identificacion  = PN.Num_Doc_Identificacion',
'	                                         UNION',
'	                                        SELECT 1',
'	                                          FROM ASEGURADO A, DETALLE_POLIZA D, POLIZAS P',
'	                                         WHERE P.NumPolUnico             = '' || CHR(39) || :P9000_NUMPOLUNICO_Q || CHR(39) ||',
'	                                         '' AND P.CodCia                  = '' || :CodCia ||',
'	                                         '' AND P.IdPoliza                = D.IdPoliza',
'	                                           AND P.CodCia                  = D.CodCia',
'	                                           AND OC_ASEGURADO_CERTIFICADO.TIENE_ASEGURADOS(D.CodCia, D.IdPoliza, D.IDetPol, 0) = '' || CHR(39) || ''N'' || CHR(39) ||',
'	                                         '' AND D.CodCia                  = A.CodCia',
'	                                           AND D.Cod_Asegurado           = A.Cod_Asegurado',
'	                                           AND A.Tipo_Doc_Identificacion = PN.Tipo_Doc_Identificacion',
'	                                           AND A.Num_Doc_Identificacion  = PN.Num_Doc_Identificacion',
'	                                         UNION',
'	                                        SELECT 1',
'	                                          FROM POLIZAS P, CLIENTES C',
'	                                         WHERE P.NumPolUnico             = '' || CHR(39) || :P9000_NUMPOLUNICO_Q || CHR(39) ||',
'	                                         '' AND P.CodCia                  = '' || :CodCia ||',
'	                                         '' AND C.CODCLIENTE              = P.CODCLIENTE',
'	                                           AND C.TIPO_DOC_IDENTIFICACION = PN.TIPO_DOC_IDENTIFICACION',
'	                                           AND C.NUM_DOC_IDENTIFICACION  = PN.NUM_DOC_IDENTIFICACION)'';',
'	   END IF;',
'	   -- ',
'     IF :P9000_NUMREF_SIN_Q IS NOT NULL THEN  	 	',
'		    IF cDefault IS NOT NULL THEN ',
'		 	     cDefault := cDefault || '' AND '';',
'		 	  END IF;',
'        cDefault := cDefault ||''EXISTS (SELECT 1',
'	                                          FROM ASEGURADO A, ASEGURADO_CERTIFICADO AC, SINIESTRO T',
'	                                         WHERE T.NumSiniRef              = '' || CHR(39) || :P9000_NUMREF_SIN_Q || CHR(39) ||    ',
'	                                         '' AND T.CodCia                  = '' || :CodCia ||',
'	                                         '' AND T.IDPOLIZA                = AC.IdPoliza',
'	                                           AND T.CODCIA                  = A.CodCia',
